KB.lade("britisch-irisch",[{"id":"britisch-irisch-fish-and-chips","name":"Fish and Chips","originalname":"Fish and Chips","kueche":"britisch-irisch","region":"England","beliebtheit":96,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Knuspriger Backteig um saftigen Kabeljau, dicke goldene Chips, sämige Mushy Peas und ein Spritzer Malzessig – das britische Nationalgericht zum Selbermachen.","hintergrund":"Fish and Chips gilt als das britische Nationalgericht schlechthin. Als erster Laden, der Fisch und Pommes zusammen verkaufte, wird meist der von Joseph Malin in London um 1860 genannt, John Lees eröffnete 1863 in Mossley in Lancashire einen weiteren. Um 1910 gab es in Großbritannien über 25.000 Läden, und im Zweiten Weltkrieg war das Gericht eines der wenigen, die nicht rationiert wurden. Im Süden isst man traditionell eher Kabeljau, im Norden Schellfisch. Gegessen wird mit Salz und Malzessig, dazu gibt es Mushy Peas, Tartarsauce oder Currysauce.","portionen":4,"zeit":{"vorbereitung":40,"garen":40,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Chips","liste":[{"menge":1,"einheit":"kg","name":"mehligkochende Kartoffeln","hinweis":"z. B. Agria, Bintje oder Marabel; in England nimmt man Maris Piper"},{"menge":2.5,"einheit":"l","name":"Frittieröl","hinweis":"raffiniertes Raps- oder Erdnussöl, hoch erhitzbar"},{"menge":null,"einheit":"","name":"feines Salz","hinweis":"zum Würzen der fertigen Chips"},{"menge":null,"einheit":"","name":"Malzessig","hinweis":"gibt es im gut sortierten Supermarkt; ersatzweise milder Apfelessig"}]},{"gruppe":"Für den Fisch im Bierteig","liste":[{"menge":4,"einheit":"Stück","name":"dicke Kabeljaufilets, ohne Haut, je ca. 180 g","hinweis":"Schellfisch ist ebenso authentisch; Seelachs ist die günstige Variante"},{"menge":250,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus 50 g zum Wenden der Filets"},{"menge":1,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":300,"einheit":"ml","name":"eiskaltes helles Bier","hinweis":"alternativ eiskaltes Mineralwasser mit Kohlensäure"}]},{"gruppe":"Mushy Peas","liste":[{"menge":400,"einheit":"g","name":"Erbsen, tiefgekühlt","hinweis":""},{"menge":20,"einheit":"g","name":"Butter","hinweis":""},{"menge":2,"einheit":"Zweig","name":"frische Minze","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"Saft und etwas Abrieb"}]},{"gruppe":"Tartarsauce","liste":[{"menge":150,"einheit":"g","name":"Mayonnaise","hinweis":""},{"menge":3,"einheit":"Stück","name":"Cornichons","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Kapern","hinweis":"abgetropft und gehackt"},{"menge":1,"einheit":"EL","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":""}]}],"ausruestung":["Fritteuse oder schwerer, hoher Topf (mind. 7 cm Öl)","Fritierthermometer","Schaumlöffel oder Drahtsieb","Küchenpapier und Gitterrost","Backofen zum Warmhalten","Pürierstab oder Kartoffelstampfer"],"schritte":[{"titel":"Alles vorbereiten und abwiegen","aktion":"vorbereiten","text":"Wiege Mehl, Backpulver und Salz für den Teig ab, hacke Cornichons, Kapern und Petersilie für die Tartarsauce und stelle das Bier in den Gefrierschrank, damit es richtig eiskalt wird. Nimm die Fischfilets aus dem Kühlschrank, tupfe sie mit Küchenpapier trocken und zupfe mit einer Pinzette verbliebene Gräten heraus – fahre dazu mit dem Finger gegen die Faserrichtung, dann spürst du sie. Heize den Backofen auf 100 °C Ober-/Unterhitze vor und lege ein Backblech mit Gitterrost bereit, auf dem später alles warm bleibt. Ein gut vorbereiteter Arbeitsplatz ist hier wichtig, weil du beim Frittieren keine Hand frei hast.","dauer":0,"tipp":"Kalter Teig und trockener Fisch sind die beiden Grundregeln für eine knusprige Hülle."},{"titel":"Kartoffeln schneiden und wässern","aktion":"schneiden","text":"Schäle die Kartoffeln und schneide sie zuerst in etwa 1,5 cm dicke Scheiben, dann in fingerdicke Stäbe von 1,5 x 1,5 cm. Gleichmäßige Größe ist entscheidend, damit alle Chips zur gleichen Zeit gar und goldbraun sind. Spüle die Stäbe in einer Schüssel mit kaltem Wasser, bis das Wasser klar bleibt – so wäschst du die oberflächliche Stärke ab, die sonst zu dunklen, klebrigen Chips führt. Lass sie anschließend mindestens 30 Minuten in frischem kaltem Wasser liegen und tupfe sie danach sehr gründlich mit einem sauberen Tuch trocken, denn Restwasser lässt das heiße Öl gefährlich spritzen.","dauer":30,"tipp":""},{"titel":"Chips in Salzwasser vorgaren","aktion":"kochen","text":"Bringe in einem großen Topf reichlich Wasser mit einem gehäuften Teelöffel Salz zum Kochen und gib die Kartoffelstäbe hinein. Lass sie bei mittlerer Hitze 6 bis 8 Minuten sieden, bis sie außen weich werden und an den Kanten leicht aufrauen, aber noch nicht zerfallen – eine Gabel sollte noch Widerstand spüren. Hebe sie vorsichtig mit einer Schaumkelle auf ein Gitter und lass sie 10 bis 15 Minuten dampfen und abkühlen. Durch das Vorgaren wird das Innere später wunderbar flaumig, und die aufgeraute Oberfläche nimmt im Öl eine besonders knusprige Kruste an. Heston Blumenthal treibt dieses Prinzip mit seinen dreifach gegarten Chips auf die Spitze.","dauer":8,"tipp":"Je trockener die Chips vor dem Frittieren sind, desto knuspriger werden sie."},{"titel":"Mushy Peas kochen","aktion":"koecheln","text":"Schmilz die Butter in einem kleinen Topf bei mittlerer Hitze, gib die gefrorenen Erbsen und die gehackten Minzblätter hinein und lass sie zugedeckt etwa 8 bis 10 Minuten leise köcheln, bis sie ganz weich und leuchtend grün sind. Zerdrücke sie dann grob mit einem Kartoffelstampfer oder püriere sie kurz mit dem Pürierstab, sodass noch ein paar ganze Erbsen übrig bleiben – das Püree soll dick und löffelfest sein, nicht glatt wie Suppe. Schmecke mit Zitronensaft, einer Prise Salz und reichlich schwarzem Pfeffer ab. Halte die Mushy Peas auf kleinster Stufe warm und rühre gelegentlich um, damit nichts ansetzt.","dauer":10,"tipp":""},{"titel":"Tartarsauce anrühren","aktion":"mischen","text":"Verrühre die Mayonnaise mit den fein gehackten Cornichons, den Kapern, der Petersilie und dem Zitronensaft in einer kleinen Schüssel. Schmecke mit Pfeffer und nur wenig Salz ab, denn Kapern und Cornichons bringen schon viel Würze mit. Die Sauce soll frisch und säuerlich schmecken, damit sie den fettigen Fisch ausgleicht, und die Stückchen sollten noch hör- und spürbar knackig sein. Stelle sie abgedeckt in den Kühlschrank, sie schmeckt nach 20 Minuten Durchziehen deutlich runder.","dauer":0,"tipp":""},{"titel":"Chips frittieren und warm halten","aktion":"frittieren","text":"Erhitze das Öl in der Fritteuse oder einem hohen Topf auf 180 °C und kontrolliere die Temperatur mit dem Thermometer; der Topf darf höchstens zu einem Drittel gefüllt sein. Frittiere die Chips in zwei bis drei Portionen jeweils 4 bis 5 Minuten, bis sie tief goldgelb sind und beim Anstoßen mit dem Schaumlöffel leise klirren. Nicht auf einmal alles hineingeben, sonst fällt die Temperatur ab und die Chips saugen sich mit Öl voll. Hebe jede Portion auf Küchenpapier, salze sofort, damit das Salz haftet, und stelle sie dann auf dem Rost in den 100 °C warmen Ofen. Lass das Öl danach wieder auf 180 °C kommen.","dauer":12,"tipp":"Das Öl muss vor jeder Charge wieder die Temperatur erreichen – sonst werden die Chips fettig."},{"titel":"Bierteig rühren und Fisch backen","aktion":"frittieren","text":"Rühre Mehl, Backpulver und Salz mit dem eiskalten Bier kurz mit einem Schneebesen glatt – ein paar kleine Klümpchen sind in Ordnung, der Teig soll etwa so dickflüssig wie halbsteif geschlagene Sahne sein. Wende die trockenen Filets in dem zusätzlichen Mehl und klopfe überschüssiges ab, damit der Teig am Fisch haftet. Ziehe jedes Filet durch den Teig, lasse es kurz abtropfen und gib es vorsichtig mit einer Bewegung weg vom Körper in das 180 °C heiße Öl. Frittiere 5 bis 6 Minuten, bis der Teig tief goldbraun, aufgebläht und knusprig ist und der Fisch im Inneren beim Anstechen in großen, weißen Lamellen zerfällt. Höchstens zwei Filets gleichzeitig backen und zwischendurch wenden, falls sie nicht von allein kippen.","dauer":12,"tipp":"Den Teig erst unmittelbar vor dem Frittieren anrühren, damit das Backpulver und die Kohlensäure maximal wirken."},{"titel":"Abtropfen und kurz ruhen lassen","aktion":"ruhen","text":"Hebe die fertigen Fischfilets mit dem Schaumlöffel aus dem Öl und lege sie auf ein Gitter, nicht flach auf Papier, denn Dampf unter dem Fisch würde die Unterseite aufweichen. Tupfe nur die Oberseite leicht ab und streue ein paar Körnchen Salz darüber. Lass den Fisch 1 bis 2 Minuten ruhen, damit sich der Saft im Inneren verteilt und der Teig seine endgültige Knusprigkeit erhält. Wenn du mehrere Chargen brauchst, halte die fertigen Stücke im 100 °C warmen Ofen auf dem Rost, aber nicht länger als 10 Minuten, sonst verliert der Teig sein Knistern.","dauer":2,"tipp":""},{"titel":"Anrichten wie im Chippy","aktion":"anrichten","text":"Verteile die heißen Chips auf vorgewärmten Tellern oder Papier, setze das knusprige Fischfilet daneben und gib einen großen Löffel Mushy Peas sowie eine Portion Tartarsauce dazu. Bring Salz und Malzessig an den Tisch, damit jeder selbst würzt: Ein Spritzer Essig über Chips und Fisch bringt Frische, die das Frittierte perfekt ausbalanciert. Serviere sofort und mit den Fingern, so wie es in den Fish-and-Chips-Läden üblich ist. Dazu passt eine Zitronenspalte und eine große Tasse starker Tee oder ein kühles Ale.","dauer":0,"tipp":""}],"profitipps":["Der Fisch muss gut abgetupft sein und der Teig eiskalt, sonst löst sich die Hülle vom Filet oder wird gummiartig.","Halte die Öltemperatur konstant bei 180 °C: Zu kühles Öl macht fettige Chips, zu heißes Öl verbrennt den Teig, bevor der Fisch gar ist.","Schellfisch und Kabeljau sind klassisch; wichtig ist festes, dickes Filet, das beim Frittieren saftig bleibt.","Wer eine besonders knusprige Variante will: die Chips nach dem Vorgaren nochmals bei 130 °C kurz frittieren und abkühlen lassen, wie bei Heston Blumenthals dreifach gegarten Chips, und erst dann bei 180 °C goldbraun ausbacken.","Salz erst nach dem Frittieren auf die Chips streuen; auf rohe Kartoffeln gestreut entzieht es Wasser und das Öl spritzt."],"varianten":["Mit Schellfisch (Haddock) im Norden Englands und Schottlands","Schottische Variante mit Currysauce oder Gravy zu den Chips","Teig mit Sprudelwasser und etwas Essig statt Bier für Kinder","Fish Supper in Schottland mit Salz und Sauce (brown sauce)"],"beilagen":["Mushy Peas","Tartarsauce","Zitronenspalten","eingelegte Zwiebeln und Gurken","Currysauce"],"getraenk":"Helles Ale oder Lager, kräftiger schwarzer Tee oder ein trockener Weißwein wie Muscadet.","koeche":[{"name":"Jamie Oliver","bezug":"Hat auf seiner Webseite mehrere Fish-and-Chips-Rezepte, darunter eine klassische Version mit Bierteig aus Mehl, Bier und Backpulver, Chips, die erst in Salzwasser vorgegart und dann frittiert werden, und selbstgemachten Mushy Peas mit Minze.","quelle":"https://www.jamieoliver.com/recipes/fish/fish-chips-and-mushy-peas"},{"name":"Heston Blumenthal","bezug":"Entwickelte ab Anfang der 1990er die dreifach gegarten Chips (erst weich simmern, trocknen, bei 130 °C und dann bei 180 °C frittieren), die er 1995 im Fat Duck servierte und die in britischen Pubs zum Standard geworden sind. In seiner Fernsehreihe In Search of Perfection widmete er sich auch Fish and Chips.","quelle":"https://en.wikipedia.org/wiki/Triple-cooked_chips"}],"quellen":[{"titel":"Fish and chips – Wikipedia","url":"https://en.wikipedia.org/wiki/Fish_and_chips"},{"titel":"Jamie Oliver – Fish, Chips and Mushy Peas","url":"https://www.jamieoliver.com/recipes/fish/fish-chips-and-mushy-peas"},{"titel":"Triple-cooked chips – Wikipedia","url":"https://en.wikipedia.org/wiki/Triple-cooked_chips"},{"titel":"The Takeout – Heston Blumenthal wants to make perfect fish and chips","url":"https://thetakeout.com/heston-blumenthal-wants-to-make-perfect-fish-and-chips-1835426705"}],"bild":"fisch","farben":["#d9a441","#f2d38a","#6b8f4e"],"schlagworte":["Klassiker","Pub","Frittiert","Nationalgericht"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-sunday-roast-yorkshire-pudding","name":"Sunday Roast mit Yorkshire Pudding","originalname":"Sunday Roast with Yorkshire Pudding","kueche":"britisch-irisch","region":"England","beliebtheit":90,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Rosa gebratenes Roastbeef, knusprige Röstkartoffeln, hoch aufgegangene Yorkshire Puddings und dunkle Gravy – das große Sonntagsessen der Briten.","hintergrund":"Der Sunday Roast ist das gemeinsame Mittagessen am Sonntag, das in Großbritannien nach dem Kirchgang auf den Tisch kam. Im 18. Jahrhundert stellten viele Familien das Fleisch vor dem Gottesdienst in den Ofen. Das Yorkshire Pudding stammt aus Nordengland: Köche nutzten das Fett, das beim Braten vom Fleisch tropfte, um darin einen Teig aus Eiern, Mehl und Milch zu backen. Der Name erscheint gedruckt erstmals 1747 bei Hannah Glasse. Ursprünglich aß man es vorab mit viel Sauce, um den Hunger zu dämpfen, bevor das teure Fleisch kam. Die Royal Society of Chemistry erklärte 2008 sogar, ein echtes Yorkshire Pudding müsse mindestens vier Zoll (10 cm) hoch sein.","portionen":6,"zeit":{"vorbereitung":45,"garen":100,"ruhen":60},"schwierigkeit":3,"zutaten":[{"gruppe":"Roastbeef","liste":[{"menge":1.5,"einheit":"kg","name":"Rinderrücken (Roastbeef) oder Hochrippe am Stück","hinweis":"Zimmertemperatur, mit schöner Fettkappe; beim Metzger vorbestellen"},{"menge":2,"einheit":"EL","name":"Rapsöl","hinweis":""},{"menge":1,"einheit":"TL","name":"englisches Senfpulver","hinweis":"optional; ersatzweise etwas Dijonsenf"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"grob gemahlen"}]},{"gruppe":"Röstkartoffeln","liste":[{"menge":1.2,"einheit":"kg","name":"mehligkochende Kartoffeln","hinweis":"in etwa 5 cm große Stücke geschnitten"},{"menge":100,"einheit":"g","name":"Gänse- oder Rinderschmalz","hinweis":"oder Rapsöl"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"mit Schale angedrückt"},{"menge":2,"einheit":"Zweig","name":"Rosmarin","hinweis":""}]},{"gruppe":"Yorkshire Puddings (12 kleine)","liste":[{"menge":140,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"gesiebt"},{"menge":4,"einheit":"Stück","name":"Eier, Größe M","hinweis":"Zimmertemperatur"},{"menge":200,"einheit":"ml","name":"Milch","hinweis":"Zimmertemperatur"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":6,"einheit":"EL","name":"Rinderschmalz oder Rapsöl","hinweis":"zum Erhitzen in der Muffinform"}]},{"gruppe":"Gravy und Gemüse","liste":[{"menge":1,"einheit":"EL","name":"Mehl","hinweis":""},{"menge":100,"einheit":"ml","name":"Rotwein","hinweis":"optional"},{"menge":500,"einheit":"ml","name":"Rinderfond","hinweis":"kräftig"},{"menge":1,"einheit":"TL","name":"Worcestershiresauce","hinweis":""},{"menge":500,"einheit":"g","name":"Karotten und Pastinaken","hinweis":"in Stücke geschnitten"},{"menge":3,"einheit":"EL","name":"Sahnemeerrettich","hinweis":"zum Servieren"}]}],"ausruestung":["Bräter oder tiefes Backblech mit Rost","12er-Muffinform oder Yorkshire-Pudding-Form","Bratenthermometer","scharfes Tranchiermesser","Alufolie","Sieb"],"schritte":[{"titel":"Planen, Fleisch temperieren und würzen","aktion":"vorbereiten","text":"Nimm das Rindfleisch 1 bis 2 Stunden vor dem Braten aus dem Kühlschrank, damit es nicht eiskalt in den Ofen kommt und gleichmäßig gart. Tupfe es trocken, reibe es rundum mit Salz, grob gemahlenem Pfeffer und dem Senfpulver ein. Schreibe dir die Zeitleiste auf, denn der Roast ist ein Timing-Gericht: Die Röstkartoffeln brauchen etwa 1 Stunde, das Fleisch rund 60 bis 70 Minuten plus 30 Minuten Ruhe, und die Yorkshire Puddings kommen als Letztes in den Ofen. Schäle und schneide Kartoffeln, Karotten und Pastinaken, hacke alles Weitere und stelle die Zutaten bereit.","dauer":0,"tipp":""},{"titel":"Yorkshire-Teig anrühren und ruhen lassen","aktion":"mischen","text":"Siebe das Mehl mit dem Salz in eine große Schüssel, mache in der Mitte eine Mulde und schlage die Eier hinein. Rühre mit einem Schneebesen von der Mitte aus, bis eine dicke, glatte Paste entsteht, und gieße dann die Milch in zwei Portionen ein. Der fertige Teig soll dünnflüssig wie flüssige Sahne sein, ohne jedes Klümpchen. Streiche ihn durch ein Sieb, falls doch Klumpen bleiben, und lass ihn mindestens 30 Minuten, besser 2 Stunden oder über Nacht im Kühlschrank ruhen. Das Mehl quillt, der Teig wird geschmeidig, und die Puddings steigen später höher auf.","dauer":30,"tipp":"Den Teig vor dem Backen auf Zimmertemperatur bringen und noch einmal kurz durchrühren."},{"titel":"Kartoffeln vorkochen und anrauen","aktion":"blanchieren","text":"Koche die Kartoffelstücke in reichlich Salzwasser 8 bis 10 Minuten, bis sich die Kanten weich anfühlen, der Kern aber noch fest ist. Gieße sie in ein Sieb ab, lass sie 2 Minuten dampfen und schüttele das Sieb dann kräftig, sodass die Oberfläche aufrauht und eine matschige Schicht entsteht. Genau diese raue Haut wird im Ofen zur extra knusprigen Kruste. Lass die Kartoffeln danach 5 Minuten offen ausdampfen, damit möglichst viel Feuchtigkeit entweicht.","dauer":12,"tipp":""},{"titel":"Fleisch anbraten und alles in den Ofen schieben","aktion":"anbraten","text":"Heize den Ofen auf 220 °C Ober-/Unterhitze (200 °C Umluft) vor und stelle den Bräter auf den Herd. Erhitze das Öl bei starker Hitze und brate das Rindfleisch 6 bis 8 Minuten rundum an, bis es dunkel gebräunt ist und kräftig duftet. Erhitze in einem zweiten Blech das Schmalz im Ofen, bis es raucht, wende die Kartoffeln darin mit Knoblauch und Rosmarin und schiebe sie auf die oberste Schiene. Lege das Fleisch auf einem Rost in den Bräter und stelle es unten in den Ofen. Nach 20 Minuten senkst du die Temperatur auf 180 °C Ober-/Unterhitze (160 °C Umluft).","dauer":20,"tipp":""},{"titel":"Roastbeef zum Garpunkt braten","aktion":"braten","text":"Brate das Rindfleisch weitere 35 bis 45 Minuten bei der gesenkten Temperatur, bis das Bratenthermometer in der dicksten Stelle 52 bis 54 °C anzeigt, das ergibt nach dem Ruhen ein rosa Roastbeef von etwa 57 °C Kerntemperatur. Wende die Kartoffeln zwischendurch einmal. Für durchgebraten ist ein Thermometer auf 62 bis 65 °C zu empfehlen. Hole das Fleisch heraus, bevor die Zielwerte erreicht sind, denn es gart durch Restwärme nach. Die Röstkartoffeln lässt du im Ofen, sie brauchen insgesamt etwa 60 Minuten.","dauer":40,"tipp":"Ein Bratenthermometer ist die einzige zuverlässige Methode, um Roastbeef auf den Punkt zu garen."},{"titel":"Fleisch ruhen lassen, Ofen auf Maximum","aktion":"ruhen","text":"Nimm das Roastbeef aus dem Bräter, lege es auf ein Brett und decke es locker mit Alufolie ab. Es muss 30 bis 40 Minuten ruhen, damit sich der Saft im Fleisch verteilt und beim Anschneiden nicht ausläuft. Drehe den Ofen währenddessen auf 230 °C Ober-/Unterhitze (210 °C Umluft) hoch und stelle die Muffinform mit je 1 gehäuften Teelöffel Schmalz pro Mulde auf die mittlere Schiene, bis das Fett raucht und Schlieren zieht. Die Röstkartoffeln bleiben oben, sie werden jetzt noch knuspriger.","dauer":30,"tipp":""},{"titel":"Yorkshire Puddings backen","aktion":"backen","text":"Hole die Muffinform mit dem heißen Fett vorsichtig aus dem Ofen, verteile den Teig zügig in die Mulden bis etwa zur Hälfte und schiebe die Form sofort zurück. Das Zischen beim Einfüllen ist ein gutes Zeichen. Backe die Puddings 20 bis 25 Minuten, ohne die Ofentür zu öffnen, denn der Dampf aus dem Teig muss sie aufbauschen. Sie sind fertig, wenn sie hoch aufgegangen, tief goldbraun und an den Wänden knusprig sind. Fallen sie beim Herausnehmen zusammen, waren sie zu früh draußen.","dauer":22,"tipp":"Heißes Fett und kalte Ofentür ruinieren die Puddings – die Ofentür bleibt zu."},{"titel":"Gravy aus dem Bratensatz kochen","aktion":"reduzieren","text":"Gieße das überschüssige Bratfett aus dem Bräter bis auf etwa 2 Esslöffel ab und stelle ihn auf den Herd. Rühre das Mehl ein, lass es 1 Minute bräunen und lösche mit dem Rotwein ab, wobei du den Bratensatz vom Boden löst. Lass den Wein fast vollständig einkochen, gieße dann den Fond zu und lass die Sauce 8 bis 10 Minuten reduzieren, bis sie leicht dicklich und glänzend ist. Würze mit Worcestershiresauce, Salz und Pfeffer und gieße sie durch ein Sieb. Gib den beim Ruhen ausgetretenen Fleischsaft dazu.","dauer":12,"tipp":""},{"titel":"Gemüse garen und anrichten","aktion":"daempfen","text":"Gare Karotten und Pastinaken in Salzwasser oder im Dampf 8 bis 12 Minuten, bis sie bissfest sind, und schwenke sie kurz in Butter. Schneide das Roastbeef quer zur Faser in dünne Scheiben, am besten mit einem scharfen, langen Messer. Richte die Scheiben mit Röstkartoffeln, Yorkshire Puddings und Gemüse auf heißen Tellern an, gieße die Gravy darüber oder reiche sie separat, und serviere Sahnemeerrettich dazu, der die Würze des Fleisches betont.","dauer":10,"tipp":""}],"profitipps":["Das Fett für die Puddings muss rauchend heiß sein – nur dann brutzelt der Teig sofort und steigt hoch.","Teig und Zutaten in Zimmertemperatur verarbeiten und den Teig ruhen lassen.","Rind und Meerrettich, Schwein und Apfelmus, Lamm und Minzsauce – das sind die klassischen Pärchen.","Röstkartoffeln werden besonders knusprig, wenn sie nach dem Vorkochen gut aufgeraut werden und in sehr heißes Fett kommen.","Das Roastbeef muss vor dem Anschneiden ruhen, sonst läuft der Saft aus."],"varianten":["Mit Schweinebraten und Apfelmus","Mit Lammkeule und Minzsauce","Mit ganzem Hähnchen, Füllung und Bread Sauce","Toad in the Hole: Würstchen im Yorkshire-Teig"],"beilagen":["Röstkartoffeln","Yorkshire Puddings","Karotten und Pastinaken","Rosenkohl oder Wirsing","Sahnemeerrettich"],"getraenk":"Kräftiger Rotwein (z. B. Rioja oder Bordeaux) oder ein dunkles englisches Ale.","koeche":[],"quellen":[{"titel":"Sunday roast – Wikipedia","url":"https://en.wikipedia.org/wiki/Sunday_roast"},{"titel":"Yorkshire pudding – Wikipedia","url":"https://en.wikipedia.org/wiki/Yorkshire_pudding"}],"bild":"braten-scheiben","farben":["#7a3b24","#c4803f","#e8c88a"],"schlagworte":["Sonntagsessen","Roastbeef","Klassiker","Familienessen"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-full-english-breakfast","name":"Full English Breakfast","originalname":"Full English Breakfast","kueche":"britisch-irisch","region":"England","beliebtheit":89,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"fruehstueck","kurz":"Spiegeleier, knuspriger Speck, saftige Würstchen, Black Pudding, Pilze, Tomaten, Baked Beans und gebratenes Brot – das üppigste Frühstück der Welt.","hintergrund":"Das gebratene Frühstück wurde in der viktorianischen Zeit in Großbritannien und Irland beliebt und erreichte im edwardianischen England seinen Höhepunkt. Isabella Beeton führte in ihrem Haushaltsbuch von 1861 bereits ein Frühstück aus gebratenem Schinken und Eiern auf. Nach dem Zweiten Weltkrieg wurde es zum Standard in den Cafés der Arbeiterklasse. Zu den klassischen Zutaten zählen Speck, Würstchen, Eier, Black Pudding, Tomaten, Pilze und gebratenes Brot, dazu kommen Baked Beans und oft Röstis. Es gibt Regionalversionen wie das schottische Frühstück mit Tattie Scones, den Ulster Fry mit Soda- und Kartoffelbrot oder das walisische mit Laverbread und Herzmuscheln.","portionen":2,"zeit":{"vorbereitung":15,"garen":35,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Eier","liste":[{"menge":4,"einheit":"Stück","name":"dicke Schweinswürstchen (z. B. Cumberland oder Bratwürstchen)","hinweis":"mit hohem Fleischanteil, möglichst ohne zu viele Gewürze"},{"menge":6,"einheit":"Scheibe","name":"Frühstücksspeck (Bacon)","hinweis":"oder Kassler-Aufschnitt"},{"menge":4,"einheit":"Scheibe","name":"Black Pudding (Blutwurst)","hinweis":"Ersatz: deutsche Blutwurst in Scheiben"},{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"möglichst frisch"}]},{"gruppe":"Beilagen","liste":[{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"halbiert"},{"menge":200,"einheit":"g","name":"braune Champignons","hinweis":"geviertelt oder in dicke Scheiben"},{"menge":1,"einheit":"Dose","name":"Baked Beans (ca. 200 g)","hinweis":"weiße Bohnen in Tomatensauce, im Supermarkt erhältlich"},{"menge":2,"einheit":"Scheibe","name":"Toastbrot oder Landbrot","hinweis":"dick geschnitten, zum Braten"},{"menge":30,"einheit":"g","name":"Butter","hinweis":""},{"menge":2,"einheit":"EL","name":"Rapsöl","hinweis":""},{"menge":null,"einheit":"","name":"Salz, Pfeffer, Ketchup oder HP-Sauce","hinweis":"zum Servieren"}]}],"ausruestung":["2 große beschichtete Pfannen","Backblech mit Gitterrost","kleiner Topf","Pfannenwender"],"schritte":[{"titel":"Alles bereitstellen und Ofen vorheizen","aktion":"vorbereiten","text":"Heize den Backofen auf 80 °C Ober-/Unterhitze vor; er dient als Warmhaltefach, damit alle Komponenten gleichzeitig heiß auf den Teller kommen. Stelle zwei Teller zum Vorwärmen hinein. Halbiere die Tomaten, schneide die Pilze in dicke Scheiben, nimm Speck, Würstchen und Black Pudding aus der Verpackung und schlage die Eier einzeln in kleine Tassen auf, damit du sie später mühelos in die Pfanne gleiten lassen kannst. Ordne alles in der Reihenfolge, in der es gebraten wird, vor dem Herd an – Würstchen zuerst, Eier zuletzt.","dauer":0,"tipp":""},{"titel":"Würstchen langsam braten","aktion":"braten","text":"Erhitze 1 Esslöffel Öl in einer Pfanne bei niedriger bis mittlerer Hitze und lege die Würstchen hinein. Brate sie 15 bis 20 Minuten und wende sie regelmäßig, damit sie gleichmäßig bräunen und durchgaren, ohne zu platzen oder außen zu verbrennen. Sie sind fertig, wenn sie rundum satt braun glänzen und beim Anstechen klarer Saft austritt. Stelle sie auf einen Teller im 80 °C warmen Ofen. Das Bratfett bleibt in der Pfanne, es gibt dem Speck später zusätzlichen Geschmack.","dauer":18,"tipp":"Geduld bei den Würstchen: Zu starke Hitze lässt sie platzen, bevor sie innen gar sind."},{"titel":"Speck knusprig braten","aktion":"braten","text":"Lege den Speck in die Pfanne zu dem Bratfett der Würstchen oder in eine zweite Pfanne und brate ihn bei mittlerer Hitze 3 bis 4 Minuten pro Seite, bis er goldbraun ist und das Fett am Rand knusprig wird. Möchtest du ihn sehr kross, drücke ihn mit dem Pfannenwender leicht an. Hebe ihn auf Küchenpapier, damit überschüssiges Fett abtropft, und stelle ihn zu den Würstchen in den Ofen. Wer es weicher mag, brät ihn kürzer.","dauer":8,"tipp":""},{"titel":"Pilze und Tomaten braten","aktion":"anbraten","text":"Erhitze Butter und etwas Öl in der Pfanne bei mittlerer bis hoher Hitze und brate die Pilze 4 bis 5 Minuten, bis sie Farbe nehmen und ihr Wasser verdampft ist; salze erst am Ende, damit sie nicht auslaufen. Gib die Pilze in die Warmhaltung, setze die Tomatenhälften mit der Schnittfläche nach unten in dasselbe Fett und brate sie 3 Minuten, bis sie angeröstet sind. Wende sie, würze mit Salz und Pfeffer und lasse sie weitere 2 Minuten garen, bis sie weich, aber noch formstabil sind.","dauer":10,"tipp":""},{"titel":"Black Pudding braten","aktion":"braten","text":"Brate die Blutwurstscheiben ohne zusätzliches Fett in einer heißen Pfanne 2 bis 3 Minuten pro Seite, bis sie eine knusprige, dunkle Kruste haben und innen weich bleiben. Wende sie vorsichtig, denn sie brechen leicht. Gib sie danach zu den übrigen Zutaten in den Ofen. Black Pudding schmeckt würzig und leicht nach Pfeffer, es ist sozusagen das Markenzeichen des Frühstücks im Norden Englands.","dauer":6,"tipp":""},{"titel":"Baked Beans erhitzen","aktion":"koecheln","text":"Gib die Bohnen mit ihrer Sauce in einen kleinen Topf und erwärme sie bei niedriger Hitze unter gelegentlichem Rühren 4 bis 5 Minuten, bis sie dampfen und leise blubbern. Nicht kochen lassen, sonst spritzen sie und die Sauce wird zu dick. Wer mag, gibt einen Klecks Butter und einen Spritzer Worcestershiresauce hinein. Halte sie im Topf bei kleinster Hitze warm.","dauer":5,"tipp":""},{"titel":"Brot in Fett braten","aktion":"braten","text":"Gib das Bratfett aus der Pfanne, das nach Speck und Würstchen duftet, ein wenig Butter dazu und lege die Brotscheiben hinein. Brate sie bei mittlerer Hitze 2 Minuten pro Seite, bis sie goldbraun und außen knusprig sind, innen aber noch weich. Das Brot saugt das aromatische Fett auf und gehört zum authentischen Frühstück. Lege die Scheiben diagonal halbiert zur Seite und halte sie warm. Wer es leichter möchte, röstet das Brot einfach im Toaster.","dauer":4,"tipp":""},{"titel":"Eier braten","aktion":"braten","text":"Erhitze frisches Fett bei mittlerer Hitze, gib die Eier vorsichtig hinein und lasse sie 2 bis 3 Minuten braten, bis das Weiße gestockt ist und der Dotter noch glänzend flüssig bleibt. Beträufle das Eiweiß mit heißem Fett, damit es oben stockt, ohne dass du wenden musst. Würze mit einer Prise Salz und Pfeffer. Eier gehören immer an den Schluss, denn sie sind schnell fertig und werden sonst gummiartig.","dauer":3,"tipp":"Frische Eier behalten ihre Form; ältere Eier laufen auseinander."},{"titel":"Anrichten und servieren","aktion":"anrichten","text":"Verteile alle Komponenten auf den vorgewärmten Tellern: Würstchen und Speck an eine Seite, Eier, Black Pudding, Pilze und Tomaten dazu, die Bohnen daneben, damit sie die anderen Zutaten nicht durchweichen. Lege das gebratene Brot an den Rand. Stelle Ketchup oder braune Sauce auf den Tisch, dazu gehört eine große Kanne starker englischer Tee mit Milch. Serviere sofort, solange alles heiß ist.","dauer":0,"tipp":""}],"profitipps":["Die Reihenfolge entscheidet: Würstchen, Speck, Pilze, Tomaten, Black Pudding, Brot, Eier – so bleibt alles heiß.","Ein warmer Backofen ist dein bester Helfer, um alle Komponenten gleichzeitig auf den Tisch zu bringen.","Für die Pilze eine heiße Pfanne verwenden, nicht zu früh salzen und nicht überfüllen, sonst dünsten sie nur.","Gutes Schweinefleisch in den Würstchen und dicker Frühstücksspeck machen den Unterschied.","Baked Beans getrennt erwärmen, damit sie die Eier und das Brot nicht aufweichen."],"varianten":["Ulster Fry mit Sodabrot-Farls und Kartoffelbrot","Schottisches Frühstück mit Haggis, Lorne-Sausage und Tattie Scones","Walisisches Frühstück mit Laverbread und Herzmuscheln","Vegetarisches Frühstück mit Halloumi, Veggie-Würstchen und Hash Browns"],"beilagen":["Toast mit Butter","Tee mit Milch","Hash Browns","Orangensaft"],"getraenk":"Starker englischer Frühstückstee (Builder's Tea) mit Milch oder frisch gepresster Orangensaft.","koeche":[],"quellen":[{"titel":"Full breakfast – Wikipedia","url":"https://en.wikipedia.org/wiki/Full_breakfast"}],"bild":"pfanne","farben":["#c2522b","#e8b84a","#4a2a1a"],"schlagworte":["Frühstück","Pub","Klassiker","Fry-up"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-fish-pie","name":"Fish Pie mit Kartoffelhaube","originalname":"Fish Pie","kueche":"britisch-irisch","region":"England (Küstenregionen, besonders Cornwall)","beliebtheit":88,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"gemischt","gang":"hauptgericht","kurz":"Zarter Weißfisch, rauchiger Schellfisch, Garnelen und Ei in cremiger Petersiliensauce, gedeckt von einer goldbraunen Kartoffelhaube – britisches Seelen-Essen in seiner besten Form.","hintergrund":"Die Fish Pie gehört zu den beliebtesten Familiengerichten Großbritanniens und ist eng mit den Fischerhäfen der Küste verwandt, wo sich Reste vom Fang unter einer sättigenden Kartoffeldecke gut verwerten ließen. Typisch ist die Mischung aus frischem Weißfisch und geräuchertem Schellfisch (smoked haddock), die der Sauce Tiefe gibt, dazu oft Garnelen und hart gekochte Eier. Rick Stein, der Fischkoch aus Padstow in Cornwall, bezeichnet den Räucherschellfisch als unverzichtbar. Traditionell wird die Pie in einer großen Auflaufform serviert, dazu gibt es einfach grüne Erbsen. Weil die Füllung vor dem Überbacken kalt werden soll, lässt sie sich hervorragend am Vortag vorbereiten.","portionen":4,"zeit":{"vorbereitung":45,"garen":45,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Fischfüllung","liste":[{"menge":450,"einheit":"g","name":"Seelachs-, Kabeljau- oder Schellfischfilet, frisch","hinweis":"mit Haut; Skrei oder MSC-zertifizierter Alaska-Seelachs von der Fischtheke funktionieren gut"},{"menge":225,"einheit":"g","name":"ungefärbtes geräuchertes Schellfisch- oder Kabeljaufilet","hinweis":"unbedingt ohne gelbe Färbung kaufen; Fischtheke oder gut sortierte Tiefkühlabteilung"},{"menge":12,"einheit":"Stück","name":"gekochte, geschälte Garnelen (ca. 150 g)","hinweis":"Tiefkühlware, über Nacht im Kühlschrank auftauen"},{"menge":4,"einheit":"Stück","name":"Eier, Größe M","hinweis":"für die hart gekochten Eier"},{"menge":450,"einheit":"ml","name":"Vollmilch","hinweis":"zum Pochieren des Fischs"},{"menge":300,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Zwiebel, in dicken Scheiben","hinweis":""},{"menge":2,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":"frisch oder getrocknet"}]},{"gruppe":"Sauce","liste":[{"menge":50,"einheit":"g","name":"Butter","hinweis":""},{"menge":45,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"glatte Petersilie, fein gehackt","hinweis":""},{"menge":null,"einheit":"","name":"frisch geriebene Muskatnuss","hinweis":"nach Geschmack"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Kartoffelhaube","liste":[{"menge":1.2,"einheit":"kg","name":"mehligkochende Kartoffeln","hinweis":"z. B. Marabel, Agria oder Bintje; vorwiegend festkochende werden schnell klebrig"},{"menge":100,"einheit":"g","name":"Butter","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":150,"einheit":"ml","name":"Vollmilch","hinweis":"zum Geschmeidigmachen des Pürees, nach Bedarf"}]}],"ausruestung":["Auflaufform (ca. 2,5–3 Liter)","großer Topf mit Deckel","Kartoffelpresse oder Stampfer","feines Sieb","kleiner Topf für die Sauce","Schneebesen"],"schritte":[{"titel":"Alles abwiegen und vorbereiten","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle die Garnelen zum Auftauen in den Kühlschrank, am besten schon am Vorabend. Prüfe die Fischfilets mit den Fingerspitzen auf Gräten: Fahre gegen die Faserrichtung über die Mitte des Filets und ziehe jede Grätenspitze mit einer Pinzette in Wuchsrichtung heraus. Frischer Fisch riecht nach Meer und frischer Gurke, nicht nach Ammoniak, und das Fleisch ist fest und feucht-glänzend. Schäle die Kartoffeln und schneide sie in gleich große Stücke von etwa 5 cm, damit sie gleichmäßig garen. Hacke die Petersilie fein und schneide die Zwiebel in dicke Scheiben, damit sie sich später leicht aus dem Sud fischen lässt.","dauer":15,"tipp":"Gleich große Kartoffelstücke garen zur selben Zeit; sonst sind die kleinen zerkocht, wenn die großen fertig werden."},{"titel":"Fisch im Sud pochieren","aktion":"kochen","text":"Gib Milch, Sahne, Zwiebelscheiben, Nelken und Lorbeer in einen weiten Topf und erhitze alles, bis kleine Bläschen am Rand aufsteigen. Lege die Fischfilets mit der Haut nach unten hinein; sie sollten fast bedeckt sein. Lass sie bei kleiner Hitze 5 bis 6 Minuten ziehen, nie sprudelnd kochen, sonst flockt die Milch und der Fisch wird zäh. Der Fisch ist fertig, wenn sich das Fleisch an der dicksten Stelle leicht mit einer Gabel in Lamellen teilen lässt und überall milchig-weiß ist. Hebe ihn mit einer Schaumkelle heraus, lege ihn auf einen Teller und seihe den Sud durch ein feines Sieb in einen Messbecher; dieser aromatische Sud wird später zur Sauce.","dauer":8,"tipp":"Hebe den Fisch vorsichtig heraus; zusammen mit der Haut bleibt er länger in Form."},{"titel":"Fisch zerpflücken und Eier kochen","aktion":"vorbereiten","text":"Ziehe von den abgekühlten Filets die Haut ab und zupfe das Fleisch in grobe Stücke von etwa 3 cm; zerdrücke es nicht, denn ganze Stücke geben der fertigen Pie Biss. Tastest du dabei eine übersehene Gräte, lege sie beiseite. Verteile den Fisch gleichmäßig in der Auflaufform. Koche die Eier in sprudelndem Wasser genau 8 Minuten, schrecke sie eiskalt ab und pelle sie unter fließendem Wasser. Schneide sie in dicke Scheiben und lege sie auf den Fisch, dann die aufgetauten und trocken getupften Garnelen darüber. Das Eigelb darf in der Mitte noch einen Hauch cremig sein, es gart beim Backen nach.","dauer":12,"tipp":"Wer keine Eier in der Pie mag, lässt sie weg; die Sauce trägt auch ohne."},{"titel":"Die Sauce rühren","aktion":"binden","text":"Schmilz die Butter in einem Topf bei mittlerer Hitze und rühre das Mehl ein, bis eine glatte, hellgelbe, leicht nussig duftende Mehlschwitze entsteht; lass sie 1 Minute unter Rühren garen, damit der rohe Mehlgeschmack verschwindet. Gieße den warmen Fischsud nun nach und nach hinzu und rühre nach jedem Schuss kräftig mit dem Schneebesen, bis keine Klümpchen mehr da sind. Lass die Sauce bei kleiner Hitze etwa 10 Minuten leise blubbern, bis sie sämig ist und einen Löffelrücken überzieht. Würze mit frisch geriebenem Muskat, Salz und weißem Pfeffer; Räucherfisch bringt schon viel Salz mit, also vorsichtig beginnen. Zum Schluss rührst du die Petersilie unter.","dauer":12,"tipp":"Weißer Pfeffer und Muskat sind der klassische Geschmack dieser Sauce; schwarzer Pfeffer setzt sichtbare Punkte."},{"titel":"Sauce über den Fisch geben und kühlen","aktion":"ruhen","text":"Gieße die Sauce gleichmäßig über Fisch, Garnelen und Eier und streiche sie sanft glatt, ohne alles zu zerdrücken. Lass die Form auf dem Tisch abkühlen und stelle sie dann mindestens 1 Stunde in den Kühlschrank; die Sauce wird dadurch fester. Dieser Schritt ist der Grund, warum die Kartoffeldecke später nicht einsinkt: Ein warmer, flüssiger Untergrund würde das Püree schlucken. Wenn du schon am Vortag arbeitest, deckst du die Form mit Folie ab und kühlst sie über Nacht.","dauer":60,"tipp":"Auf diese Weise sinkt das Püree nicht ein und die Haube bleibt hoch."},{"titel":"Kartoffeln kochen","aktion":"kochen","text":"Setze die Kartoffelstücke in kaltem, gut gesalzenem Wasser auf (etwa 1 Teelöffel Salz pro Liter), bringe sie zum Kochen und lasse sie 15 bis 20 Minuten leise sprudeln. Sie sind gar, wenn ein Messer ohne Widerstand hineingleitet und die Kanten leicht aufspringen. Gieße sie ab und lass sie 2 Minuten im offenen Topf ausdampfen, damit überschüssige Feuchtigkeit entweicht; nasse Kartoffeln ergeben wässriges Püree. Presse sie sofort durch die Presse oder stampfe sie mit dem Stampfer; ein Pürierstab macht sie klebrig und gummiartig.","dauer":25,"tipp":"Mehlige Kartoffeln saugen die Butter besser auf und werden locker."},{"titel":"Püree anrühren","aktion":"mischen","text":"Rühre die Butter in Stücken, die Eigelbe und Salz sowie weißen Pfeffer in das heiße Püree und gib die Milch nach und nach dazu. Du brauchst nicht die ganze Menge; stoppe, sobald das Püree weich, aber noch formbar ist und von einem Löffel in einem Streifen abfällt. Schmecke kräftig ab, denn die Kartoffeln müssen das Gericht allein salzig tragen. Das Eigelb gibt der Haube später eine goldene Farbe und etwas Stand.","dauer":8,"tipp":"Heißes Püree nimmt die Butter am besten auf; lass es nicht auskühlen."},{"titel":"Haube auftragen","aktion":"schichten","text":"Heize den Backofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor, mit dem Rost in der oberen Hälfte. Verteile das Püree in Klecksen über der kalten Füllung und streiche es dann mit einer Gabel bis zum Rand glatt, sodass nirgends Sauce durchblitzt. Ziehe mit den Zinken Rillen quer über die Oberfläche: Die erhöhten Spitzen werden beim Backen knusprig braun. Stelle die Form auf ein Backblech, denn bei kleiner Undichtigkeit läuft Sauce an den Rand.","dauer":8,"tipp":"Die Rillen sind nicht nur Dekoration; sie sind die Röstflächen, die der Pie ihre Farbe geben."},{"titel":"Backen","aktion":"backen","text":"Schiebe die Pie in den heißen Ofen und backe sie 35 bis 40 Minuten. Sie ist fertig, wenn die Spitzen der Kartoffelhaube goldbraun sind, am Rand Sauce blubbert und die Mitte dampfend heiß ist; ein Stäbchenthermometer im Kern zeigt dann mindestens 70 °C. Falls die Haube zu schnell Farbe nimmt, deckst du sie locker mit Alufolie ab. Wurde die Füllung gut gekühlt, brauchst du die volle Backzeit, damit die Mitte durchgart; direkt aus dem Kühlschrank rechne eher 45 Minuten.","dauer":40,"tipp":"Zum Schluss 2–3 Minuten unter den Grill stellen, wenn du mehr Röstaromen magst."},{"titel":"Ruhen lassen und servieren","aktion":"anrichten","text":"Nimm die Pie aus dem Ofen und lass sie 10 Minuten stehen, damit sich die Sauce setzt und beim Anschneiden nicht auseinanderläuft. Trage sie mit einem großen Löffel auf warmen Tellern an, sodass jeder Gast Fisch, Ei und Haube bekommt. Klassische Begleiter sind zarte grüne Erbsen mit Butter oder gedämpfter Spinat; eine Zitronenspalte bringt Frische gegen die Cremigkeit.","dauer":10,"tipp":"Schneide die Haube mit einem scharfen Messer vorab ein, dann bricht sie beim Servieren nicht."}],"profitipps":["Immer auch Räucherfisch verwenden: Er liefert den Charakter, Rick Stein hält den Räucherschellfisch für unverzichtbar.","Sud nie sprudelnd kochen: Wird die Milch zu heiß, flockt sie und der Fisch wird trocken.","Füllung vor dem Belegen kühlen, damit das Püree nicht einsinkt.","Püree mit Eigelb reichern: Es bräunt schöner und hält die Form.","Fisch nur zu 90 % garen: Er gart im Ofen noch einmal nach und bleibt so saftig.","Bei Resten ohne Eier und ohne zuvor aufgetaute Garnelen einfrieren, dann hält die Pie bis zu 3 Monate."],"varianten":["Mit Blätterteigdeckel statt Kartoffelhaube, wie Rick Stein sie ebenfalls vorschlägt.","Mit Lachs und Spinat für eine farbigere Füllung.","Mit geriebenem Cheddar auf der Haube überbacken (Cheesy Fish Pie).","Mit Süßkartoffelpüree als Haube oder halb und halb mit normalen Kartoffeln."],"beilagen":["grüne Erbsen mit Butter","gedämpfter Spinat oder Brokkoli","Zitronenspalten","knuspriges Weißbrot"],"getraenk":"Ein Weißburgunder oder Chenin Blanc passt hervorragend; alternativ ein helles englisches Ale.","koeche":[{"name":"Rick Stein","bezug":"Rick Stein, der Fischkoch aus Padstow, hat die Fish Pie mit Cornish-Räucherschellfisch, Garnelen und hart gekochten Eiern zu einem Referenzrezept gemacht und betont, dass geräucherter Schellfisch unverzichtbar ist; er schlägt außerdem vor, statt Kabeljau auch Schellfisch oder Seehecht zu nehmen.","quelle":"https://www.itv.com/thismorning/articles/rick-steins-classic-fish-pie"}],"quellen":[{"titel":"Rick Stein's classic fish pie recipe","url":"https://www.rickstein.com/blog/rick-steins-cornwall-fish-pie-recipe/"},{"titel":"Rick Stein's Classic Fish Pie (ITV This Morning)","url":"https://www.itv.com/thismorning/articles/rick-steins-classic-fish-pie"},{"titel":"Fish pie (The Happy Foodie)","url":"https://thehappyfoodie.co.uk/recipes/fish-pie/"}],"bild":"auflauf","farben":["#d9a85b","#f2e2c0","#8a5a2b"],"schlagworte":["Familienessen","Comfort Food","britischer Klassiker","Auflauf","Vorbereiten am Vortag"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-ruehrei-ramsay","name":"Cremiges Rührei nach Art von Gordon Ramsay","originalname":"Gordon Ramsay's scrambled eggs","kueche":"britisch-irisch","region":"England / Restaurantküche","beliebtheit":88,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"fruehstueck","kurz":"Weiches, glänzendes Rührei fast wie eine lockere Creme: Eier direkt in die Pfanne, ständig rühren, Pfanne immer wieder kurz vom Herd nehmen. Das Ganze dauert nur etwa vier Minuten und schmeckt mit Crème fraîche und Schnittlauch unglaublich gut.","hintergrund":"Ramsays Rührei ist wohl die bekannteste Einzelzubereitung seines Videokanals: Die Eier kommen ungeschlagen und ungesalzen mit Butter in die kalte Pfanne, werden mit dem Spatel ständig bewegt und im Wechsel von der Hitze genommen und wieder daraufgestellt. Zum Schluss rührt er etwas Kaltes wie Crème fraîche ein, damit die Eier nicht nachgaren. In seiner Luxusversion kommen Seeigelzunge und weißer Trüffel dazu; in der Heimküche genügen Schnittlauch, Crème fraîche und gutes Salz. Das ist eine Heimküchen-Fassung seiner Technik nach den beschriebenen Methoden von MasterClass und The Takeout, kein Originalrezept mit amtlichen Mengenangaben, denn die Quellen nennen keine genauen Mengen.","portionen":2,"zeit":{"vorbereitung":5,"garen":5,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für das Rührei","liste":[{"menge":4,"einheit":"Stück","name":"frische Eier (Größe M oder L)","hinweis":"Zimmertemperatur schmeckt am besten; Mengenangabe ist eine Heimküchen-Empfehlung"},{"menge":20,"einheit":"g","name":"Butter","hinweis":"gute Markenbutter, kalt in Würfeln"},{"menge":2,"einheit":"EL","name":"Crème fraîche","hinweis":"ersatzweise Schmand oder Sahne; muss kalt sein"},{"menge":1,"einheit":"EL","name":"Schnittlauch, in feinen Röllchen","hinweis":"frisch geschnitten"},{"menge":null,"einheit":"","name":"grobes Meersalz und frisch gemahlener schwarzer Pfeffer","hinweis":"erst ganz am Ende"}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"Scheibe","name":"Sauerteigbrot oder Landbrot","hinweis":"in Butter in der Pfanne geröstet"},{"menge":null,"einheit":"","name":"weißer Trüffel oder Trüffelöl (optional)","hinweis":"Luxus-Finish aus Ramsays Version; ein paar Tropfen Trüffelöl reichen"}]}],"ausruestung":["beschichtete Pfanne oder kleiner Topf (ca. 20 cm)","Silikonspatel","Uhr mit Sekundenzeiger"],"schritte":[{"titel":"Alles bereitstellen","aktion":"vorbereiten","text":"Rührei geht so schnell, dass du hinterher keine Zeit mehr hast, etwas zu suchen. Lege deshalb Spatel, Brotscheiben, Crème fraîche und den fein geschnittenen Schnittlauch griffbereit neben den Herd und wärme zwei Teller vor, zum Beispiel kurz im Ofen bei 60 °C. Nimm die Eier etwa 15 Minuten vorher aus dem Kühlschrank, damit sie nicht eiskalt in die Pfanne fallen und gleichmäßiger garen. Schneide die Butter in kleine Würfel und stelle sie bis zum Gebrauch kalt. Wähle eine Pfanne oder einen kleinen Topf mit beschichteter Fläche, denn die Eier brauchen eine Fläche, an der nichts anbackt.","dauer":5,"tipp":"Ein Silikonspatel mit weicher Kante kommt an den Rand der Pfanne und schabt dort jede Eimasse ab."},{"titel":"Eier direkt in die Pfanne schlagen","aktion":"aufschlagen","text":"Schlage die vier Eier direkt in die Pfanne und gib die Butterwürfel dazu. Verquirle die Eier nicht vorher in einer Schüssel und salze sie auch nicht, denn Salz zieht Flüssigkeit aus der rohen Masse, und das Ei wird später wässrig. Dass die Eier ganz bleiben und erst in der Pfanne zerstochen werden, ergibt später zwei Strukturen im fertigen Rührei: zarte Streifen aus Weiß und Gelb und eine cremige Grundmasse. Stelle die Pfanne erst jetzt auf den Herd und stelle ihn auf mittlere Hitze, nicht auf volle. Zu viel Hitze macht die Eier gummiartig, und genau das willst du vermeiden.","dauer":1,"tipp":"Reihenfolge merken: erst Eier und Butter in die Pfanne, dann auf den Herd, nie umgekehrt."},{"titel":"Zügig rühren, bis es anzieht","aktion":"braten","text":"Rühre die Eier nun mit dem Spatel ständig durch. Du verteilst sie dabei und schabst dabei Boden und Rand der Pfanne ab, damit nichts anlegt. Zuerst sieht alles flüssig und gelb-weiß gesprenkelt aus, die Butter schmilzt langsam und färbt die Masse leicht. Nach etwa einer Minute spürst du am Spatel, dass die Masse am Boden anfängt zu stocken, und sie wird dicklich wie eine Vanillesauce. Das ist das Zeichen, dass es Zeit für die erste Pause ist. Hör nicht auf zu rühren, solange die Pfanne auf der Platte steht.","dauer":1,"tipp":"Rühre in Achten statt im Kreis, so erreichst du jeden Teil der Pfanne."},{"titel":"Pfanne 20 Sekunden vom Herd nehmen","aktion":"ruhen","text":"Sobald die Eier anfangen anzuziehen, nimmst du die Pfanne vom Herd und rührst etwa 20 Sekunden weiter. Die Restwärme der Pfanne gart die Eier jetzt sanft weiter, ohne dass sie stocken oder trocken werden. Die Masse wird dabei sichtbar cremiger und bekommt einen leichten Glanz. Diese kurze Pause ist der eigentliche Trick der Methode: Du steuerst die Garung, nicht der Herd. Wenn dir die Eier zu schnell fest werden, verlängere die Pause. Das Ei darf nie zu Klumpen werden, sondern bleibt schlotzig und glänzend.","dauer":0,"tipp":"Zähle die 20 Sekunden wirklich laut mit, im Eifer des Gefechts sind es sonst nur fünf."},{"titel":"90 Sekunden zurück auf die Hitze","aktion":"braten","text":"Stelle die Pfanne jetzt wieder auf die mittlere Hitze und rühre etwa 90 Sekunden weiter, ohne Pause und ohne Gnade für die Ränder. In dieser Phase wird die Masse allmählich dicker, die großen Flocken verbinden sich zu feinen, weichen Stücken, und es riecht warm nach Butter. Der Gesamtzeitraum von der ersten Hitze bis zum Servieren beträgt nach den beschriebenen Methoden etwa vier Minuten. Wiederhole den Wechsel, falls die Eier noch zu flüssig sind. Sie sollen weich, aber nicht mehr laufend sein, wenn du vom Herd gehst, denn sie garen auf dem Teller noch nach.","dauer":2,"tipp":"Lieber einen Hauch zu weich servieren als einen Hauch zu fest: Auf dem heißen Teller gart Rührei nach."},{"titel":"Kalt abbremsen und würzen","aktion":"mischen","text":"Nimm die Pfanne vom Herd und rühre sofort die Crème fraîche ein, so stoppst du das Garen und bekommst eine milde, leicht säuerliche Cremigkeit. Gib auch den Schnittlauch dazu und schmecke dann erst mit grobem Meersalz und frisch gemahlenem Pfeffer ab. Wer das Salz am Ende zugibt, behält die weiche Konsistenz, denn das Salz hatte keine Zeit, den Eiern Wasser zu entziehen. Probiere einen Löffel und gib bei Bedarf eine Prise Salz nach, aber lieber vorsichtig, denn gesalzen wird später nicht mehr gerührt.","dauer":1,"tipp":"Auch ein kleiner Würfel kalte Butter oder ein Löffel Sahne stoppt die Garung, falls du keine Crème fraîche hast."},{"titel":"Auf geröstetem Brot anrichten","aktion":"anrichten","text":"Röste die Brotscheiben in einer zweiten Pfanne mit einem Stück Butter, bis sie goldbraun und knusprig sind und nach Nuss duften. Setze sie auf die vorgewärmten Teller und verteile das Rührei sofort darauf, denn jede Minute Wartezeit macht das Ei fester. Gib einen Klecks Crème fraîche und etwas Schnittlauch obendrauf und nimm als Luxus-Finish ein paar Tropfen Trüffelöl oder, wenn du es dir leisten willst, weißen Trüffel aus dem Hobel. Ramsays eigene Prunkversion kommt mit Seeigel, doch auch ohne schmeckt es hervorragend.","dauer":3,"tipp":"Das Brot darf ruhig kräftig geröstet sein: Der Kontrast zwischen knusprigem Toast und fließendem Ei macht den Reiz aus."}],"profitipps":["Mittlere statt starker Hitze: Hohe Hitze lässt Eiweiß schnell gummiartig werden.","Die Eier ungeschlagen und ungesalzen in die Pfanne geben und Salz erst am Schluss zugeben, damit die Masse nicht wässrig wird.","Im Wechsel 20 Sekunden neben dem Herd und 90 Sekunden darauf rühren, insgesamt etwa vier Minuten.","Etwas Kaltes zum Schluss (Crème fraîche, Schmand, Butter) stoppt das Nachgaren und macht die Eier cremiger.","Rührei lebt von sofortigem Servieren: Teller vorwärmen und Brot vorher rösten."],"varianten":["Luxus-Version mit Seeigel (Uni) und gehobeltem weißen Trüffel, wie sie MasterClass beschreibt.","Mit etwas Räucherlachs und Dill auf Sauerteigbrot.","Mit Trüffelöl statt frischem Trüffel als Sparversion.","Mit Ricotta oder Frischkäse statt Crème fraîche."],"beilagen":["geröstetes Sauerteigbrot","Räucherlachs","gegrillte Tomaten","Rucola-Salat"],"getraenk":"Kaffee, Orangensaft oder zum Brunch ein Glas Champagner.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsays Rührei-Methode ist weltbekannt: Eier ohne Vorquirlen in die Pfanne, ständig rühren, im Wechsel vom Herd nehmen, zum Schluss etwas Kaltes wie Crème fraîche einrühren und erst dann salzen. Seine Luxusvariante nutzt Seeigel und weißen Trüffel.","quelle":"https://www.masterclass.com/articles/how-to-make-the-perfect-scrambled-eggs-with-gordon-ramsay"}],"quellen":[{"titel":"MasterClass – How to Make the Perfect Scrambled Eggs with Gordon Ramsay","url":"https://www.masterclass.com/articles/how-to-make-the-perfect-scrambled-eggs-with-gordon-ramsay"},{"titel":"The Takeout – How Gordon Ramsay Makes Perfect Scrambled Eggs Every Time","url":"https://www.thetakeout.com/1760665/gordon-ramsay-scrambled-eggs-method/"}],"bild":"eier","farben":["#f4d35e","#fff1b8","#6b8e23"],"schlagworte":["Frühstück","Gordon Ramsay","Rührei","Brunch"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-scones-mit-clotted-cream","name":"Scones mit Clotted Cream und Erdbeermarmelade","originalname":"Scones with Clotted Cream and Jam","kueche":"britisch-irisch","region":"Südwestengland (Devon und Cornwall)","beliebtheit":87,"hauptkategorie":"suess","fleischsorte":"","gang":"gebaeck","kurz":"Hoch aufgegangene, buttrig-zarte Scones, noch lauwarm mit dicker Clotted Cream und Erdbeermarmelade – der Mittelpunkt jedes Cream Tea.","hintergrund":"Das Wort Scone ist seit dem Jahr 1480 belegt, das älteste bekannte Rezept stammt von 1669. Das süße Scone, wie wir es heute kennen, entstand erst, als Backpulver ab 1843 für alle erhältlich wurde. Beim Afternoon Tea im frühen 19. Jahrhundert wurde es zum festen Bestandteil, angeblich popularisiert durch Anna, Duchess of Bedford. Der Cream Tea mit Scones, Clotted Cream und Marmelade gehört besonders zu Devon und Cornwall. Der erste schriftliche Hinweis darauf stammt aus der Zeitung The Cornishman von 1932. Ob man Marmelade oder Sahne zuerst aufträgt, ist in beiden Grafschaften eine liebevoll gepflegte Streitfrage; Devon gibt zuerst die Sahne, Cornwall die Marmelade.","portionen":10,"zeit":{"vorbereitung":25,"garen":12,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Scones","liste":[{"menge":350,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus etwas zum Bestäuben; in England nimmt man Self-raising flour"},{"menge":4,"einheit":"TL","name":"Backpulver (ca. 16 g)","hinweis":"ersetzt das Self-raising flour; Mehl und Backpulver gründlich vermischen"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":30,"einheit":"g","name":"feiner Zucker","hinweis":""},{"menge":75,"einheit":"g","name":"kalte Butter","hinweis":"in kleinen Würfeln, direkt aus dem Kühlschrank"},{"menge":1,"einheit":"Stück","name":"Ei, Größe M","hinweis":"in einen Messbecher schlagen und mit Milch auf 150 ml auffüllen"},{"menge":75,"einheit":"g","name":"Sultaninen","hinweis":"optional für Fruit Scones"}]},{"gruppe":"Zum Servieren","liste":[{"menge":200,"einheit":"g","name":"Clotted Cream","hinweis":"Ersatz: 100 g Mascarpone mit 100 g steif geschlagener Sahne verrührt"},{"menge":150,"einheit":"g","name":"Erdbeermarmelade","hinweis":"möglichst fruchtig mit Stücken"}]}],"ausruestung":["Backblech mit Backpapier","runder Ausstecher, 6 cm Durchmesser (glatter Rand)","Nudelholz","große Schüssel","Pinsel"],"schritte":[{"titel":"Ofen vorheizen und Zutaten vorbereiten","aktion":"vorbereiten","text":"Heize den Backofen auf 220 °C Ober-/Unterhitze (200 °C Umluft) vor und lege ein Backblech mit Backpapier aus. Stelle eine Schüssel und die Butterwürfel für 10 Minuten in den Kühlschrank; kalte Butter ist die Voraussetzung für zarte, hohe Scones. Schlage das Ei in einen Messbecher und fülle mit Milch auf 150 ml auf, verquirle beides leicht und nimm 2 Esslöffel zum späteren Bestreichen in eine kleine Tasse. Wiege Mehl, Backpulver, Zucker und Salz ab und siebe sie in die kalte Schüssel.","dauer":10,"tipp":"Je kühler Butter, Schüssel und Hände, desto besser gehen die Scones auf."},{"titel":"Butter einarbeiten","aktion":"mischen","text":"Gib die kalten Butterwürfel zur Mehlmischung und reibe sie mit den Fingerspitzen schnell ein, bis die Masse wie feine Semmelbrösel aussieht und keine großen Butterstücke mehr zu sehen sind. Arbeite zügig und hebe die Mischung zwischendurch an, damit Luft hineinkommt; die Wärme deiner Hände soll die Butter nicht schmelzen. Rühre die Sultaninen unter, falls du welche verwendest. Streue 1 Esslöffel Mehl auf die Arbeitsfläche und lege ein Küchentuch bereit.","dauer":5,"tipp":""},{"titel":"Flüssigkeit unterarbeiten","aktion":"mischen","text":"Mache in der Mitte der Mehlmischung eine Mulde und gieße die Ei-Milch-Mischung bis auf den zurückbehaltenen Rest hinein. Verrühre mit einem Messer mit der flachen Seite oder mit einer Gabel, bis ein weicher, leicht klebriger Teig entsteht, und füge bei Bedarf einen Schuss Milch hinzu, falls trockene Mehlnester bleiben. Kippe den Teig auf die bemehlte Arbeitsfläche und knete ihn höchstens 2- bis 3-mal kurz zusammen. Zu langes Kneten entwickelt Gluten, und die Scones werden zäh statt zart.","dauer":3,"tipp":"Weich und noch etwas klebrig ist richtig: ein zu trockener Teig ergibt trockene Scones."},{"titel":"Ausrollen und ausstechen","aktion":"ausrollen","text":"Drücke den Teig mit der Hand oder dem Nudelholz zu einem Rechteck von etwa 2 cm Dicke zusammen; dünner ausgerollte Scones werden flach. Staube den Ausstecher in Mehl und steche Kreise von 6 cm Durchmesser aus, indem du fest gerade nach unten drückst und den Ausstecher nicht verdrehst: Ein Drehen verklebt die Teigränder und bremst das Aufgehen. Setze die Rohlinge mit etwas Abstand aufs Blech, knete die Reste kurz zusammen und steche weitere Scones aus. Es ergeben sich etwa 10 Stück.","dauer":5,"tipp":""},{"titel":"Bestreichen und kurz ruhen lassen","aktion":"ruhen","text":"Bestreiche die Oberseiten dünn mit dem zurückbehaltenen Ei-Milch-Gemisch und achte darauf, dass nichts an den Seiten herunterläuft, denn das würde die Ränder verkleben und das Aufgehen behindern. Lass die Scones auf dem Blech 10 Minuten ruhen, während der Ofen die volle Temperatur erreicht. Der Teig entspannt sich, das Backpulver beginnt zu wirken, und die Oberfläche bekommt später eine glänzende goldene Farbe.","dauer":10,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Schiebe das Blech auf die mittlere Schiene und backe die Scones 10 bis 12 Minuten, bis sie hoch aufgegangen, goldbraun und oben glänzend sind. Öffne die Ofentür in den ersten 8 Minuten nicht, damit die Hitze konstant bleibt. Sie sind fertig, wenn sie sich leicht anfühlen und beim Klopfen auf die Unterseite hohl klingen. Hole das Blech heraus und lege die Scones auf ein Gitter, am besten unter ein sauberes Tuch, damit sie nicht austrocknen.","dauer":12,"tipp":""},{"titel":"Lauwarm mit Clotted Cream servieren","aktion":"anrichten","text":"Lass die Scones 10 Minuten abkühlen; am besten schmecken sie noch lauwarm. Teile sie vorsichtig mit den Händen in der Mitte, nicht mit einem Messer, damit die Schnittfläche rau und saugfähig bleibt. Bestreiche beide Hälften mit Marmelade und Clotted Cream, entweder wie in Devon zuerst die Sahne, oder wie in Cornwall zuerst die Marmelade. Serviere dazu eine Kanne frisch gebrühten schwarzen Tee mit einem Schuss Milch.","dauer":0,"tipp":""}],"profitipps":["Alles kalt halten und den Teig kaum kneten: so gehen Scones hoch auf.","Ausstecher gerade nach unten drücken, nicht drehen; sonst gehen die Ränder schief auf.","Mit einer Ausrolldicke von 2 cm bekommen Scones eine schöne Höhe.","Ofen auf volle Temperatur bringen, bevor das Blech hineinkommt.","Am selben Tag essen; einen Tag später kurz bei 150 °C aufbacken."],"varianten":["Fruit Scones mit Sultaninen oder Rosinen","Käse-Scones mit Cheddar und einer Prise Cayennepfeffer","Schottische Girdle Scones in der Pfanne gebacken","Mit Buttermilch statt Milch für mehr Frische"],"beilagen":["Clotted Cream","Erdbeermarmelade","Butter","Lemon Curd"],"getraenk":"Schwarzer Tee wie Assam oder Earl Grey mit Milch; zum festlichen Anlass ein Glas Champagner.","koeche":[{"name":"Mary Berry","bezug":"Ihr Scone-Rezept mit Butter, Backpulver, Zucker und Ei im Teig wird oft zitiert; sie arbeitet den Teig nur kurz und sticht Scones mit einem glatten 6-cm-Ausstecher aus 2 cm dickem Teig aus.","quelle":"https://www.womanandhome.com/us/recipes/mary-berry-s-fruity-scones"}],"quellen":[{"titel":"Scone – Wikipedia","url":"https://en.wikipedia.org/wiki/Scone"},{"titel":"Woman&Home – Mary Berry's Fruity Scones","url":"https://www.womanandhome.com/us/recipes/mary-berry-s-fruity-scones"}],"bild":"gebaeck","farben":["#d9a45a","#f3dcae","#b23a48"],"schlagworte":["Afternoon Tea","Cream Tea","Gebäck","Klassiker"],"vegetarisch_moeglich":true},{"originalname":"","hauptkategorie":"suess","gang":"kuchen","koeche":[],"vegetarisch_moeglich":true,"id":"britisch-irisch-victoria-sponge","name":"Victoria Sponge Cake","region":"England","kueche":"britisch-irisch","beliebtheit":86,"kurz":"Der englische Teekuchen schlechthin: zwei zarte Rührteig-Böden mit Erdbeermarmelade und Sahne, nur mit Puderzucker bestäubt.","hintergrund":"Benannt ist der Victoria Sponge nach Queen Victoria, die laut Überlieferung gern kleine Kuchen zum Nachmittagstee aß; ihre Version war nur mit Marmelade gefüllt, heutige Varianten haben meist Sahne dazu. Möglich wurde er nach 1843, als der Birminghamer Lebensmittelhersteller Alfred Bird das Backpulver erfand und Kuchen deutlich höher aufgehen ließ. Die Mengenregel ist denkbar einfach: Butter, Zucker, Eier und Mehl zu gleichen Teilen, das Gewicht der Eier bestimmt die übrigen Mengen. Der Kuchen wird nicht glasiert und kaum verziert – seine Schlichtheit gehört zum Charakter.","portionen":8,"zeit":{"vorbereitung":25,"garen":25,"ruhen":90},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Teig (2 Backformen à 20 cm)","liste":[{"menge":225,"einheit":"g","name":"weiche Butter","hinweis":"Zimmertemperatur, ca. 21 °C – keine Margarine für feinen Geschmack"},{"menge":225,"einheit":"g","name":"feiner Zucker (Caster Sugar)","hinweis":"ersatzweise Feinzucker oder Zucker kurz im Mixer fein mahlen"},{"menge":4,"einheit":"Stück","name":"Eier (Größe L)","hinweis":"Zimmertemperatur, ca. 225 g ohne Schale"},{"menge":225,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":2.5,"einheit":"TL","name":"Backpulver","hinweis":"gestrichen"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":""},{"menge":1,"einheit":"EL","name":"Milch","hinweis":"nur bei Bedarf zum Auflockern des Teigs"},{"menge":1,"einheit":"EL","name":"weiche Butter","hinweis":"zum Ausstreichen der Formen"}]},{"gruppe":"Für die Füllung","liste":[{"menge":150,"einheit":"g","name":"Erdbeer- oder Himbeermarmelade","hinweis":"mit hohem Fruchtanteil"},{"menge":250,"einheit":"g","name":"Schlagsahne","hinweis":"mindestens 30 % Fett, gut gekühlt"},{"menge":1,"einheit":"EL","name":"Puderzucker","hinweis":"zur Sahne"},{"menge":2,"einheit":"EL","name":"Puderzucker","hinweis":"zum Bestäuben"}]}],"ausruestung":["2 Springformen oder Biskuitformen 20 cm","Backpapier","Handrührgerät","Teigschaber","Kuchengitter","Holzstäbchen","Spritzbeutel (optional)"],"schritte":[{"titel":"Zutaten temperieren und Formen vorbereiten","aktion":"vorbereiten","text":"Nimm Butter und Eier mindestens eine Stunde vorher aus dem Kühlschrank; die Butter soll sich mit dem Finger leicht eindrücken lassen, aber nicht ölig glänzen. Heize den Ofen auf 175 °C Ober-/Unterhitze (155 °C Umluft) vor, Rost in die Mitte. Fette die beiden Formen leicht ein, lege die Böden mit Backpapierkreisen aus und streue dünn Mehl an den Rand. Das Papier garantiert, dass die zarten Böden später ohne Rissbildung herauskommen.","dauer":60,"tipp":""},{"titel":"Butter und Zucker aufschlagen","aktion":"aufschlagen","text":"Schlage Butter und Zucker mit dem Handrührgerät vier bis fünf Minuten auf mittlerer bis hoher Stufe, bis die Masse blassgelb, fast weiß und sehr luftig ist und die Zuckerkörner kaum noch zu spüren sind. Zwischendurch schabst du die Schüsselwand ab. In diese Luft investierst du die ganze Lockerheit des Kuchens: Wer hier ungeduldig ist, bekommt später einen festen, kompakten Teig. Die Masse sollte deutlich heller und fast doppelt so voluminös wie am Anfang sein.","dauer":5,"tipp":"Am besten gelingt die Masse mit Zimmertemperatur; ist die Küche kalt, schlägst du die Butter vorher kurz alleine glatt."},{"titel":"Eier einzeln einrühren","aktion":"mischen","text":"Verquirle die Eier mit Vanille in einem Krug und gib sie esslöffelweise zur Butter-Zucker-Masse, jeweils mit eingearbeitet, bevor die nächste Menge folgt. Der Teig muss dabei glatt und glänzend bleiben. Beginnt er zu gerinnen – er sieht dann körnig und schwammig aus – rühre jeweils einen Esslöffel Mehl unter, das bindet die überschüssige Flüssigkeit und rettet die Emulsion. Wer die Eier zu schnell zufügt, verliert die Luft im Teig.","dauer":4,"tipp":""},{"titel":"Mehl unterheben","aktion":"mischen","text":"Siebe Mehl, Backpulver und Salz auf die Masse und hebe es mit dem Teigschaber in großen Achtern von unten nach oben unter, bis gerade kein Mehl mehr zu sehen ist. Der Teig soll cremig sein und schwer vom Löffel reißen: Fällt er in einem trägen Klecks, ist er richtig; hält er stur am Löffel, gibst du einen Esslöffel Milch dazu. Nicht kräftig rühren, sonst wird das Klebereiweiß aktiv und die Böden werden zäh.","dauer":3,"tipp":""},{"titel":"Teig teilen und einfüllen","aktion":"fuellen","text":"Teile den Teig gleichmäßig auf beide Formen auf – wiege ihn am besten ab, damit die Böden gleich hoch werden. Streiche die Oberflächen mit dem Löffelrücken glatt und drücke die Mitte leicht ein, damit die Böden nicht kuppeln. Klopfe die Formen einmal auf die Arbeitsplatte, damit große Luftblasen entweichen, und schiebe sie ohne Verzögerung nebeneinander in den Ofen.","dauer":5,"tipp":""},{"titel":"Backen und Garprobe","aktion":"backen","text":"Backe die Böden 22 bis 25 Minuten. Öffne die Tür in den ersten 15 Minuten nicht, denn kalte Luft lässt den Teig in der Mitte einfallen. Die Böden sind fertig, wenn sie hellgoldbraun sind, sich vom Rand leicht lösen und beim Druck mit dem Finger in der Mitte zurückfedern, ohne eine Delle zu hinterlassen. Das Holzstäbchen soll sauber herauskommen. Eine rosa, feuchte Mitte bedeutet noch fünf Minuten weiter.","dauer":24,"tipp":""},{"titel":"Auskühlen","aktion":"kuehlen","text":"Lass die Böden fünf Minuten in der Form stehen und löse sie dann mit einem Messer am Rand. Stürze sie auf ein Kuchengitter, ziehe das Papier ab und lass sie vollständig abkühlen, mindestens 45 Minuten. Nur ausgekühlte Böden vertragen die Sahne, sonst schmilzt die Füllung, und der Kuchen rutscht. Dreh den zweiten Boden mit der Oberseite nach oben um, damit die Deckelfläche flach bleibt.","dauer":45,"tipp":""},{"titel":"Füllen und zusammensetzen","aktion":"schichten","text":"Schlage die gekühlte Sahne mit dem Puderzucker steif, bis sie Spitzen zieht, aber noch cremig glänzt. Rühre die Marmelade glatt und streiche sie auf den unteren Boden bis fast an den Rand. Verteile die Sahne in einer gleichmäßigen Schicht darauf, am besten mit dem Spritzbeutel in Tupfen oder Wellen. Lege den zweiten Boden mit der gewölbten Seite nach oben darauf und drücke ihn nur ganz leicht an.","dauer":10,"tipp":""},{"titel":"Bestäuben und servieren","aktion":"garnieren","text":"Gib den Puderzucker in ein feines Sieb und bestäube die Oberseite des Kuchens gleichmäßig; für ein klassisches Muster kannst du eine Papierspitzendecke als Schablone verwenden. Stelle den Kuchen bis zum Servieren kühl, aber nicht länger als zwei Stunden, damit die Böden nicht durchweichen. Schneide ihn mit einem Sägemesser mit leichtem Hin- und Herbewegen an, damit die Sahne nicht herausgedrückt wird.","dauer":0,"tipp":""}],"profitipps":["Die Gleichgewichtsregel: Wiege zuerst die Eier mit Schale und nimm das gleiche Gewicht an Butter, Zucker und Mehl.","Eier immer einzeln und langsam zugeben, gerinnt die Masse, hilft ein Löffel Mehl.","Ofentür in den ersten 15 Minuten geschlossen halten.","Erst füllen, wenn die Böden vollständig kalt sind.","Nach dem Füllen wird der Kuchen am besten innerhalb weniger Stunden gegessen."],"varianten":["Mit Lemon Curd und Sahne.","Mit Buttercreme statt Sahne (zwischen den Marmeladenschichten).","Mit frischen Erdbeeren in der Sahne.","Als Cupcakes mit gleichem Teig, 18 Minuten bei 175 °C."],"beilagen":["Afternoon Tea","Frische Erdbeeren"],"getraenk":"Schwarzer Tee (Earl Grey, Assam) mit Milch","quellen":[{"titel":"Victoria sponge – Wikipedia","url":"https://en.wikipedia.org/wiki/Victoria_sponge"}],"bild":"kuchen","farben":["#f3d9a0","#c0392b","#fff8e7"],"schlagworte":["Afternoon Tea","Klassiker","Erdbeermarmelade"]},{"id":"britisch-irisch-christmas-pudding-mit-brandy-butter","name":"Christmas Pudding mit Brandy Butter","originalname":"Christmas Pudding","kueche":"britisch-irisch","region":"England","beliebtheit":86,"hauptkategorie":"suess","gang":"dessert","themen":["fest"],"kurz":"Der dunkle, gedämpfte Weihnachtspudding voller Trockenfrüchte, Gewürze und Brandy – flambiert aufgetragen, mit einer Haube aus Brandy Butter.","hintergrund":"Der Christmas Pudding stammt vom mittelalterlichen Plum Pottage ab, einem Eintopf aus Fleisch, Früchten und Gewürzen, und wurde im 17. und 18. Jahrhundert zum süßen Pudding mit Trockenfrüchten und Rindernierenfett. In Großbritannien rührt man ihn traditionell am „Stir-up Sunday“ an, dem letzten Sonntag vor dem Advent, wobei jedes Familienmitglied einmal im Uhrzeigersinn rührt und sich dabei etwas wünscht. Der Pudding reift dann wochenlang an einem kühlen, dunklen Ort. Am ersten Weihnachtstag wird er erneut gedämpft, mit angewärmtem Brandy übergossen, angezündet und unter Applaus ins verdunkelte Esszimmer getragen, mit einem Stechpalmenzweig gekrönt. In manchen Familien versteckt man eine Silbermünze im Teig, die dem Finder Glück bringen soll.","portionen":8,"zeit":{"vorbereitung":45,"garen":480,"ruhen":1440},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Pudding (1-Liter-Form)","liste":[{"menge":250,"einheit":"g","name":"Sultaninen","hinweis":""},{"menge":150,"einheit":"g","name":"Korinthen","hinweis":"kleine dunkle Rosinen; notfalls dunkle Rosinen"},{"menge":100,"einheit":"g","name":"Rosinen","hinweis":""},{"menge":50,"einheit":"g","name":"Orangeat und Zitronat, fein gehackt","hinweis":""},{"menge":1,"einheit":"Stück","name":"säuerlicher Apfel, grob gerieben","hinweis":"z. B. Boskoop oder Cox, mit Schale"},{"menge":100,"einheit":"ml","name":"Brandy (und etwas Rum)","hinweis":"zum Einlegen"},{"menge":1,"einheit":"Stück","name":"Bio-Orange, Schale und Saft","hinweis":""},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone, Schale","hinweis":""},{"menge":110,"einheit":"g","name":"Weißbrotbrösel","hinweis":"frisch, aus entrindetem Toast"},{"menge":110,"einheit":"g","name":"Rindernierenfett (Suet) oder gefrorene Butter, gerieben","hinweis":"Suet beim Metzger oder als Pflanzen-Suet; alternativ geriebene gefrorene Butter"},{"menge":110,"einheit":"g","name":"dunkler Muscovadozucker","hinweis":"alternativ brauner Zucker"},{"menge":50,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":50,"einheit":"g","name":"gehackte Mandeln","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eier, Größe L","hinweis":""},{"menge":1,"einheit":"EL","name":"Zuckerrübensirup (Black Treacle) oder Melasse","hinweis":"gibt die dunkle Farbe; ersatzweise Zuckerrübensirup/Rübenkraut"},{"menge":1,"einheit":"TL","name":"Lebkuchengewürz oder „Mixed Spice“","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":0.25,"einheit":"TL","name":"frisch geriebene Muskatnuss","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":null,"einheit":"","name":"Butter und Backpapier zum Auskleiden der Form","hinweis":""}]},{"gruppe":"Zum Flambieren","liste":[{"menge":50,"einheit":"ml","name":"Brandy","hinweis":"mindestens 40 % Alkohol"},{"menge":1,"einheit":"Zweig","name":"Stechpalme zur Dekoration","hinweis":"giftige Beeren nicht mitessen; alternativ Rosmarin"}]},{"gruppe":"Für die Brandy Butter","liste":[{"menge":125,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":125,"einheit":"g","name":"Puderzucker, gesiebt","hinweis":""},{"menge":3,"einheit":"EL","name":"Brandy","hinweis":"nach und nach einrühren"}]}],"ausruestung":["Puddingform oder Keramikschüssel (1 Liter) mit Deckel","Backpapier und Alufolie","Küchengarn","großer Topf mit Deckel und Untersetzer oder Dämpfeinsatz","Rührschüssel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle sie bereit: Trockenfrüchte, Orangeat und Zitronat, Brösel, Mehl, Gewürze und Zucker. Hacke Orangeat und Zitronat fein, reibe von der Orange und der Zitrone nur die gelbe oder orange Schale (nicht das bittere Weiß) ab und presse die Orange aus. Reibe den Apfel auf der groben Seite der Küchenreibe, ohne ihn zu schälen. Das Rindernierenfett bestellst du vorab beim Metzger und lässt es durch den Fleischwolf drehen oder reibst es gefroren auf einer groben Reibe, damit es sich später gleichmäßig verteilt.","dauer":0,"tipp":"Echten Suet gibt es auch fertig in Packungen in Briten-Läden; mit gefrorener, geriebener Butter gelingt der Pudding aber ebenfalls."},{"titel":"Früchte über Nacht einlegen","aktion":"marinieren","text":"Gib Sultaninen, Korinthen, Rosinen, Orangeat, Zitronat, Apfel, Orangensaft, Schalenabrieb und den Brandy in eine große Schüssel und rühre alles gründlich um. Decke die Schüssel ab und lasse die Früchte mindestens 12, besser 24 Stunden bei Zimmertemperatur ziehen, bis sie prall und glänzend geworden sind und fast die ganze Flüssigkeit aufgesogen haben. So bleibt der Pudding später saftig und schmeckt nach Brandy statt nach trockenen Rosinen. Rühre die Mischung zwischendurch ein-, zweimal um und prüfe, ob alle Früchte gut mit der Flüssigkeit in Berührung gekommen sind.","dauer":0,"tipp":""},{"titel":"Teig anrühren und Wünsche rühren","aktion":"mischen","text":"Vermische in einer zweiten, sehr großen Schüssel Brösel, Mehl, Zucker, Gewürze, Salz, Mandeln und das geriebene Fett mit den Händen, bis alles gleichmäßig verteilt ist. Gib die eingelegten Früchte zusammen mit der Flüssigkeit dazu, verquirle die Eier mit dem Sirup und rühre auch sie ein. Der Teig ist fest, dunkel und riecht stark nach Brandy und Weihnachtsgewürzen. Jetzt folgt die Tradition: Jeder rührt einmal von Osten nach Westen (im Uhrzeigersinn) und wünscht sich dabei etwas. Wenn du eine saubere Silbermünze einrühren willst, tust du das jetzt.","dauer":15,"tipp":"Schmecke nicht von der rohen Masse – wegen der rohen Eier; du erkennst gute Würze am intensiven Duft."},{"titel":"Form füllen und verschließen","aktion":"fuellen","text":"Fette die Puddingform dick mit Butter ein und lege den Boden mit einem Kreis Backpapier aus. Fülle den Teig in die Form und drücke ihn mit dem Löffelrücken fest, sodass keine Lufttaschen bleiben; die Form sollte höchstens zu vier Fünfteln gefüllt sein, da der Pudding beim Dämpfen aufgeht. Lege einen Kreis Backpapier auf die Oberfläche. Falte aus Backpapier und Alufolie einen Deckel mit einer Mittelfalte (damit er sich ausdehnen kann), lege ihn auf die Form und binde ihn mit Küchengarn unterhalb des Randes fest. Befestige zum Anheben eine Schlinge aus Garn am Rand.","dauer":15,"tipp":"Ein dichter Deckel hält Dampf und Wasser draußen – ein nasser Pudding wird matschig."},{"titel":"Sechs Stunden dämpfen","aktion":"daempfen","text":"Stelle die Form auf einen Untersetzer oder umgedrehten Teller in einen großen Topf mit Deckel und fülle kochendes Wasser ein, sodass es bis zur Hälfte der Form reicht. Lass das Wasser auf kleiner Hitze sanft sieden, nicht sprudelnd kochen, und dämpfe den Pudding mit geschlossenem Deckel insgesamt sechs Stunden. Kontrolliere stündlich den Wasserstand und fülle mit kochendem Wasser auf, damit der Topf nie trocken läuft. Der Pudding färbt sich im Lauf der Zeit von hellbraun zu tiefem Schokoladenbraun, und die Küche duftet nach Gewürzen und Trockenfrüchten.","dauer":360,"tipp":"Mit einem Schnellkochtopf verkürzt sich die Garzeit auf etwa zwei Stunden; halte dich an die Herstelleranleitung."},{"titel":"Reifen lassen","aktion":"ruhen","text":"Hebe den Pudding aus dem Topf, lass ihn abkühlen und tausche den feuchten Papierdeckel gegen einen frischen aus. Wickle die Form in Backpapier und Alufolie und bewahre sie an einem kühlen, dunklen und trockenen Ort auf, am besten vier bis acht Wochen. In dieser Zeit verbinden sich die Aromen, der Alkohol rundet den Geschmack ab und der Pudding wird dichter und aromatischer. Alle ein bis zwei Wochen kannst du ihn mit einem Löffel Brandy „füttern“: Stich dazu mit einem Spieß mehrere Löcher hinein, träufle den Brandy darüber und verschließe die Form wieder.","dauer":1440,"tipp":"In Familien mit Tradition wird der Pudding schon am Stir-up Sunday gemacht, und die Gäste dürfen jeweils einmal mitrühren."},{"titel":"Am Festtag erneut dämpfen","aktion":"daempfen","text":"Am Weihnachtstag stellst du die Form zwei Stunden lang erneut in den leise siedenden Wasserbad-Topf, genauso wie beim ersten Mal. Der Pudding erwärmt sich dabei gleichmäßig bis in die Mitte, wird weich und feucht und gibt seinen dunklen, fruchtigen Duft ab. Löse den Deckel, ziehe mit einem Messer am Rand entlang und stürze den Pudding vorsichtig auf einen vorgewärmten Teller. Er sollte glänzend, tiefbraun und fest sein, aber nicht trocken; zerfällt er, war die Form zu voll oder er hat zu stark gekocht.","dauer":120,"tipp":"Es geht auch im Mikrowellenherd (in der Schüssel mit Folie), wenn es schnell gehen muss, aber die Dämpfung gibt die schönere Textur."},{"titel":"Flambieren","aktion":"flambieren","text":"Erwärme den Brandy in einem kleinen Topf, bis er lauwarm ist und leicht dampft, nicht heiß, sonst entzündet er sich im Topf. Drücke den Stechpalmenzweig oben in den Pudding. Dunkle den Raum ab, gieße den warmen Brandy darüber, halte ein langes Streichholz an den Rand und trage den Pudding mit blau flackernden Flammen zu Tisch. Die Flammen brennen etwa eine halbe Minute und sind sehr eindrucksvoll. Halte lange Haare und Ärmel fern und lösche bei Bedarf mit einem Deckel; verbrennende Tischtücher gehören nicht zur Tradition.","dauer":5,"tipp":"Warmer Alkohol zündet besser; kalter Brandy lässt sich schwer entflammen."},{"titel":"Brandy Butter rühren und servieren","aktion":"aufschlagen","text":"Schlage die weiche Butter mit einem Handrührgerät 4 bis 5 Minuten cremig und hell auf, bis sie fast weiß aussieht und die Konsistenz von Schlagsahne hat. Siebe den Puderzucker darüber und rühre ihn nach und nach ein. Gieße den Brandy löffelweise dazu und rühre immer erst weiter, wenn er vollständig aufgenommen ist, damit die Masse nicht gerinnt. Forme daraus eine Rolle oder fülle sie in eine Schale und stelle sie kalt. Schneide den Pudding in Keile und serviere ihn heiß mit einem Klecks Brandy Butter, die auf dem warmen Stück langsam zerläuft.","dauer":10,"tipp":"Auch Vanillesauce, Sahne oder Rum-Rosinen-Sauce passen; in Irland gehört oft eine Whiskey-Sauce dazu."}],"profitipps":["Je länger die Reifezeit, desto besser: Vier Wochen sind das Minimum, viele Familien lagern ihn ein Jahr lang.","Dämpfe nie auf kochender Flamme, sondern bei leisem Sieden, sonst kocht Wasser in den Teig.","Gefrorene, geriebene Butter ersetzt Suet gut und macht den Pudding leichter.","Der Deckel aus Papier und Folie braucht eine Falte in der Mitte, sonst platzt er beim Aufgehen.","Reste kannst du in Scheiben schneiden und in Butter goldbraun braten – ein beliebtes Frühstück am zweiten Weihnachtstag."],"varianten":["Mit Guinness oder Portwein statt Brandy (irische Version)","Ohne Alkohol: Früchte in Orangensaft und starkem Tee einlegen","Mit getrockneten Kirschen, Cranberrys und Ingwer statt Orangeat","Als kleine Portionspuddings in Tassen, Garzeit 1,5 Stunden"],"beilagen":["Brandy Butter","Vanillesauce (Custard)","geschlagene Sahne","Mince Pies"],"getraenk":"Süßer Sherry, Portwein oder ein starker englischer Tee","koeche":[{"name":"Nigella Lawson","bezug":"Nigella hat auf ihrer Website eine ‚ultimative‘ Christmas-Pudding-Version, die sie als verlässlichen Weihnachtsklassiker anbietet.","quelle":"https://nigella.com/recipes/ultimate-christmas-pudding"},{"name":"Jamie Oliver","bezug":"Jamie Oliver bietet ein eigenes Christmas-Pudding-Rezept an und erklärt auf seiner Seite auch die Tradition des Stir-up Sunday.","quelle":"https://www.jamieoliver.com/recipes/fruit/christmas-pudding"}],"quellen":[{"titel":"Nigella Lawson – Ultimate Christmas Pudding","url":"https://nigella.com/recipes/ultimate-christmas-pudding"},{"titel":"Jamie Oliver – Christmas Pudding","url":"https://www.jamieoliver.com/recipes/fruit/christmas-pudding"},{"titel":"British Heritage – Christmas Pudding Recipe","url":"https://britishheritage.com/christmas-pudding-recipe"}],"bild":"dessert","farben":["#3b1f12","#7a4a2a","#c9a36a"],"schlagworte":["Weihnachten","England","Pudding","Stir-up Sunday","Flambieren"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-beef-wellington","name":"Beef Wellington","originalname":"Beef Wellington","kueche":"britisch-irisch","region":"England","beliebtheit":86,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zartes Rinderfilet mit Pilz-Duxelles und Parmaschinken im knusprigen Blätterteigmantel – das Festtagsgericht mit Showeffekt.","hintergrund":"Beef Wellington besteht aus Rinderfilet und Pilz-Duxelles im Blätterteigmantel. Der Name wird meist auf Arthur Wellesley, den ersten Herzog von Wellington, zurückgeführt, doch der Ursprung ist unklar. Ähnliche Gerichte gab es in Frankreich als Filet de boeuf en croûte, und das Rezept tauchte in den USA 1899 auf Speisekarten auf. Schinken oder Crêpes um das Fleisch halten die Feuchtigkeit des Duxelles zurück, damit der Teig nicht durchweicht. Berühmt wurde es heute vor allem durch Gordon Ramsay.","portionen":6,"zeit":{"vorbereitung":60,"garen":40,"ruhen":75},"schwierigkeit":3,"zutaten":[{"gruppe":"Fleisch","liste":[{"menge":800,"einheit":"g","name":"Rinderfilet-Mittelstück","hinweis":"gleichmäßig dick, pariert, vom Metzger vorbestellen"},{"menge":2,"einheit":"EL","name":"Rapsöl","hinweis":"zum Anbraten"},{"menge":2,"einheit":"EL","name":"Dijonsenf","hinweis":""},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Duxelles","liste":[{"menge":500,"einheit":"g","name":"braune Champignons","hinweis":"sehr fein gehackt oder im Mixer zerkleinert"},{"menge":2,"einheit":"Stück","name":"Schalotten","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":4,"einheit":"Zweig","name":"Thymian","hinweis":"Blättchen abgezupft"},{"menge":20,"einheit":"g","name":"Butter","hinweis":""}]},{"gruppe":"Hülle","liste":[{"menge":10,"einheit":"Scheibe","name":"Parmaschinken (Prosciutto)","hinweis":"hauchdünn geschnitten"},{"menge":450,"einheit":"g","name":"Blätterteig, frisch (aus Butter)","hinweis":"aus dem Kühlregal, ca. 3 mm dick ausgerollt"},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":"mit 1 EL Milch verquirlt, zum Bestreichen"},{"menge":1,"einheit":"TL","name":"grobes Meersalz","hinweis":"zum Bestreuen, optional"}]}],"ausruestung":["schwere Pfanne","Frischhaltefolie","Backblech mit Backpapier","Bratenthermometer","Pinsel","Nudelholz"],"schritte":[{"titel":"Planen, Fleisch vorbereiten und würzen","aktion":"vorbereiten","text":"Nimm das Filet 1 Stunde vor dem Anbraten aus dem Kühlschrank und tupfe es trocken. Binde es bei Bedarf mit Küchengarn in gleichmäßige Zylinderform, damit es gleichmäßig gart; schmale Enden schlägst du ein. Salze und pfeffere das Fleisch rundum großzügig. Lege Zutaten und Utensilien bereit: Das Gericht besteht aus mehreren Arbeitsschritten und braucht Platz auf der Arbeitsfläche. Plane die Ruhezeiten ein, sodass du nach dem Anbraten mindestens 1 Stunde bis zum Backen hast.","dauer":0,"tipp":""},{"titel":"Filet scharf anbraten","aktion":"anbraten","text":"Erhitze das Öl in einer schweren Pfanne, bis es leicht raucht. Brate das Filet rundum 1 bis 2 Minuten pro Seite an, bis es überall dunkel gebräunt ist, auch an den Enden. Es soll nur eine Kruste bekommen, nicht innen garen, daher kurz und heiß. Nimm es heraus, lasse es auf einem Gitter 5 Minuten abkühlen und bestreiche es noch warm rundum mit Dijonsenf. Der Senf würzt das Fleisch und hilft dem Schinken später, am Fleisch zu haften.","dauer":8,"tipp":"Ein trockenes Filet und eine heiße Pfanne sind das A und O für eine schöne Kruste."},{"titel":"Pilz-Duxelles trocken kochen","aktion":"braten","text":"Hacke die Pilze sehr fein oder zerkleinere sie portionsweise im Mixer, bis sie fast krümelig sind. Schmilz die Butter in der Pfanne, gib Schalotten, Knoblauch und Thymian hinein und gare sie 2 Minuten. Füge die Pilze hinzu und brate sie bei hoher Hitze 12 bis 15 Minuten unter häufigem Rühren, bis alle Flüssigkeit verdampft ist und die Masse trocken, dunkel und pastös aussieht. Würze mit Salz und Pfeffer und lasse sie vollständig abkühlen. Das Austrocknen ist entscheidend, denn nasse Füllung macht den Teig matschig.","dauer":15,"tipp":"Die Duxelles ist fertig, wenn sich ein Löffel durch die Pfanne ziehen lässt und kein Wasser mehr zusammenläuft."},{"titel":"Schinken und Duxelles anordnen","aktion":"schichten","text":"Lege ein großes Stück Frischhaltefolie auf die Arbeitsfläche und überlappe die Schinkenscheiben darauf in zwei Reihen zu einem Rechteck, das das Filet umhüllen kann. Verstreiche die abgekühlte Duxelles gleichmäßig und dünn über den Schinken. Setze das Filet an den Rand und rolle es mithilfe der Folie fest ein, sodass eine glatte Walze entsteht. Drehe die Enden der Folie wie ein Bonbon zusammen, damit die Rolle straff und gleichmäßig wird.","dauer":10,"tipp":""},{"titel":"Kühlen und straff werden lassen","aktion":"kuehlen","text":"Stelle die eingewickelte Rolle für mindestens 30 Minuten, besser 1 Stunde, in den Kühlschrank. Sie wird fest, behält ihre Form beim späteren Einwickeln in den Teig, und das Fleisch bleibt kalt, was später die Garzeit im Ofen kontrolliert. Heize den Ofen währenddessen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor und lege ein Backblech mit Backpapier bereit.","dauer":40,"tipp":""},{"titel":"In Blätterteig einschlagen","aktion":"rollen","text":"Rolle den Blätterteig auf einer leicht bemehlten Fläche auf etwa 3 mm Dicke und so groß aus, dass er die Rolle rundum mit 2 cm Überlappung umschließt. Packe das Filet aus der Folie aus und lege es auf den Teig. Bestreiche die Teigränder mit Eigelb, schlage den Teig darüber, drücke die Naht fest zusammen und schneide überschüssigen Teig an den Enden ab. Lege die Rolle mit der Naht nach unten aufs Blech. Der Teig sollte überall dicht schließen, damit kein Saft auslaufen kann.","dauer":10,"tipp":""},{"titel":"Bestreichen und Muster ritzen","aktion":"garnieren","text":"Bestreiche die gesamte Oberfläche mit dem Eigelb-Milch-Gemisch und ritze mit der Rückseite eines Messers sanft ein Rautenmuster hinein, ohne den Teig zu durchschneiden. Streue optional etwas grobes Salz darüber. Stelle das Blech für 15 bis 20 Minuten zurück in den Kühlschrank; der kalte Teig geht im Ofen höher auf und wird knuspriger.","dauer":20,"tipp":"Zwei dünne Schichten Eigelb ergeben die schönste Farbe."},{"titel":"Backen","aktion":"backen","text":"Schiebe das Blech in die Mitte des Ofens und backe das Wellington 30 bis 35 Minuten, bis der Teig tief goldbraun und knusprig ist. Mit einem Bratenthermometer kannst du den Garpunkt prüfen: Für rosa Fleisch solltest du den Ofen bei einer Kerntemperatur von 48 bis 50 °C verlassen, da das Fleisch noch nachgart. Falls der Teig zu schnell bräunt, decke ihn locker mit Alufolie ab.","dauer":33,"tipp":"Ohne Bratenthermometer ist Beef Wellington ein Ratespiel – das Gerät lohnt sich."},{"titel":"Ruhen lassen und tranchieren","aktion":"ruhen","text":"Nimm das Wellington aus dem Ofen und lasse es 10 bis 15 Minuten auf einem Brett ruhen. In dieser Zeit steigt die Kerntemperatur auf etwa 55 °C, und der Fleischsaft verteilt sich gleichmäßig. Schneide es mit einem scharfen Sägemesser in etwa 2,5 cm dicke Scheiben, ohne zu drücken. Serviere sofort mit Rotweinsauce, Kartoffelpüree und grünem Gemüse.","dauer":12,"tipp":""}],"profitipps":["Duxelles gründlich trocken braten: Feuchtigkeit ist der Feind des knusprigen Blätterteigs.","Parmaschinken oder Crêpes bilden eine Barriere zwischen Fleisch und Teig, wie Gordon Ramsay es mit Schnittlauch-Crêpes macht.","Gut kühlen, bevor das Wellington in den Ofen kommt: Das hält die Form und macht den Teig knusprig.","Kerntemperatur mit dem Thermometer prüfen; 48 bis 50 °C beim Herausnehmen ergeben rosa Fleisch.","Wellington lässt sich bis zum Einwickeln am Vortag vorbereiten und im Kühlschrank lagern."],"varianten":["Mit Schnittlauch-Crêpes statt Parmaschinken, wie bei Gordon Ramsay","Mit Gänseleberpastete zwischen Fleisch und Duxelles für die Luxusversion","Als einzelne Mini-Wellingtons pro Gast","Vegetarisches Wellington mit Rote Bete oder Nussbraten"],"beilagen":["Kartoffelpüree","Röstkartoffeln","grüne Bohnen","Rotweinsauce"],"getraenk":"Kräftiger Rotwein wie Pauillac, Rioja Reserva oder Syrah.","koeche":[{"name":"Gordon Ramsay","bezug":"Sein Beef Wellington ist weltberühmt: Er brät das Filet kurz an, bestreicht es mit Senf, umhüllt es mit Duxelles, Parmaschinken und Schnittlauch-Crêpes und backt es im Blätterteig. 2023 stellte er mit Nick DiGiovanni einen Guinness-Weltrekord für das größte Beef Wellington auf.","quelle":"https://masterclass.com/articles/gordon-ramsays-beef-wellington-recipe"}],"quellen":[{"titel":"Beef Wellington – Wikipedia","url":"https://en.wikipedia.org/wiki/Beef_Wellington"},{"titel":"MasterClass – Gordon Ramsay's Beef Wellington Recipe","url":"https://masterclass.com/articles/gordon-ramsays-beef-wellington-recipe"},{"titel":"Gordon Ramsay – Wikipedia","url":"https://en.wikipedia.org/wiki/Gordon_Ramsay"}],"bild":"braten-scheiben","farben":["#c58a4a","#7a2f2a","#e6c88e"],"schlagworte":["Festtag","Gordon Ramsay","Blätterteig","Filet"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-shepherds-pie","name":"Shepherd's Pie","originalname":"Shepherd's Pie","kueche":"britisch-irisch","region":"England","beliebtheit":85,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Würziges Lammragout mit Gemüse unter einer goldbraunen Kartoffelhaube – britisches Seelenfutter aus dem Ofen.","hintergrund":"Shepherd's Pie besteht aus Hackfleisch, traditionell vom Lamm oder Hammel, das mit Kartoffelpüree bedeckt und überbacken wird. Der Begriff Cottage Pie ist bereits 1791 belegt, Shepherd's Pie kam später auf. Strikt unterscheidet man in Großbritannien meist nach dem Fleisch: Lamm für Shepherd's Pie, Rind für Cottage Pie, wobei viele Köche die Namen austauschbar verwenden. Ursprünglich verwertete man Fleischreste vom Sonntagsbraten. Ähnliche Gerichte gibt es in Frankreich als Hachis Parmentier. Eine vegetarische Version wurde schon 1898 veröffentlicht.","portionen":6,"zeit":{"vorbereitung":30,"garen":90,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Lammragout","liste":[{"menge":700,"einheit":"g","name":"Lammhack","hinweis":"beim Metzger bestellen oder Keule selbst durchdrehen lassen"},{"menge":2,"einheit":"EL","name":"Rapsöl","hinweis":""},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gewürfelt"},{"menge":2,"einheit":"Stück","name":"Karotten","hinweis":"in 5 mm große Würfel geschnitten"},{"menge":2,"einheit":"Stange","name":"Staudensellerie","hinweis":"fein gewürfelt"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":2,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":2,"einheit":"EL","name":"Mehl","hinweis":""},{"menge":100,"einheit":"ml","name":"Rotwein","hinweis":"optional, ersatzweise mehr Fond"},{"menge":400,"einheit":"ml","name":"Lamm- oder Rinderfond","hinweis":""},{"menge":2,"einheit":"EL","name":"Worcestershiresauce","hinweis":""},{"menge":2,"einheit":"Zweig","name":"Thymian","hinweis":""},{"menge":1,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":150,"einheit":"g","name":"Erbsen, tiefgekühlt","hinweis":""}]},{"gruppe":"Kartoffelhaube","liste":[{"menge":1,"einheit":"kg","name":"mehligkochende Kartoffeln","hinweis":"geschält und geviertelt"},{"menge":60,"einheit":"g","name":"Butter","hinweis":""},{"menge":100,"einheit":"ml","name":"Milch","hinweis":"heiß"},{"menge":1,"einheit":"Stück","name":"Eigelb","hinweis":"für schöne Bräunung"},{"menge":50,"einheit":"g","name":"Cheddar","hinweis":"gerieben, optional"},{"menge":null,"einheit":"","name":"Salz, Pfeffer, Muskat","hinweis":""}]}],"ausruestung":["große Pfanne oder Schmortopf","Auflaufform (ca. 2 l)","Kartoffelpresse oder Stampfer","Gabel zum Muster ziehen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Zwiebeln, Karotten und den Sellerie und würfele alles in etwa 5 mm große Stücke; die gleichmäßige, kleine Größe sorgt dafür, dass das Gemüse später beim Schmoren weich wird und sich in die Sauce einfügt. Hacke den Knoblauch fein und zupfe die Thymianblättchen ab. Schäle die Kartoffeln, viertele sie und lege sie in einen Topf. Heize den Ofen noch nicht vor, das kommt später. Stelle alle Zutaten bereit, damit das Anbraten nicht unterbrochen wird.","dauer":0,"tipp":""},{"titel":"Kartoffeln kochen","aktion":"kochen","text":"Bedecke die Kartoffelviertel mit kaltem Wasser, füge einen gestrichenen Teelöffel Salz hinzu und bringe sie zum Kochen. Lasse sie bei mittlerer Hitze 18 bis 22 Minuten garen, bis sie sich mit einem Messer ohne Widerstand durchstechen lassen. Gieße sie ab und lasse sie 3 Minuten im offenen Topf ausdampfen; je trockener die Kartoffeln, desto fluffiger das Püree. In dieser Zeit kannst du das Hackfleisch anbraten.","dauer":20,"tipp":""},{"titel":"Gemüse anschwitzen","aktion":"anbraten","text":"Erhitze 1 Esslöffel Öl in einem großen Schmortopf bei mittlerer Hitze und gib Zwiebeln, Karotten und Sellerie hinein. Gare sie 8 bis 10 Minuten unter Rühren, bis sie weich und leicht goldfarben sind und süßlich duften. Füge den Knoblauch hinzu und röste ihn 1 Minute mit, bis er duftet, aber nicht braun wird. Nimm das Gemüse heraus und stelle es beiseite.","dauer":10,"tipp":""},{"titel":"Lammhack kräftig anbraten","aktion":"anbraten","text":"Erhitze das restliche Öl im selben Topf bei hoher Hitze, bis es flimmert. Gib das Hack in zwei Portionen hinein und brate es 6 bis 8 Minuten, ohne es zu oft zu rühren, damit sich Röstaromen bilden; das Fleisch soll krümelig und dunkelbraun werden, nicht grau kochen. Gieße überschüssiges Fett ab. Das Anbraten in Portionen verhindert, dass zu viel Flüssigkeit austritt und das Fleisch dünstet statt brät.","dauer":12,"tipp":"Röstaromen sind der Geschmack: lieber dunkel braten als blass lassen."},{"titel":"Sauce ansetzen","aktion":"binden","text":"Gib das Gemüse zurück zum Hack und rühre das Tomatenmark ein. Lasse es 2 Minuten anrösten, damit es dunkler wird und die Säure verliert. Bestäube alles mit dem Mehl und rühre 1 Minute, bis keine trockenen Stellen mehr zu sehen sind. Lösche mit dem Rotwein ab und kratze den Bratensatz vom Boden, lass den Wein fast vollständig einkochen. Gieße den Fond und die Worcestershiresauce hinzu, lege Thymian und Lorbeer ein.","dauer":5,"tipp":""},{"titel":"Ragout schmoren","aktion":"schmoren","text":"Lasse die Sauce bei niedriger Hitze ohne Deckel 25 bis 30 Minuten leise köcheln, bis sie eingedickt ist und glänzt, ähnlich wie ein dickes Ragout. Rühre gelegentlich um. Die Konsistenz soll nicht zu flüssig sein, sonst weicht das Püree auf. Nimm Lorbeer und Thymianzweige heraus, rühre die Erbsen ein und schmecke mit Salz, Pfeffer und etwas Worcestershiresauce ab.","dauer":28,"tipp":""},{"titel":"Kartoffelpüree zubereiten","aktion":"puerieren","text":"Drücke die abgetropften Kartoffeln durch die Presse oder stampfe sie fein. Gib die Butter dazu und rühre sie unter, gieße dann die heiße Milch nach und nach hinein, bis das Püree glatt und cremig, aber noch fest genug ist, um seine Form zu halten. Würze mit Salz, weißem Pfeffer und etwas frisch geriebener Muskatnuss und rühre das Eigelb unter. Es sorgt später für eine goldbraune Kruste.","dauer":8,"tipp":""},{"titel":"Schichten und Muster ziehen","aktion":"schichten","text":"Heize den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor. Fülle das Ragout in die Auflaufform und streiche es glatt. Verteile das Püree mit einem Löffel darüber, beginne am Rand, damit es dicht schließt, und streiche es glatt. Ziehe mit einer Gabel Rillen über die Oberfläche; die Spitzen bräunen im Ofen besonders knusprig. Streue den Cheddar darüber.","dauer":8,"tipp":""},{"titel":"Überbacken und ruhen lassen","aktion":"ueberbacken","text":"Backe den Auflauf auf der mittleren Schiene 25 bis 30 Minuten, bis die Kartoffelhaube goldbraun ist und die Füllung am Rand blubbert. Stelle die Form, falls nötig, für 2 bis 3 Minuten unter den Grill, um die Spitzen zu bräunen. Lass den Auflauf 10 Minuten ruhen, damit sich die Sauce setzt und sich die Portionen sauber abstechen lassen. Serviere mit grünem Gemüse.","dauer":30,"tipp":"Ein Backblech unter der Form fängt überlaufende Sauce auf."}],"profitipps":["Das Ragout soll dick sein; zu flüssige Füllung weicht die Kartoffelhaube durch.","Mehlige Kartoffeln und ein Eigelb geben ein luftiges, goldbraunes Püree.","Hack in Portionen und bei hoher Hitze braten, damit Röstaromen entstehen.","Lamm ergibt Shepherd's Pie, Rind ergibt Cottage Pie; der Rest bleibt gleich.","Über Nacht durchgezogen schmeckt das Ragout noch besser; vor dem Überbacken wieder aufwärmen."],"varianten":["Cottage Pie mit Rinderhack","Mit Süßkartoffelpüree als Haube","Vegetarisch mit Linsen und Pilzen","Mit Käse überbacken oder mit einer Schicht Kartoffelscheiben unter dem Hack"],"beilagen":["grüne Erbsen","Brokkoli","Rotkohlsalat","Worcestershiresauce"],"getraenk":"Kräftiger Rotwein, englisches Bitter oder Guinness.","koeche":[],"quellen":[{"titel":"Shepherd's pie – Wikipedia","url":"https://en.wikipedia.org/wiki/Shepherd%27s_pie"}],"bild":"auflauf","farben":["#c9953f","#7a4a2a","#e8d3a0"],"schlagworte":["Auflauf","Comfort Food","Lamm","Pub"],"vegetarisch_moeglich":true},{"originalname":"Scottish shortbread","hauptkategorie":"suess","fleischsorte":"","gang":"gebaeck","bild":"gebaeck","vegetarisch_moeglich":true,"id":"britisch-irisch-shortbread","name":"Scottish Shortbread (Fingers und Petticoat Tails)","kueche":"britisch-irisch","region":"Schottland","beliebtheit":84,"kurz":"Butterzart, sandig und mit nur drei Hauptzutaten: das schottische Gebäck, das auf der Zunge zerfällt. Als Finger oder in Tortenstückform geschnitten gehört es zu jedem Tee.","hintergrund":"Shortbread stammt aus Schottland und wird dort seit dem Mittelalter gebacken, vermutlich beeinflusst von französischen Konditoren der „Auld Alliance“. Maria Stuart wird gern als Verfeinerin des Rezepts im 16. Jahrhundert genannt, der Beleg dafür ist allerdings dünn; das erste gedruckte Rezept stammt von einer Mrs McLintock aus dem Jahr 1736. Lange war es ein Luxus für Weihnachten, Hogmanay (Silvester) und Hochzeiten. Die klassische Faustregel lautet: ein Teil Zucker, zwei Teile Butter, drei bis vier Teile Weizenmehl, ganz ohne Backpulver. Der hohe Butteranteil bremst den Kleber und macht das Gebäck mürbe und kurz (englisch „short“). Die dreieckigen „Petticoat Tails“ entstehen, wenn man einen großen runden Fladen noch heiß in Keile schneidet.","portionen":16,"zeit":{"vorbereitung":20,"garen":30,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Teig (ca. 16 Fingers oder 8 Petticoat Tails)","liste":[{"menge":200,"einheit":"g","name":"Butter","hinweis":"echte, gute Butter, zimmerwarm und weich, aber nicht flüssig"},{"menge":100,"einheit":"g","name":"feiner Zucker","hinweis":"Caster Sugar oder Kristallzucker mit 30 Sekunden im Mixer fein gemahlen"},{"menge":250,"einheit":"g","name":"Weizenmehl Type 405"},{"menge":50,"einheit":"g","name":"Reismehl oder Speisestärke","hinweis":"ergibt die typische sandige Textur; Reismehl gibt es im Asialaden"},{"menge":0.25,"einheit":"TL","name":"feines Salz"},{"menge":1,"einheit":"EL","name":"Zucker zum Bestreuen","hinweis":"nach dem Backen, am besten feiner Zucker"}]}],"ausruestung":["Küchenwaage","Rührschüssel","Gabel zum Einstechen","Tarteform (20 cm) oder eckige Form (20 × 20 cm)","Backpapier","Kuchengitter"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm die Butter etwa eine Stunde vor dem Backen aus dem Kühlschrank, sie soll sich leicht eindrücken lassen, aber nicht glänzen oder schmieren. Heize den Ofen auf 160 °C Ober-/Unterhitze (140 °C Umluft) vor. Mische Mehl, Reismehl und Salz in einer Schüssel und siebe sie einmal durch, damit der Teig später gleichmäßig wird. Lege die Form mit Backpapier aus; für Petticoat Tails nimm eine runde Tarteform (20 cm), für Fingers eine eckige Form (ca. 20 × 20 cm).","dauer":10,"tipp":"Zu weiche oder warme Butter lässt den Teig fettig und beim Backen auseinanderlaufen."},{"titel":"Butter und Zucker verrühren","aktion":"mischen","text":"Verrühre Butter und Zucker mit einem Teigspatel oder Handmixer auf niedriger Stufe, bis sie gerade eben vermischt sind; das dauert nur ein bis zwei Minuten. Anders als bei Rührkuchen soll die Masse nicht schaumig aufgeschlagen werden, denn zu viel Luft lässt das Shortbread beim Backen aufgehen und verlaufen. Die Mischung sieht cremig und leicht körnig aus. Kratze mit dem Spatel den Rand der Schüssel ab, damit keine Butterklumpen übrig bleiben.","dauer":3,"tipp":"Weniger rühren ist hier mehr: Das Ziel ist ein dichter, kompakter Teig."},{"titel":"Mehl einarbeiten und zum Teig drücken","aktion":"kneten","text":"Gib die Mehlmischung zur Butter und arbeite sie mit den Fingerspitzen oder dem Teigspatel ein, bis ein krümeliger Teig entsteht, der beim Zusammendrücken zusammenhält. Drücke ihn zu einer Kugel und knete nur so lange, bis keine trockenen Stellen mehr sichtbar sind; jedes weitere Kneten aktiviert Gluten und macht das Gebäck zäh statt mürbe. Die Wärme deiner Hände schmilzt die Butter leicht an, weshalb du zügig arbeiten solltest.","dauer":5,"tipp":"Wird der Teig schmierig, 10 Minuten in den Kühlschrank legen und dann weiterarbeiten."},{"titel":"In die Form drücken und kalt stellen","aktion":"formen","text":"Drücke den Teig gleichmäßig in die Form, etwa 1 bis 1,5 cm dick, und streiche die Oberfläche mit dem Handrücken oder einem Löffelrücken glatt. Bei der runden Form drückst du den Rand mit zwei Fingern in kleine Wellen („crimpen“), das ist die traditionelle Petticoat-Optik. Steche die Oberfläche rundherum mit einer Gabel ein, damit der Dampf entweichen kann und die Fläche eben bleibt. Stelle die geformte Form 30 Minuten in den Kühlschrank; der kalte Teig behält seine Form besser und backt gleichmäßiger.","dauer":30,"tipp":"Mit einem Messer vorab Linien einritzen, wo du später schneidest – so brichst du die Stücke gerade."},{"titel":"Backen","aktion":"backen","text":"Backe das Shortbread in der Ofenmitte bei 160 °C Ober-/Unterhitze (140 °C Umluft) 25 bis 35 Minuten. Es soll nur ganz leicht Farbe annehmen: blass cremegelb mit goldbraunen Rändern, nicht dunkelbraun. Der Duft nach gebräunter Butter ist ein guter Hinweis, dass es fast fertig ist. Öffne den Ofen während der ersten 20 Minuten nicht, damit die Hitze konstant bleibt.","dauer":30,"tipp":"Lieber etwas zu hell als zu dunkel – Shortbread wird beim Auskühlen nach."},{"titel":"Noch warm schneiden und bestreuen","aktion":"schneiden","text":"Nimm die Form aus dem Ofen und schneide das Shortbread noch heiß mit einem scharfen Messer in Finger oder in 8 Keile; nach dem Auskühlen wäre es zu brüchig. Bestreue die warme Oberfläche sofort mit feinem Zucker, der an der Butter haftet und eine feine, süße Kruste bildet. Lass das Gebäck 10 Minuten in der Form ruhen, weil es heiß noch sehr weich ist, und hebe es dann vorsichtig auf ein Kuchengitter.","dauer":12,"tipp":"Mit einer Gabel nochmals nachstechen, wenn sich beim Schneiden Blasen gebildet haben."},{"titel":"Auskühlen und lagern","aktion":"ruhen","text":"Lass die Stücke auf dem Gitter komplett auskühlen; erst jetzt wird die Textur richtig sandig und knusprig. Bewahre sie in einer luftdichten Dose bis zu zwei Wochen auf. Das Aroma der Butter entfaltet sich am zweiten Tag noch besser. Wickelst du das Shortbread einzeln ein, lässt es sich bis zu drei Monate einfrieren.","dauer":30,"tipp":""}],"profitipps":["Verhältnis 1 : 2 : 3 (Zucker : Butter : Mehl) ist die klassische Grundlage.","Gute Butter ist der einzige Geschmacksträger – hier lohnt sich Markenbutter oder irische Butter.","Den Teig nur kurz zusammenfügen; langes Kneten macht Shortbread hart.","Heiß schneiden, kalt aufbewahren – nur so brechen die Stücke gerade.","Reismehl macht das Gebäck sandiger und feiner; ohne geht es auch, aber weniger zart."],"varianten":["Pitcaithly Bannock mit kandierter Orangenschale und Mandeln","Ayrshire Shortbread mit Eigelb und etwas Sahne im Teig","Dorset-Art mit Demerara-Zucker außen","Mit Zitronenabrieb oder Lavendel verfeinert"],"beilagen":["Tee","Erdbeeren mit Clotted Cream","Vanilleeis"],"getraenk":"Schwarzer Tee (Assam, Earl Grey) oder ein Schluck Single Malt","koeche":[{"name":"Mary Berry","bezug":"Auf einer britischen Familienseite wird ein Scottish-Shortbread-Rezept ausdrücklich als an Mary Berry angelehnt geführt: Butter in Mehl einreiben, nur kurz kneten, mit Demerara-Zucker bestreuen und bei 160 °C 15–20 Minuten backen.","quelle":"https://www.cookingwithmykids.co.uk/scottish-shortbread/"}],"quellen":[{"titel":"Shortbread – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Shortbread"},{"titel":"Scottish shortbread (Mary Berry's) – Cooking with my kids","url":"https://www.cookingwithmykids.co.uk/scottish-shortbread/"}],"farben":["#e8c887","#c9954b","#fff3d6"],"schlagworte":["Schottland","Butter","Teezeit","Klassiker","Hogmanay"]},{"id":"britisch-irisch-sticky-toffee-pudding","name":"Sticky Toffee Pudding","originalname":"Sticky Toffee Pudding","kueche":"britisch-irisch","region":"England (Lake District)","beliebtheit":82,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Saftiger Dattelkuchen, getränkt in warmer Toffeesauce und mit Vanilleeis serviert – das beliebteste Dessert der britischen Pubs.","hintergrund":"Über die Herkunft des Sticky Toffee Pudding wird gestritten. Meist nennt man Francis Coulson und Robert Lee, die ihn in den 1970ern im Sharrow Bay Country House Hotel im Lake District bekannt machten. Andere Quellen verweisen auf das Gait Inn in Yorkshire oder auf das Udny Arms Hotel in Schottland. Der Teig ist ein feuchter Dattelkuchen, die Sauce besteht aus Sahne und dunklem Zucker. 1989 entwickelte der Village Shop in Cartmel eine Fertigversion, die ab Ende der 1990er in britischen Supermärkten verkauft wurde.","portionen":8,"zeit":{"vorbereitung":30,"garen":40,"ruhen":15},"schwierigkeit":1,"zutaten":[{"gruppe":"Dattelkuchen","liste":[{"menge":200,"einheit":"g","name":"entsteinte Datteln","hinweis":"weiche Medjool- oder Deglet-Nour-Datteln, grob gehackt"},{"menge":250,"einheit":"ml","name":"kochendes Wasser","hinweis":""},{"menge":1,"einheit":"TL","name":"Natron","hinweis":"Backsoda; erhältlich im Backregal oder in der Apotheke"},{"menge":60,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":150,"einheit":"g","name":"brauner Zucker","hinweis":"am besten Muscovado"},{"menge":2,"einheit":"Stück","name":"Eier, Größe M","hinweis":""},{"menge":175,"einheit":"g","name":"Weizenmehl","hinweis":""},{"menge":2,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":1,"einheit":"EL","name":"dunkler Zuckerrübensirup","hinweis":"oder Melasse (Black Treacle)"},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":""}]},{"gruppe":"Toffeesauce","liste":[{"menge":150,"einheit":"g","name":"Butter","hinweis":""},{"menge":200,"einheit":"g","name":"brauner Zucker","hinweis":"Muscovado oder dunkler Rohrzucker"},{"menge":300,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"EL","name":"dunkler Zuckerrübensirup","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":8,"einheit":"Stück","name":"Kugeln Vanilleeis oder Vanillesauce","hinweis":""}]}],"ausruestung":["quadratische Form (20 x 20 cm)","Topf für die Sauce","Schneebesen oder Handmixer","Stäbchen oder Zahnstocher"],"schritte":[{"titel":"Ofen vorheizen und Form vorbereiten","aktion":"vorbereiten","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Fette die quadratische Form mit Butter ein und lege den Boden mit Backpapier aus. Wiege alle Zutaten ab und hole die Butter und die Eier rechtzeitig aus dem Kühlschrank, damit sie Zimmertemperatur haben und sich besser verbinden. Hacke die Datteln grob und prüfe sie auf vergessene Kerne.","dauer":0,"tipp":""},{"titel":"Datteln einweichen","aktion":"marinieren","text":"Gib die gehackten Datteln in eine Schüssel und übergieße sie mit dem kochenden Wasser. Rühre das Natron ein, es schäumt leicht auf und macht die Datteln weich, sodass sie fast zu Mus zerfallen. Lass alles 10 bis 15 Minuten stehen, bis die Mischung lauwarm ist und die Datteln aufgequollen sind. Das Einweichwasser enthält viel Aroma und kommt mit in den Teig.","dauer":15,"tipp":""},{"titel":"Teig rühren","aktion":"aufschlagen","text":"Schlage die weiche Butter mit dem Zucker 3 bis 4 Minuten mit dem Handmixer, bis die Masse hell, cremig und luftig ist. Rühre die Eier einzeln unter und füge Sirup und Vanille hinzu. Mische Mehl und Backpulver und hebe es abwechselnd mit der Dattelmischung samt Flüssigkeit vorsichtig unter. Rühre nur, bis alles verbunden ist. Der Teig ist ziemlich flüssig, das ist richtig so.","dauer":8,"tipp":"Nicht zu lange rühren, sonst wird der Kuchen zäh."},{"titel":"Backen","aktion":"backen","text":"Gieße den Teig in die vorbereitete Form und streiche ihn glatt. Backe ihn auf der mittleren Schiene 35 bis 40 Minuten, bis er aufgegangen, dunkelbraun ist und ein Holzstäbchen sauber herauskommt. Der Kuchen soll federnd zurückspringen, wenn du leicht mit dem Finger drückst. Lass ihn 10 Minuten in der Form ruhen.","dauer":38,"tipp":""},{"titel":"Toffeesauce kochen","aktion":"reduzieren","text":"Schmilz in einem Topf Butter, Zucker und Sirup bei mittlerer Hitze unter Rühren, bis sich der Zucker aufgelöst hat. Gieße die Sahne dazu und lass die Sauce 3 bis 5 Minuten leise köcheln, bis sie leicht eindickt, glänzt und nach Karamell duftet. Würze mit einer Prise Salz, sie hebt die Süße hervor. Halte sie warm; die Sauce wird beim Abkühlen dicker.","dauer":8,"tipp":""},{"titel":"Kuchen tränken und karamellisieren","aktion":"ueberbacken","text":"Steche den noch warmen Kuchen mit einem Stäbchen überall ein und gieße ein Drittel der Toffeesauce darüber, sodass sie in die Löcher einsickert. Schiebe die Form für 3 bis 5 Minuten unter den heißen Backofengrill, bis die Oberfläche blubbert und leicht karamellisiert. Behalte den Kuchen im Auge, Zucker verbrennt schnell. Der Kuchen soll glänzen und klebrig aussehen, daher der Name.","dauer":5,"tipp":""},{"titel":"Schneiden und servieren","aktion":"anrichten","text":"Schneide den Kuchen in acht Quadrate und setze jedes in eine flache Schale oder auf einen Teller. Übergieße großzügig mit warmer Toffeesauce und gib eine Kugel Vanilleeis oder Vanillesauce daneben. Servieren am besten sofort, solange der Kuchen warm ist und die Sauce fließt. Reste lassen sich im Kühlschrank 3 Tage aufbewahren und in der Mikrowelle aufwärmen.","dauer":0,"tipp":""}],"profitipps":["Natron macht die Datteln weich und lässt den Kuchen locker aufgehen; nicht weglassen.","Dunkler Zucker und Sirup geben den typischen Karamellgeschmack.","Den Kuchen noch warm mit Sauce tränken, dann saugt er sie richtig auf.","Für die Sauce die Sahne langsam zugießen und bei mittlerer Hitze köcheln, damit nichts ausflockt.","Sticky Toffee Pudding lässt sich gut vorbereiten und vor dem Servieren im Ofen aufwärmen."],"varianten":["Mit Whisky oder Rum in der Sauce","Mit gehackten Walnüssen oder Pekannüssen im Teig","Als einzelne Mini-Puddings in Muffinförmchen","Mit Ingwer und Zimt für Winterwürze"],"beilagen":["Vanilleeis","Vanillesauce (Custard)","Schlagsahne"],"getraenk":"Süßer Dessertwein wie Sauternes, Tawny Port oder ein heißer Tee.","koeche":[],"quellen":[{"titel":"Sticky toffee pudding – Wikipedia","url":"https://en.wikipedia.org/wiki/Sticky_toffee_pudding"}],"bild":"dessert","farben":["#6b3a1e","#c28a4a","#f1d9a8"],"schlagworte":["Dessert","Pub","Toffee","Datteln"],"vegetarisch_moeglich":true},{"originalname":"","hauptkategorie":"suess","gang":"kuchen","koeche":[],"vegetarisch_moeglich":true,"id":"britisch-irisch-lemon-drizzle-cake","name":"Lemon Drizzle Cake","region":"England","kueche":"britisch-irisch","beliebtheit":80,"kurz":"Saftiger Zitronen-Rührkuchen aus der Kastenform, getränkt mit Zitronensirup und gekrönt von einer knusprigen, zuckerigen Kruste.","hintergrund":"Der Lemon Drizzle Cake gehört zu den beliebtesten Teekuchen Großbritanniens und steht in nahezu jedem Café neben Victoria Sponge und Scones. Er ist ein einfacher Rührkuchen mit Zitronenabrieb im Teig; sein Markenzeichen ist der kalt angerührte Zitronen-Zucker-Guss, den man auf den noch warmen Kuchen träufelt. Der Zucker kristallisiert beim Abkühlen zu einer feinen, knackigen Kruste, während der Saft in die Krume zieht und den Kuchen saftig und säuerlich macht. Die genaue Herkunft ist nicht eindeutig belegt.","portionen":10,"zeit":{"vorbereitung":25,"garen":50,"ruhen":120},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Teig (Kastenform 25 cm)","liste":[{"menge":175,"einheit":"g","name":"weiche Butter","hinweis":"Zimmertemperatur"},{"menge":175,"einheit":"g","name":"Zucker","hinweis":"fein"},{"menge":3,"einheit":"Stück","name":"Eier (Größe L)","hinweis":"Zimmertemperatur"},{"menge":175,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Backpulver","hinweis":"gestrichen"},{"menge":2,"einheit":"Stück","name":"Bio-Zitronen","hinweis":"nur die Schale, fein abgerieben"},{"menge":4,"einheit":"EL","name":"Milch","hinweis":"ca. 60 ml"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"weiche Butter","hinweis":"für die Form"}]},{"gruppe":"Für den Drizzle","liste":[{"menge":100,"einheit":"g","name":"Kristallzucker","hinweis":"grob, für die Kruste"},{"menge":3,"einheit":"EL","name":"Zitronensaft","hinweis":"frisch gepresst, ca. 50 ml (etwa 1,5 Zitronen)"}]}],"ausruestung":["Kastenform 25 cm","Backpapier","Handrührgerät","Zestenreibe","Holzstäbchen","Kuchengitter"],"schritte":[{"titel":"Zutaten und Form vorbereiten","aktion":"vorbereiten","text":"Nimm Butter und Eier eine Stunde vor dem Backen aus dem Kühlschrank. Heize den Backofen auf 170 °C Ober-/Unterhitze (150 °C Umluft) vor und fette die Kastenform ein. Lege sie mit einem Streifen Backpapier aus, der an den langen Seiten übersteht, sodass du den Kuchen später herausheben kannst. Wasche die Zitronen heiß ab und reibe die gelbe Schale fein ab, ohne das bittere Weiße darunter mitzureiben. Presse danach beide Zitronen aus und stelle den Saft beiseite.","dauer":15,"tipp":"Zitronen vor dem Auspressen auf der Arbeitsplatte fest rollen – so geben sie mehr Saft."},{"titel":"Butter und Zucker cremig schlagen","aktion":"aufschlagen","text":"Schlage Butter und Zucker mit dem Handrührgerät drei bis vier Minuten auf mittlerer Stufe, bis die Masse hell, luftig und cremig ist und die Zuckerkörner kaum noch zu spüren sind. Gib den Zitronenabrieb dazu und rühre kurz weiter. Die ätherischen Öle der Schale lösen sich im Fett und sorgen später für ein intensives, rundes Aroma. Je länger du hier rührst, desto lockerer wird der Kuchen.","dauer":5,"tipp":""},{"titel":"Eier einarbeiten","aktion":"mischen","text":"Gib die Eier einzeln dazu und rühre jedes etwa 30 Sekunden lang ein, bevor das nächste folgt. Die Masse soll dabei glatt und glänzend bleiben. Gerinnt sie, rühre einen Esslöffel Mehl hinein, das bindet überschüssige Flüssigkeit. Nach dem letzten Ei schabst du den Schüsselrand ab und rührst nur noch kurz, damit sich alles verbindet. Zu viele Luftblasen im Teig lassen den Kuchen später stark kuppeln.","dauer":3,"tipp":""},{"titel":"Mehl und Milch unterheben","aktion":"mischen","text":"Siebe Mehl, Backpulver und Salz auf den Teig und hebe es mit einem Teigschaber in zwei Portionen unter, abwechselnd mit der Milch. Rühre nur, bis gerade kein trockenes Mehl mehr sichtbar ist. Der Teig soll schwer vom Löffel reißen, glatt und glänzend sein. Gib bei zu festem Teig einen weiteren Esslöffel Milch dazu. Übermäßiges Rühren aktiviert das Gluten und macht den Kuchen zäh.","dauer":3,"tipp":""},{"titel":"Einfüllen und backen","aktion":"backen","text":"Fülle den Teig in die vorbereitete Form, streiche ihn glatt und drücke die Mitte leicht ein, damit der Kuchen gleichmäßig aufgeht. Backe ihn 45 bis 50 Minuten in der Ofenmitte, bis er hellgoldbraun ist, sich vom Rand leicht löst und beim Eindrücken der Oberfläche zurückfedert. Ein Holzstäbchen muss sauber herauskommen. Öffne in den ersten 30 Minuten die Tür nicht, damit der Kuchen nicht zusammenfällt.","dauer":48,"tipp":"Wird die Oberfläche zu dunkel, decke den Kuchen die letzten 10 Minuten mit Alufolie ab."},{"titel":"Drizzle vorbereiten","aktion":"mischen","text":"Rühre kurz vor Ende der Backzeit den Kristallzucker mit dem Zitronensaft in einer kleinen Schüssel zu einer dünnen, körnigen Paste an; der Zucker löst sich nicht ganz auf, und genau das ist gewollt, denn die ungelösten Kristalle bilden später die Kruste. Die Mischung sollte säuerlich und deutlich nach frischer Zitrone riechen. Probiere sie vorsichtig: Sie muss kräftig sauer-süß schmecken, da der Kuchen selbst eher mild ist.","dauer":3,"tipp":""},{"titel":"Kuchen tränken","aktion":"fuellen","text":"Steche den Kuchen sofort nach dem Backen, solange er noch heiß in der Form ist, mit einem langen Holzstäbchen oder Zahnstocher gleichmäßig im Abstand von etwa zwei Zentimetern ein, bis fast zum Boden. Gieße die Zitronen-Zucker-Mischung in zwei Portionen gleichmäßig über die Oberfläche; warte nach der ersten, bis der Saft eingezogen ist. Der warme Kuchen saugt den Saft wie ein Schwamm auf; die Zuckerkristalle bleiben obenauf und bilden beim Auskühlen eine feine, knackige Kruste.","dauer":5,"tipp":""},{"titel":"Auskühlen und anschneiden","aktion":"kuehlen","text":"Lass den Kuchen in der Form vollständig abkühlen, mindestens eine Stunde. Hebe ihn dann mit dem Papier heraus und lege ihn auf ein Gitter. Die Oberfläche soll jetzt fest und glasiert sein und beim Anschneiden leicht knacken. Schneide ihn mit einem Sägemesser in Scheiben. Er schmeckt frisch am besten, hält sich aber luftdicht verpackt drei Tage und wird mit der Zeit noch saftiger.","dauer":60,"tipp":""}],"profitipps":["Zitronen unbedingt aus Bio-Anbau verwenden, denn die Schale kommt in den Teig.","Den Drizzle gleich nach dem Backen aufgießen, solange der Kuchen heiß ist.","Grober Kristallzucker bildet die Kruste, Puderzucker würde schmieren.","Nicht übermäßig rühren, sonst wird der Kuchen fest.","Einen Löffel Mohn oder Joghurt im Teig macht ihn noch saftiger."],"varianten":["Mit Mohn („Lemon Poppy Seed Cake“).","Mit Zitronenglasur aus Puderzucker und Saft statt Drizzle.","Als Orange Drizzle Cake mit Orangenabrieb.","Als Blechkuchen mit der doppelten Menge im Backblech."],"beilagen":["Schlagsahne","Beeren","Tee"],"getraenk":"Earl-Grey-Tee oder Darjeeling","quellen":[{"titel":"The History of Lemon Drizzle Cake – Baking Heritage","url":"https://bakingheritage.com/history/the-history-of-lemon-drizzle-cake"}],"bild":"kuchen","farben":["#f2d85f","#fff6c9","#c9a227"],"schlagworte":["Teekuchen","Zitrone","Klassiker"]},{"id":"britisch-irisch-bangers-and-mash","name":"Bangers and Mash","originalname":"Bangers and Mash","kueche":"britisch-irisch","region":"England","beliebtheit":80,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Saftige Bratwürste auf cremigem Kartoffelpüree, übergossen mit dunkler, süß-würziger Zwiebelsauce – das Pub-Comfort-Food schlechthin.","hintergrund":"Bangers and Mash, auch Sausages and Mash genannt, ist ein Kernstück der britischen Pub-Küche: Würstchen, Kartoffelpüree und Zwiebelsauce, oft mit Erbsen. Das Wort banger soll aus dem Ersten Weltkrieg stammen, als wegen der Fleischrationierung viel Wasser in den Würsten steckte und sie beim Braten platzten; belegt ist es mindestens seit 1919. Kartoffeln kamen im späten 16. Jahrhundert aus Amerika nach Großbritannien, doch Würstchen und Kartoffeln wurden erst seit der Industriellen Revolution zu einer gemeinsamen Mahlzeit. Gravy aus Zwiebeln gilt als das klassische Beiwerk.","portionen":4,"zeit":{"vorbereitung":20,"garen":50,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Würstchen","liste":[{"menge":8,"einheit":"Stück","name":"grobe Schweinsbratwürstchen (z. B. Cumberland oder Frische Bratwurst)","hinweis":"mit hohem Fleischanteil, ohne Kümmel- oder Majorangeschmack"},{"menge":1,"einheit":"EL","name":"Rapsöl","hinweis":""}]},{"gruppe":"Kartoffelpüree","liste":[{"menge":1.2,"einheit":"kg","name":"mehligkochende Kartoffeln","hinweis":"geschält, in gleich große Stücke geschnitten"},{"menge":80,"einheit":"g","name":"Butter","hinweis":"kalt gewürfelt"},{"menge":150,"einheit":"ml","name":"Milch","hinweis":"heiß"},{"menge":null,"einheit":"","name":"Salz, weißer Pfeffer, Muskat","hinweis":"nach Geschmack"}]},{"gruppe":"Zwiebel-Gravy","liste":[{"menge":600,"einheit":"g","name":"Zwiebeln","hinweis":"in feine Halbringe geschnitten"},{"menge":40,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"TL","name":"brauner Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Weizenmehl","hinweis":""},{"menge":100,"einheit":"ml","name":"dunkles Ale oder Malzbier","hinweis":"optional, ersatzweise mehr Fond"},{"menge":500,"einheit":"ml","name":"Rinderfond","hinweis":"heiß"},{"menge":1,"einheit":"EL","name":"Worcestershiresauce","hinweis":""},{"menge":2,"einheit":"Zweig","name":"Thymian","hinweis":""}]},{"gruppe":"Beilage","liste":[{"menge":200,"einheit":"g","name":"Erbsen, tiefgekühlt","hinweis":""}]}],"ausruestung":["große Pfanne","Topf","Kartoffelpresse oder Stampfer","Backblech"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Schäle die Zwiebeln, halbiere sie und schneide sie in dünne, gleichmäßige Streifen; so garen sie gleichmäßig und karamellisieren schön. Schäle die Kartoffeln und schneide sie in etwa gleich große Stücke von 4 bis 5 cm, damit sie zur gleichen Zeit gar sind. Zupfe die Thymianblättchen ab. Nimm die Würstchen aus dem Kühlschrank, damit sie nicht eiskalt in die Pfanne kommen. Heize den Ofen auf 80 °C vor, um die fertigen Komponenten warm zu halten.","dauer":0,"tipp":""},{"titel":"Zwiebeln langsam karamellisieren","aktion":"anbraten","text":"Schmilz die Butter in einer großen Pfanne bei niedriger bis mittlerer Hitze und gib die Zwiebeln mit einer Prise Salz hinein. Gare sie 25 bis 30 Minuten unter häufigem Rühren, bis sie tief goldbraun, weich und süß geworden sind. Streue gegen Ende den braunen Zucker darüber, damit sie zusätzlich karamellisieren. Wenn die Zwiebeln am Boden ansetzen, gieße einen Schuss Wasser dazu. Geduld lohnt sich: Die Zwiebeln liefern Süße und Farbe der Sauce.","dauer":30,"tipp":"Nicht auf zu hoher Hitze braten – dann verbrennen sie außen, bevor sie innen süß werden."},{"titel":"Kartoffeln kochen","aktion":"kochen","text":"Gib die Kartoffelstücke in einen Topf, bedecke sie mit kaltem Wasser, füge einen Teelöffel Salz hinzu und bringe sie zum Kochen. Lasse sie 18 bis 22 Minuten bei mittlerer Hitze garen, bis eine Gabel mühelos hineingleitet. Gieße sie ab und lasse sie 3 Minuten im offenen Topf ausdampfen. Trockene Kartoffeln ergeben ein fluffiges, nicht wässriges Püree.","dauer":20,"tipp":""},{"titel":"Würstchen braten","aktion":"braten","text":"Erhitze das Öl in einer großen Pfanne bei mittlerer bis niedriger Hitze und lege die Würstchen hinein. Brate sie 15 bis 20 Minuten und wende sie regelmäßig, damit sie rundum gleichmäßig braun werden und innen durchgaren. Ein Anstechen vermeidest du, damit sie saftig bleiben. Sie sind fertig, wenn sie dunkelbraun glänzen und sich fest anfühlen. Alternativ kannst du sie im Ofen bei 200 °C Ober-/Unterhitze 20 bis 25 Minuten backen und einmal wenden.","dauer":18,"tipp":"Zu hohe Hitze lässt die Würstchen platzen und macht sie trocken."},{"titel":"Kartoffelpüree stampfen","aktion":"puerieren","text":"Drücke die abgetropften Kartoffeln durch die Presse oder stampfe sie mit dem Stampfer fein. Rühre die kalte Butter in Stücken ein, bis sie vollständig geschmolzen ist, und gieße die heiße Milch nach und nach unter, bis das Püree glatt und cremig ist. Würze mit Salz, weißem Pfeffer und etwas geriebener Muskatnuss. Verwende keinen Mixer, das macht Kartoffelpüree klebrig. Halte es zugedeckt warm.","dauer":6,"tipp":""},{"titel":"Zwiebelsauce kochen","aktion":"binden","text":"Streue das Mehl über die karamellisierten Zwiebeln und rühre 1 bis 2 Minuten, bis es nicht mehr roh riecht. Lösche mit dem Ale ab und lasse es einkochen. Gieße unter Rühren den heißen Fond nach und nach dazu, gib Worcestershiresauce und Thymian hinzu und lasse die Gravy 10 bis 12 Minuten leise köcheln, bis sie dunkel, glänzend und löffelsämig ist. Schmecke mit Salz und Pfeffer ab.","dauer":12,"tipp":""},{"titel":"Erbsen garen","aktion":"blanchieren","text":"Koche die Erbsen in kochendem Salzwasser 3 bis 4 Minuten, bis sie leuchtend grün und zart sind. Gieße sie ab und schwenke sie kurz mit etwas Butter. Frische Erbsen ergeben süßen Geschmack und einen frischen Kontrast zu den dunklen, würzigen Zutaten auf dem Teller. Die Erbsen sollten noch einen leichten Biss haben und beim Zerdrücken zwischen den Zähnen leise platzen; länger gegarte Erbsen werden grau und mehlig. Wer mag, rührt einen Teelöffel gehackte Minze unter.","dauer":4,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile das Püree als großzügigen Hügel in der Mitte der vorgewärmten Teller und drücke mit einem Löffel eine Mulde hinein. Lege die Würstchen darauf, gieße die dampfende Zwiebelsauce darüber und gib die Erbsen daneben. Serviere sofort mit englischem Senf und einem kühlen Ale. Ein Klecks englischer Senf am Tellerrand passt hervorragend zu den Würstchen, und ein zusätzlicher Löffel Gravy gehört zum guten Ton, damit das Püree nicht trocken wirkt.","dauer":0,"tipp":""}],"profitipps":["Würstchen langsam und bei mittlerer Hitze braten, damit sie nicht platzen.","Zwiebeln brauchen Zeit: 25 bis 30 Minuten bei niedriger Hitze ergeben Süße und Farbe.","Mehlige Kartoffeln, gut ausgedampft und mit Butter und heißer Milch, ergeben das beste Püree.","Worcestershiresauce gibt der Gravy Tiefe und Würze.","Das Püree niemals im Mixer pürieren, sonst wird es gummiartig."],"varianten":["Mit Cumberland-Sausage im Ring","Mit Yorkshire Pudding als Toad in the Hole","Mit Erbsenpüree oder Rotkohl als Beilage","Mit Senf- oder Meerrettichpüree"],"beilagen":["Erbsen","Karotten","englischer Senf","Rotkohl"],"getraenk":"Dunkles englisches Ale, Guinness oder ein kräftiger Rotwein.","koeche":[],"quellen":[{"titel":"Bangers and mash – Wikipedia","url":"https://en.wikipedia.org/wiki/Bangers_and_mash"}],"bild":"wurst","farben":["#7a4a2a","#d6a763","#f1e1b8"],"schlagworte":["Pub","Comfort Food","Würstchen","Püree"],"vegetarisch_moeglich":false},{"originalname":"Eton Mess","region":"England","hauptkategorie":"suess","fleischsorte":"","gang":"dessert","koeche":[],"vegetarisch_moeglich":true,"id":"britisch-irisch-eton-mess","name":"Eton Mess","kueche":"britisch-irisch","beliebtheit":78,"kurz":"Ein chaotisch schöner Becher aus Erdbeeren, Sahne und zerbrochenem Baiser – süß, sauer, knusprig und cremig in einem Löffel.","hintergrund":"Eton Mess ist ein Klassiker der englischen Sommerküche, der traditionell mit dem Eton College und dem Cricketspiel gegen Harrow in Verbindung gebracht wird. Die Geschichte sagt, dass ein Dessert aus Erdbeeren und Sahne zusammen mit Baiser versehentlich zerbrochen wurde und dennoch aufgegessen wurde. Die Kombination blieb, und heute gehört Eton Mess zum englischen Sommer wie Wimbledon. Die Kunst liegt darin, Baiser, Sahne und Erdbeeren erst unmittelbar vor dem Servieren zu vermengen, damit die Baiserstücke knusprig bleiben.","portionen":6,"zeit":{"vorbereitung":30,"garen":90,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Baiser","liste":[{"menge":3,"einheit":"Stück","name":"Eiweiß","hinweis":"Größe M, ca. 100 g, Zimmertemperatur"},{"menge":180,"einheit":"g","name":"feiner Zucker","hinweis":"Kristallzucker oder Backzucker"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"Speisestärke","hinweis":""},{"menge":1,"einheit":"TL","name":"weißer Essig","hinweis":""}]},{"gruppe":"Erdbeeren","liste":[{"menge":500,"einheit":"g","name":"reife Erdbeeren","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":""}]},{"gruppe":"Sahne","liste":[{"menge":400,"einheit":"ml","name":"Schlagsahne","hinweis":"mindestens 30 % Fett, sehr kalt"},{"menge":1,"einheit":"EL","name":"Puderzucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":""},{"menge":null,"einheit":"","name":"Minze oder Basilikum","hinweis":"zum Garnieren"}]}],"ausruestung":["Backblech mit Backpapier","Handrührer oder Küchenmaschine","Spritzbeutel oder zwei Esslöffel","Große Rührschüssel","Gläser oder Dessertschalen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Ofen auf 120 °C Ober-/Unterhitze (100 °C Umluft) vor und lege ein Blech mit Backpapier aus. Trenne die Eier so, dass kein Tropfen Dotter ins Eiweiß gelangt, denn schon Fett verhindert, dass sich das Eiweiß steif schlagen lässt. Wiege Zucker, Speisestärke und Essig ab. Putze die Rührschüssel mit etwas Zitronensaft oder Essig aus, damit sie fettfrei ist. Stelle die Sahne zur Seite in den Kühlschrank.","dauer":10,"tipp":""},{"titel":"Baisermasse aufschlagen","aktion":"aufschlagen","text":"Schlage das Eiweiß mit der Prise Salz bei mittlerer Geschwindigkeit an, bis es schaumig ist und weiche Spitzen bildet. Gib den Zucker jetzt esslöffelweise dazu und schlage jedes Mal rund 20 Sekunden, bevor du den nächsten hinzugibst. Zum Schluss schlägst du die Masse weitere fünf bis sieben Minuten, bis sie dick, glänzend und schneeweiß ist und beim Anheben des Rührers eine steife Spitze stehen bleibt. Reibe etwas Masse zwischen den Fingern: Spürst du keine Zuckerkörner mehr, ist alles aufgelöst. Hebe Stärke und Essig kurz unter.","dauer":12,"tipp":""},{"titel":"Baiser formen und backen","aktion":"backen","text":"Setze mit dem Spritzbeutel oder zwei Löffeln etwa zwölf rustikale Häufchen auf das Backpapier, jeweils fünf bis sechs Zentimeter groß. Backe sie 75 bis 90 Minuten bei niedriger Temperatur, bis sie sich leicht vom Papier lösen und außen trocken und hell cremefarben sind. Dabei darf nichts braun werden – das wäre ein Zeichen für zu hohe Hitze. Schalte den Ofen aus und lasse die Baisers bei leicht geöffneter Tür im Ofen auskühlen, am besten zwei Stunden, damit sie nicht reißen.","dauer":90,"tipp":"Ofentür nie in den ersten 45 Minuten öffnen – sonst fällt das Baiser zusammen."},{"titel":"Erdbeeren marinieren","aktion":"marinieren","text":"Wasche die Erdbeeren kurz, tupfe sie trocken und schneide die Kelche ab. Viertele die Hälfte der Früchte und püriere die andere Hälfte mit Zucker und Zitronensaft zu einem glatten Püree, das du bei Bedarf durch ein Sieb streichst. Mische die Erdbeerviertel mit etwa der Hälfte des Pürees und lasse alles zehn Minuten Saft ziehen. Das Aroma wird dadurch intensiver, und die Früchte geben ihre natürliche Säure an die Soße ab.","dauer":15,"tipp":""},{"titel":"Sahne schlagen","aktion":"aufschlagen","text":"Schlage die eiskalte Sahne mit Puderzucker und Vanille in einer gut gekühlten Schüssel mit dem Handrührer auf, bis sie weiche, cremige Spitzen bildet, die sich noch leicht biegen. Hör lieber zu früh auf als zu spät, denn zu steif geschlagene Sahne wird körnig und kippt in Butter. Die Konsistenz ist ideal, wenn sie langsam vom Löffel gleitet und eine weiche Welle bildet.","dauer":5,"tipp":""},{"titel":"Zusammenfügen","aktion":"mischen","text":"Zerbrich die ausgekühlten Baisers mit den Händen in grobe Stücke, mal groß, mal klein. Hebe die Hälfte davon vorsichtig unter die Sahne und füge die mazerierten Erdbeeren hinzu. Ziehe das Püree nur wenig unter, damit marmorierte Schlieren entstehen und die Masse nicht rosa wird. Arbeite zügig und nur mit wenigen Bewegungen von unten nach oben, sonst zerfallen die Baiserstücke zu Brei. Die Mischung soll chaotisch aussehen, genau das macht den Charme aus.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile die Masse in Gläsern oder Schalen und schichte dabei ein wenig Erdbeerpüree zwischen die Lagen. Streue die restlichen Baiserstücke und eine Handvoll frischer Erdbeeren obenauf. Garniere mit Minze- oder Basilikumblättern und serviere sofort, denn die Baiserstücke werden durch die Feuchtigkeit nach etwa einer Stunde weich. Der Löffel sollte beim ersten Eintauchen leise knacken, das ist das Zeichen für gelungenen Kontrast aus Knusper und Creme.","dauer":5,"tipp":""}],"profitipps":["Baiser, Sahne und Erdbeeren erst kurz vor dem Servieren mischen.","Fertiges Baiser aus dem Supermarkt spart Zeit, selbstgemacht schmeckt es aber besser.","Sahne gut kühlen und nur bis zu weichen Spitzen schlagen.","Reife, aromatische Saisonerdbeeren machen den Unterschied – im Winter lieber Himbeeren nehmen.","Ein Spritzer Rosenwasser oder Balsamico bringt Tiefe."],"varianten":["Mit Himbeeren oder Mischbeeren","Mit Mango und Passionsfrucht (tropischer Mess)","Mit Schokoladensauce und Banane","Als Gläserdessert mit Vanillecreme statt Sahne"],"beilagen":["Frische Minze","Biskuit-Löffel"],"getraenk":"Prosecco, Pimm's oder Earl-Grey-Tee","quellen":[{"titel":"Eton mess – Wikipedia","url":"https://en.wikipedia.org/wiki/Eton_mess"},{"titel":"Eton Mess: The History of a Classic English Dessert – History Hit","url":"https://www.historyhit.com/eton-mess-the-history-of-a-classic-english-dessert/"},{"titel":"The Muddled History Of How Eton Mess Came To Be – Tasting Table","url":"https://www.tastingtable.com/943724/the-muddled-history-of-how-eton-mess-came-to-be"}],"bild":"dessert","farben":["#d6405a","#f7efe4","#9c2a3f"],"schlagworte":["Sommer","Erdbeeren","Baiser"]},{"id":"britisch-irisch-english-muffins","name":"English Muffins aus der Pfanne","kueche":"britisch-irisch","region":"England","beliebtheit":76,"hauptkategorie":"vegetarisch","kurz":"Flache, in der Pfanne gebackene Hefefladen mit der berühmten löchrigen Krume – außen leicht mehlig, innen voller Luftlöcher, die geschmolzene Butter aufsaugen. Gabel statt Messer, dann geröstet.","hintergrund":"English Muffins sind kleine, runde, flache Hefegebäcke von etwa 10 cm Durchmesser, die traditionell nicht im Ofen, sondern auf einer heißen Platte (Griddle) gebacken werden. Rezepte dafür stehen schon 1747 in Hannah Glasses Kochbuch „The Art of Cookery“, und im 18. Jahrhundert verkauften „Muffin Men“ sie an der Haustür, als viele Haushalte noch keinen Ofen hatten. Samuel Bath Thomas, ein englischer Auswanderer, brachte sie 1880 in Manhattan auf den amerikanischen Markt. Anders als beim Crumpet liegen die Löcher innen und nicht an der Oberseite; deshalb wird der Muffin horizontal aufgeschnitten – klassisch mit der Gabel – und getoastet.","portionen":8,"zeit":{"vorbereitung":30,"garen":16,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (8 Muffins)","liste":[{"menge":400,"einheit":"g","name":"Weizenmehl Type 550 oder Brotmehl","hinweis":"kleberstark, damit die Löcher stabil bleiben"},{"menge":250,"einheit":"ml","name":"Vollmilch","hinweis":"lauwarm, ca. 30 °C"},{"menge":12,"einheit":"g","name":"frische Hefe","hinweis":"entspricht ca. 4 g Trockenhefe"},{"menge":7,"einheit":"g","name":"Salz","hinweis":""},{"menge":10,"einheit":"g","name":"Zucker","hinweis":""},{"menge":30,"einheit":"g","name":"Butter","hinweis":"geschmolzen und etwas abgekühlt"},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":"raumwarm, verquirlt"}]},{"gruppe":"Zum Formen und Backen","liste":[{"menge":3,"einheit":"EL","name":"Hartweizengrieß oder Maisgrieß","hinweis":"zum Wälzen und Bestäuben"},{"menge":null,"einheit":"","name":"etwas Butter oder Öl","hinweis":"zum Einfetten der Pfanne"}]}],"ausruestung":["Gusseisenpfanne oder schwere beschichtete Pfanne mit Deckel","Ausstechring 8–9 cm (optional)","Backblech oder Tablett","Teigkarte","Küchenthermometer","Abkühlgitter"],"schritte":[{"titel":"Zutaten abmessen und Hefe aktivieren","aktion":"vorbereiten","text":"Wiege Mehl, Salz und Zucker ab und lasse Ei und Butter Zimmertemperatur annehmen. Die Milch erwärmst du auf etwa 30 °C, sie soll sich nur eben lauwarm anfühlen. Zerbröckele die Hefe hinein, rühre sie auf und lasse alles 5 Minuten stehen, bis sich an der Oberfläche ein zarter Schaum bildet. Dieser Schaum ist dein Zeichen, dass die Hefe lebendig ist; bleibt er aus, ist die Hefe alt oder die Milch war zu heiß.","dauer":10,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib Hefemilch, geschmolzene Butter und Ei zum Mehl und knete 8–10 Minuten von Hand oder 5 Minuten in der Maschine auf niedriger bis mittlerer Stufe. Der Teig ist weich und leicht klebrig, ähnlich wie ein Pizzateig, und wird nach und nach glatt. Gib kein Mehl dazu, auch wenn er an den Fingern klebt: Nur ein feuchter Teig bildet später die gewünschten Löcher. Die Fensterprobe sollte gelingen, die Teigtemperatur liegt bei 25–26 °C.","dauer":10,"tipp":"Ein zu fester Teig ergibt eine geschlossene Krume – lieber etwas klebriger lassen."},{"titel":"Stockgare","aktion":"gehen","text":"Lege den Teig in eine geölte Schüssel, decke ihn ab und lasse ihn bei 24–26 °C etwa 60 Minuten gehen. Er soll sich verdoppeln, die Oberfläche ist gewölbt und voller kleiner Bläschen. Mit der Fingerprobe prüfst du es: Eine eingedrückte Delle füllt sich langsam wieder, bleibt aber leicht sichtbar. Wirkt der Teig noch fest, gib ihm weitere 15 Minuten. Ein erfahrener Bäcker erkennt den richtigen Zeitpunkt auch daran, dass der Teig beim Schütteln der Schüssel leicht schwankt.","dauer":60,"tipp":""},{"titel":"Teilen und formen","aktion":"formen","text":"Streue das Blech mit Grieß ein. Stürze den Teig auf die Fläche und teile ihn in 8 Stücke zu je etwa 85 g. Forme jedes Stück zu einer glatten Kugel, indem du die Ränder unter den Teig schiebst, und drücke sie leicht flach auf etwa 2 cm Höhe. Wälze die Teiglinge von allen Seiten im Grieß – er verhindert das Anbacken und gibt die typisch mehlig-körnige Optik. Ein Ausstechring hilft, wenn du gleichmäßig runde Muffins möchtest.","dauer":10,"tipp":""},{"titel":"Stückgare mit Fingerprobe","aktion":"gehen","text":"Decke die Muffins locker mit einem Tuch ab und lasse sie 30–40 Minuten bei Zimmertemperatur gehen. Sie sollen deutlich aufgegangen und weich wie Marshmallows sein; ein vorsichtiger Fingerdruck hinterlässt eine Delle, die sich langsam zur Hälfte zurückbildet. Dreh die Muffins nicht um, solange sie gehen – so bleibt der Grieß unversehrt. Erhitze in der Zwischenzeit die Pfanne für einige Minuten bei niedrigster bis mittlerer Hitze.","dauer":35,"tipp":""},{"titel":"In der Pfanne backen","aktion":"braten","text":"Fette die Pfanne hauchdünn mit Butter oder Öl ein, setze 3–4 Muffins mit Abstand hinein und decke die Pfanne zu. Backe sie bei niedriger Hitze (bei einem Elektroherd etwa Stufe 3 von 9) 6–7 Minuten pro Seite, bis sie goldbraun sind. Die Hitze muss niedrig sein, damit das Innere durchbacken kann, bevor außen alles verbrennt – ein zu schnell gebräunter Muffin bleibt innen roh. Beim ersten Wenden hörst du ein leichtes Zischen; die Oberseite ist hell, die Unterseite haselnussbraun. Bräunen sie zu schnell, drehe die Hitze weiter zurück.","dauer":28,"tipp":"Als Sicherheitsnetz: Schiebe die Muffins nach dem Anbraten für 5 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft) in den Ofen – dann garen sie sicher durch."},{"titel":"Gare prüfen und auskühlen","aktion":"ruhen","text":"Prüfe einen Muffin mit dem Thermometer: Die Kerntemperatur sollte mindestens 90 °C erreicht haben; sie fühlen sich dann federnd an, und der Rand klingt beim Klopfen leicht hohl. Lege die Muffins auf ein Gitter und lasse sie vollständig auskühlen, damit der Dampf entweichen kann und die Krume nicht klebrig bleibt. Frisch aus der Pfanne sind sie weich, nach dem Auskühlen setzt sich die löchrige Struktur und lässt sich besser teilen.","dauer":20,"tipp":""},{"titel":"Aufspalten und rösten","aktion":"anrichten","text":"Teile die abgekühlten Muffins nicht mit dem Messer, sondern steche rundherum mit einer Gabel ein und breche sie vorsichtig in zwei Hälften – so bleibt die löchrige, raue Innenseite erhalten, die geschmolzene Butter wunderbar aufsaugt. Rösten kannst du sie im Toaster oder in der trockenen Pfanne, bis die Schnittflächen goldbraun und knusprig sind. Bestreiche sie sofort mit Butter und lasse sie zerlaufen. Frisch gebacken halten sie sich 3 Tage; aufgeschnitten eingefroren 3 Monate.","dauer":5,"tipp":""}],"profitipps":["Niedrige Hitze, Deckel drauf: So garen die Muffins gleichmäßig durch, statt außen zu verbrennen.","Der Teig soll weich und klebrig sein – das bildet die Luftlöcher.","Gabel statt Messer: Die raue Innenfläche saugt Butter und Marmelade auf.","Grieß verhindert das Anbacken und gibt den typischen Biss.","Erst abkühlen lassen, dann aufbrechen – sonst ist die Krume gummiartig.","Zum Einfrieren aufbrechen, einfrieren und direkt aus dem Gefrierfach toasten."],"varianten":["Vollkorn: 150 g des Mehls durch Weizenvollkorn ersetzen.","Rosinen-Zimt-Muffins: 60 g Rosinen und 1 TL Zimt in den Teig.","Eggs Benedict: mit pochiertem Ei und Sauce Hollandaise.","Breakfast-Muffin mit Spiegelei, Speck und Cheddar."],"beilagen":["Butter und Marmelade","Pochierte Eier","Speck und Cheddar","Clotted Cream und Honig"],"getraenk":"English Breakfast Tea mit Milch.","koeche":[{"name":"Paul Hollywood","bezug":"Britischer Backstar und Juror in „The Great British Bake Off“; sein Rezept für English Muffins wurde in der Sendung gezeigt und gilt als das, was er bekannt gemacht hat: Hefeteig mit Ei und Butter, in der Pfanne bei sehr niedriger Hitze etwa 5–6 Minuten pro Seite gebacken.","quelle":"https://betterbakerclub.com/english-muffin-recipe-paul-hollywood/"},{"name":"Hannah Glasse","bezug":"Ihr 1747 erschienenes Buch „The Art of Cookery“ enthält frühe Rezepte für Muffins.","quelle":"https://en.wikipedia.org/wiki/English_muffin"},{"name":"Samuel Bath Thomas","bezug":"Englischer Auswanderer, der 1880 in Manhattan die Firma Thomas' gründete und den flachen Pfannen-Muffin auf dem amerikanischen Markt bekannt machte.","quelle":"https://en.wikipedia.org/wiki/English_muffin"}],"quellen":[{"titel":"English muffin – Wikipedia","url":"https://en.wikipedia.org/wiki/English_muffin"},{"titel":"English Muffin Recipe (Paul Hollywood) – Better Baker Club","url":"https://betterbakerclub.com/english-muffin-recipe-paul-hollywood/"}],"bild":"brot","farben":["#c18a3d","#e6c07f","#f5e6c4"],"schlagworte":["Frühstück","England","Pfannenbrot","Toast"],"originalname":"","fleischsorte":"","gang":"brot","vegetarisch_moeglich":true},{"id":"britisch-irisch-trifle","name":"Trifle mit Beeren, Sherry und Vanillecreme","originalname":"English Trifle","kueche":"britisch-irisch","region":"England","beliebtheit":76,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Sherry-getränkter Biskuit, fruchtige Beeren, glatte Vanillecreme und Sahnehaube, in einer großen Glasschüssel geschichtet – das klassische britische Festtagsdessert.","hintergrund":"Trifle ist ein englisches Schichtdessert aus Biskuit, der mit Sherry oder einem anderen Likörwein getränkt wird, Früchten, Vanillecreme und Sahne. Der Name taucht 1585 bei Thomas Dawson auf, damals für eine dicke, mit Ingwer und Rosenwasser gewürzte Creme. Die moderne Form mit getränkten Keksen, Creme und Syllabub ist in Rezepten von 1751 belegt, Trifle mit Gelee kam um 1760 auf. Ihren Höhepunkt erreichte die Beliebtheit im späten 19. Jahrhundert. Ähnliche Desserts sind das schottische Tipsy Laird und das italienische Zuppa Inglese.","portionen":8,"zeit":{"vorbereitung":40,"garen":15,"ruhen":300},"schwierigkeit":2,"zutaten":[{"gruppe":"Biskuit und Beeren","liste":[{"menge":200,"einheit":"g","name":"Löffelbiskuits oder Biskuitboden","hinweis":"in Würfel oder Stücke gebrochen"},{"menge":4,"einheit":"EL","name":"Himbeermarmelade","hinweis":""},{"menge":100,"einheit":"ml","name":"Cream Sherry","hinweis":"oder Madeira; alkoholfrei: Orangensaft"},{"menge":500,"einheit":"g","name":"gemischte Beeren","hinweis":"frisch oder tiefgekühlt, aufgetaut"},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":"für die Beeren"}]},{"gruppe":"Vanillecreme (Custard)","liste":[{"menge":500,"einheit":"ml","name":"Vollmilch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Vanilleschote","hinweis":"Mark ausgekratzt"},{"menge":5,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":2,"einheit":"TL","name":"Speisestärke","hinweis":""}]},{"gruppe":"Haube","liste":[{"menge":400,"einheit":"ml","name":"Sahne","hinweis":"mindestens 30 % Fett"},{"menge":2,"einheit":"EL","name":"Puderzucker","hinweis":""},{"menge":30,"einheit":"g","name":"Mandelblättchen","hinweis":"geröstet"}]}],"ausruestung":["große Glasschüssel (ca. 2 l)","Topf","Schneebesen","Handmixer","Frischhaltefolie"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle die Glasschüssel bereit, in der du später schichtest. Kratze das Mark aus der Vanilleschote, brich die Löffelbiskuits in Stücke und taue gefrorene Beeren vollständig auf, indem du sie in einem Sieb abtropfen lässt und den Saft auffängst. Röste die Mandelblättchen in einer trockenen Pfanne 2 bis 3 Minuten, bis sie goldbraun duften, und lasse sie abkühlen. Stelle die Sahne in den Kühlschrank, sie lässt sich kalt am besten aufschlagen.","dauer":0,"tipp":""},{"titel":"Vanillecreme kochen","aktion":"binden","text":"Erhitze die Milch mit Vanillemark und ausgekratzter Schote in einem Topf bis kurz vor dem Kochen. Verquirle in einer Schüssel Eigelb, Zucker und Speisestärke, bis die Masse hell und dicklich ist. Gieße die heiße Milch langsam unter ständigem Rühren dazu, gib alles zurück in den Topf und erhitze unter Rühren bei niedriger Hitze 5 bis 7 Minuten, bis die Creme dick wird und einen Löffelrücken überzieht. Sie darf nicht kochen, sonst gerinnt das Ei.","dauer":10,"tipp":"Bei etwa 80 °C dickt die Creme ein; über 85 °C droht sie zu gerinnen."},{"titel":"Creme abkühlen","aktion":"kuehlen","text":"Nimm die Vanilleschote heraus und gieße die Creme in eine Schüssel. Lege Frischhaltefolie direkt auf die Oberfläche, damit sich keine Haut bildet, und lass sie auf Zimmertemperatur abkühlen. Stelle sie danach 30 Minuten in den Kühlschrank. Warme Creme würde die Sahneschicht oben später zum Schmelzen bringen und den Biskuit aufweichen.","dauer":40,"tipp":""},{"titel":"Beeren ansetzen","aktion":"marinieren","text":"Vermische die Beeren mit 3 Esslöffeln Zucker und lasse sie 20 bis 30 Minuten ziehen, bis sich Saft gebildet hat. Der Zucker zieht Flüssigkeit aus den Früchten und lässt sie leicht aufweichen und Saft abgeben. Rühre vorsichtig um, damit die Beeren nicht zerfallen. Fange den Saft auf, du kannst ihn über den Biskuit träufeln.","dauer":25,"tipp":""},{"titel":"Biskuit tränken und schichten","aktion":"schichten","text":"Verteile die Hälfte der Biskuitstücke in der Schüssel, bestreiche sie leicht mit der Marmelade und beträufle sie mit der Hälfte des Sherrys. Gib die Hälfte der Beeren samt Saft darüber. Gieße die Hälfte der abgekühlten Creme darauf und streiche sie glatt. Wiederhole mit den restlichen Zutaten. Die Schichten sollen durch das Glas sichtbar bleiben, das gehört zum Anblick des Desserts.","dauer":10,"tipp":""},{"titel":"Durchziehen lassen","aktion":"kuehlen","text":"Decke die Schüssel mit Frischhaltefolie ab und stelle sie mindestens 4 Stunden, besser über Nacht, in den Kühlschrank. In dieser Zeit ziehen Sherry und Fruchtsaft in den Biskuit, die Aromen verbinden sich, und die Schichten setzen sich. Nigella Lawson empfiehlt für ihren Trifle ebenfalls mindestens 4 und bis zu 24 Stunden Kühlzeit.","dauer":300,"tipp":""},{"titel":"Sahne schlagen und garnieren","aktion":"aufschlagen","text":"Schlage die kalte Sahne mit dem Puderzucker mit dem Handmixer steif, bis sie weiche Spitzen bildet. Schlage nicht zu lange, sonst wird sie körnig. Verteile sie in großen Wellen auf der Creme. Bestreue sie mit den gerösteten Mandelblättchen und einigen frischen Beeren. Nimm den Trifle 30 Minuten vor dem Servieren aus dem Kühlschrank, damit sich die Aromen entfalten.","dauer":0,"tipp":""}],"profitipps":["Creme vollständig abkühlen lassen, sonst schmilzt die Sahne und der Biskuit weicht auf.","Biskuit nicht ertränken: Sherry verteilt sich gleichmäßig, aber nicht zu viel.","Mit Folie direkt auf der Creme verhindert man Hautbildung.","Frische Früchte erst kurz vor dem Servieren obenauf legen, damit sie ihre Farbe behalten.","Ein Trifle schmeckt am besten nach einer Nacht im Kühlschrank."],"varianten":["Nigellas Anglo-Italian Trifle mit Limoncello, Amaretti und Mascarpone","Mit Gelee statt frischen Früchten, wie im Viktorianischen England","Tipsy Laird: schottische Variante mit Whisky","Weihnachts-Trifle mit Lebkuchen und Orangen"],"beilagen":["frische Beeren","Vanilleeis","Löffelbiskuits"],"getraenk":"Süßer Sherry, Moscato d'Asti oder Tee.","koeche":[{"name":"Nigella Lawson","bezug":"Ihr Anglo-Italian Trifle verbindet englische Trifle-Tradition mit italienischen Aromen: Biskuit mit Johannisbeermarmelade, Limoncello, Amaretti, Brombeeren und eine Mascarpone-Creme, die sie als den Trifle bezeichnet, der alle Trifles beendet. Sie empfiehlt 4 bis 24 Stunden Kühlzeit.","quelle":"https://www.nigella.com/recipes/anglo-italian-trifle"}],"quellen":[{"titel":"Trifle – Wikipedia","url":"https://en.wikipedia.org/wiki/Trifle"},{"titel":"Nigella – Anglo-Italian Trifle","url":"https://www.nigella.com/recipes/anglo-italian-trifle"}],"bild":"dessert","farben":["#b5264d","#f3dca8","#fff4d6"],"schlagworte":["Dessert","Weihnachten","Schichtdessert","Klassiker"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-cornish-pasty","name":"Cornish Pasty","originalname":"Cornish Pasty","kueche":"britisch-irisch","region":"Cornwall","beliebtheit":75,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Handliche Teigtasche mit rohem Rindfleisch, Kartoffeln, Steckrübe und Zwiebel, in der eigenen Füllung gegart – das Arbeitsessen der Zinnbergleute.","hintergrund":"Der Cornish Pasty war das Essen der Arbeiter in Cornwall und West-Devon, darunter der Zinnbergleute des 17. und 18. Jahrhunderts: eine vollständige Mahlzeit, die ohne Besteck gegessen werden konnte und mit ihrem dichten Teig stundenlang warm blieb. Seit dem 20. Juli 2011 ist die Bezeichnung als g.g.A. geschützt. Ein echter Cornish Pasty ist D-förmig und an der Seite gecrimpt, nicht oben; die Füllung besteht aus Rindfleisch, vorzugsweise Flanksteak, Kartoffel, Steckrübe und Zwiebel mit leichter Würze. Die älteste Erwähnung aus der Region findet sich in den Stadtakten von Plymouth von 1509/10.","portionen":4,"zeit":{"vorbereitung":45,"garen":60,"ruhen":90},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig","liste":[{"menge":500,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus Mehl zum Ausrollen"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":125,"einheit":"g","name":"kalte Butter","hinweis":"in kleinen Würfeln"},{"menge":125,"einheit":"g","name":"Schweineschmalz","hinweis":"kalt; alternativ komplett Butter, 250 g"},{"menge":150,"einheit":"ml","name":"eiskaltes Wasser","hinweis":""}]},{"gruppe":"Füllung","liste":[{"menge":400,"einheit":"g","name":"Rinderflanke oder Hüftsteak","hinweis":"in 1 cm große Würfel geschnitten; Skirt Steak ist ideal"},{"menge":250,"einheit":"g","name":"Kartoffeln","hinweis":"vorwiegend festkochend, geschält, in 5 mm Würfeln"},{"menge":150,"einheit":"g","name":"Steckrübe","hinweis":"geschält, in 5 mm Würfeln; Kohlrübe aus dem Gemüsehandel"},{"menge":100,"einheit":"g","name":"Zwiebel","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.75,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]},{"gruppe":"Zum Bestreichen","liste":[{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"verquirlt"}]}],"ausruestung":["Backblech mit Backpapier","Teller oder Schüssel (20 cm) als Schablone","Nudelholz","Pinsel","scharfes Messer"],"schritte":[{"titel":"Zutaten bereitstellen und schneiden","aktion":"vorbereiten","text":"Schneide das Fleisch in 1 cm große Würfel und lasse es kalt, bis du es brauchst. Schäle die Kartoffeln und die Steckrübe, schneide sie zuerst in 5 mm dicke Scheiben, dann in Stäbchen und schließlich in 5 mm große Würfel. Würfele die Zwiebel fein. Das Gemüse und das Fleisch sollten ungefähr gleich groß sein, damit alles zur gleichen Zeit gar wird. Wiege die Zutaten für den Teig ab und stelle Butter und Schmalz kalt.","dauer":0,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib Mehl und Salz in eine große Schüssel und reibe Butter und Schmalz mit den Fingerspitzen schnell ein, bis die Masse feinen Bröseln gleicht. Gieße das eiskalte Wasser hinzu und verknete alles zügig zu einem geschmeidigen Teig. Knete nur so lange, bis er zusammenhält; zu langes Kneten macht ihn zäh. Der Teig soll fest und etwas elastisch sein, damit er die schwere, rohe Füllung später hält.","dauer":6,"tipp":""},{"titel":"Teig ruhen lassen","aktion":"kuehlen","text":"Forme den Teig zu einer flachen Scheibe, wickle ihn in Frischhaltefolie und lege ihn für mindestens 30 Minuten, besser 1 Stunde, in den Kühlschrank. Die Ruhezeit entspannt das Gluten, sodass der Teig beim Ausrollen nicht zurückschnurrt, und macht die Fettstücke kalt und fest. Das Ergebnis ist ein stabiler, später knuspriger Teig.","dauer":45,"tipp":""},{"titel":"Füllung mischen","aktion":"mischen","text":"Vermische das gewürfelte Fleisch, die Kartoffeln, die Steckrübe und die Zwiebel in einer Schüssel mit Salz und Pfeffer. Die Zutaten bleiben roh; sie garen später im Teig in ihrem eigenen Saft, und der Dampf macht alles saftig und aromatisch. Würze kräftig, denn Kartoffel und Rübe nehmen viel Salz auf. Die Mischung soll locker, nicht zusammengepresst sein.","dauer":5,"tipp":"Ein Stückchen Butter obenauf macht die Füllung noch saftiger."},{"titel":"Teig ausrollen und ausschneiden","aktion":"ausrollen","text":"Teile den Teig in vier gleiche Stücke. Rolle jedes auf einer bemehlten Fläche etwa 3 mm dick aus und schneide mit Teller oder Schüssel und Messer Kreise von etwa 20 cm Durchmesser aus. Lege die Teigkreise nebeneinander bereit. Arbeite zügig, damit der Teig kalt bleibt; wird er weich und klebrig, lege ihn kurz zurück in den Kühlschrank.","dauer":10,"tipp":""},{"titel":"Füllen und falten","aktion":"fuellen","text":"Verteile die Füllung gleichmäßig in der Mitte der Teigkreise, etwa ein Viertel pro Kreis. Bestreiche den Rand mit Wasser oder Ei. Klappe den Teig über die Füllung zu einem Halbkreis und drücke die Ränder fest zusammen, sodass kein Dampf entweichen kann. Die Füllung soll hoch aufgetürmt sein, der Teig nicht zu stark gedehnt werden.","dauer":10,"tipp":""},{"titel":"Rand crimpen","aktion":"formen","text":"Falte den Rand der Teigtasche an der Seite in kleine Falten: Drücke von einem Ende aus die erste Ecke ein, falte dann einen etwa 2,5 cm breiten Streifen nach innen und lege die nächste Falte darüber. Wiederhole das entlang der ganzen Naht, sodass ein seilartiger Rand entsteht. Dieser dicke Rand hält die Pasty dicht und war früher der Griff für schmutzige Hände. Der echte Cornish Pasty ist an der Seite gecrimpt.","dauer":8,"tipp":""},{"titel":"Bestreichen und kühlen","aktion":"kuehlen","text":"Lege die Pasties auf ein mit Backpapier belegtes Blech und bestreiche sie rundum mit verquirltem Ei. Stelle sie 30 Minuten in den Kühlschrank; der kalte Teig behält im Ofen seine Form. Heize währenddessen den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor. Schneide mit der Messerspitze ein kleines Loch in die Oberseite, damit Dampf entweichen kann.","dauer":30,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Backe die Pasties 20 Minuten bei 200 °C, damit sie schnell Farbe nehmen, und reduziere dann auf 170 °C Ober-/Unterhitze (150 °C Umluft) für weitere 35 bis 40 Minuten. Drehe das Blech nach der Hälfte der Zeit, damit alle gleichmäßig bräunen. Sie sind fertig, wenn der Teig tief goldbraun und knusprig ist und das Fleisch im Inneren durchgegart ist. Lass sie 10 Minuten ruhen und serviere sie warm oder kalt.","dauer":58,"tipp":"Frisch aus dem Ofen sind sie sehr heiß: Der Dampf im Inneren kann Zunge und Finger verbrennen."}],"profitipps":["Das Fleisch bleibt roh; es gart im Teig im eigenen Saft und wird dadurch zart.","Kalter Teig und gekühlte Pasties halten die Form im Ofen.","Steckrübe nicht durch Karotte ersetzen: sie gibt den typischen, leicht herben Geschmack.","Die Naht gut verschließen und crimpen, damit kein Saft ausläuft.","Pasties schmecken warm, aber auch kalt hervorragend und lassen sich gut mitnehmen."],"varianten":["Devon-Variante mit Crimp oben auf der Teigtasche","Mit Lammfleisch und Minze","Vegetarisch mit Käse, Zwiebeln und Kartoffeln (Cheese and Onion Pasty)","Mit Hüftsteak statt Flanke"],"beilagen":["Bratensauce (Gravy)","Bohnen","Chutney oder Brown Sauce","grüner Salat"],"getraenk":"Dunkles Ale, Cider aus Cornwall oder Tee.","koeche":[{"name":"Rick Stein","bezug":"Sein Cornish-Steak-Pasty-Rezept aus der Serie Rick Stein's Cornwall verwendet rohes Flankensteak, Kartoffel, Steckrübe und Zwiebel in einem geschichteten Teig, wird seitlich gecrimpt und eine Stunde bei 180 °C gebacken, nachdem die Pasties zuvor eine Stunde gekühlt wurden.","quelle":"https://rickstein.com/blog/rick-stein-cornwall-cornish-steak-pasty-recipe/"}],"quellen":[{"titel":"Cornish pasty – Wikipedia","url":"https://en.wikipedia.org/wiki/Cornish_pasty"},{"titel":"Rick Stein – Cornish Steak Pasty","url":"https://rickstein.com/blog/rick-stein-cornwall-cornish-steak-pasty-recipe/"}],"bild":"gebaeck","farben":["#c58a3a","#e6c27a","#7a4a2a"],"schlagworte":["Cornwall","Teigtasche","Zinnbergbau","Handessen"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-lancashire-hotpot","name":"Lancashire Hotpot","originalname":"Lancashire Hotpot","kueche":"britisch-irisch","region":"Lancashire, Nordwestengland","beliebtheit":74,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"eintopf","kurz":"Zarte Lammstücke in Zwiebelsauce, bedeckt mit einem knusprig gebräunten Dach aus hauchdünnen Kartoffelscheiben – der Schmortopf, der in Nordengland ganze Fabrikarbeiter-Generationen satt gemacht hat.","hintergrund":"Der Lancashire Hotpot stammt aus dem Nordwesten Englands, wo er seit dem 19. Jahrhundert als typisches Arbeiteressen gilt. Das Gericht kam im Ofen oder in der Glut ganz von allein zum Garen, während die Familien in den Baumwollspinnereien arbeiteten – genau darin liegt sein Reiz. Man schichtet Lamm (früher oft zähere Stücke wie Nacken oder Hammel), Zwiebeln und Kartoffelscheiben in einen hohen Topf mit eng schließendem Deckel und lässt alles langsam schmoren. Zum Schluss wird der Deckel abgenommen, damit die oberste Kartoffelschicht goldbraun und an den Rändern knusprig wird. Traditionell isst man dazu eingelegten Rotkohl, dessen Säure die Fülle des Lamms ausgleicht.","portionen":4,"zeit":{"vorbereitung":40,"garen":165,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Fleisch","liste":[{"menge":1.2,"einheit":"kg","name":"Lammnacken mit Knochen oder Lammschulter","hinweis":"in 4–5 cm große Stücke geteilt; der Knochen gibt Geschmack und Gelatine – Metzger bitten, den Nacken in Scheiben zu sägen"},{"menge":2,"einheit":"EL","name":"Weizenmehl","hinweis":"zum Bestäuben"},{"menge":2,"einheit":"EL","name":"Pflanzenöl oder Schweineschmalz","hinweis":"zum Anbraten"},{"menge":2,"einheit":"Stück","name":"Lammnieren","hinweis":"optional, traditionell; Haut und Röhren entfernt, geviertelt"},{"menge":null,"einheit":"","name":"Salz und frisch gemahlener Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für Sauce und Kartoffeldach","liste":[{"menge":3,"einheit":"Stück","name":"Zwiebeln","hinweis":"in dünne Halbringe geschnitten"},{"menge":500,"einheit":"ml","name":"Lammfond oder Rinderbrühe","hinweis":"heiß; alternativ Wasser mit einem guten Brühwürfel"},{"menge":1,"einheit":"EL","name":"Worcestershire-Sauce"},{"menge":2,"einheit":"Blatt","name":"Lorbeer"},{"menge":4,"einheit":"Zweig","name":"Thymian"},{"menge":1,"einheit":"kg","name":"vorwiegend festkochende Kartoffeln","hinweis":"z. B. Sorte Agria oder Belana; sie sollen beim Garen Form halten"},{"menge":40,"einheit":"g","name":"Butter","hinweis":"zum Bestreichen des Kartoffeldachs"},{"menge":1,"einheit":"Stück","name":"Glas eingelegter Rotkohl","hinweis":"zum Servieren; auch selbst gemachter Rotkohl in Essig passt"}]}],"ausruestung":["Gusseisen- oder Keramiktopf mit Deckel (ca. 4 l)","große Pfanne zum Anbraten","scharfes Messer oder Gemüsehobel für die Kartoffelscheiben","Pinsel für die Butter"],"schritte":[{"titel":"Mise en place: Fleisch, Zwiebeln und Kartoffeln vorbereiten","aktion":"vorbereiten","text":"Hole das Lammfleisch eine halbe Stunde vor dem Anbraten aus dem Kühlschrank, damit es nicht eiskalt in die Pfanne kommt und gleichmäßig Farbe nimmt. Tupfe die Stücke mit Küchenpapier trocken, denn Feuchtigkeit verhindert das Bräunen. Schneide die Zwiebeln in Halbringe von etwa 3 mm Dicke und die Kartoffeln mit einem Messer oder Hobel in gleichmäßige Scheiben von höchstens 3 bis 4 mm, damit sie später auch alle zur selben Zeit gar sind. Lege die Kartoffelscheiben bis zur Verwendung in eine Schüssel mit kaltem Wasser, damit sie nicht grau anlaufen, und tupfe sie erst kurz vor dem Schichten trocken. Heize den Ofen noch nicht vor, das passiert erst vor dem Schmoren.","dauer":0,"tipp":"Ein Gemüsehobel (Mandoline) spart Zeit und sorgt für gleich dicke Scheiben – ungleiche Scheiben garen ungleich."},{"titel":"Lamm würzen und bemehlen","aktion":"marinieren","text":"Gib die trockenen Fleischstücke in eine große Schüssel, bestreue sie großzügig mit Salz und Pfeffer und streue das Mehl darüber. Wälze das Fleisch mit den Händen, bis jedes Stück hauchdünn bemehlt ist und nichts mehr feucht glänzt. Das Mehl hilft, eine dunkle Kruste zu bilden, und bindet später ein wenig die Sauce, sodass sie nicht wässrig wird. Klopfe überschüssiges Mehl ab, denn Klumpen am Pfannenboden verbrennen und schmecken bitter.","dauer":0,"tipp":"Die Nieren erst ganz zuletzt bemehlen und nur kurz anbraten, sonst werden sie zäh."},{"titel":"Lamm kräftig anbraten","aktion":"anbraten","text":"Erhitze das Öl in einer schweren Pfanne bei hoher Hitze, bis es leicht flirrt. Brate das Fleisch in drei bis vier Portionen jeweils 3 bis 4 Minuten an, ohne es zu bewegen, bis die Unterseite tiefbraun ist, und wende es erst dann. Überfülle die Pfanne nicht, sonst fällt die Temperatur, das Fleisch gibt Wasser ab und kocht statt zu bräunen. Gib die fertigen Stücke in den Schmortopf. Die braune Kruste ist der wichtigste Geschmacksträger des Gerichts, daher lohnt sich die Geduld.","dauer":15,"tipp":"Entferne zwischendurch verbrannte Mehlreste aus dem Bratfett, sonst wird die Sauce herb."},{"titel":"Zwiebeln anschwitzen und Sauce ansetzen","aktion":"schmoren","text":"Reduziere die Hitze auf mittel und gib die Zwiebeln in das Bratfett der Pfanne. Lass sie unter häufigem Rühren 8 bis 10 Minuten garen, bis sie weich, goldgelb und süßlich duftend sind; dabei löst sich der Bratensatz vom Pfannenboden. Gieße die heiße Brühe und die Worcestershire-Sauce an und koche alles kurz auf, wobei du den Satz mit dem Holzlöffel losschabst. Gieße die Zwiebeln samt Flüssigkeit über das Lamm im Topf, lege Lorbeer und Thymian dazu und schmecke vorsichtig mit Salz ab, denn die Sauce reduziert noch.","dauer":15,"tipp":"Gib nicht zu viel Flüssigkeit zu: Die Kartoffeln garen später im Dampf und saugen die Sauce an, sie soll nicht oben schwimmen."},{"titel":"Ofen vorheizen und Topf schichten","aktion":"schichten","text":"Heize den Ofen auf 160 °C Ober-/Unterhitze (140 °C Umluft) vor und schiebe den Rost auf die untere Schiene. Tupfe die Kartoffelscheiben trocken und lege sie dachziegelartig, eng überlappend auf Fleisch und Zwiebeln, bis die gesamte Oberfläche bedeckt ist. Wer Nieren verwendet, schichtet sie zwischen das Fleisch. Würze die oberste Kartoffellage mit Salz und Pfeffer und stecke ein paar Thymianzweige hinein. Je dichter die Scheiben liegen, desto besser dichten sie den Topf ab und desto saftiger bleibt das Lamm.","dauer":10,"tipp":"Eine Lage Kartoffeln auch zwischen Fleisch und Zwiebeln macht den Topf noch gehaltvoller, weil sie die Sauce binden."},{"titel":"Zugedeckt im Ofen schmoren","aktion":"schmoren","text":"Setze den Deckel fest auf den Topf und schiebe ihn in den Ofen. Lass alles 2 Stunden bei 160 °C Ober-/Unterhitze (140 °C Umluft) schmoren, ohne den Deckel zu öffnen, damit der Dampf im Topf bleibt. Nach 2 Stunden sollte das Lamm sich beim Hineinstechen mit einer Gabel fast von selbst vom Knochen lösen und die Kartoffeln oben müssen weich sein. Du hörst während des Garens nur ein leises Blubbern, wenn der Topf dicht ist. Ist das Fleisch noch fest, gib weitere 20 bis 30 Minuten dazu.","dauer":120,"tipp":"Bei hartem Wasser oder altem Hammelfleisch lieber länger schmoren – das Lamm verzeiht Zeit, aber keine Hast."},{"titel":"Deckel ab: Kartoffeldach bräunen","aktion":"backen","text":"Nimm den Deckel ab, schmelze die Butter und bestreiche die Kartoffeloberfläche damit großzügig. Erhöhe die Temperatur auf 200 °C Ober-/Unterhitze (180 °C Umluft) und backe den Hotpot unbedeckt weitere 35 bis 40 Minuten. Die Oberfläche soll tief goldbraun und an den Rändern knusprig sein, und die Sauce am Topfrand leise blubbern. Wird das Dach zu schnell dunkel, deckst du es locker mit Alufolie ab. Dieser Moment macht den Hotpot zum Hotpot, denn der Kontrast zwischen weichem Inneren und knuspriger Kruste ist sein Markenzeichen.","dauer":40,"tipp":"Für eine besonders knusprige Kruste die letzten 5 Minuten den Grill (Oberhitze) zuschalten, aber nicht weglaufen."},{"titel":"Ruhen lassen und anrichten","aktion":"anrichten","text":"Nimm den Topf aus dem Ofen und lass ihn 10 Minuten ruhen, damit sich die Sauce setzt und die Kartoffeln nicht mehr zerfallen. Entferne Thymianzweige und Lorbeerblätter. Schöpfe mit einem großen Löffel aus der Tiefe, sodass jeder Teller etwas vom Kartoffeldach, Fleisch und Sauce bekommt. Serviere den Hotpot sehr heiß mit eingelegtem Rotkohl, dessen Säure und Biss die Schwere des Lamms ausgleichen, und mit frischem Brot, um die Sauce aufzunehmen.","dauer":10,"tipp":"Am nächsten Tag schmeckt der Hotpot noch besser – aufgewärmt im Ofen wird die Kruste sogar wieder knusprig."}],"profitipps":["Fleisch am Knochen verwenden: Er liefert Gelatine und Aroma, und die Sauce wird dadurch von selbst sämig.","Kartoffelscheiben dünn und gleichmäßig schneiden – zu dicke Scheiben sind beim Servieren noch fest, zu dünne zerfallen.","Deckel während der ersten zwei Stunden geschlossen halten; der eingeschlossene Dampf gart die Kartoffeln und hält das Lamm saftig.","Salz maßvoll einsetzen, solange die Sauce noch reduziert – die Brühe konzentriert sich im Ofen.","Eingelegter Rotkohl oder Silberzwiebeln dazu sind kein Beiwerk, sondern gehören zum traditionellen Genuss."],"varianten":["Mit Lammnieren und Austern (historische Version aus Lancashire)","Mit Hammel statt Lamm für kräftigeren Geschmack","Mit Rinderwade und Bier als Sauce – nahe verwandt mit dem Eintopf der britischen Arbeiterküche","Mit Karotten und Lauch zwischen den Lagen als Gemüsevariante"],"beilagen":["eingelegter Rotkohl","Silberzwiebeln","Erbsen oder grüne Bohnen","dunkles Brot"],"getraenk":"Ein britisches Ale (Bitter oder Brown Ale) oder ein kräftiger Rotwein aus dem Rhône-Tal","koeche":[{"name":"Mary Berry","bezug":"Die britische Backbuch- und Fernsehautorin hat ein viel zitiertes Rezept für den Lancashire Hotpot veröffentlicht, das auch in der englischen Fachpresse als Referenz genannt wird.","quelle":"https://en.wikipedia.org/wiki/Lancashire_hotpot"}],"quellen":[{"titel":"Lancashire hotpot – Wikipedia","url":"https://en.wikipedia.org/wiki/Lancashire_hotpot"}],"bild":"eintopf","farben":["#a8651f","#d9a441","#5a3216"],"schlagworte":["England","Lancashire","Lamm","Schmortopf","Ofengericht","Arbeiteressen"],"vegetarisch_moeglich":false,"themen":[]},{"id":"britisch-irisch-roastbeef-zwiebelsauce-ramsay","name":"Roastbeef mit karamellisierter Zwiebelsauce nach Art von Gordon Ramsay","originalname":"Roast Beef with Caramelised Onion Gravy","kueche":"britisch-irisch","region":"England","beliebtheit":74,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Rosa gebratenes Roastbeef, mit Knoblauch und Thymian gewürzt, dazu eine tiefdunkle Sauce aus karamellisierten Zwiebeln und Rotwein, direkt im Bratentopf gekocht. Ein Sonntagsbraten ohne Schnickschnack.","hintergrund":"Roastbeef mit Yorkshire Pudding gilt als das englische Sonntagsessen schlechthin. Ramsay veröffentlicht auf seiner Webseite eine Version, bei der das Fleisch mit Knoblauch und Thymian eingerieben, scharf angebraten und im Ofen rosa gegart wird. Die Sauce entsteht im selben Bräter, in dem das Fleisch gebraten wurde, aus Zwiebeln, Mehl, Rotwein und Brühe. Dies ist eine Heimküchen-Fassung nach seinem veröffentlichten Rezept, mit meinen Erklärungen zu jedem Schritt.","portionen":6,"zeit":{"vorbereitung":30,"garen":100,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Roastbeef","liste":[{"menge":1.8,"einheit":"kg","name":"Rinderhüfte oder Roastbeef am Stück (Sirloin)","hinweis":"möglichst mit etwas Fettdeckel, beim Metzger vorbestellen"},{"menge":1,"einheit":"Knolle","name":"Knoblauch","hinweis":"quer halbiert, ca. 12 Zehen"},{"menge":6,"einheit":"Zweig","name":"Thymian","hinweis":"5 Zweige abzupfen, 1 ganz lassen"},{"menge":3,"einheit":"EL","name":"Olivenöl","hinweis":"3–4 EL nach Bedarf"},{"menge":null,"einheit":"","name":"Meersalz und schwarzer Pfeffer","hinweis":"kräftig"}]},{"gruppe":"Für die Zwiebelsauce","liste":[{"menge":4,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in feine Ringe geschnitten"},{"menge":150,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"so in der Vorlage angegeben; für eine schlankere Sauce kannst du weniger nehmen"},{"menge":500,"einheit":"ml","name":"kräftiger Rotwein","hinweis":"trocken, kein billiger Kochwein"},{"menge":1.5,"einheit":"l","name":"heiße Rinderbrühe","hinweis":"gute Qualität"}]}],"ausruestung":["Bräter oder feuerfeste Bratform, auch auf dem Herd nutzbar","große Pfanne","Fleischthermometer","Alufolie","warme Platte"],"schritte":[{"titel":"Mise en place und Fleisch würzen","aktion":"vorbereiten","text":"Nimm das Roastbeef etwa eine Stunde vor dem Braten aus dem Kühlschrank, damit es nicht eiskalt in den Ofen kommt. Halbiere die Knoblauchknolle quer, zupfe von fünf Thymianzweigen die Blättchen ab und reibe das Fleisch rundum mit den Knoblauchhälften und den Blättchen ein. Beträufle es mit drei bis vier Esslöffeln Olivenöl und reibe es ein, bis die Oberfläche gleichmäßig glänzt. Salzen und pfeffern kannst du jetzt großzügig. Schneide die vier Zwiebeln in feine Ringe und lege sie beiseite, denn sie brauchen später den Bräter.","dauer":15,"tipp":"Wer Zeit hat, lässt das Fleisch ein bis zwei Tage so im Kühlschrank durchziehen – das macht es aromatischer."},{"titel":"Ofen vorheizen und Fleisch scharf anbraten","aktion":"anbraten","text":"Heize den Ofen auf 190 °C Ober-/Unterhitze vor, bei Umluft auf 170 °C. Erhitze eine große Pfanne ohne Fett, bis sie sehr heiß ist und leicht raucht, und brate das Roastbeef darin rundherum an. Es zischt laut und bekommt nach etwa zwei bis drei Minuten pro Seite eine tiefbraune Kruste. Drehe es erst, wenn es sich von allein löst; klebt es fest, ist es noch nicht fertig gebräunt. Die Kruste bringt Röstaromen und hält später den Saft im Inneren.","dauer":12,"tipp":"Das Fleisch gut abtupfen: Feuchtigkeit verhindert die Bräunung."},{"titel":"Im Ofen rosa garen","aktion":"braten","text":"Lege die Knoblauchhälften und den ganzen Thymianzweig in einen großen Bräter, der auch auf den Herd darf, und setze das Roastbeef darauf. Schiebe ihn in die Mitte des Ofens und brate das Fleisch etwa 45 Minuten für medium rare. In der Vorlage wird dafür eine Kerntemperatur von 45–47 °C genannt. Für medium rechnest du 10–12 Minuten mehr (55–60 °C), für durchgebraten etwa 20 Minuten mehr. Stecke das Fleischthermometer in die dickste Stelle und prüfe lieber früher als später.","dauer":45,"tipp":"Ein Kernthermometer ist beim Roastbeef die beste Investition, denn Garzeiten hängen von Form und Ofen ab."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Hole das Fleisch aus dem Ofen und lege es auf eine vorgewärmte Platte. Deck es locker mit Alufolie ab und lass es mindestens 20 Minuten, am besten bis zu 40 Minuten, ruhen. In dieser Zeit verteilen sich die Säfte wieder im Fleisch, und die Kerntemperatur steigt noch etwas nach. Schneidest du zu früh an, läuft der Saft auf das Brett und das Fleisch wird trocken. Nutze die Zeit für die Sauce und lass den Bräter dafür auf der Herdplatte stehen.","dauer":30,"tipp":"Je länger das Fleisch ruht, desto saftiger bleibt es – du kannst es also in Ruhe vor dem Servieren anrichten."},{"titel":"Zwiebeln im Bratensatz karamellisieren","aktion":"schmoren","text":"Stelle den Bräter mit dem Bratensaft und dem Knoblauch bei niedriger Hitze auf den Herd und gib die Zwiebelringe hinein. Lass sie etwa 20 Minuten unter gelegentlichem Rühren langsam weich und goldbraun werden. Sie nehmen den Bratensatz auf, werden süß und duften nach Karamell. Sind sie nur blass, brauchen sie länger; verbrennen sie, hast du zu stark erhitzt. Schiebe den Knoblauch zur Seite, er soll nur leicht Aroma abgeben.","dauer":20,"tipp":"Ein Spritzer Wasser löst festgebackenen Bratensatz am Boden, ohne dass die Zwiebeln anbrennen."},{"titel":"Mehl einrühren und mit Wein ablöschen","aktion":"reduzieren","text":"Streue das Mehl über die Zwiebeln und rühre es etwa eine Minute ein, bis keine weißen Klümpchen mehr zu sehen sind und es leicht nussig riecht. Gieße den Rotwein dazu und rühre kräftig mit dem Schneebesen, damit keine Klumpen bleiben. Lass den Wein stark kochen, bis er etwa auf die Hälfte reduziert ist. Der Alkohol verfliegt, die Säure rundet sich ab, und die Sauce wird dunkel und glänzend. Das dauert in der Regel zehn bis fünfzehn Minuten.","dauer":12,"tipp":"Gieße den Wein in mehreren Portionen ein, dann bleibt die Sauce glatter."},{"titel":"Brühe zugeben und sämig einkochen","aktion":"binden","text":"Gib die heiße Brühe nach und nach unter Rühren in den Bräter. Lass die Sauce bei mittlerer Hitze etwa acht Minuten kochen, bis sie dick genug ist, um einen Löffelrücken zu überziehen. Probiere und schmecke mit Salz und Pfeffer ab. Wird sie zu dick, verdünne sie mit etwas Brühe, wird sie zu dünn, lass sie weiter einkochen. Gieße die Sauce zum Servieren in eine vorgewärmte Kanne; sie hält sich auf kleiner Flamme gut warm.","dauer":10,"tipp":"Heiße Brühe verhindert, dass die Sauce klumpt, kalte Flüssigkeit lässt das Mehl verkleben."},{"titel":"Tranchieren und anrichten","aktion":"anrichten","text":"Schneide das Roastbeef mit einem langen, scharfen Messer quer zur Faser in dünne Scheiben. Die Schnittfläche soll gleichmäßig rosa sein, mit einem schmalen braunen Rand. Lege die Scheiben auf eine vorgewärmte Platte, träufle den ausgetretenen Fleischsaft darüber und serviere die Zwiebelsauce getrennt dazu. Passend sind Yorkshire Puddings, Röstkartoffeln und gedünsteter Mangold, so wie Ramsay es zum Fleisch empfiehlt.","dauer":10,"tipp":"Wärme die Teller vor, denn kaltes Porzellan kühlt Fleisch und Sauce sofort aus."}],"profitipps":["Das Fleisch rechtzeitig aus dem Kühlschrank nehmen, damit es gleichmäßiger gart.","Mit dem Kernthermometer arbeiten: 45–47 °C für medium rare laut Vorlage, danach ruhen lassen.","Das Ruhen ist Pflicht: 20 bis 40 Minuten unter Folie, damit der Saft im Fleisch bleibt.","Die Sauce direkt im Bratentopf kochen, denn der Bratensatz ist der Geschmacksträger.","Das Mehl gut anrösten und heiße Brühe verwenden, damit die Sauce glatt und klumpenfrei wird."],"varianten":["Mit Schalotten statt Zwiebeln für eine feinere Sauce.","Mit einem Löffel Johannisbeergelee in der Sauce.","Als kaltes Roastbeef mit Remoulade und Bratkartoffeln.","Mit Meerrettichsahne als Beigabe."],"beilagen":["Yorkshire Puddings","Röstkartoffeln","Mangold oder Rosenkohl","Meerrettich"],"getraenk":"Kräftiger Rotwein, etwa ein Rioja oder ein Bordeaux.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht dieses Roastbeef auf seiner Webseite mit Knoblauch-Thymian-Marinade und einer Sauce aus Zwiebeln, Rotwein und Brühe, die er direkt im Bratentopf zubereitet.","quelle":"https://www.gordonramsay.com/gr/recipes/roast-beef-with-caramelised-onion-gravy/"}],"quellen":[{"titel":"Gordon Ramsay – Roast Beef with Caramelised Onion Gravy","url":"https://www.gordonramsay.com/gr/recipes/roast-beef-with-caramelised-onion-gravy/"},{"titel":"Gordon Ramsay – Rezeptübersicht","url":"https://www.gordonramsay.com/gr/recipes/"}],"bild":"braten-scheiben","farben":["#7a3b2e","#c0504d","#e8c9a0"],"schlagworte":["Sonntagsbraten","Gordon Ramsay","Roastbeef","England"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-irish-stew","name":"Irish Stew","originalname":"Irish Stew","kueche":"britisch-irisch","region":"Irland","beliebtheit":74,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Zartes Lamm mit Kartoffeln und Zwiebeln, langsam im eigenen Saft geköchelt – irisches Nationalgericht in seiner einfachsten und besten Form.","hintergrund":"Irish Stew gilt als irisches Nationalgericht und besteht traditionell aus Lamm oder Hammel, Kartoffeln, Zwiebeln und Petersilie. Ursprünglich wurde im Kessel über offenem Feuer gekocht, denn Backöfen waren in Irland lange kaum verbreitet. Ältere Tiere, deren Wolle und Milch nicht mehr wirtschaftlich waren, landeten im Topf, weshalb Hammel dominierte. Manche Historiker vermuten, dass ursprünglich Ziege üblich war. Kartoffeln kamen im 16. Jahrhundert nach Irland. Purist:innen lehnen Karotten, Rüben und Perlgraupen ab, andere verwenden sie gern.","portionen":4,"zeit":{"vorbereitung":30,"garen":120,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Eintopf","liste":[{"menge":1.2,"einheit":"kg","name":"Lammschulter oder Lammhals mit Knochen","hinweis":"in 4 cm große Stücke geschnitten; Knochen verbessern die Brühe"},{"menge":1,"einheit":"kg","name":"Kartoffeln","hinweis":"halb mehlig, halb festkochend, geschält"},{"menge":4,"einheit":"Stück","name":"Zwiebeln","hinweis":"in dicke Ringe geschnitten"},{"menge":3,"einheit":"Stück","name":"Karotten","hinweis":"optional, in dicke Scheiben geschnitten"},{"menge":3,"einheit":"Zweig","name":"Thymian","hinweis":""},{"menge":1,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":700,"einheit":"ml","name":"Wasser oder leichte Lammbrühe","hinweis":""},{"menge":2,"einheit":"EL","name":"glatte Petersilie","hinweis":"gehackt, zum Servieren"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":""}]}],"ausruestung":["schwerer Schmortopf mit Deckel","Schaumlöffel","scharfes Messer"],"schritte":[{"titel":"Fleisch und Gemüse vorbereiten","aktion":"schneiden","text":"Schneide das Fleisch vom Knochen und in etwa 4 cm große Würfel, wobei du überschüssigen Fettrand entfernst, aber etwas Fett zurücklässt, das Geschmack gibt. Bewahre die Knochen auf, sie geben dem Eintopf Tiefe. Schäle Kartoffeln und Zwiebeln, schneide die Zwiebeln in dicke Ringe und teile die Kartoffeln: die Hälfte in große, die Hälfte in kleinere Stücke, denn die kleinen zerfallen und binden die Brühe. Lege alles bereit.","dauer":0,"tipp":""},{"titel":"Fleisch blanchieren","aktion":"blanchieren","text":"Gib Fleisch und Knochen in einen großen Topf, bedecke sie mit kaltem Wasser und bringe sie langsam zum Kochen. Lass sie 3 bis 5 Minuten sieden, bis grauer Schaum aufsteigt. Gieße das Wasser ab, spüle das Fleisch kurz unter kaltem Wasser ab und wasche den Topf aus. Dieser Schritt entfernt Eiweiß und Blutreste, sodass der Eintopf später klar und mild schmeckt.","dauer":8,"tipp":""},{"titel":"Schichten","aktion":"schichten","text":"Lege den Boden des Topfes mit der Hälfte der Zwiebeln und Karotten aus, gib das Fleisch und die Knochen darauf, dann Thymian und Lorbeer, und salze und pfeffere jede Schicht leicht. Bedecke mit den großen Kartoffelstücken und den restlichen Zwiebeln. Die Kartoffeln garen im Dampf, während die kleineren die Brühe binden. Gieße so viel Wasser hinzu, dass alles gerade bedeckt ist, das sind etwa 700 ml.","dauer":10,"tipp":""},{"titel":"Aufkochen und abschäumen","aktion":"kochen","text":"Bringe den Topf bei mittlerer Hitze zum Kochen und schöpfe den aufsteigenden Schaum mit einer Kelle ab. Stelle dann die Hitze auf die niedrigste Stufe und setze den Deckel leicht versetzt auf. Die Flüssigkeit darf nur leise blubbern, denn heftiges Kochen macht das Fleisch zäh und trübt die Brühe. Ein Hauch von Dampf über dem Topf ist ein gutes Zeichen.","dauer":10,"tipp":""},{"titel":"Langsam schmoren","aktion":"schmoren","text":"Lasse den Eintopf 1,5 bis 2 Stunden bei kleinster Hitze schmoren. Rühre nur vorsichtig um, damit die Kartoffeln nicht zerfallen. Nach etwa 90 Minuten ist das Fleisch zart und löst sich vom Knochen, die kleineren Kartoffelstücke haben sich aufgelöst und die Brühe leicht sämig gemacht. Prüfe mit einer Gabel: Das Lamm soll sich ohne Widerstand zerteilen lassen.","dauer":110,"tipp":"Der Eintopf schmeckt am besten, wenn er nie richtig kocht, sondern nur leise zieht."},{"titel":"Knochen entfernen und abschmecken","aktion":"abschmecken","text":"Nimm die Knochen, Thymianzweige und das Lorbeerblatt heraus. Schöpfe überschüssiges Fett von der Oberfläche mit einem Löffel ab. Schmecke mit Salz und frisch gemahlenem Pfeffer ab. Wenn die Brühe zu dünn ist, zerdrücke einige Kartoffeln gegen den Topfrand; ist sie zu dick, gieße einen Schuss heißes Wasser hinzu. Die Konsistenz soll eher dickflüssig sein, wie eine kräftige Suppe.","dauer":5,"tipp":""},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse den Eintopf 10 Minuten mit aufgelegtem Deckel ruhen. Die Aromen verbinden sich, die Brühe bindet sich leicht, und das Fleisch bleibt saftig. Wie viele Eintöpfe schmeckt Irish Stew am nächsten Tag noch besser, wenn er über Nacht durchgezogen ist und dann sanft aufgewärmt wird.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile den Eintopf in vorgewärmte tiefe Teller oder Schalen, sodass jeder Fleisch, Kartoffeln und Brühe bekommt. Bestreue großzügig mit gehackter Petersilie, die dem Gericht Frische und Farbe verleiht. Serviere dazu Irish Soda Bread und Butter, mit dem du die Brühe auftunkst. Am Tisch ergänzt etwas Pfeffer aus der Mühle.","dauer":0,"tipp":""}],"profitipps":["Fleisch am Knochen verwenden; Knochen geben Geschmack und Bindung.","Nie sprudelnd kochen, nur leise ziehen lassen: So bleibt das Lamm zart.","Gemischte Kartoffelsorten verwenden; die mehligen zerfallen und binden die Brühe.","Der Eintopf schmeckt am nächsten Tag noch besser; Fett vorher von der Oberfläche abschöpfen.","Karotten sind Geschmackssache; Puristen lassen sie weg."],"varianten":["Mit Perlgraupen für mehr Bindung","Mit Guinness für eine dunklere, malzige Brühe","Mit Rindfleisch als Beef Stew","Mit Lammkeule und Petersilienwurzeln"],"beilagen":["Irish Soda Bread","Butter","Kohl oder Wirsing"],"getraenk":"Guinness oder ein irisches Red Ale; als Wein ein kräftiger Rotwein.","koeche":[],"quellen":[{"titel":"Irish stew – Wikipedia","url":"https://en.wikipedia.org/wiki/Irish_stew"}],"bild":"eintopf","farben":["#a8794a","#e6d2a3","#5b7a3a"],"schlagworte":["Irland","Eintopf","Lamm","Nationalgericht"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-banoffee-pie","name":"Banoffee Pie","kueche":"britisch-irisch","region":"East Sussex, England","beliebtheit":72,"bild":"torte","kurz":"Keksboden, dicke Toffeeschicht, reife Bananen und eine Haube aus Sahne: Ein englischer Pub-Klassiker, der ohne Backofen auskommt.","hintergrund":"Banoffee Pie wurde Anfang der 1970er Jahre im Restaurant The Hungry Monk im ostenglischen Jevington erfunden. Nigel Mackenzie und Ian Dowding verfeinerten dort ein amerikanisches Rezept für Toffee-Kaffee-Kuchen, bis sie mit Bananen die perfekte Kombination fanden. Der Name ist ein Wortspiel aus „banana“ und „toffee“. Der Kuchen wurde schnell britisches Nationalgut, zu finden auf fast jeder Pub-Dessertkarte. Das Besondere ist, dass die Toffeecreme aus gezuckerter Kondensmilch entsteht und der Kuchen weitgehend ohne Ofen auskommt.","portionen":10,"zeit":{"vorbereitung":30,"garen":180,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Boden","liste":[{"menge":250,"einheit":"g","name":"Vollkorn- oder Butterkekse","hinweis":"Digestive-Kekse sind original; als Alternative Butterkekse mit 1 Prise Salz"},{"menge":120,"einheit":"g","name":"Butter","hinweis":"geschmolzen"}]},{"gruppe":"Toffee","liste":[{"menge":2,"einheit":"Dose","name":"gezuckerte Kondensmilch","hinweis":"je 397 g; alternativ fertiger Dulce de Leche (ca. 800 g)"},{"menge":1,"einheit":"Prise","name":"Meersalz","hinweis":""}]},{"gruppe":"Belag","liste":[{"menge":3,"einheit":"Stück","name":"reife Bananen","hinweis":"mittelgroß, gelb mit leichten Punkten"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":300,"einheit":"ml","name":"Schlagsahne","hinweis":"sehr kalt"},{"menge":1,"einheit":"EL","name":"Puderzucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Instantkaffee","hinweis":"optional, in 1 TL Wasser gelöst"},{"menge":30,"einheit":"g","name":"Zartbitterschokolade","hinweis":"zum Hobeln"}]}],"ausruestung":["Springform 24 cm","großer Topf","Küchenhandtuch oder Untersetzer","Handrührer","Gemüsehobel oder Reibe"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Fette den Boden und die Ränder der Springform leicht ein und lege den Boden mit Backpapier aus, damit sich der fertige Kuchen später problemlos lösen lässt. Zerbrösele die Kekse in einem Gefrierbeutel mit dem Nudelholz oder in der Küchenmaschine zu feinen Bröseln, die keine großen Stücke mehr enthalten. Schmilz die Butter in einem kleinen Topf bei niedriger Hitze und lass sie kurz abkühlen. Stelle die Sahne kalt, sie wird am Ende geschlagen und verträgt keine Wärme.","dauer":10,"tipp":""},{"titel":"Keksboden formen","aktion":"formen","text":"Vermische die Keksbrösel und die flüssige Butter gründlich, bis das Ganze wie feuchter Sand aussieht und sich in der Faust zusammendrücken lässt. Gib die Masse in die Springform, drücke sie mit dem Boden eines Glases fest und gleichmäßig an und ziehe einen etwa 3 cm hohen Rand hoch. Festes Andrücken ist wichtig, denn der Boden hält später die schwere Toffeeschicht. Stelle die Form für mindestens 30 Minuten ins Gefrierfach, bis die Butter fest geworden ist.","dauer":35,"tipp":"Ein Glas mit geradem Boden presst den Rand gleichmäßiger als die Hände."},{"titel":"Toffee kochen","aktion":"kochen","text":"Lege die ungeöffneten Dosen mit Kondensmilch in einen hohen Topf und fülle ihn so mit Wasser, dass die Dosen immer mindestens 5 cm bedeckt sind. Lass das Wasser bei schwacher Hitze köcheln, 2,5 bis 3 Stunden lang, und fülle bei Bedarf kochendes Wasser nach. Dosen, die aus dem Wasser ragen, können platzen. Nimm sie anschließend heraus und lass sie vollständig abkühlen, bevor du sie öffnest. Der Inhalt ist nun goldbraun, zäh und duftet nach Karamell. Wer Sicherheit will, nimmt fertigen Dulce de Leche.","dauer":170,"tipp":"Dosen nie unbeaufsichtigt köcheln lassen und nie heiß öffnen – heißes Karamell spritzt."},{"titel":"Toffee einfüllen","aktion":"schichten","text":"Öffne die abgekühlten Dosen, gib den Inhalt in eine Schüssel und rühre ihn mit einer Prise Meersalz glatt. Die Masse sollte sich streichen lassen, aber nicht laufen. Ist sie zu fest, rühre einen Esslöffel Milch ein. Verteile das Toffee gleichmäßig auf dem gekühlten Keksboden und streiche es mit einem feuchten Löffelrücken glatt. Stelle die Form für mindestens zwei Stunden in den Kühlschrank, bis das Toffee fest ist und sich beim Schneiden nicht mehr bewegt.","dauer":120,"tipp":"Das Salz hebt das Karamellaroma und bremst die Süße spürbar."},{"titel":"Bananen und Sahne vorbereiten","aktion":"schneiden","text":"Schneide die Bananen kurz vor dem Servieren in etwa 5 mm dicke Scheiben und beträufle sie mit Zitronensaft, damit sie nicht braun werden. Schlage die kalte Sahne mit Puderzucker und, wenn du magst, mit dem gelösten Instantkaffee auf, bis sie weiche, aber standfeste Spitzen bildet. Sie soll glänzen und beim Anheben des Rührers eine Spitze halten, ohne körnig zu werden. Schlägst du zu lange, gerät sie zu fest und lässt sich nicht mehr streichen.","dauer":10,"tipp":""},{"titel":"Belegen und garnieren","aktion":"garnieren","text":"Lege die Bananenscheiben dicht an dicht oder in leicht überlappenden Kreisen auf das Toffee. Verteile die Sahne darüber, entweder mit dem Löffel in rustikalen Wellen oder mit einem Spritzbeutel in Tupfen. Hobel die Zartbitterschokolade mit einem Sparschäler direkt darüber, sodass feine Späne herabrieseln. Stelle den Kuchen bis zum Servieren kühl, er schmeckt am besten nach ein bis zwei Stunden Ruhe, aber noch am selben Tag.","dauer":15,"tipp":"Erst kurz vorm Servieren mit Banane belegen, sonst oxidieren die Scheiben und die Sahne wird wässrig."}],"profitipps":["Gekauften Dulce de Leche kannst du direkt nutzen und sparst dir die dreistündige Kochzeit.","Nur reife, aber nicht überreife Bananen nehmen – sonst wird der Belag matschig.","Den Kuchen mit einem heißen, feuchten Messer schneiden, so bleibt der Toffee sauber an seinem Platz.","Eine Prise Salz im Toffee gleicht die Süße aus.","Die Dosen beim Kochen immer unter Wasser halten – das ist die wichtigste Sicherheitsregel."],"varianten":["Mit Mürbeteigboden statt Keksen, wie ursprünglich","Mit Kaffee-Sahne und Schokoladenraspeln","Mit Erdnussbutter im Toffee","Als Gläschen-Dessert in Einmachgläsern"],"beilagen":["frischer Kaffee","Vanilleeis"],"getraenk":"Starker schwarzer Tee oder Kaffee","koeche":[{"name":"Ian Dowding","bezug":"Gilt gemeinsam mit Nigel Mackenzie als Erfinder des Banoffee Pie, den er als Koch im Restaurant The Hungry Monk 1971 entwickelte.","quelle":"https://en.wikipedia.org/wiki/Banoffee_pie"}],"quellen":[{"titel":"Banoffee pie – Wikipedia","url":"https://en.wikipedia.org/wiki/Banoffee_pie"}],"farben":["#c68a43","#f3e1a8","#5a3a22"],"schlagworte":["Pub-Klassiker","ohne Backen","Toffee"],"originalname":"","fleischsorte":"","hauptkategorie":"suess","gang":"dessert","vegetarisch_moeglich":true},{"id":"britisch-irisch-cullen-skink","name":"Cullen Skink – schottische Räucherfisch-Suppe","originalname":"Cullen Skink","kueche":"britisch-irisch","region":"Schottland (Cullen, Moray)","beliebtheit":72,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"suppe","kurz":"Cremige, rauchige Suppe aus Räucherschellfisch, Kartoffeln und Zwiebeln – Schottlands Küstenklassiker, der an kalten Tagen von innen wärmt.","hintergrund":"Cullen Skink stammt aus dem Küstenort Cullen in der Grafschaft Moray im Nordosten Schottlands. Der Überlieferung nach erfanden die Fischer die Suppe, um ihren reichlichen Schellfischfang zu verwerten. Das Wort Skink bedeutet im Schottischen ursprünglich Hachse oder Haxe vom Rind und wurde später zum Wort für eine kräftige Suppe. Authentisch wird der geräucherte Schellfisch Finnan Haddie verwendet, ein kalt geräucherter, ungefärbter Schellfisch; im Handel findest du ihn oft als ungefärbten Räucherschellfisch. Die Suppe wird in Schottland als Vorspeise bei festlichen Essen serviert, oft mit Brot oder Haferkeksen. Jedes Jahr findet in Cullen sogar eine Weltmeisterschaft im Cullen-Skink-Kochen statt.","portionen":4,"zeit":{"vorbereitung":20,"garen":30,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Suppe","liste":[{"menge":400,"einheit":"g","name":"ungefärbter geräucherter Schellfisch (Finnan Haddie)","hinweis":"ersatzweise ungefärbter Räucherkabeljau oder -seelachs aus der Fischtheke; Tiefkühlware geht auch"},{"menge":500,"einheit":"g","name":"mehligkochende Kartoffeln","hinweis":"z. B. Agria oder Marabel"},{"menge":1,"einheit":"Stück","name":"große Zwiebel (ca. 150 g)","hinweis":"fein gewürfelt"},{"menge":40,"einheit":"g","name":"Butter","hinweis":""},{"menge":500,"einheit":"ml","name":"Vollmilch","hinweis":""},{"menge":250,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":100,"einheit":"ml","name":"Sahne","hinweis":"optional, für mehr Cremigkeit"},{"menge":null,"einheit":"","name":"frisch gemahlener Pfeffer","hinweis":"nach Geschmack"},{"menge":null,"einheit":"","name":"Salz","hinweis":"erst am Ende, da Räucherfisch salzig ist"},{"menge":1,"einheit":"EL","name":"Schnittlauch oder Petersilie, fein gehackt","hinweis":"zum Servieren"}]}],"ausruestung":["großer Topf mit Deckel","Kartoffelstampfer","Schaumkelle","Suppenkelle"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Schäle die Kartoffeln und schneide sie in 1 bis 1,5 cm große Würfel; kleine, gleichmäßige Stücke garen schnell und lassen sich später gut zerdrücken. Würfele die Zwiebel fein und hacke die Kräuter. Prüfe den Fisch auf Gräten, indem du mit dem Finger gegen die Faserrichtung über die Mitte fährst, und entferne sie mit einer Pinzette. Ungefärbter Räucherfisch ist hellbeige bis cremeweiß und riecht rauchig-süßlich; leuchtend gelbe Ware ist gefärbt und für dieses Gericht nicht geeignet.","dauer":15,"tipp":"Wähle immer ungefärbten Räucherfisch: Der Geschmack ist weicher und sauberer."},{"titel":"Fisch pochieren","aktion":"kochen","text":"Lege den Fisch mit der Haut nach unten in einen weiten Topf, gieße Milch und Wasser darüber und gib das Lorbeerblatt dazu. Erhitze alles langsam, bis kleine Bläschen am Rand aufsteigen; die Flüssigkeit darf nicht sprudelnd kochen, sonst flockt die Milch aus. Lasse den Fisch 5 bis 6 Minuten sanft ziehen, bis er an der dicksten Stelle milchig-weiß ist und sich mit einer Gabel in Lamellen teilen lässt. Hebe ihn mit einer Schaumkelle heraus, lege ihn auf einen Teller und seihe den Sud durch ein Sieb in ein Gefäß; er enthält das gesamte Raucharoma.","dauer":8,"tipp":"Den Sud nie wegschütten: Er ist die Suppenbasis."},{"titel":"Fisch zerpflücken","aktion":"vorbereiten","text":"Ziehe die Haut vom abgekühlten Fisch ab und zupfe das Fleisch in mundgerechte Stücke von etwa 2 cm. Schiebe dabei noch einmal mit den Fingern über das Fleisch, um letzte Gräten zu finden. Stelle die Hälfte der Stücke zur Seite; sie werden am Schluss in die Suppe gegeben, damit sie nicht zerfallen. Die andere Hälfte darf beim Rühren zerfallen und die Suppe aromatisieren.","dauer":8,"tipp":"Nicht zu fein zerpflücken: Die Stücke sollen als Einlage erkennbar bleiben."},{"titel":"Zwiebel andünsten","aktion":"anbraten","text":"Schmilz die Butter im Topf bei mittlerer Hitze. Gib die Zwiebelwürfel hinein und dünste sie 6 bis 8 Minuten unter gelegentlichem Rühren, bis sie glasig, weich und leicht süßlich duften, aber keine braune Farbe annehmen. Das Zwiebelaroma bildet das Fundament für die Suppe; gebräunte Zwiebel würde einen fremden Röstgeschmack bringen. Wenn der Topf zu heiß ist, nimm ihn kurz vom Herd und gib einen Löffel Wasser dazu.","dauer":8,"tipp":"Geduld: Weich gedünstete Zwiebeln sind der Unterschied zwischen gut und sehr gut."},{"titel":"Kartoffeln garen","aktion":"kochen","text":"Gib die Kartoffelwürfel zur Zwiebel und gieße den lauwarmen Fischsud darüber. Falls zu wenig Flüssigkeit da ist, fülle mit Milch oder Wasser auf, bis die Kartoffeln knapp bedeckt sind. Bringe alles zum Kochen, schalte zurück und lasse die Kartoffeln zugedeckt 12 bis 15 Minuten sanft köcheln, bis sie weich sind und sich mit einer Gabel zerdrücken lassen. Rühre gelegentlich um, damit nichts am Topfboden ansetzt.","dauer":15,"tipp":"Mehlige Kartoffeln zerfallen leicht und verdicken die Suppe von selbst."},{"titel":"Teilweise zerstampfen","aktion":"puerieren","text":"Zerdrücke etwa ein Drittel der Kartoffeln direkt im Topf mit dem Stampfer; die Stärke bindet die Suppe zu einer sämigen, aber noch stückigen Konsistenz. Ein Pürierstab würde alles gleichmäßig glatt machen und die Struktur zerstören, die diese Suppe ausmacht. Die Suppe soll dick wie Sahne sein und einen Löffelrücken überziehen. Ist sie zu dick, verdünnst du sie mit etwas heißer Milch.","dauer":5,"tipp":"Nur grob zerdrücken; Kartoffelstücke sind Teil des Charakters."},{"titel":"Fisch einlegen und abschmecken","aktion":"abschmecken","text":"Gib den zerpflückten Fisch in die Suppe und lasse alles bei kleiner Hitze 3 bis 4 Minuten ziehen; er soll nur noch erwärmen. Rühre nach Wunsch die Sahne ein und schmecke mit Pfeffer ab. Salze erst jetzt und nur nach Probe, denn Räucherfisch ist bereits salzig. Die Suppe soll rauchig, mild, cremig und leicht süßlich schmecken. Entferne das Lorbeerblatt.","dauer":6,"tipp":"Nach dem Einlegen des Fisches nicht mehr kräftig kochen, sonst wird er zäh."},{"titel":"Anrichten","aktion":"anrichten","text":"Erwärme tiefe Teller oder Schalen kurz mit heißem Wasser. Schöpfe die Suppe hinein, verteile die zurückgehaltenen Fischstücke gleichmäßig darauf und bestreue sie mit Schnittlauch oder Petersilie. Serviere sofort mit Brot oder schottischen Haferkeksen (Oatcakes), die du in die Suppe brichst. Ein Tropfen Olivenöl oder ein Klecks Crème fraîche gibt Glanz.","dauer":5,"tipp":"Wenn du magst, einen pochierten Eierkopf als Topping ergänzen."}],"profitipps":["Ungefärbten Räucherfisch verwenden; er schmeckt milder und sauberer.","Milch nie kochen lassen: Sie flockt aus und der Fisch wird zäh.","Kartoffeln nur grob zerdrücken: So bleibt die Suppe stückig.","Nie vor der Probe salzen: Der Räucherfisch bringt viel Salz mit.","Die Suppe ist am zweiten Tag intensiver; langsam und ohne Kochen erwärmen."],"varianten":["Mit Lauch zusätzlich zur Zwiebel.","Mit Lachs statt Schellfisch.","Mit Ocean Perch oder Lachs statt Schellfisch, wie es manche Rezepte vorsehen.","Mit Butter und Sahne am Ende für ein reicheres Ergebnis oder nur mit Milch für die schlichte Küstenversion."],"beilagen":["Haferkekse (Oatcakes)","Roggen- oder Weißbrot mit Butter","Zitronenspalte"],"getraenk":"Ein trockener Weißwein (Chardonnay) oder ein Schottisches Ale.","koeche":[],"quellen":[{"titel":"Cullen skink (Wikipedia)","url":"https://en.wikipedia.org/wiki/Cullen_skink"},{"titel":"Traditional Cullen Skink (Browne Trading)","url":"https://brownetrading.com/blogs/recipes/traditional-cullen-skink"},{"titel":"Cullen Skink – Scottish smoked fish chowder (The Daring Gourmet)","url":"https://www.daringgourmet.com/wprm_print/cullen-skink-scottish-smoked-fish-chowder"}],"bild":"suppe","farben":["#f1e2b8","#d8b878","#8a6a3a"],"schlagworte":["Schottland","Räucherfisch","Suppe","Vorspeise","Kartoffelsuppe"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-gebratener-truthahn-ramsay","name":"Gebratener Truthahn mit Zitronen-Petersilien-Butter nach Art von Gordon Ramsay","originalname":"Roast Turkey with Lemon, Parsley and Garlic","kueche":"britisch-irisch","region":"England","beliebtheit":72,"hauptkategorie":"fleisch","fleischsorte":"pute","gang":"hauptgericht","kurz":"Ein ganzer Truthahn mit Würzbutter aus Zitrone, Petersilie und Knoblauch unter der Haut, mit Speck belegt. Die Haut wird goldbraun, das Fleisch bleibt saftig und duftet nach Zitrone.","hintergrund":"Der Truthahn ist der klassische Weihnachtsbraten in Großbritannien. Ramsay veröffentlicht auf seiner Webseite eine Version, bei der ein Großteil der Butter unter die Haut gedrückt wird und das Tier mit Zwiebeln, Zitrone, Knoblauch und Lorbeer gefüllt wird. Auf der Brust liegt gebratener Speck, der das Fleisch zusätzlich schützt. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, ausführlicher erklärt.","portionen":8,"zeit":{"vorbereitung":40,"garen":170,"ruhen":45},"schwierigkeit":2,"themen":["fest"],"zutaten":[{"gruppe":"Für den Truthahn","liste":[{"menge":5.25,"einheit":"kg","name":"frischer Truthahn","hinweis":"Freilandtier, 5–5,5 kg; rechtzeitig beim Metzger bestellen; die Vorlage nennt Norfolk Black oder Bronze"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"geschält und halbiert"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"halbiert, für die Füllung"},{"menge":1,"einheit":"Knolle","name":"Knoblauch","hinweis":"quer halbiert"},{"menge":6,"einheit":"Blatt","name":"Lorbeerblätter","hinweis":"2 in die Höhlung, 4 unter die Haut"},{"menge":8,"einheit":"Scheibe","name":"geräucherter durchwachsener Speck","hinweis":"dünne Scheiben"},{"menge":null,"einheit":"","name":"Meersalz, schwarzer Pfeffer, Olivenöl","hinweis":"zum Würzen und Beträufeln"}]},{"gruppe":"Für die Zitronen-Petersilien-Butter","liste":[{"menge":375,"einheit":"g","name":"weiche Butter","hinweis":"Zimmertemperatur"},{"menge":1,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":2,"einheit":"Stück","name":"kleine Bio-Zitronen","hinweis":"Schale fein abgerieben, Saft ausgepresst"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt oder zerdrückt"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"Blätter fein gehackt"}]}],"ausruestung":["große Bratenform oder Bräter","Fleischthermometer oder Holzspieß","Küchengarn","Alufolie","Pinsel oder großer Löffel zum Übergießen"],"schritte":[{"titel":"Truthahn und Butter vorbereiten","aktion":"vorbereiten","text":"Nimm den Truthahn rechtzeitig aus dem Kühlschrank, etwa eine bis zwei Stunden vorher, und entferne die Innereien aus der Höhlung. Die Würzbutter bereitest du, indem du die weiche Butter mit Salz, Pfeffer, Olivenöl, der abgeriebenen Schale und dem Saft von zwei Zitronen, dem Knoblauch und der gehackten Petersilie gründlich verrührst. Die Masse soll gleichmäßig grün gesprenkelt und streichfähig sein. Halbiere Zwiebeln, Zitrone und Knoblauch für die Füllung und lege alles bereit. Heize den Ofen auf 220 °C Ober-/Unterhitze vor, bei Umluft auf etwa 200 °C.","dauer":25,"tipp":"Die Butter kannst du am Vortag anrühren, sie wird mit der Zeit aromatischer."},{"titel":"Höhlung füllen","aktion":"fuellen","text":"Würze die Höhlung des Truthahns innen mit Salz und Pfeffer. Fülle sie mit den halbierten Zwiebeln, der halbierten Zitrone, den Knoblauchhälften und zwei Lorbeerblättern. Diese Aromaten geben beim Braten Duft von innen ab und stützen das Tier; sie sind keine Füllung zum Essen. Verschließe die Öffnung nicht zu fest, denn heiße Luft muss zirkulieren, damit das Fleisch gleichmäßig durchgart.","dauer":5,"tipp":"Lege die Zitrone mit der Schnittfläche nach außen, so verströmt sie beim Garen mehr Duft."},{"titel":"Haut lösen und Butter einarbeiten","aktion":"fuellen","text":"Fahre mit den Fingern vorsichtig von beiden Seiten zwischen Brust und Haut und löse die Haut, ohne sie zu zerreißen. Mache dasselbe an den Keulen. Drücke die Hälfte der Würzbutter in die Taschen und streiche sie von außen über die Brust glatt. Schiebe die übrigen Lorbeerblätter unter die Haut der Brust. Die Butter schmilzt beim Braten, tropft über das Fleisch und hält es saftig.","dauer":10,"tipp":"Arbeite mit kalten, trockenen Händen und gehe langsam vor – dünne Haut reißt schnell."},{"titel":"Den Truthahn einstreichen","aktion":"marinieren","text":"Setze den Truthahn mit der Brust nach oben in eine große Bratenform. Streiche die restliche Butter großzügig über die Haut, würze mit Salz und Pfeffer und beträufle ihn mit Olivenöl. Wenn du ihn schon einen Tag vorher vorbereitest, decke ihn jetzt mit Alufolie ab und stelle ihn in den Kühlschrank; dann nimm ihn vor dem Braten rechtzeitig heraus. Die Haut sollte vor dem Braten möglichst gleichmäßig mit Butter bedeckt sein.","dauer":5,"tipp":"Ein vorbereiteter Truthahn spart dir am Festtag viel Stress."},{"titel":"Heiß anbraten, Speck auflegen","aktion":"braten","text":"Schiebe die Form in den 220 °C heißen Ofen und brate den Truthahn etwa 10 bis 15 Minuten. Nimm ihn dann heraus, übergieße ihn mit dem Bratfett aus der Form und lege die Speckscheiben über die Brust. Übergieße sie nochmals mit Bratfett. Der Speck schützt die Brust vor dem Austrocknen und gibt Würze ab. Die Haut färbt sich in dieser Phase schon goldgelb.","dauer":15,"tipp":"Übergieße den Vogel mit einem großen Löffel, nicht mit kalter Flüssigkeit."},{"titel":"Bei niedrigerer Temperatur durchgaren","aktion":"braten","text":"Senke die Ofentemperatur auf 180 °C Ober-/Unterhitze, bei Umluft auf ca. 160 °C, und brate den Truthahn etwa 2 1/2 Stunden, nach der Faustregel von 30 Minuten pro Kilogramm. Übergieße ihn zwischendurch mehrmals mit dem Bratfett. Wird die Haut zu dunkel, decke die Brust locker mit Alufolie ab. Das Aroma von Zitrone, Butter und gebratenem Speck füllt bald die Küche.","dauer":150,"tipp":"Öffne die Ofentür nur zum Übergießen, jedes Öffnen kostet Hitze."},{"titel":"Garprobe machen","aktion":"abschmecken","text":"Beginne etwa 30 Minuten vor Ende der berechneten Zeit mit der Garprobe. Stich einen Holzspieß in den dicksten Teil der Keule: Der austretende Saft soll klar sein, ohne rosa Schimmer. Als Orientierung zeigt ein Fleischthermometer in der Keule etwa 72–74 °C. Ist der Saft noch rosa, brate den Vogel weitere 15 Minuten und prüfe erneut. Wenn die Haut schön braun ist, aber das Innere noch roh, decke ihn mit Folie ab.","dauer":5,"tipp":"Messe nie am Knochen, der ist heißer als das Fleisch."},{"titel":"Ruhen lassen und tranchieren","aktion":"ruhen","text":"Hebe den Truthahn auf eine vorgewärmte Platte und lass ihn mindestens 45 Minuten an einem warmen Ort ruhen. Löse Flügel, Bürzel und Keulenspitzen ab; sie eignen sich für eine Bratensauce. Entferne die Lorbeerblätter unter der Haut und tranchiere die Brust in dicke Scheiben, die Keulen im Ganzen oder ebenfalls in Stücken. In der Ruhezeit kannst du aus dem Bratfond und den abgetrennten Teilen eine Sauce kochen, denn die Vorlage nennt dafür keine Rezeptur.","dauer":45,"tipp":"Die Ruhezeit ist kein Luxus: Sie macht die Brust saftiger und das Schneiden einfacher."}],"profitipps":["Die Würzbutter unter die Haut zu streichen, bringt Aroma direkt ans Fleisch und hält die Brust saftig.","Der Speck auf der Brust schützt vor dem Austrocknen und gibt Würze.","Fängt die Haut an zu dunkel zu werden, locker mit Alufolie abdecken.","Mit Spieß oder Thermometer prüfen: Der Saft in der Keule soll klar laufen.","Mindestens 45 Minuten ruhen lassen, am besten ohne Deckel, damit die Haut knusprig bleibt."],"varianten":["Mit Kräuterbutter aus Salbei und Thymian.","Mit Orangenschale statt Zitrone.","Kleinere Variante mit Truthahnkeule oder -brust.","Mit Maronenfüllung als Beilage."],"beilagen":["Bratkartoffeln","Rosenkohl","Preiselbeersauce","Brotfüllung (Stuffing)","Bratensauce"],"getraenk":"Kräftiger Weißwein wie ein Chardonnay oder ein leichter Rotwein wie Pinot Noir.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diesen Truthahn auf seiner Webseite: Würzbutter mit Zitrone, Petersilie und Knoblauch unter der Haut, Füllung der Höhlung mit Zwiebeln, Zitrone und Lorbeer, Speck auf der Brust.","quelle":"https://www.gordonramsay.com/gr/recipes/roast-turkey-with-lemon-parsley-and-garlic/"}],"quellen":[{"titel":"Gordon Ramsay – Roast Turkey with Lemon, Parsley and Garlic","url":"https://www.gordonramsay.com/gr/recipes/roast-turkey-with-lemon-parsley-and-garlic/"},{"titel":"Gordon Ramsay – Rezeptübersicht","url":"https://www.gordonramsay.com/gr/recipes/"}],"bild":"haehnchen","farben":["#a8561e","#d98e3f","#f0d9a3"],"schlagworte":["Weihnachten","Festtagsbraten","Gordon Ramsay","Truthahn"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-kedgeree","name":"Kedgeree – Reis mit Räucherschellfisch und Ei","originalname":"Kedgeree","kueche":"britisch-irisch","region":"England (viktorianisches Frühstück, anglo-indisch)","beliebtheit":70,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"fruehstueck","kurz":"Ein anglo-indischer Frühstücksklassiker: duftender Reis mit Räucherschellfisch, hart gekochten Eiern, Curry und Petersilie.","hintergrund":"Kedgeree geht auf das indische Gericht Khichri zurück, einen Eintopf aus Reis und Linsen, den britische Kolonialbeamte nach England mitbrachten. Dort wurde daraus im 19. Jahrhundert ein elegantes Frühstücksgericht mit geräuchertem Schellfisch, Eiern, Reis und mildem Currypulver. Es war in viktorianischer Zeit ein Standardgericht auf den Frühstückstischen der gehobenen Gesellschaft und wurde warm oder kalt gegessen. In den 1930er- und 1940er-Jahren wurde es zum günstigen Frühstück in Schulen und Kantinen. Heute ist es ein Brunch- und Abendessen-Klassiker.","portionen":4,"zeit":{"vorbereitung":20,"garen":30,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Reis und Fisch","liste":[{"menge":400,"einheit":"g","name":"ungefärbter geräucherter Schellfisch","hinweis":"ersatzweise Räucherkabeljau; auch Kippers (Räucherhering) sind schottische Variante"},{"menge":500,"einheit":"ml","name":"Vollmilch","hinweis":"zum Pochieren"},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":250,"einheit":"g","name":"Basmatireis","hinweis":""},{"menge":4,"einheit":"Stück","name":"Eier, Größe M","hinweis":"hart gekocht"}]},{"gruppe":"Würze","liste":[{"menge":1,"einheit":"Stück","name":"Zwiebel, fein gewürfelt","hinweis":""},{"menge":40,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"EL","name":"Öl","hinweis":"zum Anbraten"},{"menge":2,"einheit":"TL","name":"mildes Currypulver (Madras)","hinweis":""},{"menge":1,"einheit":"Msp.","name":"Cayennepfeffer","hinweis":"optional"},{"menge":30,"einheit":"g","name":"Sultaninen","hinweis":"optional, ein viktorianisches Detail"},{"menge":2,"einheit":"EL","name":"Sahne","hinweis":"optional"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"Saft"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf mit Deckel","tiefe Pfanne oder breiter Topf","Schaumkelle"],"schritte":[{"titel":"Alles bereitstellen","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle sie in Reichweite. Würfele die Zwiebel fein, hacke die Petersilie und schneide die Zitrone in Spalten. Prüfe den Fisch auf Gräten mit den Fingerspitzen und ziehe sie mit der Pinzette heraus. Ungefärbter Räucherschellfisch ist hellbeige, nicht knallgelb, und riecht angenehm rauchig. Gib den Reis in ein Sieb und spüle ihn unter kaltem Wasser, bis das Wasser fast klar ist, denn so verkleben die Körner nicht.","dauer":10,"tipp":"Gespülter Reis bleibt körnig und locker."},{"titel":"Fisch pochieren","aktion":"kochen","text":"Lege den Fisch in einen weiten Topf und gieße die Milch darüber; gib das Lorbeerblatt dazu. Erhitze langsam, bis sich an der Oberfläche kleine Bläschen zeigen, dann nimm die Hitze zurück und lass den Fisch 4 bis 5 Minuten ziehen, ohne dass es sprudelt. Er ist gar, wenn sich das Fleisch mit der Gabel in Lamellen teilen lässt. Hebe ihn heraus, lass ihn kurz abkühlen und zupfe ihn in grobe Stücke, nachdem du die Haut abgezogen hast.","dauer":8,"tipp":"Die Milch kannst du für Suppen oder Saucen verwenden."},{"titel":"Reis kochen","aktion":"kochen","text":"Gib den Reis mit der doppelten Menge leicht gesalzenem Wasser (500 ml) in einen Topf, bringe ihn zum Kochen und lass ihn zugedeckt bei kleinster Hitze 10 bis 12 Minuten quellen, bis das Wasser aufgesogen ist. Nimm den Topf vom Herd und lasse den Reis weitere 10 Minuten zugedeckt ruhen, damit er gleichmäßig durchzieht. Lockere ihn danach mit einer Gabel auf. Der Reis soll weich, aber körnig sein und nicht kleben.","dauer":25,"tipp":"Während des Quellens nicht den Deckel heben."},{"titel":"Eier kochen","aktion":"kochen","text":"Lege die Eier in kochendes Wasser und koche sie genau 8 Minuten für festes, aber noch nicht trockenes Eigelb. Schrecke sie sofort eiskalt ab, damit sie sich leichter pellen lassen und kein grauer Rand entsteht. Pelle sie unter fließendem Wasser und viertele sie. Wenn du magst, lässt du das Eigelb in der Mitte leicht cremig, dann kochst du nur 7 Minuten.","dauer":10,"tipp":"Eier mit Raumtemperatur reißen weniger auf."},{"titel":"Zwiebel und Curry anbraten","aktion":"anbraten","text":"Schmilz Butter und Öl in einer großen Pfanne bei mittlerer Hitze. Gib die Zwiebel hinein und dünste sie 6 bis 8 Minuten, bis sie weich, glasig und leicht golden ist. Rühre das Currypulver ein und röste es 1 Minute mit, bis es aromatisch duftet, denn rohes Currypulver schmeckt bitter. Gib optional Cayenne und Sultaninen dazu und schwenke alles kurz durch.","dauer":10,"tipp":"Curry kurz anrösten, aber nicht anbrennen lassen."},{"titel":"Alles vermengen","aktion":"mischen","text":"Gib den gegarten Reis in die Pfanne und wende ihn vorsichtig mit einem Löffel oder einer Gabel, bis jedes Korn mit dem Curry-Zwiebel-Mix überzogen ist. Hebe die Fischstücke unter, ohne sie zu zerdrücken, und erwärme alles 2 bis 3 Minuten. Rühre bei Wunsch Sahne und Zitronensaft ein. Schmecke mit Salz und Pfeffer ab; der Räucherfisch bringt viel Salz mit, daher vorsichtig beginnen.","dauer":5,"tipp":"Vorsichtig mischen: Die Fischstücke sollen ganz bleiben."},{"titel":"Eier und Petersilie unterheben","aktion":"abschmecken","text":"Hebe die Eierviertel und die Hälfte der Petersilie sanft unter. Der Reis soll glänzen, nach Curry und Rauch duften und leuchtend gelb sein. Probiere und gib bei Bedarf Zitronensaft hinzu; er hebt den Rauchgeschmack und macht das Gericht frischer. Lasse alles 2 Minuten ziehen, damit die Aromen sich verbinden, und schwenke dabei den Topf, damit nichts anhaftet.","dauer":3,"tipp":"Zitrone ist der Gegenspieler zu Rauch und Fett."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Kedgeree auf einer vorgewärmten Platte an und streue die übrige Petersilie darüber. Reiche Zitronenspalten, ein Stück Butter und Mango-Chutney dazu. In England wird es oft mit Worcestershire-Sauce und gebuttertem Toast gegessen. Es schmeckt warm als Frühstück oder Abendessen und kalt am nächsten Tag.","dauer":5,"tipp":"Reste kalt im Kühlschrank aufbewahren und innerhalb eines Tages essen; Reis sollte nie lange warm stehen."}],"profitipps":["Ungefärbten Räucherfisch kaufen: milder im Geschmack.","Curry kurz anrösten, nicht roh unterrühren.","Reis immer spülen und ruhen lassen.","Eier abschrecken, damit sie leicht zu pellen sind.","Reisreste schnell abkühlen und kühl lagern, um Bakterienwachstum zu vermeiden."],"varianten":["Mit Räucherlachs oder Kippers statt Schellfisch.","Mit Erbsen und Spinat für mehr Grün.","Mit Garam Masala statt Currypulver.","Kalt als Salat mit Joghurt-Dressing."],"beilagen":["Buttertoast","Mango-Chutney","Zitronenspalten","Tomatenscheiben"],"getraenk":"Starker schwarzer Tee mit Milch oder ein trockener Riesling.","koeche":[],"quellen":[{"titel":"Kedgeree (Wikipedia)","url":"https://en.wikipedia.org/wiki/Kedgeree"},{"titel":"Classic British Kedgeree Recipe (Tasting Table)","url":"https://www.tastingtable.com/1368650/classic-british-kedgeree-recipe"},{"titel":"Kedgeree (James Beard Foundation Archive)","url":"https://archive.jamesbeard.org/recipes/kedgeree"}],"bild":"reis","farben":["#e8b84a","#f2ead0","#5a7a3a"],"schlagworte":["Frühstück","Räucherfisch","Brunch","anglo-indisch"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-mulligatawny","name":"Mulligatawny – anglo-indische Currysuppe mit Huhn","originalname":"Mulligatawny","kueche":"britisch-irisch","region":"Anglo-Indien / England","beliebtheit":70,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"suppe","kurz":"Sämige, goldgelbe Currysuppe mit zartem Huhn, Apfel, Linsen und einem Hauch Kokos – würzig-warm statt scharf, ein Souvenir aus der Kolonialzeit.","hintergrund":"Die Mulligatawny geht auf eine indische, fleischlose Pfeffer-Chili-Sauce zurück, die einfachen Reisgerichten Würze gab; der Name ist ein anglisiertes Kompositum aus den tamilischen Wörtern für Pfeffer und Wasser. Britische Kolonialbeamte bauten die Sauce zu einer gehaltvollen Suppe aus, weil ein Mehrgängemenü mit Suppe in Großbritannien als Zeichen höheren Standes galt. Die erste schriftliche Erwähnung dort steht in William Kitchiners ‚Cook's Oracle‘ (1822). Ab etwa 1850 war die Suppe in Großbritannien populär. Heute wird sie meist mit Crème double oder Kokosmilch sämig gemacht und mit Reis serviert.","portionen":4,"zeit":{"vorbereitung":25,"garen":50,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Suppe","liste":[{"menge":500,"einheit":"g","name":"Hähnchenkeulen ohne Haut","hinweis":"Ober- und Unterschenkel mit Knochen, für mehr Geschmack; ersatzweise 400 g Hähnchenbrust"},{"menge":2,"einheit":"EL","name":"Butterschmalz oder Pflanzenöl","hinweis":""},{"menge":1,"einheit":"Stück","name":"große Zwiebel","hinweis":"ca. 150 g, fein gewürfelt"},{"menge":1,"einheit":"Stück","name":"Möhre","hinweis":"geschält, in 5 mm Würfel"},{"menge":1,"einheit":"Stange","name":"Staudensellerie","hinweis":"in 5 mm Würfel"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":20,"einheit":"g","name":"frischer Ingwer","hinweis":"geschält und fein gerieben"},{"menge":2,"einheit":"EL","name":"mildes Currypulver","hinweis":"oder eine eigene Mischung (siehe Profitipps)"},{"menge":1,"einheit":"TL","name":"Kurkuma","hinweis":"gemahlen"},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":"gemahlen"},{"menge":0.5,"einheit":"TL","name":"Chilipulver","hinweis":"nach Schärfewunsch"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":1,"einheit":"Stück","name":"säuerlicher Apfel","hinweis":"z. B. Boskoop oder Elstar, geschält und gewürfelt"},{"menge":80,"einheit":"g","name":"rote Linsen","hinweis":"nicht vorgeweicht"},{"menge":1,"einheit":"l","name":"Hühnerbrühe","hinweis":"oder Wasser plus Brühwürfel"},{"menge":200,"einheit":"ml","name":"Kokosmilch","hinweis":"aus der Dose, gut geschüttelt"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":120,"einheit":"g","name":"Basmatireis","hinweis":"separat gekocht"},{"menge":1,"einheit":"Bund","name":"frischer Koriander","hinweis":"gehackt, ersatzweise glatte Petersilie"},{"menge":null,"einheit":"","name":"Naturjoghurt","hinweis":"optional als Klecks"}]}],"ausruestung":["großer Topf mit Deckel","Pfanne oder Bräter","Stabmixer (optional)","Reibe für den Ingwer","kleiner Topf für den Reis"],"schritte":[{"titel":"Mise en place: Gemüse, Gewürze und Huhn vorbereiten","aktion":"vorbereiten","text":"Schneide Zwiebel, Möhre und Staudensellerie in gleichmäßige, etwa 5 mm große Würfel, damit sie gleichzeitig weich werden. Hacke den Knoblauch fein, reibe den Ingwer und schäle und würfle den Apfel. Miss alle Gewürze in einer kleinen Schale ab, denn sobald sie im Topf sind, geht es schnell. Spüle die Hähnchenkeulen kurz kalt ab, tupfe sie sehr gut trocken und salze sie rundum, damit sie später kräftig braun werden.","dauer":0,"tipp":"Apfel erst direkt vor dem Verwenden schneiden oder mit etwas Zitronensaft beträufeln, sonst wird er braun."},{"titel":"Huhn goldbraun anbraten","aktion":"anbraten","text":"Erhitze 1 Esslöffel Butterschmalz im Topf bei mittlerer bis hoher Hitze, bis es leicht schimmert. Lege die Keulen hinein und brate sie von allen Seiten etwa 6 bis 8 Minuten an, bis sie goldbraun sind und es nach gebratenem Geflügel duftet. Nimm sie heraus und stelle sie beiseite. Am Topfboden haftet jetzt brauner Bratensatz, den du später mit Brühe löst, denn er ist ein wichtiger Geschmacksträger. Das Huhn muss noch nicht gar sein.","dauer":8,"tipp":"Nicht zu früh wenden. Sobald die Haut oder das Fleisch braun ist, löst es sich von allein vom Topfboden."},{"titel":"Gemüse anschwitzen","aktion":"anbraten","text":"Gib den restlichen Esslöffel Fett in den Topf und schwitze Zwiebel, Möhre und Sellerie bei mittlerer Hitze 6 bis 8 Minuten, bis die Zwiebel glasig wird und die Ränder leicht Farbe nehmen. Rühre dabei gelegentlich mit dem Holzlöffel und löse den Bratensatz vom Boden. Gib Knoblauch und Ingwer dazu und lass beides 1 Minute mitduften, bis es würzig-scharf riecht, aber nicht verbrennt.","dauer":8,"tipp":""},{"titel":"Gewürze rösten","aktion":"anbraten","text":"Rühre Currypulver, Kurkuma, Kreuzkümmel, Chili und Tomatenmark ein und röste alles etwa 1 Minute unter ständigem Rühren, bis die Gewürze intensiv duften und das Tomatenmark leicht dunkler wird. Dieses kurze Anrösten in Fett löst die fettlöslichen Aromen der Gewürze und nimmt ihnen die Rohheit. Nimm den Topf vom Herd, falls es zu stark brutzelt, denn verbrannte Gewürze schmecken bitter und sind nicht zu retten.","dauer":1,"tipp":"Gib einen Schuss Brühe dazu, sobald es zu trocken wird, damit nichts anbrennt."},{"titel":"Aufgießen und garen","aktion":"koecheln","text":"Gib Apfel, Linsen, die angebratenen Keulen und die Brühe in den Topf und bringe alles zum Kochen. Reduziere die Hitze, lege den Deckel schräg auf und lass die Suppe 30 bis 35 Minuten leise köcheln. Die Linsen zerfallen dabei und binden die Suppe natürlich. Das Hühnerfleisch ist gar, wenn es sich leicht vom Knochen löst und der austretende Saft klar ist. Die Suppe duftet nach Curry, Apfel und Huhn und hat eine goldgelbe Farbe.","dauer":35,"tipp":"Zwischendurch umrühren, denn rote Linsen setzen sich gern am Boden ab."},{"titel":"Huhn auslösen","aktion":"schneiden","text":"Hole die Hähnchenkeulen aus der Suppe und lass sie 5 Minuten abkühlen. Löse das Fleisch vom Knochen und zerpflücke es mit zwei Gabeln in mundgerechte Stücke von etwa 2 cm. Entsorge Knochen und Sehnen. Das Fleisch soll saftig sein und zerfasern. Lege es abgedeckt beiseite. So wird es später nicht trocken und bleibt als Einlage saftig.","dauer":0,"tipp":""},{"titel":"Pürieren und mit Kokosmilch verfeinern","aktion":"puerieren","text":"Püriere die Suppe mit dem Stabmixer, bis sie fein und cremig ist; für mehr Biss kannst du auch nur die Hälfte pürieren und den Rest grob lassen. Rühre die Kokosmilch ein und erwärme die Suppe noch einmal sanft, ohne sie kräftig kochen zu lassen, damit die Kokosmilch nicht ausflockt. Die Suppe soll jetzt sämig sein und gelb schimmern. Ist sie zu dick, verdünne sie mit etwas Brühe oder Wasser.","dauer":5,"tipp":"Wenn du es cremiger magst, rühre zusätzlich 2 EL Crème double ein, so wie es in der klassischen britischen Version üblich ist."},{"titel":"Reis kochen und Suppe abschmecken","aktion":"abschmecken","text":"Koche den Basmatireis in einem kleinen Topf nach Packungsangabe, meist 10 bis 12 Minuten, bis er locker und weich ist. Schmecke die Suppe mit Salz, Limettensaft und eventuell einer Prise Zucker ab: Die Säure hebt die Gewürze, und ein wenig Süße rundet sie ab. Probiere mit einem Löffel und achte darauf, dass die Gewürze warm und rund schmecken, nicht staubig. Gib das zerpflückte Huhn zurück in die Suppe und erwärme es 2 Minuten.","dauer":12,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Gib einen kleinen Löffel gekochten Reis in die Mitte jedes vorgewärmten Tellers und schöpfe die Suppe mit reichlich Huhn darum. Streue gehackten Koriander darüber und setze nach Wunsch einen Klecks Joghurt auf die Suppe. Serviere sie sofort, solange sie heiß ist; die Suppe duftet jetzt nach Curry, Ingwer und frischen Kräutern.","dauer":0,"tipp":"Mit Naan oder Fladenbrot wird die Suppe zur vollen Mahlzeit."}],"profitipps":["Eigene Currymischung: 2 TL Koriander, 2 TL Kreuzkümmel, 1 TL Kurkuma, 1 TL gemahlener Ingwer, 1/2 TL Senfkörner, 1/2 TL Chili und 1/4 TL Kardamom; trocken anrösten und im Mörser mahlen.","Gewürze immer kurz im Fett anrösten, nie roh in Flüssigkeit rühren. Das gibt tiefen Geschmack und nimmt die Schärfe der rohen Gewürze.","Der Apfel gibt Säure und Süße und gehört zur klassischen britischen Version; Mango ist eine moderne Alternative.","Rote Linsen binden die Suppe ohne Mehl und verleihen ihr Körper; bei zu dicker Suppe einfach Brühe nachgießen.","Die Suppe schmeckt am nächsten Tag noch besser, weil die Gewürze durchziehen. Dann nur sanft erwärmen."],"varianten":["Vegetarisch: Gemüsebrühe statt Hühnerbrühe, dazu Süßkartoffel- oder Kürbiswürfel statt Huhn.","Klassisch britisch mit Crème double und Reis, wie in der Kolonialzeit serviert.","Mit Lamm- oder Rindfleisch statt Huhn, im Topf länger geschmort.","Mit Mango, Süßkartoffeln oder Kirschtomaten als Gemüseeinlage."],"beilagen":["Basmatireis","Naan oder Fladenbrot","Mango-Chutney"],"getraenk":"Kühles Lagerbier, Lassi oder ein halbtrockener Riesling","koeche":[{"name":"William Kitchiner","bezug":"Der englische Arzt und Autor veröffentlichte 1822 in seinem Bestseller ‚The Cook's Oracle‘ die erste bekannte schriftliche Mulligatawny-Rezeptur in Großbritannien, mit Geflügelbrühe, Zwiebel, Ingwer, Curry und Kurkuma.","quelle":"https://de.wikipedia.org/wiki/Mulligatawny"}],"quellen":[{"titel":"Mulligatawny (Wikipedia)","url":"https://de.wikipedia.org/wiki/Mulligatawny"}],"bild":"suppe","farben":["#d9a21b","#f0cf6a","#b8541f"],"schlagworte":["Currysuppe","Anglo-Indien","Kolonialküche","Huhn","würzig"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-irish-soda-bread","name":"Irish Soda Bread","originalname":"Irish Soda Bread","kueche":"britisch-irisch","region":"Irland","beliebtheit":70,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"brot","kurz":"Hefefreies Brot aus Mehl, Buttermilch und Natron, mit tiefem Kreuz eingeschnitten und in Minuten angerührt – Irlands schnellster Klassiker.","hintergrund":"Soda Bread entstand im frühen 19. Jahrhundert, als Natron (Backsoda) verfügbar wurde und Hefe ersetzen konnte; irischer Weizen war glutenarm und eignete sich schlecht für Hefebrot. Ab den 1830er-Jahren war es in Irland bekannt, in der Zeit der Großen Hungersnot kam hartes Weizenmehl aus Nordamerika, und in den 1860er-Jahren war es das typische Hausbrot. Der Teig ist sehr nass, wird nicht geknetet und tief kreuzförmig eingeschnitten. Das Kreuz soll die Hitze gleichmäßig eindringen lassen und gilt in der Folklore außerdem als Segen oder als Tür für Feen. Mit Zucker und Rosinen wird es zum süßen Spotted Dog.","portionen":8,"zeit":{"vorbereitung":15,"garen":40,"ruhen":15},"schwierigkeit":1,"zutaten":[{"gruppe":"Brot","liste":[{"menge":350,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus Mehl zum Bestäuben"},{"menge":100,"einheit":"g","name":"Weizenvollkornmehl","hinweis":"für Brown Soda Bread; ganz weiß: 450 g Type 405"},{"menge":1,"einheit":"TL","name":"Natron (Backsoda)","hinweis":"gestrichen; kein Backpulver ersetzt es 1:1"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":400,"einheit":"ml","name":"Buttermilch","hinweis":"Ersatz: 400 ml Milch mit 1 EL Zitronensaft, 10 Minuten stehen lassen"}]}],"ausruestung":["große Schüssel","Backblech mit Backpapier","scharfes Messer","Küchentuch"],"schritte":[{"titel":"Ofen vorheizen und Zutaten bereitstellen","aktion":"vorbereiten","text":"Heize den Ofen auf 230 °C Ober-/Unterhitze (210 °C Umluft) vor und lege ein Backblech mit Backpapier aus. Wiege Mehl, Natron und Salz ab und siebe sie in eine große Schüssel, damit das Natron gleichmäßig verteilt wird. Stelle die Buttermilch bereit. Soda Bread gelingt nur, wenn alles zügig geht, denn die Reaktion zwischen Säure und Natron beginnt sofort, sobald Flüssigkeit dazukommt.","dauer":0,"tipp":""},{"titel":"Trockene Zutaten mischen","aktion":"mischen","text":"Vermische beide Mehlsorten mit Natron und Salz gründlich mit den Händen oder einem Schneebesen, bis die Mischung gleichmäßig aussieht. Mache in der Mitte eine tiefe Mulde. Das Natron muss überall gleichmäßig verteilt sein, sonst schmeckt das Brot an einzelnen Stellen seifig und bitter. Hebe das Mehl dabei etwas an, damit Luft hineinkommt.","dauer":3,"tipp":""},{"titel":"Buttermilch zugießen und kurz mischen","aktion":"mischen","text":"Gieße fast die gesamte Buttermilch in die Mulde und rühre mit gespreizten Fingern in kreisenden Bewegungen von der Mitte aus, bis ein sehr feuchter, klebriger Teig entsteht. Gib bei Bedarf den Rest der Buttermilch dazu, wenn trockene Mehlnester bleiben. Rühre nur so lange, bis alles gerade verbunden ist; höchstens 30 Sekunden. Der Teig ist nass und weich, das ist richtig, denn zu trockener Teig ergibt ein hartes Brot.","dauer":2,"tipp":"Nicht kneten: Kneten bildet Gluten, und das Brot wird zäh statt zart."},{"titel":"Zum Laib formen","aktion":"formen","text":"Kippe den Teig auf eine gut bemehlte Arbeitsfläche, bestäube die Hände mit Mehl und forme ihn mit wenigen, schnellen Handgriffen zu einer runden Kugel. Drücke sie zu einem etwa 4 cm hohen Laib flach und setze ihn aufs Backblech. Je weniger du den Teig anfasst, desto besser. Bemehle die Oberfläche leicht, das gibt dem Brot nach dem Backen sein typisches rustikales Aussehen.","dauer":3,"tipp":""},{"titel":"Kreuz einschneiden","aktion":"schneiden","text":"Schneide mit einem scharfen, bemehlten Messer ein tiefes Kreuz in den Laib, das fast bis zum Boden reicht, etwa 3 cm tief. Der Schnitt lässt die heiße Luft in das Innere strömen, damit der dichte Teig gleichmäßig gart, und bildet beim Backen vier Viertel, die sich öffnen. Das Kreuz gilt in Irland außerdem als Segen für das Brot und als Weg, auf dem die Feen entweichen können.","dauer":1,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Schiebe das Blech sofort in den heißen Ofen. Backe das Brot 15 Minuten bei 230 °C, damit es schnell aufgeht und eine Kruste bildet, und senke dann die Temperatur auf 200 °C Ober-/Unterhitze (180 °C Umluft) für weitere 25 Minuten. Es ist fertig, wenn es tief goldbraun ist und hohl klingt, wenn du auf die Unterseite klopfst. Wenn es noch dumpf klingt, backe es 5 bis 10 Minuten länger.","dauer":40,"tipp":"Das Klopf-Test ist der zuverlässigste Garnachweis für Soda Bread."},{"titel":"Abkühlen lassen","aktion":"kuehlen","text":"Nimm das Brot aus dem Ofen und lasse es auf einem Gitter abkühlen. Für eine weichere Kruste wickelst du es noch warm in ein sauberes Küchentuch, die Feuchtigkeit verteilt sich, und die Kruste wird zarter. Warte mindestens 15 Minuten, bevor du es anschneidest. Soda Bread schmeckt am besten am Backtag, mit viel Butter und etwas Käse oder zu Suppe und Eintopf.","dauer":15,"tipp":""}],"profitipps":["Natron nur mit saurer Flüssigkeit verwenden; die Buttermilch aktiviert es.","Nicht kneten und schnell arbeiten: Die Reaktion beginnt sofort.","Das Kreuz tief einschneiden, damit das Innere durchbackt.","Am gleichen Tag essen; am nächsten Tag getoastet schmeckt es ebenfalls gut.","Ein feuchtes Küchentuch um das warme Brot gewickelt hält die Kruste weich."],"varianten":["Brown Soda Bread mit mehr Vollkornmehl","Spotted Dog mit Zucker und Rosinen","Mit Haferflocken und Saaten","Soda Farls: in Dreiecke geschnitten und in der Pfanne gebacken"],"beilagen":["Butter","Käse","Irish Stew","Räucherlachs"],"getraenk":"Tee mit Milch, Irish Coffee oder ein irisches Ale.","koeche":[],"quellen":[{"titel":"Irish soda bread – Wikipedia","url":"https://en.wikipedia.org/wiki/Irish_soda_bread"}],"bild":"brot","farben":["#b8814a","#e6c88e","#7a4a2a"],"schlagworte":["Brot ohne Hefe","Schnell","Irland","Buttermilch"],"vegetarisch_moeglich":true},{"originalname":"Bread and Butter Pudding","region":"England","hauptkategorie":"suess","fleischsorte":"","gang":"dessert","koeche":[{"name":"Gary Rhodes","bezug":"Der britische TV-Koch, bekannt für seine modernen Interpretationen traditioneller englischer Gerichte, hat ein eigenes Bread-and-Butter-Pudding-Rezept veröffentlicht, das auf Lovefood nachzulesen ist.","quelle":"https://www.lovefood.com/recipes/60593/gary-rhodes-bread-and-butter-pudding"},{"name":"Mary Berry","bezug":"Die britische Backautorin hat ein eigenes Rezept für Bread and Butter Pudding veröffentlicht, das auf The Happy Foodie nachzulesen ist.","quelle":"https://thehappyfoodie.co.uk/recipes/mary-berrys-bread-and-butter-pudding/"}],"vegetarisch_moeglich":true,"id":"britisch-irisch-bread-and-butter-pudding","name":"Bread and Butter Pudding","kueche":"britisch-irisch","beliebtheit":68,"kurz":"Buttrige Brotscheiben mit Rosinen in Vanillecreme gebacken, bis die Oberseite knusprig und das Innere weich-puddingartig ist.","hintergrund":"Bread and Butter Pudding gehört zu den Klassikern der traditionellen englischen Hausmannskost und gilt als typisches Resteverwertungsdessert: Altbackenes Brot wird mit Butter bestrichen, mit Trockenfrüchten geschichtet und in Eiermilch gebacken. Rezepte dafür finden sich schon in alten englischen Kochbüchern. Beim Backen saugt das Brot die Creme auf, die Oberseite wird knusprig und goldbraun, das Innere cremig und weich. Mit gutem Brioche oder Panettone wird daraus ein echtes Restaurantdessert.","portionen":6,"zeit":{"vorbereitung":25,"garen":40,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Pudding","liste":[{"menge":8,"einheit":"Scheibe","name":"Toastbrot oder Brioche","hinweis":"ca. 250 g, entrindet"},{"menge":60,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":75,"einheit":"g","name":"Rosinen oder Sultaninen","hinweis":""},{"menge":1,"einheit":"EL","name":"Rum","hinweis":"oder Orangensaft zum Einweichen"}]},{"gruppe":"Für die Eiermilch","liste":[{"menge":400,"einheit":"ml","name":"Vollmilch","hinweis":""},{"menge":200,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eier","hinweis":"Größe M"},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":"oder Mark von einer Schote"},{"menge":1,"einheit":"Prise","name":"Muskatnuss","hinweis":"frisch gerieben"}]},{"gruppe":"Zum Überbacken","liste":[{"menge":2,"einheit":"EL","name":"Demerara- oder brauner Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Aprikosenmarmelade","hinweis":"zum Glasieren"}]}],"ausruestung":["Auflaufform 20 x 25 cm","Schneebesen","Sieb","Pinsel","Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Ofen noch nicht an. Fette die Auflaufform mit etwas Butter ein. Weiche die Rosinen 15 Minuten in Rum oder Orangensaft ein, damit sie prall und weich werden und im Ofen nicht verbrennen. Entferne die Rinde vom Toast, schneide die Scheiben diagonal in Dreiecke und bestreiche sie dünn mit weicher Butter. Das Buttern auf nur einer Seite genügt.","dauer":15,"tipp":""},{"titel":"Brot schichten","aktion":"schichten","text":"Lege eine Lage Brotdreiecke dachziegelartig mit der gebutterten Seite nach oben in die Form und streue die Hälfte der Rosinen darüber. Setze die zweite Lage darauf und verteile die übrigen Rosinen zwischen den Zwischenräumen. Die obere Schicht sollte fest in die Form gedrückt sein. Die Ecken der obersten Dreiecke ragen später knusprig heraus.","dauer":8,"tipp":""},{"titel":"Eiermilch anrühren","aktion":"mischen","text":"Erhitze Milch und Sahne mit der Vanille in einem Topf, bis sich am Rand kleine Bläschen zeigen, und lasse die Mischung kurz abkühlen. Verrühre in einer Schüssel Eier, Eigelb und Zucker, bis die Masse hell ist. Gieße die warme Milch langsam unter Rühren dazu, würze mit Muskat und streiche die Mischung durch ein Sieb. Sie soll flüssig und glatt wie Sahne sein.","dauer":10,"tipp":""},{"titel":"Einweichen lassen","aktion":"ruhen","text":"Gieße die Eiermilch langsam und gleichmäßig über das Brot und drücke die Scheiben mit einem Löffel leicht an, damit sie die Flüssigkeit aufsaugen. Lasse alles mindestens 30 Minuten bei Zimmertemperatur ruhen, bis das Brot weich und vollgesogen ist. Das Einweichen ist entscheidend für die cremige Textur; zu kurz eingeweicht bleibt das Innere trocken.","dauer":30,"tipp":"Über Nacht im Kühlschrank wird das Ergebnis noch besser."},{"titel":"Zucker aufstreuen und backen","aktion":"backen","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Streue den braunen Zucker gleichmäßig über das Brot. Backe den Pudding 35 bis 40 Minuten, bis die Oberfläche goldbraun und knusprig ist und die Creme in der Mitte nur noch ganz leicht wackelt. Beim Backen duftet er nach Butter und Vanille. Wird die Oberfläche zu dunkel, decke die Form locker mit Alufolie ab.","dauer":40,"tipp":""},{"titel":"Glasieren und servieren","aktion":"garnieren","text":"Erwärme die Aprikosenmarmelade mit einem Esslöffel Wasser und streiche sie durch ein Sieb. Bepinsle damit den heißen Pudding; das gibt Glanz und eine zarte Fruchtnote. Lasse den Pudding zehn Minuten ruhen, damit sich die Creme setzt, und serviere ihn warm mit Vanillesauce, Custard oder Sahne. Die Glasur macht die Kruste leicht klebrig-glänzend und bringt eine feine Säure, die gegen die Süße der Creme hilft.","dauer":12,"tipp":""}],"profitipps":["Das Brot ausreichend einweichen lassen, sonst bleibt der Pudding trocken.","Altbackenes Brot saugt besser als frisches.","Demerarazucker sorgt für die knusprige Kruste.","Brioche oder Panettone ergibt eine feinere Variante.","Ein Wasserbad macht den Pudding noch cremiger."],"varianten":["Mit Marmelade zwischen den Brotlagen","Mit Schokolade und Orange","Als Panettone-Pudding zu Weihnachten","Mit Apfelstücken und Zimt"],"beilagen":["Vanillesauce (Custard)","Schlagsahne","Clotted Cream"],"getraenk":"Tee mit Milch oder ein Dessertwein","quellen":[{"titel":"Gary Rhodes' Bread and butter pudding – Lovefood","url":"https://www.lovefood.com/recipes/60593/gary-rhodes-bread-and-butter-pudding"},{"titel":"Mary Berry's Bread and Butter Pudding – The Happy Foodie","url":"https://thehappyfoodie.co.uk/recipes/mary-berrys-bread-and-butter-pudding/"}],"bild":"auflauf","farben":["#d8a24a","#f5e1b0","#7d4a1c"],"schlagworte":["Resteverwertung","Klassiker","Winter"]},{"id":"britisch-irisch-jakobsmuscheln-butternut-ramsay","name":"Gebratene Jakobsmuscheln mit Butternut-Püree und Granatapfel-Quitten-Krautsalat nach Art von Gordon Ramsay","originalname":"Pan-Seared Scallops with Butternut Squash Puree and Pomegranate-Quince Slaw","kueche":"britisch-irisch","region":"England / Restaurantküche","beliebtheit":68,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Goldbraun karamellisierte Jakobsmuscheln auf seidigem Kürbispüree, dazu ein knackiger Krautsalat mit Granatapfel, Haselnüssen und Quittengelee. Ein Restaurant-Start für zu Hause.","hintergrund":"Gebratene Jakobsmuscheln gehören zu den Gerichten, die Ramsay in seinen Restaurants und im Fernsehen immer wieder zubereitet. Auf seiner Webseite steht diese herbstliche Version mit Butternut-Püree und einem Krautsalat, der mit Quittenpaste angemacht wird. Der Kniff liegt im sehr heißen Anbraten und im Übergießen mit Butter und Zitrone zum Schluss. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept.","portionen":4,"zeit":{"vorbereitung":30,"garen":70,"ruhen":0},"schwierigkeit":2,"themen":["fest"],"zutaten":[{"gruppe":"Für das Butternut-Püree","liste":[{"menge":1.4,"einheit":"kg","name":"Butternut-Kürbis","hinweis":"halbiert, entkernt (ca. 1 großer Kürbis)"},{"menge":60,"einheit":"g","name":"Butter","hinweis":"zur Hälfte aufteilen"},{"menge":3,"einheit":"Zweig","name":"Thymian oder Rosmarin","hinweis":"frisch"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"zerdrückt, ungeschält mitrösten"},{"menge":null,"einheit":"","name":"Olivenöl, Salz und Pfeffer","hinweis":"zum Rösten und Würzen"}]},{"gruppe":"Für den Granatapfel-Quitten-Krautsalat","liste":[{"menge":30,"einheit":"g","name":"Quittenpaste (Membrillo)","hinweis":"ersatzweise Quittengelee"},{"menge":2,"einheit":"EL","name":"Schalotte, fein gehackt","hinweis":""},{"menge":1,"einheit":"EL","name":"Apfelessig","hinweis":""},{"menge":3,"einheit":"EL","name":"Olivenöl","hinweis":"2–3 EL"},{"menge":150,"einheit":"g","name":"Rotkohl und Wirsing, fein geschnitten","hinweis":"gemischt, roh"},{"menge":40,"einheit":"g","name":"Granatapfelkerne","hinweis":""},{"menge":35,"einheit":"g","name":"Haselnüsse, geröstet und gehackt","hinweis":"in der Pfanne ohne Fett rösten"},{"menge":1,"einheit":"Handvoll","name":"frische Minze","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"Schale abgerieben, Saft für die Muscheln"}]},{"gruppe":"Für die Jakobsmuscheln","liste":[{"menge":8,"einheit":"Stück","name":"große Jakobsmuscheln (ohne Corail)","hinweis":"frisch oder aufgetaut, gut abgetupft"},{"menge":2,"einheit":"TL","name":"Olivenöl","hinweis":""},{"menge":45,"einheit":"g","name":"Butter","hinweis":"kalt"},{"menge":null,"einheit":"","name":"Zitronensaft, Salz und Pfeffer","hinweis":"zum Abschmecken"}]}],"ausruestung":["Backblech mit Alufolie","Standmixer oder Pürierstab","schwere Pfanne, am besten Gusseisen oder Edelstahl","Pinzette oder Pfannenwender"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Ofen auf 220 °C Ober-/Unterhitze vor, bei Umluft auf 200 °C. Halbiere den Butternut-Kürbis, entferne die Kerne und lege die Hälften mit der Schnittfläche nach oben auf ein mit Alufolie belegtes Blech. Bereite die Jakobsmuscheln vor: Nimm sie aus dem Kühlschrank, entferne den kleinen seitlichen Muskel, falls noch vorhanden, und tupfe sie auf Küchenpapier trocken. Schneide den Kohl in feine Streifen und röste die Haselnüsse in einer Pfanne ohne Fett, bis sie duften.","dauer":20,"tipp":"Je trockener die Muscheln, desto besser bräunen sie später."},{"titel":"Kürbis im Ofen rösten","aktion":"backen","text":"Verteile die halbe Butter, die Kräuterzweige und den zerdrückten Knoblauch auf den beiden Kürbishälften, würze kräftig mit Salz und Pfeffer und beträufle sie mit Olivenöl. Schiebe das Blech in den Ofen und röste den Kürbis 45 bis 60 Minuten, bis das Fruchtfleisch ganz weich ist und sich mit einer Gabel leicht durchstechen lässt. Der Rand der Schnittfläche bräunt dabei an und riecht nach Karamell und Röstaromen.","dauer":55,"tipp":"Je dunkler die Ränder, desto tiefer das Aroma – nur nicht verbrennen lassen."},{"titel":"Püree mixen","aktion":"puerieren","text":"Lass den Kürbis kurz abkühlen, bis du ihn anfassen kannst. Löffle das Fruchtfleisch samt dem weich gerösteten Knoblauch aus der Schale, entferne die Kräuterzweige und püriere alles mit der restlichen Butter im Mixer, bis das Püree ganz glatt und samtig ist. Schmecke mit Salz und Pfeffer ab. Hält das Püree nicht zusammen, füge einen Schuss Wasser hinzu. Halte es zugedeckt warm, bis die Muscheln fertig sind.","dauer":10,"tipp":"Ein Standmixer macht das Püree seidiger als ein Pürierstab."},{"titel":"Vinaigrette und Krautsalat","aktion":"mischen","text":"Rühre die Quittenpaste mit einem Esslöffel heißem Wasser glatt und verrühre sie mit Schalotte, Apfelessig und Olivenöl zu einer Vinaigrette. Mische die Kohlstreifen mit den Granatapfelkernen, den gerösteten Haselnüssen und der Minze und reibe die Zitronenschale darüber. Gib gerade so viel Vinaigrette dazu, dass der Salat glänzt. Er soll knackig bleiben und nicht matschig werden, daher lieber sparsam dosieren.","dauer":10,"tipp":"Den Salat erst kurz vor dem Servieren anmachen, damit er knackig bleibt."},{"titel":"Jakobsmuscheln würzen","aktion":"vorbereiten","text":"Lege die Jakobsmuscheln mit der flacheren, breiteren Seite nach oben auf einen mit Küchenpapier belegten Teller, denn diese Seite kommt später nach unten in die Pfanne. Würze sie mit Salz und Pfeffer. Bereite alles für die Pfanne vor: Butter, Zitrone und Pfannenwender liegen griffbereit, denn das Anbraten geht schnell.","dauer":3,"tipp":"Würze erst kurz vor dem Braten, damit das Salz den Muscheln kein Wasser entzieht."},{"titel":"Scharf anbraten","aktion":"anbraten","text":"Erhitze die Pfanne bei hoher Hitze, bis sie richtig heiß ist, und gib das Olivenöl hinein. Lege die Jakobsmuscheln mit der breiten Seite nach unten hinein, ohne die Pfanne zu überladen. Brate sie etwa eineinhalb bis zwei Minuten, bis die Unterseite tiefgoldbraun und karamellisiert ist. Du erkennst es an der kräftigen Farbe und am Röstduft; bewege sie dabei nicht, sonst bildet sich keine Kruste.","dauer":3,"tipp":"Nicht zu viele Muscheln auf einmal, sonst fällt die Pfannentemperatur und sie kochen statt zu braten."},{"titel":"Mit Zitrone und Butter übergießen","aktion":"braten","text":"Wende die Muscheln, drücke den Saft einer halben Zitrone darüber und gib die kalte Butter in Stücken in die Pfanne. Lass die Butter schäumen und bräunen und übergieße die Muscheln damit etwa eine Minute lang. Die Muscheln sollen außen goldbraun und innen noch leicht glasig sein. Schmecke zum Schluss mit dem restlichen Zitronensaft, Salz und Pfeffer ab. Überbraten macht sie zäh, also lieber früher herausnehmen.","dauer":2,"tipp":"Beim Druck mit dem Finger sollen sie leicht nachgeben, nicht fest sein."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile das warme Kürbispüree in einem Löffelschwung auf vorgewärmten Tellern oder in flachen Schalen. Setze die Jakobsmuscheln darauf und lege den Krautsalat daneben. Beträufle die Teller mit etwas Vinaigrette und serviere sofort. Der Kontrast aus süßem, warmem Püree, saftigen Muscheln und knackigem, säuerlichem Salat macht das Gericht aus.","dauer":3,"tipp":"Wärme die Teller vor, damit die Muscheln nicht zu schnell auskühlen."}],"profitipps":["Muscheln gut trocken tupfen und in sehr heißer Pfanne braten, sonst bräunen sie nicht.","Nur so viele Muscheln auf einmal in die Pfanne legen, dass sie sich nicht berühren.","Am Ende mit Zitrone und Butter übergießen, so wird die Kruste glänzend und das Fleisch saftig.","Nicht übergaren: innen darf der Kern leicht glasig bleiben.","Den Salat sparsam anmachen, damit er knackig bleibt."],"varianten":["Mit Erbsenpüree statt Kürbis im Frühling.","Mit Blumenkohlpüree und Kapernbutter.","Mit Chorizo-Stückchen für eine herzhafte Note.","Als Hauptgericht mit mehr Muscheln pro Person."],"beilagen":["Baguette","Rucola-Salat"],"getraenk":"Kühler Chardonnay, Chablis oder ein trockener Riesling.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht dieses Gericht auf seiner Webseite: Jakobsmuscheln in der heißen Pfanne mit Butter und Zitrone, dazu Butternut-Püree und einen Krautsalat mit Quittenpaste.","quelle":"https://www.gordonramsay.com/gr/recipes/pan-seared-scallops-with-butternut-squash-puree-and-pomegranate-quince-slaw/"}],"quellen":[{"titel":"Gordon Ramsay – Pan-Seared Scallops with Butternut Squash Puree & Pomegranate-Quince Slaw","url":"https://www.gordonramsay.com/gr/recipes/pan-seared-scallops-with-butternut-squash-puree-and-pomegranate-quince-slaw/"},{"titel":"Gordon Ramsay – Seafood-Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/seafood"}],"bild":"meeresfruechte","farben":["#e08a2e","#f2c27a","#a63c5a"],"schlagworte":["Vorspeise","Jakobsmuscheln","Gordon Ramsay","Herbst"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-cawl","name":"Cawl","originalname":"Cawl","kueche":"britisch-irisch","region":"Wales","beliebtheit":66,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"eintopf","kurz":"Walisisches Nationalgericht: Lammfleisch mit Lauch, Steckrübe, Möhren und Kartoffeln, sanft in Brühe gegart – am zweiten Tag am besten.","hintergrund":"Cawl gilt als das inoffizielle Nationalgericht von Wales. Rezepte reichen bis ins 14. Jahrhundert zurück, damals mit Speck oder Rind und Wurzelgemüse; Kartoffeln kamen erst im späten 18. Jahrhundert dazu, und heute sind Lamm und Lauch das typische Paar. Gekocht wurde Cawl früher im Eisenkessel über offenem Feuer und mit Holzlöffeln gegessen. Man servierte erst die Brühe, dann das Fleisch und Gemüse als zweiten Gang; moderne Haushalte schöpfen alles zusammen in einen Teller. In Nordwales kennt man die Variante Lobsgows mit kleiner geschnittenem Gemüse, in manchen Gegenden isst man dazu Brot und Käse (Caerphilly) auf separatem Teller.","portionen":6,"zeit":{"vorbereitung":30,"garen":150,"ruhen":720},"schwierigkeit":1,"zutaten":[{"gruppe":"Für Fleisch und Brühe","liste":[{"menge":1,"einheit":"kg","name":"Lammhals oder Lammschulter mit Knochen","hinweis":"in 5 cm große Stücke geschnitten"},{"menge":200,"einheit":"g","name":"geräucherter Bauchspeck am Stück","hinweis":"im Ganzen, wird später gewürfelt"},{"menge":2,"einheit":"Blatt","name":"Lorbeer"},{"menge":1,"einheit":"Zweig","name":"Thymian"},{"menge":2,"einheit":"l","name":"Wasser"},{"menge":1,"einheit":"TL","name":"Salz"}]},{"gruppe":"Für das Gemüse","liste":[{"menge":4,"einheit":"Stange","name":"Lauch","hinweis":"in 2 cm dicke Ringe; zwei Drittel Weißes, ein Drittel Grünes"},{"menge":3,"einheit":"Stück","name":"Möhren","hinweis":"in dicke Scheiben"},{"menge":400,"einheit":"g","name":"Steckrübe","hinweis":"in 2 cm große Würfel; ersatzweise Kohlrabi"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"gewürfelt"},{"menge":600,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"in 3 cm große Würfel"},{"menge":2,"einheit":"EL","name":"Haferflocken","hinweis":"zart, zum Binden"},{"menge":1,"einheit":"Bund","name":"Petersilie","hinweis":"gehackt"},{"menge":null,"einheit":"","name":"Salz und frisch gemahlener weißer Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf (6–8 l)","Schaumkelle","Sieb","tiefe Schüsseln"],"schritte":[{"titel":"Fleisch ansetzen","aktion":"kochen","text":"Lege Lamm und Speckstück in den Topf, gieße 2 Liter kaltes Wasser an und bringe alles langsam zum Kochen. Wenn sich grauer Schaum bildet, schöpfst du ihn mit der Schaumkelle ab und wiederholst das, bis die Brühe klar bleibt. Gib Lorbeer, Thymian und 1 Teelöffel Salz dazu. Kalt anzusetzen lässt das Eiweiß langsam austreten, sodass die Brühe klar und das Fleisch saftig bleibt.","dauer":15,"tipp":""},{"titel":"Brühe 1 Stunde ziehen lassen","aktion":"koecheln","text":"Stelle die Hitze auf niedrig, sodass die Brühe nur leise vor sich hin blubbert, und lass das Fleisch zugedeckt 60 Minuten garen. Rühre nicht um und lass nicht sprudeln, denn zu heißes Kochen macht die Brühe trüb und das Fleisch trocken. Das Fleisch ist ausreichend gegart, wenn es zu zerfallen beginnt und sich am Knochen löst. Probiere die Brühe: Sie soll deutlich nach Lamm und Räucherspeck schmecken.","dauer":60,"tipp":""},{"titel":"Gemüse vorbereiten und zugeben","aktion":"schneiden","text":"Schneide inzwischen die Möhren, die Steckrübe, die Zwiebel und die Kartoffeln in gleich große Stücke von 2 bis 3 cm, damit sie gleichmäßig garen. Gib die Steckrübe, Möhren und Zwiebel zuerst in den Topf, da sie am längsten brauchen. Schwemme den Lauch gründlich ab, denn zwischen den Blättern sitzt Sand. Lass alles weitere 20 Minuten weiterköcheln.","dauer":5,"tipp":""},{"titel":"Kartoffeln und Lauch zugeben","aktion":"kochen","text":"Gib Kartoffeln zu der Brühe und lass sie 15 Minuten kochen, dann kommen die Lauchringe dazu, die nur 8 bis 10 Minuten brauchen. Die Brühe sollte das Gemüse gerade bedecken; gieße bei Bedarf heißes Wasser nach. Die Kartoffeln sind fertig, wenn sie weich sind und sich am Rand leicht auflösen, was die Brühe leicht andickt.","dauer":25,"tipp":""},{"titel":"Fleisch herausnehmen und zerteilen","aktion":"vorbereiten","text":"Hebe Lamm und Speck mit der Schaumkelle auf ein Brett. Löse das Fleisch von den Knochen, entferne Fett und Sehnen und zerpflücke es in mundgerechte Stücke; würfele den Speck. Gib das Fleisch zurück in den Topf. Wirf die Knochen weg oder koche sie für eine zweite Brühe nochmals aus. Rühre die Haferflocken ein, damit die Brühe leicht sämig wird.","dauer":10,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Lass den Cawl noch 5 bis 10 Minuten leise köcheln, damit sich die Haferflocken auflösen und alles vermischt. Schmecke mit Salz und weißem Pfeffer ab; der Speck bringt schon Salz mit, also vorsichtig würzen. Wenn zu viel Fett oben schwimmt, schöpfe es mit einem Löffel ab. Die Brühe soll kräftig, leicht cremig und gleichzeitig klar schmecken.","dauer":5,"tipp":"Cawl ist am zweiten Tag am besten: Über Nacht abkühlen lassen, Fettdecke abnehmen, dann erhitzen."},{"titel":"Servieren","aktion":"anrichten","text":"Schöpfe den Cawl in tiefe, vorgewärmte Schalen und streue frische Petersilie darüber. Reiche dazu dicke Scheiben Brot mit Butter und ein Stück kräftigen Käse wie Caerphilly oder Cheddar, den man in die Brühe tunkt oder dazu isst. Traditionell isst man zuerst die Brühe und danach das Fleisch und Gemüse; heute wird alles gleichzeitig gegessen.","dauer":0,"tipp":""},{"titel":"Aufwärmen am nächsten Tag","aktion":"kochen","text":"Stelle den Topf über Nacht kalt. Am nächsten Tag hat sich das Fett an der Oberfläche gesammelt und lässt sich in einem Stück abheben. Erwärme den Cawl langsam bei schwacher Hitze und rühre vorsichtig, damit die Kartoffeln nicht ganz zerfallen. Dabei zieht die Brühe durch, das Gemüse hat noch mehr Fleischgeschmack aufgenommen, und das Ganze schmeckt voller als am ersten Tag. Gib bei Bedarf etwas heißes Wasser dazu.","dauer":15,"tipp":""}],"profitipps":["Fleisch am Knochen und etwas Speck geben die Tiefe, die Cawl ausmacht.","Kalt ansetzen und gut abschäumen – dann bleibt die Brühe hell und klar.","Lauch erst spät zugeben, sonst wird er matschig und die Farbe stumpf.","Über Nacht ruhen lassen und Fett abnehmen: So wird Cawl, wie ihn die Waliser mögen.","Haferflocken statt Mehl binden sanft und schmecken leicht nussig."],"varianten":["Cawl cennin: vegetarische Lauchsuppe in Brühe","Lobsgows aus Nordwales mit kleiner geschnittenem Gemüse, ungebunden","Cawl mit Rindfleisch statt Lamm","Cawl Mamgu (Omas Cawl) mit Kohl und Pastinaken"],"beilagen":["Brot und Butter","Caerphilly-Käse","eingelegte Zwiebeln"],"getraenk":"Ein dunkles Ale oder ein kräftiges Welsh Bitter","koeche":[],"quellen":[{"titel":"Cawl – Wikipedia","url":"https://en.wikipedia.org/wiki/Cawl"},{"titel":"Cawl – traditional Welsh recipe – Visit Wales","url":"https://www.visitwales.com/things-do/food-drink/welsh-food/cawl-our-traditional-welsh-recipe"}],"bild":"eintopf","farben":["#b87a3a","#e6d5a8","#5d6b2e"],"schlagworte":["Wales","Lamm","Lauch","Nationalgericht","Wintergericht"],"vegetarisch_moeglich":false,"themen":[]},{"id":"britisch-irisch-dublin-bay-prawns-knoblauchbutter","name":"Dublin Bay Prawns mit Knoblauchbutter","originalname":"Dublin Bay Prawns","kueche":"britisch-irisch","region":"Irland, Dublin, Howth","beliebtheit":66,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Süßlich-zarter Kaisergranat, kurz gegart und in Knoblauchbutter geschwenkt – schlicht, luxuriös und typisch irisch, mit braunem Soda-Brot zum Auftunken.","hintergrund":"Dublin Bay Prawn ist ein anderer Name für Nephrops norvegicus, den Kaisergranat, auch Norwegischer Hummer, Langustine oder Scampi genannt. Er ist ein schlanker, blass orangefarbener kleiner Hummer, der bis etwa 25 cm lang wird und im Nordostatlantik und Teilen des Mittelmeers lebt. Der muskulöse Schwanz wird am häufigsten gegessen und als Scampi oder Langustine verkauft. Die irischen Hafenorte rund um Dublin Bay, Howth und Dunmore East leben vom Fang der Prawns, und fast jedes Fischrestaurant dort führt sie auf der Karte: gekocht mit Mayonnaise, gebraten in Knoblauchbutter oder als „Dublin Lawyer“ mit Whiskey und Sahne. Das Fleisch ist süßlich, fest und zart.","portionen":4,"zeit":{"vorbereitung":25,"garen":10,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Prawns","liste":[{"menge":16,"einheit":"","name":"Kaisergranat (Dublin Bay Prawns), je 60–100 g","hinweis":"frisch oder tiefgekühlt, ganz mit Schale"},{"menge":2,"einheit":"EL","name":"Salz","hinweis":"für das Kochwasser"},{"menge":2,"einheit":"l","name":"Wasser","hinweis":""}]},{"gruppe":"Für die Knoblauchbutter","liste":[{"menge":100,"einheit":"g","name":"gesalzene irische Butter (z. B. Kerrygold)","hinweis":"ersatzweise normale Butter plus 1 Prise Salz"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":2,"einheit":"EL","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":1,"einheit":"","name":"Bio-Zitrone","hinweis":"Schale abgerieben, Saft für den Fisch"},{"menge":1,"einheit":"Prise","name":"Chiliflocken","hinweis":"optional"}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"","name":"irisches Soda-Brot oder dunkles Brot","hinweis":"zum Auftunken"},{"menge":4,"einheit":"EL","name":"Mayonnaise oder Aioli","hinweis":"optional"},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"in Spalten"}]}],"ausruestung":["Großer Topf","Schaumlöffel","Große Pfanne","Scharfe Schere oder Messer"],"schritte":[{"titel":"Mise en place und Frische prüfen","aktion":"vorbereiten","text":"Frischer Kaisergranat riecht nach Meer, nicht nach Ammoniak; die Schale ist glänzend und fest, das Fleisch durchscheinend und fest. Tiefgekühlte Prawns taust du über Nacht im Kühlschrank auf. Spüle die Tiere kalt ab und tupfe sie trocken. Der Darm verläuft als dunkler Strich im Rücken: Er wird je nach Größe entfernt, indem du den Panzer am Rücken mit der Schere aufschneidest und den Darm vorsichtig herausziehst.","dauer":10,"tipp":"Bei kleinen Prawns kannst du den Darm im Schwanz einfach lassen, bei größeren ist er sandig und sollte entfernt werden."},{"titel":"Knoblauchbutter vorbereiten","aktion":"mischen","text":"Lasse die Butter auf Zimmertemperatur weich werden und verrühre sie mit Knoblauch, Petersilie, abgeriebener Zitronenschale und Chili. Die Mischung soll homogen und leuchtend grün sein. Schmecke sie ab: Wenn die Butter ungesalzen ist, gib eine Prise Salz dazu. Stelle sie bei Bedarf kurz kalt, sodass sie formbar bleibt. Streiche die Butter bei Bedarf auf ein Stück Backpapier, rolle sie zu einer Rolle und lasse sie im Kühlschrank fest werden; dann kannst du Scheiben abschneiden. Der Duft nach frischem Knoblauch und Zitrone ist ein gutes Zeichen, dass die Mischung stimmt.","dauer":5,"tipp":""},{"titel":"Kochwasser ansetzen","aktion":"kochen","text":"Bringe zwei Liter Wasser mit zwei Esslöffeln Salz in einem großen Topf zum Kochen. Das Wasser soll wie Meerwasser schmecken, damit die Prawns nicht auslaugen. Bereite eine Schüssel mit Eiswasser vor, um den Garprozess nach dem Kochen zu stoppen. Nimm einen Topf, der groß genug ist, damit die Prawns frei schwimmen können, denn zu viele Tiere in zu wenig Wasser bringen die Temperatur zum Absinken und das Garen dauert zu lange. Decke den Topf zu, damit das Wasser schneller wieder sprudelt, und halte den Schaumlöffel bereit.","dauer":5,"tipp":""},{"titel":"Prawns kurz blanchieren","aktion":"blanchieren","text":"Gib die Prawns in das sprudelnde Wasser und koche sie 2–3 Minuten, bei großen Tieren bis zu 4 Minuten. Sie färben sich leuchtend orange-rot, und das Fleisch wird fest und opak. Hebe sie sofort mit dem Schaumlöffel heraus und tauche sie in Eiswasser, damit sie nicht übergaren. Zu langes Kochen macht das Fleisch gummiartig. Lass sie 2 Minuten im Eiswasser, bis sie ganz kalt sind, und lege sie dann auf Küchenpapier. Sie sollen glänzend orangerot aussehen, mit festem, elastischem Fleisch. Hängen sie schlaff und blass aus der Schale, waren sie nicht frisch genug.","dauer":4,"tipp":"Der Kaisergranat ist gar, wenn der Schwanz sich nach unten krümmt und das Fleisch glasig-weiß ist."},{"titel":"Schale öffnen","aktion":"schneiden","text":"Halbiere die Prawns der Länge nach mit einem scharfen Messer oder öffne den Panzer am Bauch mit einer Schere, sodass das Fleisch freiliegt. Lass die Schale zur Zierde dran. Entferne den Darm, falls noch vorhanden. Tupfe das Fleisch trocken. Arbeite zügig, damit das Fleisch nicht austrocknet, und lege die geöffneten Tiere mit dem Fleisch nach oben auf ein Tuch. Die Scheren enthalten ebenfalls zartes Fleisch: Knacke sie mit dem Rücken eines schweren Messers, bevor du sie später isst.","dauer":5,"tipp":""},{"titel":"In Knoblauchbutter schwenken","aktion":"braten","text":"Erhitze eine große Pfanne bei mittlerer Hitze und gib die Hälfte der Knoblauchbutter hinein. Sobald sie schäumt, lege die Prawns mit der Fleischseite nach unten hinein und schwenke sie 1–2 Minuten, bis sie leicht gebräunt und von der Butter überzogen sind. Der Knoblauch soll duften, aber nicht verbrennen; sonst wird er bitter. Gib einen Spritzer Zitronensaft dazu.","dauer":3,"tipp":"Nicht zu lange erhitzen: Die Prawns sind bereits gar und sollen nur heiß werden."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile die Prawns auf warme Teller und gieße die Butter aus der Pfanne darüber. Reiche Zitronenspalten, eine Schale Mayonnaise oder Aioli und dicke Scheiben dunkles Brot zum Auftunken dazu. Gegessen wird mit den Fingern; stelle eine Schale für die Schalen und Fingerschalen mit Zitronenwasser auf den Tisch. Die Prawns sollen noch dampfen und in einer duftenden, grünen Buttersauce glänzen. Tauche das Brot hinein, damit nichts verloren geht, und reiche dazu eine Schüssel zum Ablegen der Schalen sowie Servietten oder Fingerschalen.","dauer":0,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere ein Stück: Das Fleisch soll süßlich, zart und leicht nach Butter und Knoblauch schmecken. Fehlt Frische, gib mehr Zitrone dazu; fehlt Würze, eine Prise Salz oder Pfeffer aus der Mühle. Serviere sofort, solange alles warm ist. Wenn die Butter zu fettig wirkt, hilft ein Spritzer Zitronensaft, der sie leicht und frisch macht. Zu viel Salz ist bei gesalzener Butter schnell erreicht, probiere also zuerst und salze dann. Ein Hauch Chili gibt ihr zusätzlich Tiefe, ohne zu dominieren.","dauer":0,"tipp":""}],"profitipps":["Prawns nie zu lange kochen – 2–3 Minuten genügen.","Eiswasser stoppt den Garprozess und hält das Fleisch zart.","Knoblauch nie braun werden lassen, sonst ist er bitter.","Irische Butter ist cremig und leicht gesalzen – sie gibt dem Gericht seinen typischen Geschmack.","Den Panzer nach dem Kochen nicht wegwerfen: Er ergibt einen hervorragenden Fond."],"varianten":["Dublin Lawyer: Prawns in Whiskey-Sahnesauce.","Kalt mit Mayonnaise und Zitrone, wie in Pubs.","Gegrillt über Holzkohle.","Als Teil eines Meeresfrüchte-Tellers."],"beilagen":["Irisches Soda-Brot","Aioli","Zitronenspalten","Gemischter Salat"],"getraenk":"Guinness oder Murphy's Stout; alternativ ein trockener Sauvignon Blanc.","koeche":[],"quellen":[{"titel":"Dublin Bay prawn (Nephrops norvegicus) – Wikipedia","url":"https://en.wikipedia.org/wiki/Dublin_Bay_prawn"},{"titel":"Dublin Bay Prawns – Food Smart Dublin (TCD)","url":"https://www.tcd.ie/tceh/projects/foodsmartdublin/recipes/November_Nephrops/prawns.php"}],"bild":"meeresfruechte","farben":["#e8743a","#f5d6a0","#7ca05a"],"schlagworte":["Irland","Krustentiere","Vorspeise","Pub"],"vegetarisch_moeglich":false,"hinweis":"In Deutschland heißt Kaisergranat auch Langustine oder Scampi. Er ist tiefgekühlt im Fachhandel und beim Fischhändler erhältlich. Achte auf MSC-Siegel oder Herkunft Nordostatlantik."},{"id":"britisch-irisch-pavlova-himbeercurd-ramsay","name":"Pavlova für zwei mit Himbeer-Curd nach Art von Gordon Ramsay","originalname":"Pavlova for Two with Raspberry Curd","kueche":"britisch-irisch","region":"England (Ramsays Version eines Desserts aus Ozeanien)","beliebtheit":66,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Eine knusprige Baiserschale mit marshmallowweichem Kern, gefüllt mit säuerlicher Himbeercreme und serviert mit schokoladenüberzogenen Erdbeeren. Ein elegantes Dessert für zwei.","hintergrund":"Die Pavlova ist ein Dessert, um dessen Herkunft Australien und Neuseeland streiten; benannt ist sie nach der Ballerina Anna Pawlowa. Ramsay veröffentlicht auf seiner Webseite eine Miniversion für zwei Personen mit selbst gekochtem Himbeer-Curd. Das Baiser wird bei niedriger Hitze getrocknet und bleibt zum Auskühlen im Ofen. Dies ist eine Heimküchen-Fassung mit eigenen Erklärungen, nach dem veröffentlichten Rezept.","portionen":2,"zeit":{"vorbereitung":40,"garen":100,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Mini-Pavlova","liste":[{"menge":1,"einheit":"Stück","name":"Eiweiß","hinweis":"von einem frischen Ei, Zimmertemperatur, ohne Spur Eigelb"},{"menge":50,"einheit":"g","name":"feiner Zucker","hinweis":"Kristallzucker"},{"menge":1.5,"einheit":"TL","name":"Speisestärke","hinweis":""},{"menge":0.5,"einheit":"TL","name":"weißer Essig","hinweis":"Branntweinessig"},{"menge":0.5,"einheit":"TL","name":"Vanilleextrakt","hinweis":""},{"menge":null,"einheit":"","name":"rosa Lebensmittelfarbe","hinweis":"optional, tropfenweise"}]},{"gruppe":"Für den Himbeer-Curd (ergibt ca. 350 ml)","liste":[{"menge":100,"einheit":"g","name":"Butter","hinweis":"ungesalzen"},{"menge":125,"einheit":"g","name":"Himbeeren","hinweis":"frisch oder aufgetaut"},{"menge":100,"einheit":"g","name":"Zucker","hinweis":""},{"menge":5,"einheit":"Stück","name":"Eigelb","hinweis":"eines davon vom Pavlova-Ei"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"nur die fein abgeriebene Schale"}]},{"gruppe":"Für die Schoko-Erdbeeren und zum Servieren","liste":[{"menge":170,"einheit":"g","name":"Zartbitterschokolade","hinweis":"gehackt oder als Chips"},{"menge":1,"einheit":"EL","name":"Kokosöl","hinweis":"für schönen Glanz"},{"menge":8,"einheit":"Stück","name":"Erdbeeren","hinweis":"gewaschen und sehr gut getrocknet, 5–10 Stück"},{"menge":1,"einheit":"Handvoll","name":"frische Himbeeren","hinweis":"zum Servieren"}]}],"ausruestung":["Handmixer oder Schneebesen","Backblech mit Backpapier","feines Sieb","kleiner Topf und Hitzebeständige Schüssel","Küchenthermometer","Schneebesen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lege ein Backblech mit Backpapier aus und heize den Ofen auf 175 °C Ober-/Unterhitze vor, bei Umluft auf 155 °C. Achte darauf, dass Schüssel und Schneebesen vollkommen sauber und fettfrei sind, denn schon ein Hauch Fett oder Eigelb verhindert, dass das Eiweiß steif wird. Trenne die Eier: Das Eiweiß ist für das Baiser, die Eigelbe für den Curd. Verrühre in einem kleinen Schälchen Speisestärke, Essig und Vanille glatt.","dauer":10,"tipp":"Wische die Schüssel vorher mit etwas Essig oder Zitrone aus, um Fettspuren sicher zu entfernen."},{"titel":"Baiser aufschlagen","aktion":"aufschlagen","text":"Schlage das Eiweiß mit dem Zucker bei niedriger bis mittlerer Stufe, bis sich beides verbunden hat, das dauert unter einer Minute. Erhöhe dann die Geschwindigkeit und schlage etwa zwei bis drei Minuten, bis weiche Spitzen entstehen. Gib die Stärke-Essig-Mischung dazu, bei Wunsch auch tropfenweise Farbe, und schlage weitere drei bis fünf Minuten, bis die Masse steif und glänzend ist. Sie muss stehende Spitzen bilden, die nicht abknicken.","dauer":10,"tipp":"Wenn du die Schüssel auf den Kopf drehst, darf die Masse nicht herausrutschen."},{"titel":"Formen und im Ofen trocknen","aktion":"formen","text":"Streiche das Baiser auf dem Backblech zu einem Kreis von etwa 10 cm Durchmesser und mindestens 2,5 cm Höhe. Drücke in der Mitte eine flache Mulde ein und ziehe den Rand leicht nach oben, damit später der Curd halten kann. Schiebe das Blech in den Ofen und senke die Temperatur sofort auf 105 °C Ober-/Unterhitze, bei Umluft etwa 90 °C. Backe es 1 Stunde 15 Minuten, ohne die Tür zu öffnen.","dauer":75,"tipp":"Nicht die Ofentür öffnen: Der Temperaturabfall lässt das Baiser zusammenfallen."},{"titel":"Im Ofen auskühlen lassen","aktion":"ruhen","text":"Schalte den Ofen aus und lass die Pavlova mehrere Stunden im geschlossenen Ofen auskühlen, mindestens drei Stunden nach dem Ausschalten. So bleibt die Oberfläche trocken und knusprig, ohne zu reißen, und der Kern bleibt weich. Öffne die Tür nicht, auch nicht einen Spalt. Du kannst die Pavlova auch über Nacht im Ofen lassen.","dauer":180,"tipp":"Am besten backst du die Pavlova am Vortag, dann ist sie am Servierabend bereit."},{"titel":"Himbeer-Curd kochen","aktion":"binden","text":"Stelle ein feines Sieb über eine hitzebeständige Schüssel. Schmilz in einem kleinen Topf die Butter bei mittlerer bis niedriger Hitze und gib Himbeeren, Zucker, Eigelb, Zitronensaft und Salz dazu. Rühre ständig mit dem Schneebesen, damit nichts anlegt und die Eigelbe nicht stocken. Lass die Masse 7 bis 9 Minuten erhitzen, bis sie mindestens 70 °C erreicht und wie Pudding andickt, sie soll einen Löffelrücken überziehen.","dauer":10,"tipp":"Bei Temperaturen über 80 °C kann das Eigelb flocken, dann schnell vom Herd ziehen und weiterrühren."},{"titel":"Curd passieren und kühlen","aktion":"abseihen","text":"Gieße den heißen Curd sofort durch das Sieb und drücke ihn mit einem Löffel durch, um Kerne und eventuell geronnene Teile zu entfernen. Rühre die abgeriebene Zitronenschale unter und schmecke ab. Stelle die Schüssel in ein Eisbad und rühre öfter um, wenn du ihn bald brauchst. Soll er länger halten, drücke Frischhaltefolie direkt auf die Oberfläche, damit sich keine Haut bildet, und stelle ihn in den Kühlschrank.","dauer":10,"tipp":"Der Curd hält im Kühlschrank bis zu drei Tage."},{"titel":"Schoko-Erdbeeren tauchen","aktion":"kochen","text":"Lege ein Blech mit Backpapier aus. Schmilz die Schokolade mit dem Kokosöl über einem Wasserbad, das nur sanft simmert; die Schüssel darf das Wasser nicht berühren. Rühre, bis die Masse glatt ist. Nimm die Schüssel vom Wasserbad und trockne sie außen ab. Halte jede Erdbeere am Stiel, tauche sie etwa zu drei Vierteln ein, lass überschüssige Schokolade abtropfen und lege sie aufs Papier.","dauer":15,"tipp":"Die Erdbeeren müssen absolut trocken sein, sonst haftet die Schokolade nicht."},{"titel":"Schokolade fest werden lassen","aktion":"kuehlen","text":"Lass die Erdbeeren bei Raumtemperatur 30 bis 45 Minuten stehen oder stelle sie 15 bis 25 Minuten in den Kühlschrank, bis die Schokolade fest ist. Nimm sie 20 bis 30 Minuten vor dem Servieren wieder heraus, damit die Schokolade nicht zu hart ist und das Aroma sich entfaltet. Sie schmecken am besten innerhalb weniger Stunden.","dauer":30,"tipp":"Im Kühlschrank kann die Schokolade matt werden, das beeinträchtigt nur die Optik."},{"titel":"Anrichten","aktion":"anrichten","text":"Setze die ausgekühlte Pavlova auf einen Servierteller und fülle die Mulde großzügig mit Himbeer-Curd. Stecke die Schoko-Erdbeeren hinein und rund um die Pavlova und verteile frische Himbeeren. Serviere sofort mit zwei Löffeln, denn die Feuchtigkeit des Curds weicht das Baiser mit der Zeit auf. Die Kruste knackt beim Anstechen, darunter ist das Innere weich wie Marshmallow.","dauer":3,"tipp":"Fülle die Pavlova erst direkt vor dem Servieren, damit der Boden knusprig bleibt."}],"profitipps":["Schüssel und Schneebesen fettfrei halten und kein Eigelb ins Eiweiß lassen.","Das Baiser bei 105 °C trocknen und im geschlossenen Ofen auskühlen lassen.","Den Curd auf mindestens 70 °C erhitzen und durch ein Sieb streichen.","Pavlova nie im Kühlschrank lagern: Sie hält sich bis zu 24 Stunden luftdicht und kühl.","Erst kurz vor dem Servieren füllen."],"varianten":["Mit Passionsfruchtcurd und Mango.","Mit Schlagsahne und frischen Beeren.","Als große Pavlova für sechs Personen mit der doppelten Menge.","Mit Zitronencurd und Blaubeeren."],"beilagen":["frische Himbeeren","geschlagene Sahne"],"getraenk":"Prosecco, Moscato d'Asti oder ein Himbeer-Spritz.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diese Mini-Pavlova für zwei mit selbst gekochtem Himbeer-Curd und Schoko-Erdbeeren auf seiner Webseite.","quelle":"https://www.gordonramsay.com/gr/recipes/pavlovawithraspberrycurd/"}],"quellen":[{"titel":"Gordon Ramsay – Pavlova for Two with Raspberry Curd","url":"https://www.gordonramsay.com/gr/recipes/pavlovawithraspberrycurd/"},{"titel":"Gordon Ramsay – Dessert-Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/dessert"}],"bild":"dessert","farben":["#f6c1cc","#c2185b","#fff5f0"],"schlagworte":["Dessert","Baiser","Gordon Ramsay","Himbeeren"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-haehnchen-herbstgemuese-pies-ramsay","name":"Hähnchen-Herbstgemüse-Pies nach Art von Gordon Ramsay","originalname":"Chicken & Autumn Vegetable Pies","kueche":"britisch-irisch","region":"England","beliebtheit":66,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Zartes Hähnchen mit Sellerie, Kürbis, Lauch und Pancetta in cremiger Sherry-Sauce, darüber ein knuspriger Blätterteigdeckel, der separat gebacken wird. Das Comfort Food der britischen Küche, schlanker und schneller gemacht.","hintergrund":"Pies mit Hähnchen gehören zum Alltag der britischen Küche. Ramsay veröffentlicht auf seiner Webseite eine Variante, bei der die Füllung im Topf gekocht wird und die Blätterteigdeckel separat auf einem Blech backen. So bleibt der Teig knusprig und wird nicht unten matschig. Als Füllung dient gegartes Hähnchen, das du gut aus einem Brathähnchen vom Vortag nehmen kannst. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, mit meinen Erklärungen.","portionen":3,"zeit":{"vorbereitung":25,"garen":55,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Füllung","liste":[{"menge":50,"einheit":"g","name":"Pancetta oder Speckwürfel","hinweis":"gewürfelt"},{"menge":1,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lauchstange","hinweis":"geputzt, in Ringen"},{"menge":200,"einheit":"g","name":"Knollensellerie","hinweis":"geschält, in kleine Würfel (ca. 1 cm) geschnitten"},{"menge":200,"einheit":"g","name":"Butternut-Kürbis","hinweis":"geschält, in kleine Würfel geschnitten; ersatzweise Hokkaido"},{"menge":1,"einheit":"Handvoll","name":"Thymian","hinweis":"nur die Blättchen"},{"menge":50,"einheit":"ml","name":"trockener Sherry","hinweis":"Fino oder Amontillado"},{"menge":200,"einheit":"ml","name":"Hühnerbrühe","hinweis":""},{"menge":100,"einheit":"ml","name":"Crème fraîche","hinweis":""},{"menge":250,"einheit":"g","name":"gegartes Hähnchenfleisch","hinweis":"in mundgerechte Stücke geschnitten; z. B. vom Brathähnchen"},{"menge":null,"einheit":"","name":"Meersalz und schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Für die Blätterteigdeckel","liste":[{"menge":200,"einheit":"g","name":"Blätterteig","hinweis":"frisch oder aus der Kühlung"},{"menge":null,"einheit":"","name":"Mehl","hinweis":"zum Ausrollen"},{"menge":1,"einheit":"Stück","name":"Eigelb","hinweis":"mit 1 TL Wasser verquirlt"}]}],"ausruestung":["große Pfanne oder breiter Topf","Backblech mit Antihaft-Backmatte","Ausstechring oder kleiner Teller als Schablone (ca. 14 cm)","Pinsel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide Pancetta, Lauch, Sellerie und Kürbis klein, damit alles später in derselben Zeit gar wird: Sellerie und Kürbis gehören in etwa 1 cm große Würfel. Zupfe die Thymianblättchen ab und schneide das gegarte Hähnchenfleisch in mundgerechte Stücke. Stelle Crème fraîche, Sherry und Brühe bereit und hole den Blätterteig rechtzeitig aus dem Kühlschrank, damit er sich gut ausrollen lässt. Heize den Ofen noch nicht vor, das kommt später.","dauer":15,"tipp":"Gleichmäßig große Würfel sorgen dafür, dass alles zur selben Zeit weich wird."},{"titel":"Pancetta knusprig braten","aktion":"anbraten","text":"Erhitze eine große Pfanne ohne Fett bei mittlerer bis hoher Hitze und brate die Pancetta darin drei bis vier Minuten, bis das Fett ausgetreten und die Würfel leicht goldbraun sind. Hole sie mit dem Schaumlöffel heraus und lege sie auf Küchenpapier. Wische die Pfanne mit Küchenpapier aus, damit nichts anbrennt, und stelle sie wieder auf die Hitze. Die Pancetta kommt später wieder in die Sauce und liefert Würze und Rauch.","dauer":5,"tipp":"Durchwachsener Räucherspeck funktioniert genauso gut wie Pancetta."},{"titel":"Gemüse anschwitzen","aktion":"braten","text":"Gib das Olivenöl in die Pfanne und schwitze Lauch, Sellerie und Kürbis mit dem Thymian bei mittlerer Hitze etwa sieben Minuten an, bis das Gemüse an den Rändern leicht Farbe nimmt und nach Thymian duftet. Würze mit Salz und Pfeffer. Rühre dabei häufig um, damit nichts am Boden festsetzt. Das Gemüse soll noch Biss haben, es gart im nächsten Schritt weiter.","dauer":8,"tipp":"Salz zieht Wasser aus dem Gemüse, das hilft beim Bräunen und Garen."},{"titel":"Mit Sherry ablöschen","aktion":"reduzieren","text":"Gieße den Sherry über das Gemüse und lass ihn etwa fünf Minuten sprudelnd einkochen, bis er fast verdampft ist und nur ein sirupartiger Rest bleibt. Dabei verfliegt der Alkohol und es bleibt der nussige, leicht süße Geschmack. Gib die Pancetta zurück in die Pfanne und rühre sie unter. Löse mit dem Löffel alles vom Boden, denn dort sitzen Röstaromen.","dauer":5,"tipp":"Trockener Sherry passt besser als süßer, weil die Sauce sonst zu schwer wird."},{"titel":"Brühe einkochen","aktion":"koecheln","text":"Gieße die Hühnerbrühe zu und lass sie bei starker Hitze 10 bis 15 Minuten kochen, bis sich die Flüssigkeit etwa um die Hälfte reduziert hat. Das Gemüse wird dabei weich, und die Brühe wird konzentrierter und gebundener. Probiere ein Kürbisstück: Es soll sich leicht zerdrücken lassen. Ist die Flüssigkeit zu schnell weg, gib einen Schuss Wasser nach.","dauer":15,"tipp":"Je kräftiger die Brühe, desto mehr Geschmack bekommt die Füllung."},{"titel":"Crème fraîche einrühren","aktion":"binden","text":"Rühre die Crème fraîche ein und lass die Sauce etwa fünf Minuten leise köcheln, bis sie um ein Drittel eingekocht und cremig ist. Schmecke mit Salz und Pfeffer ab. Nimm die Pfanne dann vom Herd und stelle sie zur Seite; das Hähnchenfleisch kommt erst kurz vor dem Servieren hinein, damit es nicht trocken wird.","dauer":5,"tipp":"Die Sauce darf dickflüssig sein, sie dickt beim Abkühlen noch nach."},{"titel":"Blätterteigdeckel ausstechen","aktion":"ausrollen","text":"Heize den Ofen auf 200 °C Ober-/Unterhitze vor, bei Umluft auf 180 °C. Rolle den Blätterteig auf einer leicht bemehlten Fläche etwa 3 mm dick aus und stich mit einem Ausstechring oder rund um einen kleinen Teller drei Kreise von etwa 14 cm Durchmesser aus. Lege sie auf ein Blech mit Antihaftmatte und ritze mit der Messerspitze ein Rautenmuster ein, ohne durchzuschneiden.","dauer":10,"tipp":"Den Teig nicht zu stark bemehlen, sonst wird er weiß und trocken."},{"titel":"Deckel backen","aktion":"backen","text":"Bestreiche die Teigkreise mit dem verquirlten Eigelb und backe sie etwa 10 Minuten, bis sie aufgegangen und goldbraun sind. Öffne dann die Ofentür einen Spalt und backe noch zwei Minuten weiter, damit der Boden knusprig durchtrocknet. Hebe die Deckel auf ein Gitter und lass sie kurz ruhen, sie sollen beim Anstechen knistern.","dauer":12,"tipp":"Eigelb nur auf die Oberseite streichen, nicht an den Rand laufen lassen, sonst geht der Teig schief auf."},{"titel":"Hähnchen erwärmen und anrichten","aktion":"anrichten","text":"Gib das Hähnchenfleisch in die Sauce und erwärme es bei niedriger Hitze, bis es durchgehend heiß ist. Schmecke ein letztes Mal mit Salz und Pfeffer ab. Löffle die Füllung auf vorgewärmte tiefe Teller und setze je einen Blätterteigdeckel obenauf. Serviere sofort, damit der Deckel schön knusprig bleibt und nicht durchweicht.","dauer":5,"tipp":"Wer mag, streut frischen Thymian oder Petersilie darüber."}],"profitipps":["Die Deckel getrennt zu backen verhindert einen matschigen Teigboden.","Die Sauce muss gut einkochen, sonst wird die Füllung wässrig.","Gegartes Hähnchen vom Vortag spart Zeit und ist saftiger als gekochtes.","Den Ofen zum Schluss einen Spalt öffnen, damit der Teig trocknet und knusprig bleibt.","Die Füllung lässt sich einen Tag vorher zubereiten, die Deckel backst du frisch."],"varianten":["Mit Pilzen statt Kürbis.","Mit Putenfleisch vom Festtagsbraten.","Als klassischer Pie im Auflaufförmchen mit ganzem Teigdeckel.","Vegetarisch mit Kichererbsen und mehr Gemüse."],"beilagen":["Erbsen mit Butter","grüner Salat","Kartoffelpüree"],"getraenk":"Chardonnay, Apfelwein oder ein britisches Ale.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diese Pies auf seiner Webseite als gemüsereiche, schnellere Version eines Familienklassikers, mit separat gebackenen Blätterteigdeckeln.","quelle":"https://www.gordonramsay.com/gr/recipes/chicken-and-autumn-vegetable-pies/"}],"quellen":[{"titel":"Gordon Ramsay – Chicken & Autumn Vegetable Pies","url":"https://www.gordonramsay.com/gr/recipes/chicken-and-autumn-vegetable-pies/"},{"titel":"Gordon Ramsay – Chicken-Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/chicken"}],"bild":"auflauf","farben":["#c98a3a","#f1d9a0","#7a5230"],"schlagworte":["Pie","Herbst","Gordon Ramsay","Comfort Food"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-garnelen-scampi-capellini-ramsay","name":"Garnelen-Scampi mit Capellini nach Art von Gordon Ramsay","originalname":"Ramsay in 10: Shrimp Scampi with Capellini Pasta","kueche":"britisch-irisch","region":"Großbritannien / USA (Ramsay in 10)","beliebtheit":64,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"hauptgericht","kurz":"Zarte Garnelen und feine Engelshaarnudeln in einer Sauce aus Weißwein, Zitrone, Kapern und Butter. Dank der Ramsay-in-10-Methode steht alles in zehn Minuten auf dem Tisch.","hintergrund":"Aus Ramsays Kochbuch und Webreihe Ramsay in 10 stammt dieses Gericht, das auf Tempo ausgelegt ist. Die Sauce wird zuerst gekocht, die Garnelen werden direkt darin pochiert, und die Nudeln werden zum Schluss in der Sauce geschwenkt. Zum Schluss kommt kalte Butter in die Sauce, damit sie cremig bindet. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, das auf der Webseite für eine Portion angegeben ist und hier für zwei Portionen umgerechnet wurde.","portionen":2,"zeit":{"vorbereitung":10,"garen":15,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Pasta und Garnelen","liste":[{"menge":16,"einheit":"Stück","name":"Garnelen, geschält und entdarmt","hinweis":"im Original 8–12 pro Portion; roh, ohne Schale, ca. 250 g"},{"menge":230,"einheit":"g","name":"Capellini oder Engelshaar-Nudeln","hinweis":"ersatzweise dünne Spaghettini"},{"menge":3,"einheit":"EL","name":"Olivenöl extra vergine","hinweis":"2 EL zum Anschwitzen, 1 EL zum Beträufeln"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gerieben"},{"menge":1,"einheit":"Stück","name":"große Schalotte","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"TL","name":"Chiliflocken","hinweis":"Original: 2 TL pro Portion, hier milder; nach Geschmack mehr"},{"menge":2,"einheit":"Stück","name":"Bio-Zitronen","hinweis":"Schale abgerieben und Saft"},{"menge":150,"einheit":"ml","name":"trockener Weißwein","hinweis":""},{"menge":3,"einheit":"EL","name":"Kapern","hinweis":"abgetropft"},{"menge":120,"einheit":"g","name":"Kirschtomaten","hinweis":"halbiert"},{"menge":150,"einheit":"ml","name":"Meeresfrüchte- oder Fischfond","hinweis":"ersatzweise Gemüsebrühe"},{"menge":80,"einheit":"g","name":"kalte Butter","hinweis":"in Würfeln"},{"menge":1,"einheit":"Zweig","name":"Basilikum","hinweis":"Blätter abzupfen"},{"menge":null,"einheit":"","name":"Parmesan zum Reiben, Salz, Pfeffer","hinweis":""}]}],"ausruestung":["großer Topf für die Pasta","weite Pfanne mit hohem Rand","feine Reibe"],"schritte":[{"titel":"Mise en place und Wasser aufsetzen","aktion":"vorbereiten","text":"Bring in einem großen Topf reichlich Wasser zum Kochen und salze es kräftig. Schäle die Garnelen, falls nötig, und entferne den dunklen Darm. Würfle die Schalotte fein, reibe den Knoblauch, halbiere die Tomaten und reibe von beiden Zitronen die Schale ab, bevor du den Saft auspresst. Stelle alle Zutaten griffbereit neben den Herd, denn die Sauce geht schnell und es bleibt keine Zeit zum Suchen.","dauer":8,"tipp":"Das Nudelwasser darf ruhig kräftig nach Meer schmecken."},{"titel":"Schalotte und Knoblauch anschwitzen","aktion":"braten","text":"Erhitze zwei Esslöffel Olivenöl in einer weiten Pfanne bei mittlerer Hitze und schwitze Schalotte und Knoblauch etwa zwei Minuten an, bis sie weich und glasig sind und duften. Sie sollen keine Farbe nehmen, sonst wird die Sauce bitter. Gib bei Bedarf einen Spritzer Wasser dazu. Der Duft nach weichem Knoblauch und süßlicher Schalotte ist dein Signal, dass es weitergehen kann; riecht es scharf oder röstig, ist die Pfanne zu heiß gewesen.","dauer":2,"tipp":"Knoblauch immer auf der niedrigeren Hitze halten, er verbrennt in Sekunden."},{"titel":"Weißwein einkochen","aktion":"reduzieren","text":"Gieße den Weißwein dazu und lass ihn fast vollständig einkochen. Das dauert etwa zwei bis drei Minuten, die Flüssigkeit wird sirupartig, und der Alkohol verfliegt. Dadurch bleibt nur die fruchtige Säure und das Aroma des Weins übrig. Das Aroma wird später durch Zitrone und Kapern ergänzt. Du erkennst den richtigen Punkt daran, dass der Boden der Pfanne nur noch leicht feucht ist und die Blasen dick und langsam aufsteigen.","dauer":3,"tipp":"Nimm einen Wein, den du auch trinken würdest, nie Kochwein."},{"titel":"Sauce aufbauen","aktion":"koecheln","text":"Gieße den Fond in die Pfanne und gib Chiliflocken, Kapern, Kirschtomaten sowie Schale und Saft der Zitronen dazu. Lass alles zum Köcheln kommen. Die Tomaten fallen leicht zusammen, die Sauce riecht frisch nach Zitrone und leicht scharf. Das reicht jetzt, um die Garnelen zu garen. Die Säure der Zitronen und die Salzigkeit der Kapern bestimmen später den Charakter der Sauce, darum lohnt sich das Probieren, bevor die Garnelen hineinkommen.","dauer":3,"tipp":"Probiere die Sauce schon jetzt und stelle Säure und Schärfe ein, bevor die Garnelen hineinkommen."},{"titel":"Garnelen pochieren","aktion":"koecheln","text":"Würze die Garnelen mit Salz und Pfeffer und lege sie in die leicht köchelnde Sauce. Lass sie pro Seite etwa eine Minute garen, bis sie sich rosa färben und fest, aber noch zart sind. Zu langes Garen macht sie gummiartig, also nimm die Pfanne lieber etwas früher vom Herd, sie garen in der Sauce noch nach.","dauer":3,"tipp":"Wenn die Garnelen ein „C“ formen, sind sie perfekt, ein enges „O“ bedeutet überkocht."},{"titel":"Kalte Butter einrühren","aktion":"binden","text":"Ziehe die Pfanne vom Herd oder stelle die Hitze klein und rühre die kalte Butter würfelweise ein, bis sie sich aufgelöst hat und die Sauce glänzend und leicht sämig ist. Die Butter bindet Flüssigkeit und Fett zu einer cremigen Emulsion. Kocht die Sauce dabei stark, kann sie sich trennen, also halte die Temperatur niedrig. Schmecke mit Salz und Pfeffer ab.","dauer":2,"tipp":"Kalte Butter bindet besser als weiche; immer nur ein Stück auf einmal einarbeiten."},{"titel":"Capellini kochen","aktion":"kochen","text":"Gib die Capellini in das kochende Salzwasser und drücke sie vorsichtig unter. Rühre gelegentlich um und koche sie drei bis fünf Minuten, bis sie bissfest sind. Capellini sind sehr dünn und garen schnell, deshalb starte die Pasta idealerweise, wenn die Garnelen schon in der Sauce sind. Hebe vor dem Abgießen eine Tasse Nudelwasser ab.","dauer":5,"tipp":"Das Nudelwasser macht die Sauce später bei Bedarf schön geschmeidig."},{"titel":"Alles verbinden und servieren","aktion":"mischen","text":"Gieße die Capellini ab und gib sie direkt in die Pfanne zu Sauce und Garnelen. Schwenke alles gut durch, bis jeder Faden von Sauce überzogen ist. Ist die Sauce zu dick, gib einen Schuss Nudelwasser dazu. Zupfe das Basilikum darüber und richte die Pasta in tiefen Schalen hoch auf. Reibe frisch Parmesan darüber und beträufle mit einem Löffel Olivenöl. Sofort essen.","dauer":3,"tipp":"Pasta in Sauce zu schwenken, statt sie daneben zu legen, ist der Unterschied zwischen gut und sehr gut."}],"profitipps":["Alle Zutaten vor dem Kochen bereitstellen: Dieses Gericht lässt keine Pausen.","Garnelen nur etwa eine Minute pro Seite garen, sonst werden sie zäh.","Kalte Butter erst am Ende und bei niedriger Hitze einrühren.","Die Nudeln erst starten, wenn die Garnelen in der Sauce liegen.","Das Nudelwasser aufheben, es löst eine zu dicke Sauce."],"varianten":["Mit Spaghetti statt Capellini.","Mit Petersilie und Parmesan statt Basilikum.","Ohne Pasta, nur mit Brot zum Dippen.","Mit Sahne statt Butter für eine reichere Sauce."],"beilagen":["Rucola-Salat","geröstetes Weißbrot"],"getraenk":"Trockener Weißwein wie Pinot Grigio oder Vermentino.","koeche":[{"name":"Gordon Ramsay","bezug":"Das Rezept stammt aus Ramsays Reihe Ramsay in 10 und ist auf seiner Webseite veröffentlicht: Garnelen werden direkt in der Weißwein-Zitronen-Sauce pochiert und mit kalter Butter gebunden.","quelle":"https://www.gordonramsay.com/gr/recipes/ramsay-in-10-shrimp-scampi-with-capellini-pasta/"}],"quellen":[{"titel":"Gordon Ramsay – Ramsay in 10: Shrimp Scampi with Capellini Pasta","url":"https://www.gordonramsay.com/gr/recipes/ramsay-in-10-shrimp-scampi-with-capellini-pasta/"},{"titel":"Gordon Ramsay – Seafood-Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/seafood"}],"bild":"nudeln","farben":["#f2c94c","#e07a5f","#8fbc8f"],"schlagworte":["Schnell","Pasta","Garnelen","Gordon Ramsay"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-hummer-ravioli-ramsay","name":"Hummer-Ravioli mit Safranteig und Zitronengras-Velouté nach Art von Gordon Ramsay","originalname":"Gordon Ramsay's lobster ravioli","kueche":"britisch-irisch","region":"England / Restaurantküche","beliebtheit":62,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Große, safrangelbe Ravioli, gefüllt mit Hummer, Langustine und Lachsfarce, dazu eine Velouté mit Zitronengras und Kerbel. Ein Gericht für besondere Anlässe, das sich gut vorbereiten lässt.","hintergrund":"Hummer-Ravioli sind eines der Gerichte, die man mit Ramsays Restaurantküche verbindet. Die Version, die Food and Travel Magazine veröffentlicht, nutzt einen Safran-Nudelteig und eine Füllung aus Lachs, Hummer und Langustinen, die durch ein Lachspüree gebunden wird. Dazu gibt es eine Velouté mit Zitronengras und Kerbel. In einer weiteren veröffentlichten Version wird der Hummerfond zum Pochieren genutzt. Dies ist eine Heimküchen-Fassung auf Basis dieser Veröffentlichungen, kein Originalrezept aus dem Restaurant.","portionen":4,"zeit":{"vorbereitung":90,"garen":45,"ruhen":60},"schwierigkeit":3,"themen":["fest"],"zutaten":[{"gruppe":"Für den Safran-Nudelteig","liste":[{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"große Prise, in 1 EL kochendem Wasser eingeweicht"},{"menge":250,"einheit":"g","name":"Pastamehl Tipo 00","hinweis":"ersatzweise Weizenmehl Type 405"},{"menge":0.25,"einheit":"TL","name":"feines Meersalz","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eier","hinweis":"Größe L"},{"menge":3,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":1,"einheit":"EL","name":"Olivenöl","hinweis":""}]},{"gruppe":"Für die Füllung","liste":[{"menge":150,"einheit":"g","name":"Lachsfilet ohne Haut","hinweis":"sehr frisch, ein Drittel davon wird püriert"},{"menge":30,"einheit":"ml","name":"Sahne","hinweis":"kalt"},{"menge":150,"einheit":"g","name":"Hummerfleisch","hinweis":"von Schwanz und Scheren, vorgegart; ersatzweise TK-Hummerschwanz"},{"menge":75,"einheit":"g","name":"Langustinenfleisch","hinweis":"oder gute Garnelen"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"ein Spritzer Saft"},{"menge":1,"einheit":"Handvoll","name":"gehackte Kräuter","hinweis":"Basilikum, Koriander und Kerbel"}]},{"gruppe":"Für die Zitronengras-Kerbel-Velouté","liste":[{"menge":0.5,"einheit":"Stück","name":"Schalotte","hinweis":"in Scheiben"},{"menge":0.25,"einheit":"TL","name":"weiße Pfefferkörner","hinweis":""},{"menge":0.25,"einheit":"TL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":"zerdrückt"},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":"klein"},{"menge":2,"einheit":"Zweig","name":"Thymian","hinweis":""},{"menge":1,"einheit":"Stange","name":"Zitronengras","hinweis":"längs halbiert und angedrückt"},{"menge":60,"einheit":"ml","name":"trockener Wermut","hinweis":"Noilly Prat oder ähnlich"},{"menge":125,"einheit":"ml","name":"Fischfond","hinweis":""},{"menge":125,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"Bund","name":"Kerbel","hinweis":"Blättchen gehackt, erst zum Schluss"}]},{"gruppe":"Zum Anrichten","liste":[{"menge":1,"einheit":"Stück","name":"Eigelb","hinweis":"mit Prise Salz und 1 TL Wasser verquirlt, als Kleber"},{"menge":100,"einheit":"ml","name":"reduzierter Krustentierfond","hinweis":"Hummer- oder Garnelenfond, eingekocht; aus dem Glas möglich"},{"menge":150,"einheit":"g","name":"Blattspinat","hinweis":"in Butter geschwenkt"},{"menge":null,"einheit":"","name":"Olivenöl, Basilikumblätter","hinweis":"zum Beträufeln und Garnieren"}]}],"ausruestung":["Nudelmaschine","Ausstecher 12 cm Durchmesser","Küchenmaschine oder Pürierstab","Pinsel","Schaumlöffel","Schüssel mit Eiswasser","feines Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Beginne mit dem Safran, der gibt dem Teig Farbe: Übergieße die Fäden mit einem Esslöffel kochendem Wasser und lasse sie fünf Minuten ziehen. Schneide alle Zutaten für die Füllung bereit: den Lachs in grobe Stücke, Hummer und Langustinen in 1 cm große Würfel. Stelle alles gekühlt beiseite. Bereite für die Velouté Schalotte, Gewürze und Zitronengras vor und lege Mehl, Eier und Eigelbe in Reichweite.","dauer":15,"tipp":"Je kälter die Füllung, desto leichter lässt sie sich formen."},{"titel":"Safranteig kneten","aktion":"kneten","text":"Gib Mehl, Salz, Eier, Eigelbe und Olivenöl in eine Küchenmaschine oder verknete alles per Hand, und füge den abgeseihten Safransud hinzu. Knete den Teig etwa zehn Minuten, bis er glatt, geschmeidig und federnd ist und sich nicht mehr klebrig anfühlt. Wickle ihn in Frischhaltefolie und lass ihn mindestens 30 Minuten bei Raumtemperatur ruhen. Das Gluten entspannt sich, und der Teig lässt sich später dünn ausrollen, ohne zu reißen.","dauer":40,"tipp":"Ist der Teig zu trocken, gib einen Teelöffel Wasser dazu, ist er zu feucht, ein wenig Mehl."},{"titel":"Velouté ansetzen","aktion":"koecheln","text":"Gib Schalotte, Pfefferkörner, Koriandersamen, Knoblauch, Lorbeer, Thymian und Zitronengras mit dem Wermut in einen kleinen Topf und lass alles köcheln, bis die Flüssigkeit auf einen sirupartigen Rest eingekocht ist. Gieße den Fischfond zu und reduziere ihn um die Hälfte. Rühre dann die Sahne ein und koche sie, bis die Sauce einen Löffel leicht überzieht. Passiere sie durch ein Sieb, würze mit Salz und halte sie warm. Den Kerbel gibst du erst kurz vor dem Servieren dazu, sonst verliert er sein Aroma.","dauer":25,"tipp":"Die Velouté kannst du vorbereiten und vor dem Servieren nur noch erwärmen."},{"titel":"Füllung herstellen","aktion":"puerieren","text":"Püriere ein Drittel des Lachses (etwa 50 g) mit Salz und Pfeffer in der Küchenmaschine zu einem festen, glatten Püree. Lass dann die kalte Sahne langsam einlaufen, bis die Masse geschmeidig ist, und stelle sie kalt. Würfle den restlichen Lachs sowie Hummer und Langustinen und vermenge alles mit gerade so viel Püree, dass die Stücke zusammenhalten. Schmecke mit Zitronensaft, Kräutern, Salz und Pfeffer ab. Stelle die Masse mindestens 20 Minuten kalt, bis sie fest ist, und forme dann vier Kugeln zu je etwa 80 g.","dauer":30,"tipp":"Die Farce kann einen Tag vorher gemacht werden."},{"titel":"Teig ausrollen und Ravioli formen","aktion":"ausrollen","text":"Rolle den Teig portionsweise mit der Nudelmaschine sehr dünn aus, bis du durchsehen kannst, und steche mit dem Ausstecher je Ravioli zwei Kreise von 12 cm aus. Setze auf einen Kreis jeweils eine Füllungskugel, bestreiche den Rand mit Eigelb-Mischung und lege den zweiten Kreis darüber. Drücke die Luft vorsichtig heraus und verschließe den Rand fest; beschneide ihn bei Bedarf mit einer Schere. Luft im Ravioli lässt sie beim Kochen platzen.","dauer":30,"tipp":"Decke die ungebrauchten Teigstücke mit einem feuchten Tuch ab, damit sie nicht austrocknen."},{"titel":"Ravioli vorgaren","aktion":"kochen","text":"Koche die Ravioli in reichlich siedendem Salzwasser drei bis vier Minuten, die Flüssigkeit soll nur sanft wallen. Hole sie mit dem Schaumlöffel heraus, schrecke sie sofort in Eiswasser ab und lege sie auf ein geöltes Tuch. Dieses Vorgaren erlaubt dir, das Gericht bis zum Servieren im Kühlschrank bereitzuhalten, so ist die Küche beim Anrichten ruhig.","dauer":10,"tipp":"Nicht zu viele Ravioli auf einmal kochen, sie dürfen sich nicht berühren."},{"titel":"Spinat und Fond vorbereiten","aktion":"braten","text":"Schwenke den Blattspinat in einer Pfanne mit etwas Butter, bis er gerade zusammenfällt, und würze mit Salz. Erwärme den reduzierten Krustentierfond in einem kleinen Topf, ohne ihn zu kochen. Rühre die gehackten Kerbelblätter in die warme Velouté. Wärme die Teller vor. Erst jetzt lohnt sich das Anrichten in Ruhe: Alle Komponenten sind warm, der Teller ist heiß, und nichts kann mehr anbrennen oder auskühlen.","dauer":5,"tipp":"Spinat gut ausdrücken, damit kein Wasser auf den Teller läuft."},{"titel":"Ravioli erwärmen und anrichten","aktion":"anrichten","text":"Erhitze die Ravioli etwa zwei bis drei Minuten in kochendem Wasser, nimm sie heraus und tupfe sie ab. Ziehe auf jeden Teller eine Spirale aus warmem Krustentierfond, lege einen Löffel Spinat in die Mitte und setze das Ravioli darauf. Beträufle es mit Olivenöl und garniere mit Basilikum. Serviere die Velouté dazu oder gieße sie am Tisch darüber.","dauer":10,"tipp":"Servierst du das Gericht als Hauptgericht, rechne zwei Ravioli pro Person."}],"profitipps":["Die Ravioli lassen sich vorkochen und kurz vor dem Servieren in heißem Wasser erwärmen.","Die Füllung gut kühlen: Kalte Farce bindet besser und lässt sich besser formen.","Luft aus den Ravioli drücken, sonst platzen sie im Wasser.","Kerbel erst zuletzt in die Velouté geben.","Statt eines ganzen Hummers genügen TK-Hummerschwänze aus dem Fachhandel."],"varianten":["Mit Garnelen statt Hummer und Langustinen.","Mit Hummerbisque als Sauce.","Als kleine Ravioli, die du in Hummerfond servierst.","Mit Krebsfleisch und Dill."],"beilagen":["Blattspinat","frisches Weißbrot"],"getraenk":"Chablis, Champagner oder Riesling Spätlese trocken.","koeche":[{"name":"Gordon Ramsay","bezug":"Food and Travel Magazine und MasterClass veröffentlichen Hummer-Ravioli unter Ramsays Namen mit Safranteig, Lachs-Hummer-Füllung und Velouté bzw. Hummerfond.","quelle":"https://foodandtravel.com/food/recipes/gordon-ramsays-lobster-ravioli"}],"quellen":[{"titel":"Food and Travel – Gordon Ramsay's lobster ravioli","url":"https://foodandtravel.com/food/recipes/gordon-ramsays-lobster-ravioli"},{"titel":"MasterClass – Gordon Ramsay's Famous Lobster Ravioli Recipe","url":"https://www.masterclass.com/articles/gordon-ramsays-famous-lobster-ravioli-recipe"}],"bild":"dumplings","farben":["#f4b942","#e8d9b5","#d9534f"],"schlagworte":["Festessen","Hummer","Gordon Ramsay","Pasta"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-cranachan","name":"Cranachan","kueche":"britisch-irisch","region":"Schottland","beliebtheit":60,"bild":"dessert","kurz":"Geröstete Haferflocken, Whisky-Sahne, Heidehonig und Himbeeren: das schottische Nationaldessert zum Löffeln.","hintergrund":"Cranachan ist ein schottisches Dessert, das ursprünglich als Erntefest nach der Himbeerernte im August gefeiert wurde. Es geht auf ein Frühstück aus Crowdie-Frischkäse, geröstetem Hafer, Rahm und Honig zurück, zu dem im Sommer Himbeeren kamen. Die frühen Versionen kamen ohne Whisky aus, moderne Rezepte verwenden ihn aber fast immer. Heute gibt es Cranachan das ganze Jahr, besonders gern zu festlichen Anlässen wie Burns Night, dem Fest zu Ehren des Dichters Robert Burns am 25. Januar.","portionen":4,"zeit":{"vorbereitung":20,"garen":10,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Hafer","liste":[{"menge":60,"einheit":"g","name":"grobe Haferflocken","hinweis":"kernige, nicht zarte; ideal: schottisches Pinhead Oatmeal"},{"menge":1,"einheit":"EL","name":"Butter","hinweis":""},{"menge":1,"einheit":"EL","name":"Honig","hinweis":""}]},{"gruppe":"Creme","liste":[{"menge":300,"einheit":"ml","name":"Schlagsahne","hinweis":"sehr kalt, mind. 30 % Fett"},{"menge":3,"einheit":"EL","name":"Heidehonig","hinweis":"ersatzweise ein kräftiger Waldhonig"},{"menge":4,"einheit":"EL","name":"Whisky","hinweis":"ca. 6 cl; Single Malt, mild, nicht rauchig"},{"menge":100,"einheit":"g","name":"Quark oder Frischkäse","hinweis":"optional für eine Crowdie-ähnliche Note"}]},{"gruppe":"Himbeeren","liste":[{"menge":300,"einheit":"g","name":"frische Himbeeren","hinweis":""},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Whisky","hinweis":"optional"}]}],"ausruestung":["beschichtete Pfanne","Schüssel und Handrührer","4 Gläser oder Schalen","Gabel zum Zerdrücken"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Stelle die Sahne, die Schüssel und die Rührbesen mindestens 20 Minuten kalt, damit die Sahne gut steif wird. Verlese die Himbeeren vorsichtig und lege sie auf Küchenpapier, aber wasche sie nur, wenn es wirklich nötig ist, weil sie sich vollsaugen und verwässern. Miss Honig und Whisky ab, sodass du später beim Rühren nichts suchen musst. Wähle Haferflocken mit Biss, denn zarte Haferflocken weichen in der Creme zu schnell durch.","dauer":10,"tipp":""},{"titel":"Hafer rösten","aktion":"anbraten","text":"Erhitze eine trockene Pfanne bei mittlerer Hitze und gib die Haferflocken hinein, ohne Fett. Rühre sie drei bis vier Minuten ständig um, bis sie nussig duften und leicht gebräunt sind. Gib Butter und einen Esslöffel Honig dazu, rühre eine weitere Minute, bis alles leicht karamellisiert und die Flocken klebrig glänzen. Nimm die Pfanne vom Herd und schütte den Hafer auf einen Teller, wo er auskühlt und dabei knusprig wird. Ein zu stark gebräunter Hafer wird bitter.","dauer":8,"tipp":"Das Rösten ist der Schlüssel: Es gibt dem Dessert Nussaroma und Biss."},{"titel":"Sahne aufschlagen","aktion":"aufschlagen","text":"Schlage die kalte Sahne mit dem Handrührer auf mittlerer Stufe, bis sie weiche, cremige Spitzen bildet. Sie soll sich locker wie eine Wolke anfühlen und nicht steif sein, denn Honig und Whisky machen sie beim Unterheben noch fester. Hör rechtzeitig auf: Sobald die Sahne matt statt glänzend aussieht, ist sie zu lange geschlagen und beginnt zu Butter zu werden. Rühre bei Verwendung von Quark diesen zuerst glatt und hebe die Sahne dann unter.","dauer":5,"tipp":""},{"titel":"Würzen","aktion":"mischen","text":"Gib den Heidehonig und den Whisky zur Sahne und hebe beides mit einem Teigschaber behutsam unter, bis die Creme gleichmäßig cremig aussieht. Koste sie: Der Whisky soll als warmes, leicht malziges Aroma durchscheinen, ohne zu dominieren. Passe Honig und Whisky nach Geschmack an. Zerdrücke die Hälfte der Himbeeren mit der Gabel und die restlichen lässt du ganz. Den Zucker und den Teelöffel Whisky untermischen, so entsteht ein saftiges, säuerliches Gegengewicht.","dauer":5,"tipp":"Nicht zu viel Whisky, sonst wird die Sahne instabil und zu scharf."},{"titel":"Schichten","aktion":"schichten","text":"Verteile eine Lage Himbeeren auf dem Boden der Gläser, darüber einen Löffel Creme und eine Handvoll Hafer. Wiederhole die Schichten, bis die Gläser gefüllt sind, und schließe mit Creme ab, auf die du zuletzt etwas Hafer und ein paar ganze Himbeeren streust. Achte darauf, dass du Hafer und Himbeeren sichtbar am Glasrand platzierst, so erkennt man die Schichten von außen. Stelle die Gläser für 30 Minuten in den Kühlschrank, damit sich die Aromen verbinden.","dauer":30,"tipp":"Den Hafer erst kurz vor dem Servieren obenauf, so bleibt er knusprig."},{"titel":"Servieren","aktion":"anrichten","text":"Hole die Gläser kurz vor dem Servieren aus dem Kühlschrank und garniere sie mit einem Teelöffel Honig und einem Minzblatt. Traditionell wird das Dessert in der Runde mit einem Tropfen Whisky am Tisch begossen. Bring die Gläser sofort an den Tisch, damit der Hafer seinen Biss behält. Gegessen wird mit dem Löffel von oben bis zum Boden, so mischen sich alle Schichten in jedem Bissen.","dauer":5,"tipp":""}],"profitipps":["Nur kernige Haferflocken verwenden – zarte weichen in Minuten durch.","Himbeeren erst kurz vorher waschen oder gar nicht, um Wasserbildung zu vermeiden.","Der Whisky sollte mild sein; ein stark rauchiger Islay-Whisky würde die Himbeere übertönen.","Heidehonig hat ein blumig-herbes Aroma, das original schottisch ist.","Für Alkoholfreies: Whisky durch Orangensaft und etwas Zitronenschale ersetzen."],"varianten":["Mit Brombeeren oder Erdbeeren statt Himbeeren","Mit Crowdie oder Quark für eine säuerliche Note","Mit Baiserstücken als Brücke zum Eton Mess","Als Parfait im Glas eingefroren"],"beilagen":["Shortbread","Heidelbeeren"],"getraenk":"Ein milder Highland-Single-Malt oder ein Glas Moscato","quellen":[{"titel":"Cranachan – Wikipedia","url":"https://en.wikipedia.org/wiki/Cranachan"}],"farben":["#c2415b","#f4e8d8","#b8864b"],"schlagworte":["Schottland","Burns Night","Whisky","Himbeeren"],"themen":["fest"],"originalname":"","fleischsorte":"","hauptkategorie":"suess","gang":"dessert","koeche":[],"vegetarisch_moeglich":true},{"id":"britisch-irisch-gefuellter-lammruecken-ramsay","name":"Gefüllter Lammrücken mit Spinat und Pinienkernen nach Art von Gordon Ramsay","originalname":"Stuffed Lamb with Spinach and Pine Nuts","kueche":"britisch-irisch","region":"England","beliebtheit":60,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Ein ausgelöster Lammsattel, gefüllt mit Spinat, Feta und Pinienkernen und mit Sumach gewürzt, dazu ein frischer Joghurt-Gurken-Dip mit Minze und Granatapfelsirup. Ein Festtagsbraten, den man auch kalt genießen kann.","hintergrund":"Lamm ist in Großbritannien ein klassischer Festtagsbraten. Ramsay veröffentlicht auf seiner Webseite eine Version, bei der ein ausgelöster Lammsattel mit einer Mischung aus Spinat, Feta und Pinienkernen gefüllt, gerollt und gebunden wird. Dazu serviert man einen Dip aus Joghurt, Gurke und Minze mit Granatapfelmelasse. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, mit meinen Erklärungen.","portionen":6,"zeit":{"vorbereitung":40,"garen":65,"ruhen":45},"schwierigkeit":2,"themen":["fest"],"zutaten":[{"gruppe":"Für Füllung und Lamm","liste":[{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"fein gehackt"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"in Scheiben"},{"menge":3,"einheit":"EL","name":"Pinienkerne","hinweis":""},{"menge":250,"einheit":"g","name":"junger Blattspinat","hinweis":"gewaschen"},{"menge":150,"einheit":"g","name":"Feta","hinweis":"zerbröckelt"},{"menge":1.9,"einheit":"kg","name":"Lammsattel, ausgelöst","hinweis":"im Ganzen, vom Metzger auslösen lassen (1,75–2 kg)"},{"menge":1.5,"einheit":"TL","name":"Sumach","hinweis":"1–2 TL nach Geschmack; im türkischen Laden oder Gewürzhandel"},{"menge":null,"einheit":"","name":"Olivenöl, Meersalz, schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Für den Joghurt-Dip","liste":[{"menge":0.5,"einheit":"Stück","name":"große Salatgurke","hinweis":"geschält, entkernt, in Scheiben oder dünnen Streifen"},{"menge":150,"einheit":"ml","name":"Naturjoghurt","hinweis":"mindestens 3,5 % Fett"},{"menge":1,"einheit":"Bund","name":"Minze","hinweis":"klein, in Streifen"},{"menge":1,"einheit":"EL","name":"Granatapfelsirup","hinweis":"nach Geschmack"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone und etwas Limettensaft","hinweis":"Schale der Zitrone, ein Spritzer Limette"}]}],"ausruestung":["Bräter oder Bratform für den Herd","Küchengarn","Fleischthermometer","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Bestelle den Lammsattel rechtzeitig beim Metzger und lass ihn auslösen, also so aufschneiden, dass du ihn flach ausbreiten kannst. Die Innenfilets bleiben daran. Hacke die Zwiebel, schneide den Knoblauch in Scheiben, wasche den Spinat gründlich und zerbröckle den Feta. Lege Garn zum Binden und ein Brett bereit und nimm das Fleisch etwa 30 Minuten vorher aus dem Kühlschrank.","dauer":20,"tipp":"Frage deinen Metzger auch nach den Knochen für eine Sauce."},{"titel":"Füllung vorgaren","aktion":"braten","text":"Schwitze Zwiebel und Knoblauch in einem Schuss Olivenöl bei mittelhoher Hitze etwa fünf Minuten an, bis sie weich und duftend sind. Würze mit Salz und Pfeffer, gib die Pinienkerne hinzu und röste sie etwa eine Minute, bis sie goldgelb sind. Gib den Spinat dazu und lass ihn kurz zusammenfallen. Nimm die Pfanne vom Herd und rühre den Feta unter. Die Füllung soll abkühlen, bevor sie ins Fleisch kommt.","dauer":10,"tipp":"Roher Zwiebel und Knoblauch würden im Fleisch zu lange brauchen, daher schwitzt du sie vor."},{"titel":"Lamm füllen","aktion":"fuellen","text":"Breite den Lammsattel mit der Fleischseite nach oben auf einem Brett aus, würze ihn mit Salz, Pfeffer und Sumach und verteile die erkaltete Füllung in einem Streifen in der Mitte. Die Innenfilets nutzt du als Stütze an den Seiten. Gib an den Rändern etwas mehr Füllung, denn beim Rollen drückt sich ein Teil heraus.","dauer":10,"tipp":"Nicht zu viel Füllung, sonst lässt sich das Fleisch nicht mehr schließen."},{"titel":"Rollen und binden","aktion":"rollen","text":"Rolle das Fleisch von der langen Seite her fest um die Füllung zusammen und binde es in Abständen von etwa 3 cm mit Küchengarn. Das Garn soll das Fleisch halten, aber nicht zusammenquetschen. Würze die Außenseite mit Salz und Pfeffer und stelle das Lamm mindestens 30 Minuten oder über Nacht in den Kühlschrank. So festigt sich die Form, und das Fleisch bräunt später besser.","dauer":35,"tipp":"Eine Schlinge pro Hand-Breite hält die Form, ohne dass sich Wülste bilden."},{"titel":"Ofen vorheizen und anbraten","aktion":"anbraten","text":"Heize den Ofen auf 190 °C Ober-/Unterhitze vor, bei Umluft auf 170 °C. Erhitze den Bräter auf dem Herd, gib etwas Öl hinein und brate das Lamm etwa 10 Minuten rundum an. Es soll eine gleichmäßig tiefbraune Kruste bekommen, die kräftig duftet. Wende es erst, wenn es sich leicht lösen lässt. Das Anbraten bringt den Röstgeschmack, den der Ofen allein nicht liefert; die Kruste schützt außerdem den Saft im Fleisch.","dauer":12,"tipp":"Bei zu viel Rauch die Hitze reduzieren, denn verbranntes Fett schmeckt bitter."},{"titel":"Im Ofen rosa braten","aktion":"braten","text":"Schiebe den Bräter in den Ofen und brate das Lamm 45 bis 55 Minuten, je nach Gewicht und gewünschtem Gargrad. Als Orientierung zeigt ein Kernthermometer für rosa etwa 56 bis 58 °C, bevor du das Fleisch herausnimmst. Es gart beim Ruhen noch einige Grad nach. Prüfe lieber früher, denn Lamm wird bei Überhitzung trocken und grau.","dauer":50,"tipp":"Das Thermometer in die Mitte des Fleischs, nicht in die Füllung stecken."},{"titel":"Dip anrühren","aktion":"mischen","text":"Während das Lamm im Ofen ist, verrührst du den Joghurt mit der Gurke, der Minze, dem Granatapfelsirup, der Zitronenschale und einem Spritzer Limettensaft. Würze leicht mit Salz und Pfeffer und probiere: Er soll frisch, leicht säuerlich und ein wenig süß sein. Stelle ihn kühl, bis du ihn servierst. Der Dip passt zu warmem wie zu kaltem Lamm, denn Joghurt und Minze bringen Frische gegen das kräftige Fleisch.","dauer":10,"tipp":"Gurke vorher leicht salzen und abtropfen lassen, damit der Dip nicht wässrig wird."},{"titel":"Ruhen, aufschneiden und servieren","aktion":"ruhen","text":"Nimm das Lamm aus dem Ofen und lass es mindestens 30 Minuten ruhen, locker mit Folie bedeckt. Die Säfte verteilen sich, das Fleisch wird zarter und lässt sich sauber schneiden. Entferne das Garn und schneide das Lamm in dicke Scheiben. Serviere es warm oder bei Raumtemperatur mit dem Dip. Als Beilage passen Ofenkartoffeln oder Couscous.","dauer":30,"tipp":"Schneide mit einem langen Messer und in einem Zug, so bleibt die Füllung an Ort und Stelle."}],"profitipps":["Die Füllung vorgaren und abkühlen lassen, sonst gart sie im Fleisch nicht richtig und erwärmt es von innen.","Gerolltes Lamm vor dem Braten kühlen, es hält die Form besser.","Mit Thermometer garen, denn Garzeit hängt vom Gewicht ab.","Mindestens 30 Minuten ruhen lassen, bevor du aufschneidest.","Das Lamm schmeckt auch kalt als Aufschnitt."],"varianten":["Mit getrockneten Aprikosen in der Füllung.","Mit Ziegenkäse statt Feta.","Mit Pistazien statt Pinienkernen.","Als kleine Lammkeule für weniger Personen."],"beilagen":["Ofenkartoffeln","Couscous mit Kräutern","grüne Bohnen"],"getraenk":"Kräftiger Rotwein wie Syrah oder Rioja.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diesen gefüllten Lammsattel mit Spinat, Feta, Pinienkernen und Sumach auf seiner Webseite, dazu einen Joghurt-Minz-Dip.","quelle":"https://www.gordonramsay.com/gr/recipes/stuffed-lamb-with-spinach-and-pine-nuts/"}],"quellen":[{"titel":"Gordon Ramsay – Stuffed Lamb with Spinach and Pine Nuts","url":"https://www.gordonramsay.com/gr/recipes/stuffed-lamb-with-spinach-and-pine-nuts/"},{"titel":"Gordon Ramsay – Rezeptübersicht","url":"https://www.gordonramsay.com/gr/recipes/"}],"bild":"braten-scheiben","farben":["#8b4a2b","#6b8e23","#f3e9d2"],"schlagworte":["Festtagsbraten","Lamm","Gordon Ramsay","Ostern"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-pilz-toast-ei-gruyere-ramsay","name":"Cremiger Pilz-Toast mit weichem Ei und Gruyère nach Art von Gordon Ramsay","originalname":"Creamy Mushroom Toast with Soft Egg & Gruyère","kueche":"britisch-irisch","region":"England","beliebtheit":60,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"fruehstueck","kurz":"Knuspriges Brot, darauf goldbraun gebratene Pilze in einer cremigen Sauce aus Crème fraîche, ein Rucola-Salat, ein weiches pochiertes Ei und Gruyère-Späne. Frühstück, Brunch oder leichtes Abendessen.","hintergrund":"Pilze auf Toast gehören zur britischen Frühstückskultur. Ramsay macht daraus auf seiner Webseite ein Gericht, das nach Restaurant schmeckt: Die Pilze werden in Butter kräftig gebraten und mit Schalotte, Sherryessig und Crème fraîche abgeschmeckt. Das weiche Ei und der Gruyère machen das Ganze reichhaltig. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept; die Webseite nennt weder Portionszahl noch Eier-Garzeit, daher stammen diese Angaben von mir.","portionen":2,"zeit":{"vorbereitung":10,"garen":20,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Pilze","liste":[{"menge":30,"einheit":"g","name":"Butter","hinweis":"2 EL; bei mehreren Portionen etwas mehr zum Nachgeben"},{"menge":1,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":225,"einheit":"g","name":"Pilze","hinweis":"Champignons, Kräuterseitlinge oder Waldpilze, geputzt und in gleichmäßige Stücke geschnitten"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"angedrückt, mit Schale"},{"menge":3,"einheit":"Zweig","name":"Thymian","hinweis":"große Zweige"},{"menge":2,"einheit":"EL","name":"Schalotte, fein gehackt","hinweis":"etwa eine halbe Schalotte"},{"menge":1,"einheit":"TL","name":"Sherryessig","hinweis":"Spritzer nach Geschmack"},{"menge":3,"einheit":"EL","name":"Crème fraîche","hinweis":""},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"Scheibe","name":"dicke Sauerteig- oder Landbrotscheiben","hinweis":"in Butter in der Pfanne geröstet"},{"menge":1,"einheit":"Handvoll","name":"Rucola","hinweis":"mit Olivenöl, Zitronensaft und Salz angemacht"},{"menge":2,"einheit":"Stück","name":"Eier","hinweis":"weich pochiert, sehr frisch"},{"menge":30,"einheit":"g","name":"Gruyère","hinweis":"in Spänen gehobelt"},{"menge":null,"einheit":"","name":"Meersalzflocken","hinweis":"für die Eier"}]}],"ausruestung":["große Pfanne","kleiner Topf zum Pochieren","Schaumlöffel","Käsehobel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Putze die Pilze mit einem feuchten Tuch oder einer Bürste statt sie zu waschen, denn Wasser macht sie schwammig und verhindert das Anbraten. Schneide sie in gleichmäßige Stücke, damit sie gleichzeitig Farbe nehmen. Würfle die Schalotte fein, drücke den Knoblauch an, schneide Brot und Käse und mache die Eier und das Dressing bereit. Stelle einen Topf mit Wasser für die Eier auf.","dauer":10,"tipp":"Frische Eier lassen sich besser pochieren, denn ihr Eiweiß ist fester."},{"titel":"Pilze goldbraun braten","aktion":"anbraten","text":"Erhitze die Butter mit einem Schuss Olivenöl in einer großen Pfanne bei mittelhoher Hitze und brate die Pilze mit Knoblauch und Thymian darin an. Wende sie gelegentlich und brate sie, bis sie leicht gebräunt und weich sind und ihr Wasser verdampft ist, das dauert etwa fünf bis acht Minuten. Arbeite in Portionen, wenn die Pfanne voll ist, denn zu viele Pilze dämpfen statt zu bräunen. Gib bei Bedarf etwas Butter nach.","dauer":8,"tipp":"Salze die Pilze erst am Ende, sonst ziehen sie Wasser und werden zäh."},{"titel":"Schalotte und Sauce","aktion":"braten","text":"Gib die Schalotte zu den Pilzen, würze mit Salz und Pfeffer und brate alles ein bis zwei Minuten, bis die Schalotte weich ist und duftet. Entferne Knoblauch und Thymian. Gib einen Spritzer Sherryessig dazu, er löst den Bratensatz und bringt Frische, und rühre die Crème fraîche ein. Lass es bei reduzierter Hitze kurz köcheln, bis die Sauce cremig bindet.","dauer":4,"tipp":"Der Essig soll nur einen feinen Säurekick geben, nicht dominieren."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Pilzmischung und schmecke mit Salz, Pfeffer und einem Hauch Essig nach. Nimm die Pfanne vom Herd, damit die Sauce nicht weiter einkocht, und halte sie warm. Die Pilze sollen saftig, cremig und herzhaft schmecken, ohne dass die Sahne dominiert. Gelingt die Sauce, glänzen die Pilze leicht und ein Löffel davon bleibt am Rücken des Löffels haften, ohne zu laufen. Ist sie zu dünn, lass sie eine Minute länger köcheln.","dauer":1,"tipp":"Ein Hauch Muskat passt ebenfalls gut zu Pilzen und Sahne."},{"titel":"Eier pochieren","aktion":"kochen","text":"Lass das Wasser knapp unter dem Siedepunkt sprudeln und gib einen kleinen Schuss Essig hinein. Gib jedes Ei vorsichtig aus einer Tasse hinein und lass es etwa drei Minuten ziehen, bis das Eiweiß fest ist und das Eigelb noch flüssig bleibt. Hebe die Eier mit dem Schaumlöffel heraus und tupfe sie auf Küchenpapier ab. Würze sie mit Salzflocken und Pfeffer.","dauer":5,"tipp":"Strudle das Wasser vorher mit einem Löffel, das Eiweiß legt sich dann sauber um das Eigelb."},{"titel":"Brot rösten","aktion":"braten","text":"Röste die Brotscheiben in einer Pfanne mit etwas Butter bei mittlerer Hitze von beiden Seiten goldbraun und knusprig. Das Brot duftet nach Butter und Nuss. Mache den Rucola mit Olivenöl, Zitronensaft und einer Prise Salz an, so schmeckt er frisch und kontrastiert die reiche Pilzsauce. Gut geröstet ist es, wenn es beim Klopfen auf die Kruste hohl klingt und die Ränder dunkelgolden sind.","dauer":4,"tipp":"Eine Pfanne mit Rillen gibt dem Brot zusätzlich Biss."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege das Brot auf warme Teller und verteile die Pilze samt Sauce darauf. Häufe den Rucola darüber, setze die pochierten Eier obenauf und hobele den Gruyère darüber. Serviere sofort, damit das Brot knusprig bleibt und das Ei warm ist. Beim Anstechen läuft der Dotter in die Pilzsauce. Probiere einen Bissen mit allem zusammen: Wenn die Säure fehlt, hilft ein Spritzer Zitrone auf den Rucola.","dauer":3,"tipp":"Ein Hauch frisch gemahlener Pfeffer zum Schluss vollendet das Gericht."}],"profitipps":["Pilze nicht waschen, sondern nur abbürsten.","Nicht zu viele Pilze auf einmal braten, sonst dämpfen sie.","Salz erst am Ende zugeben.","Ein Spritzer Sherryessig bringt Säure in die cremige Sauce.","Das Ei darf noch weich sein: Sein Dotter ist die zweite Sauce."],"varianten":["Mit Spiegelei statt pochiertem Ei.","Mit Parmesan oder Bergkäse statt Gruyère.","Mit gemischten Wildpilzen im Herbst.","Vegan mit Hafersahne und ohne Ei."],"beilagen":["grüner Salat","Tomatensalat"],"getraenk":"Kaffee, Tee oder ein Glas Weißwein zum Brunch.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diesen Pilz-Toast auf seiner Webseite: gebratene Pilze mit Crème fraîche und Sherryessig auf Toast, mit Rucola, weichem Ei und Gruyère.","quelle":"https://www.gordonramsay.com/gr/recipes/mushroomtoast/"}],"quellen":[{"titel":"Gordon Ramsay – Creamy Mushroom Toast with Soft Egg & Gruyère","url":"https://www.gordonramsay.com/gr/recipes/mushroomtoast/"},{"titel":"Gordon Ramsay – Vegetarische Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/vegetarian"}],"bild":"sandwich","farben":["#a67c52","#f0d9a8","#6b8e23"],"schlagworte":["Brunch","Pilze","Gordon Ramsay","Vegetarisch"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-schoko-tartelettes-erdnusskrokant-ramsay","name":"Mini-Schokoladentartelettes mit Erdnusskrokant nach Art von Gordon Ramsay","originalname":"Indulgent Mini Chocolate Tarts With Peanut Brittle","kueche":"britisch-irisch","region":"England","beliebtheit":58,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Knusprige Mürbeteig-Förmchen mit dunkler Schokoladen-Ganache und splittrigem, salzigem Erdnusskrokant. Süß, bitter, salzig und knusprig in einem Bissen.","hintergrund":"Schokoladentarte mit Karamell- oder Nusskrokant gehört zu den Desserts, die auf britischen Tafeln gern als Abschluss eines Festessens stehen. Ramsay veröffentlicht auf seiner Webseite eine Version aus zehn kleinen Tartelettes mit dünnem Mürbeteig, einer festen Ganache und selbst gemachtem Erdnusskrokant. Die Förmchen werden vor dem Backen so lange gekühlt, bis sie ganz fest sind, damit man ohne Blindbacken auskommt. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, mit meinen Erklärungen.","portionen":10,"zeit":{"vorbereitung":45,"garen":35,"ruhen":80},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Mürbeteig","liste":[{"menge":125,"einheit":"g","name":"kalte Butter","hinweis":"in Würfeln"},{"menge":90,"einheit":"g","name":"feiner Zucker","hinweis":"Kristallzucker"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"},{"menge":250,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus etwas für die Arbeitsfläche"},{"menge":1,"einheit":"EL","name":"kaltes Wasser","hinweis":"nur falls der Teig zu trocken ist"},{"menge":null,"einheit":"","name":"Öl oder Butter","hinweis":"zum Einfetten der Förmchen"}]},{"gruppe":"Für den Erdnusskrokant","liste":[{"menge":150,"einheit":"g","name":"feiner Zucker","hinweis":""},{"menge":100,"einheit":"g","name":"gesalzene Erdnüsse","hinweis":"grob gehackt"}]},{"gruppe":"Für die Schokoladen-Ganache","liste":[{"menge":400,"einheit":"g","name":"Zartbitterschokolade","hinweis":"mindestens 60 % Kakao, grob gehackt"},{"menge":8,"einheit":"EL","name":"Sahne","hinweis":"mindestens 30 % Fett, etwa 120 ml"},{"menge":60,"einheit":"g","name":"Butter","hinweis":"in Würfeln"},{"menge":2,"einheit":"EL","name":"feiner Zucker","hinweis":"optional, falls du es süßer magst"}]}],"ausruestung":["10 kleine Tarteletteförmchen (8 cm) mit Hebeboden","Ausstecher oder Glas (11 cm)","Küchenmaschine","Backblech mit Backpapier","beschichtete Pfanne","Wasserbad oder hitzebeständige Schüssel mit Topf"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Stelle alle Zutaten bereit und wiege sie genau ab, denn Mürbeteig und Karamell vertragen keine Experimente. Schneide die kalte Butter in kleine Würfel, hacke die Erdnüsse grob und brich die Schokolade in kleine Stücke, damit sie später gleichmäßig schmilzt. Fette die Förmchen leicht ein und lege ein Backblech mit Backpapier aus. Die Butter muss sehr kalt sein, sonst wird der Teig fettig und schwer zu verarbeiten.","dauer":15,"tipp":"Kalte Zutaten und kühle Hände sind das Geheimnis eines knusprigen Mürbeteigs."},{"titel":"Mürbeteig herstellen","aktion":"kneten","text":"Verarbeite Butter und Zucker in der Küchenmaschine kurz, bis sie nur gerade verbunden sind. Gib das Ei dazu und verarbeite es etwa 30 Sekunden. Füge das Mehl hinzu und pulsiere nur kurz, bis der Teig zusammenkommt. Knete ihn auf einer bemehlten Fläche ein- bis zweimal, forme eine flache Scheibe, wickle sie in Folie und kühle sie 30 Minuten. Zu langes Kneten entwickelt Gluten, und der Teig wird zäh. Ist er zu trocken, gib einen Esslöffel kaltes Wasser dazu.","dauer":40,"tipp":"Eine flache Scheibe kühlt schneller und lässt sich leichter ausrollen als eine Kugel."},{"titel":"Förmchen auslegen","aktion":"ausrollen","text":"Heize den Ofen auf 190 °C Ober-/Unterhitze vor, bei Umluft auf 170 °C. Rolle den Teig auf einer bemehlten Fläche sehr dünn aus, etwa 2 mm, und steche zehn Kreise von 11 cm aus. Lege die Förmchen damit aus, drücke den Teig in die Ecken und lass den Rand überstehen. Steche den Boden mit einer Gabel mehrfach ein und stelle die Förmchen 20 Minuten kühl, bis der Teig richtig fest ist. Der kalte Teig zieht sich beim Backen weniger zusammen.","dauer":30,"tipp":"Reste kannst du zusammenkneten, kühlen und noch einmal ausrollen."},{"titel":"Tartelettes backen","aktion":"backen","text":"Backe die gekühlten Teighüllen auf dem Blech 12 Minuten im Ofen, bis sie goldgelb sind. Der Teig duftet nach Butter und Keks. Schneide den überstehenden Rand mit einem scharfen Messer ab und lass die Förmchen in den Formen auf einem Gitter auskühlen. Erst wenn sie ganz kalt sind, lassen sie sich ohne Bruch aus der Form lösen. Sie müssen vollständig durchgebacken sein, damit sie die Ganache tragen.","dauer":25,"tipp":"Wenn sich der Teig beim Backen aufbläht, drücke ihn nach der ersten Minute mit einem Löffel zurück."},{"titel":"Erdnusskrokant kochen","aktion":"kochen","text":"Lege ein Blech mit Backpapier oder geöltem Alufolie aus. Erhitze den Zucker in einer trockenen Pfanne bei mittelhoher Hitze drei bis vier Minuten, ohne zu rühren, bis er zu schmelzen beginnt. Schwenke die Pfanne vorsichtig, sobald sich Karamell bildet, und warte weitere zwei bis drei Minuten, bis der Zucker hellbraun ist und karamellig riecht. Gib die Erdnüsse hinzu, schwenke sie durch und gieße die Masse sofort auf das Blech. Streiche sie dünn aus; sie wird fast sofort hart.","dauer":15,"tipp":"Vorsicht: Karamell ist über 150 °C heiß und haftet auf der Haut. Nie mit den Fingern berühren."},{"titel":"Krokant abkühlen lassen","aktion":"kuehlen","text":"Lass den Krokant etwa zehn Minuten abkühlen, bis er vollständig hart ist und beim Antippen klingt. Zerbrich ihn dann in unregelmäßige Splitter. Bewahre die Stücke bis zum Servieren trocken auf, denn Feuchtigkeit macht Krokant klebrig. Alles, was du nicht brauchst, hält sich in einer Dose mehrere Tage.","dauer":10,"tipp":"Klebrige Reste in der Pfanne löst du mit heißem Wasser."},{"titel":"Ganache zubereiten","aktion":"kochen","text":"Gib Schokolade, Sahne, Butter und nach Wunsch den Zucker in eine hitzebeständige Schüssel und setze sie auf einen Topf mit sanft simmerndem Wasser. Die Schüssel darf das Wasser nicht berühren. Rühre die Masse sieben bis acht Minuten, bis sie glatt und glänzend ist. Probiere und füge nach Geschmack mehr Zucker hinzu. Wird die Ganache körnig oder fettig, hilft ein Löffel warme Sahne beim Wiederverbinden.","dauer":10,"tipp":"Rühre in der Mitte mit kleinen Kreisen, so entsteht eine stabile Emulsion."},{"titel":"Füllen und kühlen","aktion":"fuellen","text":"Löffle die warme Ganache in die ausgekühlten Teigförmchen und streiche sie glatt. Stelle sie 20 Minuten in den Kühlschrank, bis die Ganache fest, aber noch weich zum Anschnitt ist. Löse die Tartelettes vorsichtig aus den Förmchen. Eine Messerspitze am Rand und ein sanfter Druck von unten helfen dabei.","dauer":25,"tipp":"Nimm sie 10 Minuten vor dem Servieren aus dem Kühlschrank, dann schmeckt die Schokolade intensiver."},{"titel":"Anrichten","aktion":"garnieren","text":"Setze auf jede Tarte einen oder zwei Krokantsplitter und serviere sie mit etwas Crème fraîche oder Schlagsahne. Probiere einen Bissen: Es sollte knackig, bitter-süß und leicht salzig sein. Fehlt dir Süße, hilft Sahne; ist es dir zu schwer, serviere frische Beeren dazu. Die Tartelettes halten sich im Kühlschrank mehrere Tage, der Krokant kommt aber erst kurz vor dem Servieren darauf.","dauer":5,"tipp":"Ein paar Flocken Meersalz auf der Ganache machen sie noch aromatischer."}],"profitipps":["Die Teigförmchen vor dem Backen richtig durchkühlen, dann brauchst du kein Blindbacken.","Den Mürbeteig nicht zu lange kneten, sonst wird er zäh.","Den Karamell nie anfassen und den Krokant zügig ausgießen.","Die Ganache nur sanft erwärmen, zu heiße Schokolade wird körnig.","Krokant erst kurz vor dem Servieren auflegen."],"varianten":["Mit Haselnuss- oder Mandelkrokant.","Mit Orangenabrieb in der Ganache.","Mit Salzkaramell statt Krokant.","Als eine große Tarte in der 24-cm-Form."],"beilagen":["Crème fraîche","frische Himbeeren","Vanilleeis"],"getraenk":"Espresso, Portwein oder ein kräftiger Rotwein.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diese Mini-Schokoladentartelettes mit Erdnusskrokant auf seiner Webseite, mit Mürbeteig, der vor dem Backen gekühlt wird, und Ganache über dem Wasserbad.","quelle":"https://www.gordonramsay.com/gr/recipes/indulgent-mini-chocolate-tarts-with-peanut-brittle/"}],"quellen":[{"titel":"Gordon Ramsay – Indulgent Mini Chocolate Tarts With Peanut Brittle","url":"https://www.gordonramsay.com/gr/recipes/indulgent-mini-chocolate-tarts-with-peanut-brittle/"},{"titel":"Gordon Ramsay – Chocolate Recipes","url":"https://www.gordonramsay.com/gr/recipes/category/chocolate"}],"bild":"torte","farben":["#3b1f14","#8b5a2b","#e6c27a"],"schlagworte":["Dessert","Schokolade","Tartelette","Gordon Ramsay"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-mini-apfel-galettes-ramsay","name":"Mini-Apfel-Galettes mit Gewürzen nach Art von Gordon Ramsay","originalname":"Mini Apple Galettes","kueche":"britisch-irisch","region":"England (Ramsays Version eines französischen Klassikers)","beliebtheit":55,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Rustikale Mini-Tartes mit Zimt-Mürbeteig, dünn geschnittenen Äpfeln, Orange und Kardamom. Der Rand wird einfach nach innen gefaltet, die Optik darf gern ungleichmäßig sein.","hintergrund":"Die Galette ist eine freie, ungeformte Tarte, bei der der Teig einfach um die Füllung geschlagen wird. Ramsay veröffentlicht auf seiner Webseite eine Mini-Variante: Der Zimt-Mürbeteig wird mit Eiswasser gebunden, die Äpfel kommen mit Zucker, Zimt, Kardamom, Nelke und Orangenschale auf den Teig. Zum Schluss gibt es Eigelb-Sahne-Glasur und groben Zucker. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, mit meinen Erklärungen. Ramsay gibt dort keine Portionsangabe; die Menge reicht für vier kleine Galettes.","portionen":4,"zeit":{"vorbereitung":40,"garen":35,"ruhen":40},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Mürbeteig","liste":[{"menge":225,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus etwas zum Bestäuben"},{"menge":2,"einheit":"EL","name":"Puderzucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":"gemahlen"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":170,"einheit":"g","name":"kalte Butter","hinweis":"in kleine Würfel geschnitten"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"verquirlt"},{"menge":null,"einheit":"","name":"Eiswasser","hinweis":"esslöffelweise, nach Bedarf"}]},{"gruppe":"Für die Füllung","liste":[{"menge":450,"einheit":"g","name":"feste Äpfel","hinweis":"Granny Smith oder Pink Lady, dünn aufgeschnitten, nach Wunsch geschält"},{"menge":50,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":"gemahlen"},{"menge":0.5,"einheit":"TL","name":"Kardamom","hinweis":"gemahlen"},{"menge":0.25,"einheit":"TL","name":"Gewürznelken","hinweis":"gemahlen"},{"menge":1,"einheit":"Stück","name":"Bio-Orange","hinweis":"nur die abgeriebene Schale"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Vanilleextrakt","hinweis":""}]},{"gruppe":"Zum Bestreichen","liste":[{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"für die Glasur"},{"menge":1,"einheit":"EL","name":"Sahne","hinweis":""},{"menge":null,"einheit":"","name":"grober brauner Zucker","hinweis":"Demerara oder Rohrzucker zum Bestreuen"}]}],"ausruestung":["Schüssel","Teigrolle","Backbleche mit Backpapier","großer Teller oder Schüssel (ca. 16 cm) als Schablone","Pinsel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und schneide die Butter in kleine Würfel, die sofort wieder in den Kühlschrank wandern, damit sie kalt bleiben. Wasche die Äpfel, entferne das Kerngehäuse und schneide sie in dünne Scheiben von etwa 3 mm. Je dünner die Scheiben, desto besser garen sie in der kurzen Backzeit. Lege zwei Bleche mit Backpapier aus und heize den Ofen auf 190 °C Ober-/Unterhitze vor, bei Umluft auf 170 °C.","dauer":15,"tipp":"Mit einem Gemüsehobel gelingen gleichmäßig dünne Apfelscheiben."},{"titel":"Teig herstellen","aktion":"kneten","text":"Vermische Mehl, Puderzucker, Zimt und Salz in einer großen Schüssel. Verreibe die kalte Butter mit den Fingerspitzen im Mehl, bis kleine Stückchen von der Größe von Erbsen übrig bleiben. Rühre das Ei unter, gib esslöffelweise Eiswasser dazu und rühre, bis sich ein Teig mit einigen losen Krümeln bildet. Knete ihn leicht, teile ihn in zwei Kugeln und wickle sie ein. Kühle sie mindestens 30 Minuten im Kühlschrank.","dauer":40,"tipp":"Je weniger du den Teig anfasst, desto zarter wird er; die Hände sind warm."},{"titel":"Teigkreise ausrollen und ausschneiden","aktion":"ausrollen","text":"Rolle jede Teigkugel auf einer bemehlten Fläche oval aus, etwa 20 × 40 cm und 3 bis 5 mm dick. Lege einen umgedrehten Teller oder eine Schüssel mit etwa 16 cm Durchmesser darauf und schneide vier Kreise mit einem kleinen scharfen Messer aus. Verwerfe die Reste oder verwende sie für Kekse. Lege die Kreise auf die Bleche und kühle sie mindestens 10 Minuten, damit der Teig fest bleibt.","dauer":15,"tipp":"Rolle auf einem bemehlten Backpapier, so kannst du die Teigkreise samt Papier aufs Blech ziehen."},{"titel":"Äpfel würzen","aktion":"mischen","text":"Mische die Apfelscheiben in einer großen Schüssel mit Zucker, Zimt, Kardamom, Nelkenpulver und der abgeriebenen Orangenschale. Gib den Zitronensaft und die Vanille dazu und wende alles vorsichtig, bis jede Scheibe überzogen ist. Es duftet schon jetzt nach Weihnachtsbäckerei. Lass die Äpfel nicht zu lange stehen, damit sie nicht zu viel Saft ziehen.","dauer":5,"tipp":"Der Zitronensaft verhindert, dass die Äpfel braun werden und gibt Frische."},{"titel":"Galettes füllen und falten","aktion":"formen","text":"Schlage das Ei mit der Sahne verquirlt als Glasur an. Lege auf jeden Teigkreis ein Viertel der Äpfel in einem hübschen, überlappenden Muster und lass rundherum einen Rand von etwa 4 cm frei. Schlage diesen Rand über die Äpfel und drücke ihn alle paar Zentimeter zu einer Falte zusammen. Der Rand muss die Füllung eng umschließen, sonst läuft der Saft aus.","dauer":10,"tipp":"Kleine Risse im Teig kannst du mit einem Tropfen Wasser und dem Finger verschließen."},{"titel":"Bestreichen und bestreuen","aktion":"garnieren","text":"Bestreiche den gefalteten Rand mit der Eiglasur und bestreue ihn großzügig mit grobem braunem Zucker. Der Zucker karamellisiert beim Backen und gibt dem Rand Knusprigkeit und Glanz. Achte darauf, nicht zu viel Glasur auf die Äpfel zu geben, sonst tropft sie ab. Streue den Zucker am besten aus der Höhe, dann verteilt er sich gleichmäßiger und bleibt nicht auf den Äpfeln liegen, wo er nur verbrennen würde.","dauer":5,"tipp":"Wer mag, streut noch ein paar Mandelblättchen über die Äpfel."},{"titel":"Goldbraun backen","aktion":"backen","text":"Backe die Galettes 30 bis 35 Minuten auf der mittleren Schiene, bis der Teig goldbraun ist und die Äpfel weich sind. Du erkennst es an den leicht gebräunten Apfelkanten und am Zuckerrand, der nach Karamell duftet. Dreht sich ein Blech nicht gleichmäßig, drehe es nach der Hälfte der Zeit. Lass sie zehn Minuten ruhen, bevor du sie servierst, damit die Füllung fest werden kann.","dauer":35,"tipp":"Auf einem heißen Blech garen sie schneller; stelle das Blech beim Vorheizen in den Ofen."},{"titel":"Servieren","aktion":"anrichten","text":"Serviere die Galettes lauwarm mit einer Kugel Vanilleeis, Schlagsahne oder einer Karamellsauce. Der Kontrast aus warmem, knusprigem Teig und kalter Creme ist ein Hochgenuss. Reste halten sich bis zum nächsten Tag und lassen sich im Ofen bei 160 °C in zehn Minuten wieder knusprig machen. Prüfe vor dem Servieren noch einmal den Boden: Er soll goldbraun und fest sein, nicht blass und weich.","dauer":3,"tipp":"Ein Löffel Crème fraîche statt Eis passt auch sehr gut."}],"profitipps":["Butter und Wasser möglichst kalt halten, damit der Teig mürbe wird.","Äpfel dünn schneiden, damit sie in der Backzeit weich werden.","Den Rand fest andrücken, damit kein Saft ausläuft.","Groben Zucker nicht sparen: Er sorgt für Knusprigkeit.","Lauwarm servieren, wenn die Füllung gesetzt hat."],"varianten":["Mit Birnen statt Äpfeln.","Als große Galette für sechs Personen.","Mit Mandelcreme unter den Äpfeln.","Mit Käse und Zwiebeln als herzhafte Variante, wie Ramsay sie andeutet."],"beilagen":["Vanilleeis","Schlagsahne","Karamellsauce"],"getraenk":"Heißer Tee, Kaffee oder ein Glas Apfelwein.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diese Mini-Galettes mit Zimt-Mürbeteig und gewürzten Äpfeln auf seiner Webseite.","quelle":"https://www.gordonramsay.com/gr/recipes/mini-apple-galettes/"}],"quellen":[{"titel":"Gordon Ramsay – Mini Apple Galettes","url":"https://www.gordonramsay.com/gr/recipes/mini-apple-galettes/"},{"titel":"Gordon Ramsay – Dessert-Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/dessert"}],"bild":"kuchen","farben":["#c47f3a","#e8c07a","#8b3a2b"],"schlagworte":["Dessert","Äpfel","Herbst","Gordon Ramsay"],"vegetarisch_moeglich":true},{"id":"britisch-irisch-wolfsbarsch-fenchel-kapern-ramsay","name":"Wolfsbarsch aus der Folie mit Fenchel, Zitrone und Kapern nach Art von Gordon Ramsay","originalname":"Sea Bass with Fennel, Lemon and Capers","kueche":"britisch-irisch","region":"England","beliebtheit":55,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Ganze Wolfsbarsche im Folienpäckchen, gefüllt mit Fenchel, Zitrone, Dill und Kapern und mit einem Schuss Weißwein gedämpft. Wenig Aufwand, viel Aroma, und die Fische werden am Tisch geöffnet.","hintergrund":"Ganze Fische im Ofen zu garen ist eine der einfachsten Möglichkeiten, saftigen Fisch zu bekommen. Ramsay veröffentlicht auf seiner Webseite diese Version: Die Fische werden gefüllt, in Alufolie gewickelt und mit Weißwein im eigenen Dampf gegart. Das Päckchen konserviert alle Aromen, und der Fisch bleibt saftig. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept, mit meinen Erklärungen.","portionen":4,"zeit":{"vorbereitung":20,"garen":20,"ruhen":5},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Fische","liste":[{"menge":2,"einheit":"Stück","name":"ganze Wolfsbarsche (je ca. 600 g)","hinweis":"küchenfertig, geschuppt und ausgenommen; ersatzweise 4 kleine Fische à 300 g"},{"menge":2,"einheit":"Stück","name":"kleine Fenchelknollen","hinweis":"mit Grün, das Grün aufheben"},{"menge":3,"einheit":"EL","name":"kleine Kapern","hinweis":"abgetropft und abgespült"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"in Scheiben geschnitten"},{"menge":2,"einheit":"Zweig","name":"Dill","hinweis":""},{"menge":25,"einheit":"g","name":"Butter","hinweis":"in kleine Stücke"},{"menge":100,"einheit":"ml","name":"trockener Weißwein","hinweis":""},{"menge":null,"einheit":"","name":"Olivenöl, Meersalz, schwarzer Pfeffer","hinweis":""}]}],"ausruestung":["Backblech","Alufolie (stabil)","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Ofen auf 200 °C Ober-/Unterhitze vor, bei Umluft auf 180 °C. Spüle die Fische innen und außen kalt ab und tupfe sie trocken. Schneide den Fenchel in dünne Scheiben und hebe das zarte Grün auf. Schneide die Zitrone in dünne Scheiben, spüle die Kapern ab und bereite zwei große Stücke Alufolie vor, die jeweils deutlich größer als ein Fisch sind. Lege sie mit der glänzenden Seite nach unten aus.","dauer":15,"tipp":"Ein Fischhändler schuppt und nimmt den Fisch gern für dich aus."},{"titel":"Fische würzen","aktion":"marinieren","text":"Würze die Fische großzügig mit Salz und Pfeffer, innen wie außen. Der Fisch hat wenig Eigengeschmack, daher braucht er ausreichend Würze. Lege jeden Fisch in die Mitte eines Folienstücks. Du kannst zusätzlich die Haut zwei- bis dreimal leicht einschneiden, damit die Würze und der Dampf besser eindringen.","dauer":3,"tipp":"Wolfsbarsch verträgt auch ein wenig mehr Salz, denn der Fisch ist von Natur aus mild."},{"titel":"Füllung einlegen","aktion":"fuellen","text":"Verteile die Fenchelscheiben mit etwas Grün im Bauchraum jedes Fisches und streue Kapern darüber. Lege Zitronenscheiben darauf und lege einen Dillzweig dazu. Setze einige Butterflöckchen darauf. Die Zutaten dampfen von innen und aromatisieren das Fleisch, während die Butter dem Dampf Fülle gibt. Überlade den Fisch nicht, sonst lässt sich die Folie nicht mehr schließen.","dauer":5,"tipp":"Auch die Außenseite kannst du mit Zitronenscheiben und Dill belegen."},{"titel":"Folie schließen","aktion":"formen","text":"Beträufle die Fische mit etwas Olivenöl und falte die Folie an den Längsseiten zusammen, sodass sie dicht schließt. Gieße den Weißwein dazu, bevor du die letzte Ecke zufaltest. Falte die Ränder mehrfach, damit kein Dampf entweicht, und lege bei Bedarf eine zweite Lage Folie darum. Ist das Päckchen undicht, geht der Dampf verloren und der Fisch wird trocken.","dauer":5,"tipp":"Das Päckchen darf locker sein: Der Dampf braucht Luft um den Fisch."},{"titel":"Im Ofen dämpfen","aktion":"backen","text":"Lege die Päckchen auf ein Blech und schiebe sie in die Mitte des Ofens. Garen musst du sie etwa 20 Minuten bei Fischen von etwa 600 g und 8 bis 10 Minuten bei kleineren Fischen von etwa 300 g. Der Fisch ist gar, wenn sich das Fleisch an der dicksten Stelle leicht vom Knochen löst und nicht mehr glasig ist. Prüfe im Zweifel durch einen vorsichtigen Einschnitt am Rücken.","dauer":20,"tipp":"Die Garzeit richtet sich nach der Dicke, nicht nach dem Gewicht."},{"titel":"Garprobe machen","aktion":"abschmecken","text":"Öffne ein Päckchen an einer Ecke einen Spalt und prüfe den Fisch an der dicksten Stelle neben dem Rückgrat. Das Fleisch soll weiß und undurchsichtig sein und sich mit einer Gabel leicht in Blättchen vom Knochen heben lassen. Ist es noch glasig oder haftet es am Knochen, schließe die Folie wieder und gare den Fisch noch zwei bis drei Minuten nach. Achte auf den heißen Dampf und halte das Gesicht zur Seite. Ein zu lange gegarter Fisch wird trocken, ein zu kurz gegarter bleibt weich und wässrig.","dauer":3,"tipp":"Mit dem Daumen auf den Rücken drücken: Das Fleisch soll leicht nachgeben und sich vom Knochen lösen."},{"titel":"Kurz ruhen lassen","aktion":"ruhen","text":"Nimm das Blech aus dem Ofen und lass die Päckchen drei bis fünf Minuten ruhen. Der Dampf setzt sich, und der Fisch gart sanft nach. Öffne die Folie danach vorsichtig und mit dem Gesicht weg vom Dampf, denn der Dampf ist sehr heiß. Das Aroma, das jetzt entweicht, nach Fenchel, Zitrone und Wein, ist der erste Hinweis, dass der Fisch gelungen ist.","dauer":5,"tipp":"Am Tisch geöffnet wirkt das Päckchen besonders festlich."},{"titel":"Anrichten","aktion":"anrichten","text":"Öffne die Päckchen und streue das Fenchelgrün darüber. Löse die Filets vorsichtig vom Knochen: Schneide an Rücken und Bauch entlang, hebe das obere Filet ab, ziehe die Mittelgräte heraus und nimm das untere Filet. Gieße den Garsud aus der Folie über den Fisch und serviere sofort mit Kartoffeln oder Brot. Überprüfe zum Schluss auf Gräten.","dauer":5,"tipp":"Der Sud aus Wein, Butter und Fisch ist eine fertige Sauce; nicht wegschütten."}],"profitipps":["Die Folie muss dicht verschlossen sein, sonst geht der Dampf verloren.","Garzeit nach der Fischgröße richten und beim ersten Mal an der Gräte prüfen.","Den Sud aus der Folie als Sauce servieren.","Vorsicht beim Öffnen: Heißer Dampf kann verbrennen.","Auch Dorade oder Forelle gelingen so."],"varianten":["Mit Dorade statt Wolfsbarsch.","Mit Zitronengras und Ingwer asiatisch.","Mit Tomaten und Oliven mediterran.","Als Filetpäckchen für kürzere Garzeit."],"beilagen":["Kartoffeln","Baguette","grüner Salat"],"getraenk":"Trockener Weißwein wie Sauvignon Blanc oder Vermentino.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diesen Wolfsbarsch aus der Folie mit Fenchel, Zitrone und Kapern auf seiner Webseite.","quelle":"https://www.gordonramsay.com/gr/recipes/sea-bass-with-fennel-lemon-and-capers/"}],"quellen":[{"titel":"Gordon Ramsay – Sea Bass with Fennel, Lemon and Capers","url":"https://www.gordonramsay.com/gr/recipes/sea-bass-with-fennel-lemon-and-capers/"},{"titel":"Gordon Ramsay – Fisch-Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/fish"}],"bild":"fisch","farben":["#9fb7c4","#e8e2c4","#6b8e23"],"schlagworte":["Fisch","Ofengericht","Fenchel","Gordon Ramsay"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-arbroath-smokies-mit-butter","name":"Arbroath Smokies mit Butter und Haferkeksen","originalname":"Arbroath Smokie","kueche":"britisch-irisch","region":"Schottland, Angus, Arbroath","beliebtheit":52,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"abendbrot","kurz":"Heiß geräucherter Schellfisch aus dem schottischen Arbroath, warm mit Butter und Pfeffer serviert – dazu Haferkekse und etwas Salat: ein einfaches Abendessen mit großem Raucharoma.","hintergrund":"Arbroath Smokies sind Schellfische, die ursprünglich aus dem Fischerdorf Auchmithie bei Arbroath in Schottland stammen sollen und später nach Arbroath gebracht wurden, als Fischerfamilien Ende des 19. Jahrhunderts dorthin zogen. Die Fische werden über Nacht gesalzen, paarweise mit Hanfschnur zusammengebunden, getrocknet und dann an Holzstangen über einem Hartholzfeuer in einem geschlossenen Fass aufgehängt. Dort garen sie durch intensive Hitze und dichten Rauch in etwa einer Stunde. Seit 2004 hat die Europäische Kommission den Namen „Arbroath Smokies“ als geschützte geografische Angabe (g.g.A.) eingetragen. Die Fische sind bereits gar und werden warm gegessen, oft mit Butter und Brot.","portionen":4,"zeit":{"vorbereitung":15,"garen":15,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Smokies","liste":[{"menge":4,"einheit":"","name":"Arbroath Smokies (je ca. 200–250 g, bei Paaren: 2 Paare)","hinweis":"bereits gar; alternativ heiß geräucherter Schellfisch oder Räucherforelle"},{"menge":60,"einheit":"g","name":"Butter","hinweis":"zerlassen"},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"in Spalten"},{"menge":null,"einheit":"","name":"frisch gemahlener schwarzer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":8,"einheit":"","name":"schottische Haferkekse (Oatcakes)","hinweis":"ersatzweise dunkles Brot oder Toast"},{"menge":4,"einheit":"","name":"Eier","hinweis":"als pochiertes Ei oder Rührei, optional"},{"menge":1,"einheit":"Handvoll","name":"Feldsalat oder Brunnenkresse","hinweis":""},{"menge":2,"einheit":"EL","name":"Schnittlauchröllchen","hinweis":""}]}],"ausruestung":["Backblech mit Backpapier oder Alufolie","Kleiner Topf","Scharfes Messer","Gabel"],"schritte":[{"titel":"Mise en place und Rauchfisch prüfen","aktion":"vorbereiten","text":"Packe die Smokies aus und prüfe sie: Die Haut soll goldbraun bis kupferfarben und leicht glänzend sein, der Duft ausgeprägt rauchig, aber frisch; das Fleisch darunter ist cremeweiß und zart. Lass die Fische vor dem Erwärmen 15 Minuten bei Zimmertemperatur stehen, damit sie gleichmäßig warm werden. Heize den Backofen auf 180 °C (Ober-/Unterhitze, 160 °C Umluft) vor.","dauer":5,"tipp":"Arbroath Smokies sind bereits gegart – sie müssen nur erwärmt werden."},{"titel":"Fisch einpacken","aktion":"vorbereiten","text":"Lege jeden Smokie auf ein Stück Alufolie, beträufle ihn mit etwas zerlassener Butter und einem Spritzer Zitronensaft und falte die Folie locker zu einem Päckchen. Die Folie hält den Dampf zurück, sodass das Fleisch saftig bleibt. Lege die Päckchen auf ein Backblech. Achte darauf, dass die Folie dicht schließt, aber nicht eng anliegt, sodass sich Dampf bilden kann. Das feuchte Klima im Päckchen verhindert, dass die Haut austrocknet und das Fleisch zäh wird, und verteilt die Butter gleichmäßig auf dem Fisch.","dauer":5,"tipp":""},{"titel":"Erwärmen","aktion":"backen","text":"Schiebe das Blech in die Mitte des Backofens und erwärme die Smokies 8–10 Minuten. Sie sind fertig, wenn die Haut leicht knistert und der Fisch heiß ist; das Fleisch soll sich leicht mit einer Gabel teilen lassen und einen Kern von etwa 60–65 °C erreichen. Wärmst du zu lange, wird er trocken. Öffne die Päckchen vorsichtig, da heißer Dampf entweicht.","dauer":10,"tipp":"Alternativ im Grill unter geschlossenem Deckel 5–6 Minuten erwärmen."},{"titel":"Butter bräunen","aktion":"braten","text":"Zerlasse die restliche Butter in einem kleinen Topf und lasse sie 2–3 Minuten weiter erhitzen, bis sie nussig duftet und leicht goldbraun ist. Nimm sie sofort vom Herd, sobald sie haselnussbraun aussieht. Die Butter ergänzt das Rauch-Aroma und rundet es ab. Die Butter soll sich am Boden des Topfes goldgelb färben und nach Haselnuss duften; die Milchbestandteile setzen sich als feine braune Pünktchen ab. Gieße sie vorsichtig durch ein Sieb, wenn du sie besonders klar möchtest. Sie schmeckt hervorragend zum Raucharoma des Fisches.","dauer":3,"tipp":""},{"titel":"Haut abziehen und entgräten","aktion":"vorbereiten","text":"Ziehe die Haut vorsichtig mit den Fingern ab; sie löst sich bei heißem Fisch leicht. Löse das Fleisch mit der Gabel von der Mittelgräte, hebe diese heraus und prüfe das Fleisch auf feine Gräten. Das Fleisch soll in großen, saftigen Blättchen zerfallen. Gehe ruhig vor, denn das Fleisch ist zart und bricht leicht. Die Haut ist meist dunkel und rauchig; sie kann gegessen werden, wenn du es magst, wird aber meist entfernt. Lege die Fleischstücke auf einen Teller und halte sie mit Folie warm.","dauer":5,"tipp":""},{"titel":"Haferkekse und Beilage","aktion":"anrichten","text":"Wärme die Oatcakes kurz im Ofen auf und richte sie auf den Tellern an. Für ein Frühstücks- oder Brunch-Gericht kannst du ein pochiertes Ei oder Rührei dazu servieren. Wasche den Salat und verteile ihn dekorativ mit Schnittlauch. Erwärme sie nur wenige Minuten, bis sie leicht knusprig sind und nach geröstetem Hafer duften. Sie sind ein klassischer schottischer Begleiter zu Fisch und Käse. Der Salat sorgt mit Brunnenkresse für eine scharfe, frische Note.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile das warme Fischfleisch auf Haferkekse oder Toast, beträufle es mit brauner Butter, würze mit frisch gemahlenem schwarzem Pfeffer und serviere es mit Zitronenspalten. Esse es sofort, solange der Rauchduft am intensivsten ist. Der Geschmack soll rauchig, leicht süßlich und buttrig sein, das Fleisch zart und feucht. Wenn dir das Raucharoma zu stark ist, hilft etwas saure Sahne oder Meerrettichcreme als Ausgleich. Serviere dazu ein Stück Zitrone und genieße alles warm.","dauer":0,"tipp":"Ein Spritzer Zitrone hebt das Raucharoma und bricht die Fettigkeit."}],"profitipps":["Smokies nie roh oder kalt aus dem Kühlschrank braten – sie sind bereits gar und brauchen nur Wärme.","Die Haut lässt sich im warmen Zustand am besten abziehen.","Echte Arbroath Smokies tragen die g.g.A.-Kennzeichnung.","Zu langes Erwärmen macht den Fisch trocken.","Mit Sahne und Käse zu einem überbackenen Smokie-Auflauf verarbeiten."],"varianten":["Arbroath Smokie Pâté mit Frischkäse und Zitrone.","Smokie-Omelette mit Kartoffeln.","Kalt im Salat mit Kartoffeln und Meerrettichcreme.","Als Auflauf mit Sahne und Käse."],"beilagen":["Haferkekse","Dunkles Brot","Pochierte Eier","Salat"],"getraenk":"Schottisches Ale oder ein kräftiger Tee; für Genießer ein rauchiger Islay-Whisky.","koeche":[],"quellen":[{"titel":"Arbroath smokie – Wikipedia","url":"https://en.wikipedia.org/wiki/Arbroath_smokie"},{"titel":"Arbroath Smokies – Rezepte","url":"https://arbroathsmokiesonline.co.uk/category/haddock-recipes"}],"bild":"fisch","farben":["#b8793a","#e8d3a2","#6a7f4a"],"schlagworte":["Schottland","Räucherfisch","einfach","g.g.A."],"vegetarisch_moeglich":false,"hinweis":"Echte Arbroath Smokies bekommst du in Deutschland nur im Spezialhandel oder online. Ersatz: heiß geräucherter Schellfisch, Räucherforelle oder Makrele von der Fischtheke."},{"id":"britisch-irisch-gefuellter-schweinerollbraten-manchego-ramsay","name":"Gefüllter Schweinebraten mit Manchego und Quittenpaste nach Art von Gordon Ramsay","originalname":"Stuffed Pork Tenderloin (Pork Stuffed with Manchego and Membrillo)","kueche":"britisch-irisch","region":"England (mit spanischen Zutaten)","beliebtheit":52,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Ein aufgeklappter Schweinerücken, gefüllt mit würzigem Manchego und süßer Quittenpaste, mit Salbei aromatisiert und im Ofen gebraten. Dazu eine schnelle Sauce aus dem Bratensatz mit Sherry.","hintergrund":"Schweinebraten mit knuspriger Kruste ist ein britischer Klassiker, den Ramsay hier mit spanischen Zutaten verbindet: Manchego, ein reifer Schafskäse, und Membrillo, eine feste Quittenpaste, die in Spanien zu Käse gegessen wird. Beide schmelzen und karamellisieren im Fleisch. Die Sauce entsteht mit Sherry im Bräter. Die Webseite nennt das Gericht Stuffed Pork Tenderloin, verwendet aber ein Stück Schweinerücken mit Schwarte. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept.","portionen":4,"zeit":{"vorbereitung":30,"garen":80,"ruhen":20},"schwierigkeit":2,"themen":["fest"],"zutaten":[{"gruppe":"Für den Braten","liste":[{"menge":1,"einheit":"kg","name":"Schweinerücken ohne Knochen, mit Schwarte","hinweis":"Schwarte vom Metzger kreuzweise einritzen lassen"},{"menge":175,"einheit":"g","name":"Manchego","hinweis":"in dünne Scheiben geschnitten; ersatzweise Pecorino oder Gruyère"},{"menge":150,"einheit":"g","name":"Quittenpaste (Membrillo)","hinweis":"in dünne Scheiben; Feinkostladen oder gut sortierter Supermarkt"},{"menge":2,"einheit":"Zweig","name":"Salbei","hinweis":"Blätter eines Zweigs für die Füllung, der zweite für die Form"},{"menge":1,"einheit":"Knolle","name":"Knoblauch","hinweis":"quer halbiert"},{"menge":1,"einheit":"Zweig","name":"Thymian","hinweis":""},{"menge":null,"einheit":"","name":"Olivenöl, Meersalz, schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Für die Sauce","liste":[{"menge":200,"einheit":"ml","name":"halbtrockener Sherry","hinweis":"Amontillado oder Medium-Dry"}]}],"ausruestung":["Bräter, auch für den Herd geeignet","Küchengarn","Fleischthermometer","feines Sieb","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm das Fleisch etwa eine Stunde vor dem Braten aus dem Kühlschrank und tupfe es trocken, besonders die Schwarte. Schneide den Manchego und die Quittenpaste in dünne Scheiben, zupfe die Blätter eines Salbeizweigs ab und halbiere den Knoblauch. Bereite Küchengarn in Stücken von je 30 cm vor und heize den Ofen auf 220 °C Ober-/Unterhitze, bei Umluft auf 200 °C.","dauer":15,"tipp":"Eine trockene Schwarte wird später richtig knusprig."},{"titel":"Fleisch aufschneiden","aktion":"schneiden","text":"Lege den Braten mit der Schwarte nach unten auf ein Brett. Schneide ihn der Länge nach etwa zu drei Vierteln durch und klappe ihn wie ein Buch zu einem langen Rechteck auf. Würze die Innenseite mit Salz und Pfeffer. Arbeite mit einem langen, scharfen Messer und führe den Schnitt gleichmäßig, damit die Fleischdicke überall ähnlich ist.","dauer":8,"tipp":"Frage deinen Metzger, ob er das Fleisch gleich für dich aufschneidet."},{"titel":"Füllen","aktion":"fuellen","text":"Verteile die Käsescheiben und die Quittenpaste in der Mitte des Fleisches, lege sie gleichmäßig aus und streue die Salbeiblätter darüber. Lass seitlich etwas Platz, denn beim Rollen drückt sich die Füllung heraus. Der Käse schmilzt später, die Quitte karamellisiert, und das Fleisch bekommt eine süßlich-würzige Mitte.","dauer":5,"tipp":"Nicht zu viel Quitte, sonst wird die Füllung zu süß."},{"titel":"Rollen und binden","aktion":"rollen","text":"Rolle das Fleisch von einer langen Seite her zusammen, sodass die Schwarte außen liegt, und binde es im Abstand von etwa 3 cm mit Küchengarn. Binde gleichmäßig fest, damit der Braten seine Form hält und die Füllung nicht entweicht. Wenn Füllung herausquillt, schiebe sie zurück. Prüfe, ob das Paket gleich dick ist, damit es gleichmäßig gart.","dauer":10,"tipp":"Beginne in der Mitte zu binden und arbeite dich zu den Enden vor."},{"titel":"In die Form legen und würzen","aktion":"marinieren","text":"Lege Thymian, den zweiten Salbeizweig und die Knoblauchhälften in einen Bräter, der auch auf die Herdplatte darf. Setze den Braten mit der Schwarte nach oben darauf, beträufle ihn mit Olivenöl und würze ihn kräftig mit Salz und Pfeffer. Das Salz zieht Feuchtigkeit aus der Schwarte und macht sie beim Braten knusprig.","dauer":3,"tipp":"Salz die Schwarte erst unmittelbar vor dem Braten."},{"titel":"Heiß anbraten","aktion":"braten","text":"Schiebe den Bräter in die Mitte des Ofens und brate den Braten bei 220 °C etwa 20 Minuten, bis die Schwarte goldbraun und knusprig ist; sie blubbert und knistert dabei. Das heiße Anbraten sorgt für die Kruste, bevor das Fleisch langsamer weitergart. Schau nach etwa 15 Minuten nach: Wird die Kruste an einzelnen Stellen zu dunkel, decke diese Stellen locker mit Alufolie ab.","dauer":20,"tipp":"Wenn die Schwarte nicht aufpufft, schalte die Grillfunktion für wenige Minuten dazu, aber beobachte sie genau."},{"titel":"Bei niedrigerer Temperatur durchgaren","aktion":"braten","text":"Senke die Ofentemperatur auf 180 °C Ober-/Unterhitze, bei Umluft auf 160 °C, und brate den Braten weitere 50 Minuten, bis er gerade durchgegart ist. Als Orientierung zeigt ein Fleischthermometer in der Mitte etwa 65 bis 68 °C, bevor du ihn herausnimmst. Das Fleisch soll saftig und leicht rosig, nicht trocken sein. Hebe den Braten dann auf eine Platte und lass ihn ruhen.","dauer":50,"tipp":"Das Thermometer nicht in die Füllung stecken, sondern in das Fleisch daneben."},{"titel":"Sauce aus dem Bratensatz","aktion":"reduzieren","text":"Stelle den Bräter auf den Herd, gieße den Sherry hinein und koche alles auf. Löse mit einem Holzlöffel den Bratensatz vom Boden, denn dort sitzen die Aromen. Reduziere die Hitze und drücke den weichen Knoblauch aus der Schale, damit er die Sauce bindet. Entferne die Kräuter und rühre den ausgetretenen Fleischsaft ein. Lass die Sauce kurz einkochen und schmecke sie ab.","dauer":8,"tipp":"Ist die Sauce zu dünn, lass sie einige Minuten länger einkochen."},{"titel":"Aufschneiden und servieren","aktion":"anrichten","text":"Entferne das Garn, schneide den Braten nach 15 bis 20 Minuten Ruhezeit in dicke Scheiben und lege sie auf warme Teller. Die Füllung aus geschmolzenem Käse und Quitte sollte sichtbar im Inneren glänzen. Seihe die Sauce durch ein Sieb und löffle sie über das Fleisch. Dazu passen Ofenkartoffeln und grünes Gemüse.","dauer":5,"tipp":"Mit einem scharfen Wellenschliffmesser lässt sich die Schwarte besser schneiden."}],"profitipps":["Die Schwarte vor dem Braten sehr gut abtrocknen, damit sie knusprig wird.","Gleichmäßig dick aufschneiden und binden, damit das Fleisch gleichmäßig gart.","Mit dem Thermometer arbeiten; Schweinefleisch wird schnell trocken.","Den Bratensatz mit Sherry lösen: Er ist die Basis der Sauce.","Den Braten mindestens 15 Minuten ruhen lassen."],"varianten":["Mit Ziegenkäse und Feigenmarmelade.","Mit Äpfeln und Cheddar nach englischer Art.","Mit Serrano-Schinken in der Füllung.","Als kalter Aufschnitt für ein Büfett."],"beilagen":["Ofenkartoffeln","Rosenkohl","Apfelmus"],"getraenk":"Spanischer Rotwein wie Rioja Crianza oder trockener Sherry.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht diesen gefüllten Schweinebraten mit Manchego, Quittenpaste und Salbei auf seiner Webseite; die Sauce entsteht aus dem Bratensatz mit Sherry.","quelle":"https://www.gordonramsay.com/gr/recipes/pork-stuffed-with-manchego-and-membrillo/"}],"quellen":[{"titel":"Gordon Ramsay – Stuffed Pork Tenderloin (Manchego and Membrillo)","url":"https://www.gordonramsay.com/gr/recipes/pork-stuffed-with-manchego-and-membrillo/"},{"titel":"Gordon Ramsay – Rezeptübersicht","url":"https://www.gordonramsay.com/gr/recipes/"}],"bild":"braten-scheiben","farben":["#a05a2c","#e0b36b","#7a8f4a"],"schlagworte":["Festtagsbraten","Schwein","Manchego","Gordon Ramsay"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-cock-a-leekie","name":"Cock-a-leekie – schottische Hühnersuppe mit Lauch und Pflaumen","originalname":"Cock-a-leekie soup","kueche":"britisch-irisch","region":"Schottland","beliebtheit":52,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"suppe","kurz":"Kräftige schottische Hühnersuppe mit Lauch, Graupen und Backpflaumen, die mild-süßlich mit dem Hühnerfleisch harmoniert – ein Gericht aus dem Mittelalter.","hintergrund":"Cock-a-leekie ist eine schottische Suppe oder ein Eintopf aus Huhn und Lauch; der Name setzt sich aus ‚cock‘ (Hahn) und ‚leek‘ (Lauch) zusammen und ist seit dem 18. Jahrhundert belegt, das Gericht selbst dürfte aus dem Mittelalter stammen. Ursprünglich enthielt es Zwiebeln statt Lauch sowie Backpflaumen und teils Rosinen; das gekochte Huhn wurde getrennt gegessen und die Brühe dazu getrunken. Heute serviert man das zerkleinerte Hühnerfleisch direkt in der Suppe. Lady Grisell Baillie (1665–1746) beschrieb das Gericht angeblich als ‚Hühnersuppe mit Hühnern drin‘, und Sir Walter Scott erwähnte es in seinen Waverley-Romanen. Es gilt als schottisches Nationalgericht und wird am Burns Supper gern serviert.","portionen":6,"zeit":{"vorbereitung":25,"garen":120,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Suppe","liste":[{"menge":1,"einheit":"Stück","name":"Suppenhuhn (ca. 1,5 kg)","hinweis":"ersatzweise 1 kg Hühnerkeulen mit Knochen"},{"menge":2.5,"einheit":"l","name":"kaltes Wasser","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"halbiert"},{"menge":1,"einheit":"Stück","name":"Möhre","hinweis":""},{"menge":1,"einheit":"Blatt","name":"Lorbeerblatt","hinweis":""},{"menge":6,"einheit":"Stück","name":"Pfefferkörner","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":4,"einheit":"Stange","name":"Lauch","hinweis":"nur Weiß- und Hellgrünes, in 1 cm Ringe"},{"menge":60,"einheit":"g","name":"Perlgraupen","hinweis":"optional, traditionell, vorher kalt abspülen"},{"menge":10,"einheit":"Stück","name":"entsteinte Backpflaumen","hinweis":"in feine Streifen geschnitten"},{"menge":1,"einheit":"EL","name":"gehackte Petersilie","hinweis":""},{"menge":null,"einheit":"","name":"Pfeffer","hinweis":"frisch gemahlen"}]}],"ausruestung":["großer Suppentopf","Schaumkelle","feines Sieb","Schneidebrett und Messer","zwei Gabeln zum Zerpflücken"],"schritte":[{"titel":"Mise en place: Huhn und Gemüse vorbereiten","aktion":"vorbereiten","text":"Spüle das Suppenhuhn innen und außen unter kaltem Wasser ab und tupfe es trocken. Entferne überflüssiges Fett am Hals- und Bürzelansatz. Halbiere die Zwiebel, schäle die Möhre und schneide sie in grobe Stücke. Putze den Lauch, schneide das dunkle Grün ab, halbiere die Stangen der Länge nach und wasche sie zwischen den Blättern gründlich. Schneide die Lauchringe erst später. Spüle die Graupen kalt ab und schneide die Pflaumen in feine Streifen.","dauer":0,"tipp":"Das dunkelgrüne Lauchende kommt mit in den Brühtopf: Es gibt Geschmack und wird später entfernt."},{"titel":"Huhn kalt ansetzen und abschäumen","aktion":"kochen","text":"Lege das Huhn in den Topf, füge Zwiebel, Möhre, Lorbeer, Pfefferkörner und das Lauchgrün hinzu und gieße 2,5 Liter kaltes Wasser auf. Erhitze langsam bei mittlerer Hitze, bis kurz vor dem Sieden. Nach etwa 15 bis 20 Minuten bildet sich grauer Eiweißschaum, den du mit der Schaumkelle abschöpfst. Kaltes Wasser und sanfte Hitze sorgen dafür, dass die Brühe klar und goldgelb wird.","dauer":20,"tipp":""},{"titel":"Brühe ziehen lassen","aktion":"koecheln","text":"Senke die Hitze, bis die Brühe nur noch leise zittert, und lege den Deckel schräg auf. Lass das Huhn 1,5 Stunden ziehen, bis das Fleisch beim Einstechen sehr weich ist und sich die Keule leicht lösen lässt. Salze erst gegen Ende. Der Duft ist warm und kräftig nach Huhn, die Brühe ist goldgelb. Je langsamer sie zieht, desto klarer wird sie.","dauer":90,"tipp":"Ein altes Suppenhuhn braucht mehr Zeit als ein junges Huhn, bringt aber auch mehr Geschmack."},{"titel":"Huhn herausnehmen und Brühe abseihen","aktion":"abseihen","text":"Hebe das Huhn vorsichtig mit einer Kelle oder zwei Löffeln aus dem Topf und lege es auf ein Brett. Gieße die Brühe durch ein feines Sieb in einen sauberen Topf, entferne Gemüse und Gewürze und schöpfe das Fett oben mit einem Löffel ab; ein bisschen Fett darf für den Geschmack bleiben. Schmecke die Brühe mit Salz und Pfeffer ab. Sie soll klar, goldgelb und kräftig schmecken.","dauer":0,"tipp":""},{"titel":"Fleisch auslösen","aktion":"schneiden","text":"Ziehe von dem noch warmen Huhn Haut und Knochen ab und zupfe das Fleisch mit zwei Gabeln in mundgerechte Stücke von 2 bis 3 cm. Das Fleisch soll saftig und zart sein. Lege es abgedeckt beiseite und gib einen Schöpflöffel Brühe darauf, damit es nicht austrocknet. Die Knochen kannst du für eine zweite Brühe einfrieren.","dauer":0,"tipp":""},{"titel":"Lauch, Graupen und Pflaumen garen","aktion":"koecheln","text":"Bringe die Brühe wieder zum Sieden, gib die Graupen hinein und lass sie 20 Minuten kochen. Füge dann die Lauchringe und die Pflaumenstreifen hinzu und koche alles weitere 10 bis 15 Minuten, bis die Graupen weich sind und der Lauch zart ist. Die Pflaumen geben der Suppe eine dezente fruchtige Süße und färben sie leicht dunkler. Rühre gelegentlich um, damit die Graupen nicht ansetzen.","dauer":35,"tipp":"Die Pflaumen sind der traditionelle Kontrast zum salzigen Huhn. Anfangs ungewohnt, aber sehr stimmig."},{"titel":"Fleisch zugeben und abschmecken","aktion":"abschmecken","text":"Gib das zerpflückte Hühnerfleisch in die Suppe und erwärme alles 3 Minuten bei kleiner Hitze. Schmecke kräftig mit Salz und frisch gemahlenem Pfeffer ab. Falls die Suppe zu dick geworden ist, gieße etwas heißes Wasser oder Brühe nach. Der Geschmack sollte herzhaft, mild-süß und angenehm lauchig sein.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schöpfe die Suppe in vorgewärmte tiefe Teller und achte darauf, dass in jeder Portion Fleisch, Lauch und Pflaumenstreifen schwimmen. Bestreue sie mit gehackter Petersilie und mahle noch etwas frischen Pfeffer darüber. Serviere sie sehr heiß mit dickem, dunklem Brot und Butter, damit man die Brühe auftunken kann. Die Suppe duftet nach Huhn, Lauch und einer Spur Frucht; die Graupen sind weich, aber noch leicht bissfest, und die Brühe glänzt goldgelb.","dauer":0,"tipp":"Zum Burns Supper am 25. Januar serviert man sie in Schottland oft als Vorspeise vor dem Haggis."}],"profitipps":["Ein Suppenhuhn gibt mehr Geschmack als ein junges Brathuhn; als Ersatz Hühnerkeulen mit Knochen verwenden.","Die Brühe nie sprudelnd kochen, sonst wird sie trüb.","Nur Weiß- und Hellgrünes vom Lauch in die Einlage geben, das Dunkelgrün schmeckt zäh und herb.","Pflaumen sind klassisch, aber Geschmackssache: Wer sie nicht mag, serviert sie separat.","Der erste Schaum muss gründlich abgeschöpft werden, sonst wird die Brühe trüb und schmeckt flach."],"varianten":["Edle Version auf Basis von Consommé: klare Brühe mit Lauchjulienne, Hühnerstreifen und einer Pflaume.","Mit Resten vom Brathuhn: Karkasse und Bratenreste statt Suppenhuhn, für eine schnelle Version.","Ohne Graupen, dafür mit etwas Reis oder Kartoffelwürfeln.","Ohne Pflaumen, dafür mit Petersilie und Karotten."],"beilagen":["dunkles Brot mit Butter","Haferflocken-Bannock","schottischer Cheddar"],"getraenk":"Schottisches Ale oder ein Glas Weißwein","koeche":[{"name":"Michel Roux jr.","bezug":"Wird auf Wikipedia als Quelle für die Variante genannt, bei der Karkasse und Bratenreste eines Brathuhns als Basis der Cock-a-leekie-Brühe dienen (Hinweis: Der Bezug stammt aus einer Literaturangabe, nicht aus einer eigenen Rezeptseite).","quelle":"https://de.wikipedia.org/wiki/Cock-a-leekie"}],"quellen":[{"titel":"Cock-a-leekie (Wikipedia)","url":"https://de.wikipedia.org/wiki/Cock-a-leekie"}],"bild":"suppe","farben":["#e3b55a","#f5deb0","#6b8e3e"],"schlagworte":["Schottland","Hühnersuppe","Lauch","Burns Supper","Klassiker"],"vegetarisch_moeglich":false},{"id":"britisch-irisch-perlgraupen-risotto-pilze-ramsay","name":"Perlgraupen-„Risotto“ mit Pilzen und Trüffelkäse nach Art von Gordon Ramsay","originalname":"Mushroom Barley “Risotto” with Truffle Cheese, Herb and Microgreen Salad","kueche":"britisch-irisch","region":"England / USA","beliebtheit":45,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Nussige Perlgraupen, wie ein Risotto mit selbst gekochtem Pilzfond zubereitet, mit Lauch, Shiitake, Weißwein und Trüffelkäse. Obendrauf ein frischer Kräutersalat mit Zitrone.","hintergrund":"Perlgraupen sind in Großbritannien und Irland eine traditionelle Suppen- und Eintopfeinlage. Ramsay nutzt sie auf seiner Webseite statt Reis für ein „Risotto“, das mit starkem Pilzfond aus frischen und getrockneten Pilzen gekocht wird. Zum Schluss rührt er Trüffelkäse und Zitronenschale ein. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept; die Webseite nennt keine Portionszahl, vier Portionen sind meine Schätzung.","portionen":4,"zeit":{"vorbereitung":30,"garen":90,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Pilzfond","liste":[{"menge":225,"einheit":"g","name":"frische Pilze","hinweis":"Champignons, geputzt und grob gehackt; Stiele der Risotto-Pilze kannst du hier mitverwenden"},{"menge":1,"einheit":"Stück","name":"Karotte","hinweis":"grob gehackt"},{"menge":1,"einheit":"Stück","name":"gelbe Zwiebel","hinweis":"grob gehackt"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"angedrückt"},{"menge":30,"einheit":"g","name":"getrocknete Steinpilze","hinweis":"oder Mischpilze"},{"menge":2.4,"einheit":"l","name":"Wasser","hinweis":"kalt"},{"menge":null,"einheit":"","name":"Olivenöl und Salz","hinweis":"zum Anschwitzen"}]},{"gruppe":"Für das Graupen-Risotto","liste":[{"menge":30,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"Stück","name":"Schalotte","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Lauchstange","hinweis":"weißer und hellgrüner Teil in Halbmonden, gewaschen"},{"menge":450,"einheit":"g","name":"Pilze (z. B. Shiitake)","hinweis":"Stiele entfernt, dünn geschnitten"},{"menge":2,"einheit":"Zweig","name":"Thymian","hinweis":""},{"menge":200,"einheit":"g","name":"Perlgraupen","hinweis":"ca. 1 Tasse"},{"menge":120,"einheit":"ml","name":"trockener Weißwein","hinweis":""},{"menge":60,"einheit":"g","name":"Trüffelkäse","hinweis":"z. B. Trüffel-Taleggio oder Pecorino al tartufo, gewürfelt oder gerieben"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"Schale fein abgerieben"}]},{"gruppe":"Für den Kräutersalat","liste":[{"menge":15,"einheit":"g","name":"glatte Petersilie","hinweis":"Blätter, grob gezupft"},{"menge":15,"einheit":"g","name":"Microgreens oder Kresse","hinweis":""},{"menge":1,"einheit":"EL","name":"Olivenöl extra vergine","hinweis":"gutes Öl"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"Schale und ein Spritzer Saft"}]}],"ausruestung":["großer Topf (5 l)","weite Pfanne oder Schmortopf","feines Sieb","Schöpfkelle"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Putze alle Pilze mit einem feuchten Tuch und schneide die für den Fond grob, die für das Risotto in dünne Scheiben. Hebe die Pilzstiele auf, sie wandern in den Fond. Schneide Schalotte, Lauch und Karotte, zerdrücke den Knoblauch und zupfe den Thymian. Stelle alles übersichtlich bereit, denn der Fond braucht mindestens 45 Minuten, und das Risotto lässt sich nicht unterbrechen.","dauer":20,"tipp":"Den Lauch gründlich waschen, denn zwischen den Schichten sitzt oft Sand."},{"titel":"Pilzfond ansetzen","aktion":"schmoren","text":"Erhitze in einem großen Topf einen Schuss Olivenöl bei niedriger bis mittlerer Hitze und gib die frischen Pilze, Karotte, Zwiebel, Knoblauch und eine kleine Prise Salz hinein. Schwitze alles 10 bis 15 Minuten unter Rühren an, ohne zu bräunen, bis das Gemüse weich ist und duftet. So bekommt der Fond Tiefe. Das langsame Anschwitzen holt Aroma aus dem Gemüse, ohne Bitterstoffe zu erzeugen.","dauer":15,"tipp":"Eine Prise Salz hilft dem Gemüse beim Anschwitzen, Wasser abzugeben."},{"titel":"Fond kochen und passieren","aktion":"koecheln","text":"Gib die getrockneten Pilze und das Wasser in den Topf, bringe alles zum Kochen, reduziere die Hitze auf mittlere bis niedrige Stufe und lass den Fond mindestens 30 Minuten sanft köcheln. Seihe ihn durch ein feines Sieb in einen zweiten Topf, drücke das Gemüse aus und verwirf die Reste. Der Fond sollte tiefbraun und aromatisch riechen. Halte ihn auf kleinster Flamme heiß, denn kalter Fond bremst das Garen der Graupen.","dauer":40,"tipp":"Die gequollenen Trockenpilze kannst du fein hacken und ins Risotto geben."},{"titel":"Lauch und Pilze anschwitzen","aktion":"braten","text":"Wische den großen Topf trocken. Schmilz die Butter bei mittlerer Hitze und schwitze Schalotte und Lauch mit einer Prise Salz drei bis fünf Minuten, bis sie weich sind. Gib die dünn geschnittenen Pilze und den Thymian dazu und brate sie, bis sie weich sind und das meiste Wasser verdampft ist. Die Pilze sollen leicht Farbe nehmen und nach Wald duften.","dauer":15,"tipp":"Wenn die Pilze zu viel Wasser lassen, brate sie in zwei Portionen."},{"titel":"Graupen rösten und ablöschen","aktion":"anbraten","text":"Gib die Perlgraupen und eine kleine Prise Salz zu den Pilzen und röste sie ein bis zwei Minuten unter Rühren, bis sie nussig duften. Gieße den Weißwein ein und löse mit dem Löffel alles vom Boden. Lass ihn fast vollständig verdampfen. Das Rösten macht die Graupen aromatischer, und der Wein bringt Säure, die das erdige Gericht später ausgleicht.","dauer":5,"tipp":"Die Graupen vorher kurz mit kaltem Wasser abspülen, das entfernt Staub."},{"titel":"Mit Fond aufgießen","aktion":"koecheln","text":"Reduziere die Hitze auf mittlere bis niedrige Stufe und gib eine Kelle Pilzfond zu den Graupen. Rühre häufig um, bis fast alles aufgesogen ist, und gieße dann die nächste Kelle nach. Wiederhole das etwa 30 bis 40 Minuten lang. Perlgraupen brauchen länger als Reis, die Körner quellen langsam und geben Stärke ab, die das Gericht cremig macht.","dauer":40,"tipp":"Wird der Fond knapp, ergänze mit heißem Wasser; Graupen sollen nie trocken stehen."},{"titel":"Käse und Zitronenschale einrühren","aktion":"mischen","text":"Wenn die Graupen weich sind, aber noch Biss haben, ziehe den Topf vom Herd. Rühre den Trüffelkäse und die Zitronenschale ein, bis der Käse geschmolzen ist und das Gericht sämig und glänzend wird. Probiere und schmecke mit Salz und Pfeffer ab. Der Trüffelkäse ist schon recht salzig, daher vorsichtig nachwürzen.","dauer":3,"tipp":"Ist das Risotto zu fest, rühre einen Schuss heißen Fond unter."},{"titel":"Kräutersalat und Anrichten","aktion":"anrichten","text":"Mische Petersilie und Microgreens in einer Schüssel mit einem Schuss Olivenöl, etwas Zitronenschale, einer Prise Salz und einem Spritzer Zitronensaft. Löffle das Risotto in vorgewärmte Teller und lege den Salat darauf. Serviere sofort, denn das Risotto zieht beim Stehen nach. Der frische, säuerliche Salat bildet einen wunderbaren Kontrast zur erdigen, cremigen Basis.","dauer":5,"tipp":"Den Salat erst kurz vor dem Servieren anmachen, sonst fällt er zusammen."}],"profitipps":["Der Pilzfond bringt den Geschmack; nimm dir dafür Zeit und verwende getrocknete Pilze.","Den Fond während des Garens heiß halten.","Graupen brauchen länger als Risottoreis; plane 30 bis 40 Minuten ein.","Trüffelkäse erst am Ende einrühren und vorsichtig nachsalzen.","Die Pilzstiele nicht wegwerfen, sondern im Fond verwenden."],"varianten":["Mit Dinkel oder Emmer statt Perlgraupen.","Mit Parmesan statt Trüffelkäse.","Mit Gemüsefond statt Pilzfond.","Mit gebratenem Spiegelei obenauf."],"beilagen":["grüner Salat","geröstetes Brot"],"getraenk":"Kräftiger Weißwein wie Grauburgunder oder ein leichter Pinot Noir.","koeche":[{"name":"Gordon Ramsay","bezug":"Ramsay veröffentlicht dieses „Risotto“ aus Perlgraupen mit selbst gemachtem Pilzfond, Lauch, Trüffelkäse und Kräutersalat auf seiner Webseite.","quelle":"https://www.gordonramsay.com/gr/recipes/barleyrisotto/"}],"quellen":[{"titel":"Gordon Ramsay – Mushroom Barley “Risotto” with Truffle Cheese, Herb and Microgreen Salad","url":"https://www.gordonramsay.com/gr/recipes/barleyrisotto/"},{"titel":"Gordon Ramsay – Vegetarische Rezepte","url":"https://www.gordonramsay.com/gr/recipes/category/vegetarian"}],"bild":"reis","farben":["#8b6b4a","#d9c7a3","#5f7f3a"],"schlagworte":["Vegetarisch","Pilze","Graupen","Gordon Ramsay"],"vegetarisch_moeglich":true}]);
